# check_rain_transitions, чтобы решить, считать ли переход "усилением"
# (дождь -> ливень) и стоит ли из-за этого слать ДОПОЛНИТЕЛЬНЫЙ пуш, даже
# если пуш о начале осадков уже был отправлен. 0 и коды без активных осадков
# (туман, облачность) не считаются осадками вообще - PRECIP_WEATHERCODES ниже
# ограничивает список только теми кодами, что реально означают дождь/снег/град.
WEATHERCODE_INFO = {
    0: ('ясно', 0, '☀️'),
    1: ('малооблачно', 0, '🌤'),
    2: ('облачно с прояснениями', 0, '⛅'),
    3: ('пасмурно', 0, '☁️'),
    45: ('туман', 0, '🌫'),
    48: ('изморозь', 0, '🌫'),
    51: ('морось слабая', 1, '🌦'),
    53: ('морось', 2, '🌦'),
    55: ('морось сильная', 3, '🌧'),
    56: ('ледяная морось слабая', 2, '🌧'),
    57: ('ледяная морось сильная', 3, '🌧'),
    61: ('дождь слабый', 2, '🌧'),
    63: ('дождь', 3, '🌧'),
    65: ('сильный дождь', 5, '🌧'),
    66: ('ледяной дождь слабый', 3, '🌧'),
    67: ('ледяной дождь сильный', 5, '🌧'),
    71: ('снег слабый', 2, '🌨'),
    73: ('снег', 3, '🌨'),
    75: ('сильный снегопад', 5, '❄️'),
    77: ('снежная крупа', 2, '🌨'),
    80: ('ливень слабый', 3, '🌧'),
    81: ('ливень', 4, '🌧'),
    82: ('сильный ливень', 6, '⛈'),
    85: ('снежный заряд слабый', 3, '🌨'),
    86: ('снежный заряд сильный', 5, '❄️'),
    95: ('гроза', 6, '⛈'),
    96: ('гроза с градом слабая', 7, '⛈'),
    99: ('гроза с сильным градом', 8, '⛈'),
}
# Коды, которые считаем "осадками" для целей пуша/фонового мониторинга -
# всё, что не входит сюда (ясно/облачно/туман), не запускает предупреждение.
PRECIP_WEATHERCODES = {code for code, (_, weight, _) in WEATHERCODE_INFO.items() if weight > 0}

def describe_weathercode(code):
    return WEATHERCODE_INFO.get(code, ('осадки', 1, '🌧'))

# Влияние осадков на спрос по 10-балльной шкале, присланное пользователем
# 22.09.2026 - ДВЕ РАЗНЫЕ шкалы: у Ultima (Business/Premier/Élite/Cruise)
# спрос от дождя растёт заметнее, чем у обычного такси (Эконом/Комфорт/
# Комфорт+) - меньше свободных премиальных машин, клиенты охотнее берут
# дорогое такси, лишь бы не мокнуть. Ключ - интенсивность осадков (см.
# WEATHERCODE_TO_INTENSITY ниже, сопоставляет каждый код погоды Open-Meteo
# с одной из этих 7 градаций).
RAIN_IMPACT_TAXI = {
    'none': 0, 'drizzle': 1, 'light': 2, 'moderate': 3,
    'heavy': 5, 'downpour': 7, 'extreme': 8,
}
RAIN_IMPACT_ULTIMA = {
    'none': 0, 'drizzle': 1, 'light': 2, 'moderate': 4,
    'heavy': 7, 'downpour': 9, 'extreme': 10,
}
# Категория -> своя шкала выше. courier/cargo своей шкалы не прислали -
# используют шкалу обычного такси (ближе по типу транспорта/спроса, чем
# Ultima), как и любая не перечисленная категория.
CATEGORY_RAIN_IMPACT = {
    'taxi': RAIN_IMPACT_TAXI,
    'ultima': RAIN_IMPACT_ULTIMA,
}

def get_rain_impact_scale(category):
    """Возвращает 10-балльную шкалу влияния осадков на спрос для категории -
    см. CATEGORY_RAIN_IMPACT/RAIN_IMPACT_TAXI/RAIN_IMPACT_ULTIMA выше."""
    return CATEGORY_RAIN_IMPACT.get(category, RAIN_IMPACT_TAXI)

# Код погоды Open-Meteo -> градация интенсивности осадков (ключ шкалы выше).
# Коды без активных осадков (0-3, туман 45/48) сюда не входят - для них
# интенсивность 'none' (обрабатывается отдельно, см. rain_impact_score).
WEATHERCODE_TO_INTENSITY = {
    51: 'drizzle', 53: 'drizzle', 55: 'light', 56: 'light', 57: 'moderate',
    61: 'light', 63: 'moderate', 65: 'heavy', 66: 'moderate', 67: 'heavy',
    71: 'light', 73: 'moderate', 75: 'heavy', 77: 'light',
    80: 'moderate', 81: 'downpour', 82: 'extreme',
    85: 'moderate', 86: 'heavy',
    95: 'downpour', 96: 'downpour', 99: 'extreme',
}

def rain_impact_score(code, category):
    """Балл влияния текущих/ожидаемых осадков (код Open-Meteo) на спрос для
    данной категории - по 10-балльной шкале пользователя (см.
    CATEGORY_RAIN_IMPACT). 0, если осадков нет/код неизвестен."""
    intensity = WEATHERCODE_TO_INTENSITY.get(code, 'none')
    return get_rain_impact_scale(category).get(intensity, 0)

# ==================== НАСТРОЙКИ ПУШЕЙ ====================
# По просьбе пользователя - каждый тип автопуша можно включить/выключить
# отдельно (кнопка "🔔 Уведомления" в "Инструменты водителя", см.
# notification_settings_keyboard/show_notification_settings ниже). Настройка
# хранится в user_state[uid]['notif_prefs'][key] - словарь key->bool, читается
# через notifications_enabled(). Отсутствие ключа = включено (все типы по
# умолчанию ON, чтобы не заставлять существующих пользователей заново всё
# включать после обновления бота).
NOTIFICATION_TYPES = {
    'weather': {'label': 'ПОГОДА/ОСАДКИ', 'emoji': '🌤'},
    'airport_status': {'label': 'СТАТУС АЭРОПОРТА', 'emoji': '✈️'},
    'high_demand': {'label': 'ПОВЫШЕННЫЙ СПРОС', 'emoji': '📈'},
    'holidays': {'label': 'ПРАЗДНИКИ', 'emoji': '🎉'},
    'peak_hours': {'label': 'ЧАСЫ ПИКА', 'emoji': '📅'},
    # По просьбе пользователя (20.09.2026): "делай пуши перекрытий... и
    # крупные ДТП" - общая настройка на весь город (см. AskUserQuestion:
    # "всем в городе, у кого включены пуши"), не привязана к
    # активной смене - см. push_road_incident_alerts ниже.
    'road_events': {'label': 'ПЕРЕКРЫТИЯ И КРУПНЫЕ ДТП', 'emoji': '⛔'},
    # По просьбе пользователя (20.09.2026): "сделай приветственное сообщение
    # утром каждый день в 9.00" - см. morning_greeting_checker ниже.
    'morning_greeting': {'label': 'УТРЕННЕЕ ПРИВЕТСТВИЕ 9:00', 'emoji': '☀️'},
}

def notifications_enabled(state, notif_key):
    """True, если пользователь не выключал явно этот тип пуша - отсутствие
    записи в notif_prefs (новый пользователь или пуш добавлен позже, чем
    пользователь в последний раз открывал настройки) трактуется как ON."""
    if not isinstance(state, dict):
        return True
    prefs = state.get('notif_prefs') or {}
    return prefs.get(notif_key, True)

# ==================== ОЧЕРЕДЬ У АЭРОПОРТА (гео) ====================
# Идея пользователя: водитель/курьер включает в Telegram трансляцию живой
# геопозиции, бот сам считает расстояние до ближайшего аэропорта
# (nearest_airport(), см. haversine_km) и присылает пуш за каждый уровень
# расстояния из AIRPORT_QUEUE_RADIUS_LEVELS_KM (по убыванию), а дальше
# "уже N минут рядом" на каждой отметке из AIRPORT_QUEUE_TIME_PUSHES_MIN
# - помогает не терять счёт времени в очереди на посадку у аэропорта. Любой
# из этих пушей можно заглушить на AIRPORT_QUEUE_SNOOZE_MINUTES кнопкой
# "📍 Ошибка GPS" (см. handle_airport_queue_snooze) - для водителя, который
# едет с заказом/не планирует вставать в очередь, ИЛИ у которого геолокация
# ошибочно показала близость к аэропорту (глушение GPS сигнала).
# Включается/выключается кнопкой "📍 ОЧЕРЕДЬ У АЭРОПОРТА" в Инструментах
# водителя (обычный toggle) - НЕ добавлена в NOTIFICATION_TYPES/notif_prefs,
# потому что сам факт включения трансляции уже и есть согласие на эти пуши;
# отдельная on/off настройка была бы избыточной.
# Состояние - НЕ отдельная таблица в БД, а user_state[uid]['airport_queue']
# (dict) и user_state[uid]['airport_queue_active'] (bool) - у user_state уже
# есть персистентность (см. PersistentUserDict выше), дублировать её в SQL
# нет смысла. См. process_airport_queue_ping/check_airport_queue_timers ниже
# (рядом с push_airport_status_change).
# ИЗМЕНЕНО 21.09.2026 (прямая просьба пользователя, уточнена в тот же день -
# "убери 3 км, оставь только 2/1/500м"): раньше было всего два уровня по
# расстоянию (3км/1.5км), затем ТРИ - 2км/1км/500м - чтобы водитель получал
# более частые и точные ориентиры по мере приближения к аэропорту. Список
# ОБЯЗАТЕЛЬНО по убыванию - код в process_airport_queue_ping идёт по нему
# по порядку и шлёт пуш за каждый
# впервые пройденный уровень.
AIRPORT_QUEUE_RADIUS_LEVELS_KM = [2.0, 1.0, 0.5]
# ИЗМЕНЕНО 22.09.2026 (прямая, жёсткая просьба пользователя - "радиус
# действия стояния в очереди 1 км во всех аэропортах, кроме Внуково - там
# 2 км"): внешний ("въехал в зону аэропорта") уровень из
# AIRPORT_QUEUE_RADIUS_LEVELS_KM[0] теперь берётся отсюда - во всех 12
# городах бота обычная зона 1 км; для Внуково (UUWW), единственного
# исключения из всех аэропортов, явно задано 2 км. см.
# airport_queue_outer_radius_km() ниже - process_airport_queue_ping
# использует именно её вместо AIRPORT_QUEUE_RADIUS_LEVELS_KM[0] для первого
# (самого внешнего) уровня, остальные уровни (1.0/0.5 км) не меняются - для
# всех аэропортов, кроме Внуково, внешний уровень (1 км) теперь совпадает
# со вторым уровнем AIRPORT_QUEUE_RADIUS_LEVELS_KM[1] (тоже 1 км), поэтому
# фактически остаётся два различимых уровня - 1 км/500 м (см. levels_km в
# process_airport_queue_ping - совпадающий уровень просто схлопывается).
AIRPORT_QUEUE_OUTER_RADIUS_DEFAULT_KM = 1.0
AIRPORT_QUEUE_OUTER_RADIUS_OVERRIDES_KM = {
    'UUWW': 2.0,  # VKO (Внуково) - единственное исключение, прямая просьба пользователя
}

def airport_queue_outer_radius_km(icao):
    """Радиус "зоны аэропорта" для самого внешнего уровня гео-пушей очереди
    (см. AIRPORT_QUEUE_OUTER_RADIUS_DEFAULT_KM/_OVERRIDES_KM выше) - 1 км
    для всех аэропортов, кроме Внуково (2 км, прямая просьба пользователя,
    22.09.2026)."""
    return AIRPORT_QUEUE_OUTER_RADIUS_OVERRIDES_KM.get(icao, AIRPORT_QUEUE_OUTER_RADIUS_DEFAULT_KM)
# Пользователь также попросил убрать пуш "уже 1 час рядом" и пуш "уже 15
# минут рядом" (последнего на самом деле и не было - только 30/60), оставив
# ТОЛЬКО "уже 30 минут рядом" - это финальное ненавязчивое напоминание,
# после которого новых пушей по времени больше не будет (пока не сменится
# аэропорт/зона или не начнётся новый заход в радиус).
AIRPORT_QUEUE_TIME_PUSHES_MIN = (30,)  # "уже 30 минут рядом"
# ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя), ПЕРЕИМЕНОВАНО
# 21.09.2026 в "📍 Ошибка GPS" (та же кнопка/callback aqsnooze_, тот же
# эффект - водитель едет с заказом/не планирует вставать в очередь, либо
# GPS ошибочно показал близость к аэропорту из-за глушения сигнала в РФ).
# Снимает ВСЕ пуши очереди (по расстоянию и по времени) для этого
# аэропорта на AIRPORT_QUEUE_SNOOZE_MINUTES минут - см.
# process_airport_queue_ping/check_airport_queue_timers ('is_snoozed') и
# handle_airport_queue_snooze.
#
# ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - у Шереметьево GPS в
# зоне глушения "скачет" между терминалами B/C/D по несколько раз за
# минуту, из-за чего snooze раньше НЕ работал как надо): раньше snooze
# хранился ВНУТРИ user_state[uid]['airport_queue'] (aq), который целиком
# пересоздаётся при смене (icao, zone_key) - то есть каждый скачок GPS
# между зонами B/C/D считался "новым заходом" и обнулял/обходил snooze,
# и кнопка "Ошибка GPS", нажатая на пуше про зону B, не действовала на
# зону D. Теперь snooze хранится ОТДЕЛЬНО, per-АЭРОПОРТ (не per-зона) - в
# user_state[uid]['airport_queue_snooze'][icao] - переживает смену зоны
# внутри того же аэропорта и одним нажатием глушит пуши по ВСЕМ его
# зонам сразу. См. get_airport_queue_snoozed_until/set_airport_queue_snooze
# ниже.
AIRPORT_QUEUE_SNOOZE_MINUTES = 15
# Как часто (минуты) фоновый чекер досылает пуши по времени - пуши по
# расстоянию (AIRPORT_QUEUE_RADIUS_LEVELS_KM) шлются сразу по факту нового
# пинга геопозиции, а этот идёт по прошедшему времени, поэтому нужен
# отдельный фоновый прогон (см. airport_queue_checker) - иначе он бы не
# пришёл, если юзер просто стоит на месте и новых пингов долго нет.
AIRPORT_QUEUE_CHECK_INTERVAL_MINUTES = 5
# Инструкция рекомендует делиться геопозицией «Пока не отключу» (бессрочно) -
# так трансляция не обрывается сама, водителю не нужно вспоминать её включить
# заново каждые несколько часов. У такого режима Telegram шлёт live_period =
# 0x7FFFFFFF (условная "бесконечность"), поэтому ориентироваться на live_period
# при определении "трансляция скорее всего закончилась" больше нельзя - вместо
# этого просто следим за тем, сколько времени НЕТ новых пингов геопозиции:
# дольше AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES без единого обновления - считаем,
# что трансляция прервалась (юзер сам отключил, разрядился телефон и т.п.), и
# шлём напоминание включить её заново (см. send_airport_queue_expired_push).
AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES = 30

# ==================== ПАРКОВКА (гео, "стоишь на месте?") ====================
# Идея пользователя: пока у водителя активна смена (is_shift_active) и идёт
# трансляция живой геопозиции (та же трансляция, что и у "Очередь у
# аэропорта" - см. process_airport_queue_ping/_location_tracking_active
# выше), если он не двигается достаточно долго - скорее всего встал на
# парковку в ожидании заказа - предложить оплатить платную парковку (кнопка
# со ссылкой на приложение оплаты, см. PARKING_APP_LINKS) или отметить, что
# парковка бесплатная (кнопка "🅿️ Стою на бесплатной парковке" глушит
# напоминание, пока водитель не поедет дальше). Состояние - НЕ отдельная
# таблица в БД, а user_state[uid]['parking'] (dict), по аналогии с
# user_state[uid]['airport_queue']. См. process_parking_ping/
# send_parking_push/handle_parking_free_ack ниже (рядом с
# process_airport_queue_ping).
#
# На сколько метров нужно СМЕСТИТЬСЯ от "якорной" точки, чтобы считать
# водителя снова двигающимся (и сбросить отсчёт времени стоянки) - разумная
# середина между шумом GPS в городе (обычно единицы-десятки метров) и
# реальным перемещением на соседнее парковочное место/через дорогу.
PARKING_MOVEMENT_THRESHOLD_METERS = 40
# Сколько минут подряд без смещения больше PARKING_MOVEMENT_THRESHOLD_METERS
# считаем "стоит на месте, похоже, припарковался" - после этого шлём пуш
# (один раз за этот заход стоянки, см. process_parking_ping).
PARKING_STATIONARY_MINUTES = 2.5
# Радиус "в черте города" вокруг центра города (см. RAIN_CITY_COORDS) для
# фичи парковки - НЕ переиспользуем никакой из радиусов "Очереди у
# аэропорта" (AIRPORT_QUEUE_*), это независимая зона: город целиком, а не
# конкретная точка аэропорта. За пределами города (кроме зон аэропортов, см.
# nearest_airport_zone) напоминание не шлём - там платных городских парковок
# нет. 30 км - с запасом покрывает сам город и ближайшие пригороды, где ещё
# действуют городские платные парковки.
PARKING_CITY_RADIUS_KM = 30
# Зона аэропорта для пуша о платной парковке (см. _in_parking_zone). ИЗМЕНЕНО
# 21.09.2026 по просьбе пользователя: пуш о платной парковке не должен
# приходить внутри радиуса, где уже работает отдельный пуш "Встать в
# очередь" (airport_queue_outer_radius_km) - иначе водитель получает два
# конфликтующих пуша про одну и ту же точку. Поэтому зона аэропорта для
# парковки теперь - "бублик" от airport_queue_outer_radius_km(icao) (не
# включая) до PARKING_AIRPORT_ZONE_RADIUS_KM: ближе к терминалу зона занята
# фичей "Очередь", дальше (но всё ещё в районе аэропорта) может сработать
# пуш о платной парковке.
PARKING_AIRPORT_ZONE_RADIUS_KM = 8
# После "🅿️ Стою на бесплатной парковке" пуш не глушится навсегда - через
# столько минут (если водитель так и не поехал дальше) спрашиваем снова
# (вдруг парковка на самом деле стала платной/сменилась зона и т.п.), по
# просьбе пользователя.
PARKING_FREE_ACK_RECHECK_MINUTES = 15
# Ссылки на приложения для оплаты городских парковок, по городам и
# платформам (iOS/Android). Если для города+платформы своей ссылки нет -
# используется общий фолбэк PARKING_APP_LINK_FALLBACK ниже (одно
# приложение "Парковки России" покрывает все города, поэтому по
# умолчанию везде одна и та же ссылка и на iOS, и на Android).
PARKING_APP_LINKS = {
    # 'moscow': {'ios': 'https://...', 'android': 'https://...'},
}
