# user_state раньше жил только в памяти процесса - при каждом рестарте/редеплое
# (то есть при каждом git push) состояние ВСЕХ водителей обнулялось, и им
# приходилось заново жать /start. При росте числа водителей (сотни-тысяча)
# это уже реальная проблема, а не мелочь. Решение: user_state[user_id] и
# вложенные в него ключи автоматически сохраняются в SQLite при любом
# изменении - а при старте бота состояние подгружается обратно. Весь
# остальной код бота работает с user_state как с обычным dict, ничего в нём
# менять не пришлось - персистентность спрятана внутри этих двух классов.

# ИЗМЕНЕНО 21.09.2026 (готовим бота к нагрузке ~1000 пользователей) -
# раньше PersistentUserDict.__setitem__ синхронно открывал соединение к
# SQLite и коммитил на КАЖДОЕ изменение ключа состояния (а это происходит
# буквально на каждый клик/переход по меню у каждого пользователя). Бот
# однопроцессный (один event loop на всех), и эта синхронная запись
# блокировала обработку ВСЕХ остальных пользователей на время своего
# выполнения - при малом числе водителей незаметно, но при сотнях
# одновременных стало бы узким местом. Теперь запись "write-behind":
# __setitem__/__delitem__/pop только помечают пользователя "грязным"
# (быстрая операция в памяти, без I/O), а фоновая задача
# user_state_flusher() ниже раз в USER_STATE_FLUSH_INTERVAL_SECONDS
# сбрасывает изменившихся пользователей в БД через asyncio.to_thread (не
# блокирует event loop). in-memory user_state остаётся источником правды
# для ЧТЕНИЯ - поведение бота не меняется, меняется только момент записи
# в БД. Цена - при аварийном падении процесса (не при штатном
# рестарте/редеплое, там флаш вызывается явно в finally у main(), см.
# ниже) можно потерять последние доли секунды изменений состояния
# (курсор в меню, а не заказы/данные) - приемлемый компромисс.
USER_STATE_FLUSH_INTERVAL_SECONDS = 1.0
_dirty_user_ids = set()

def _mark_user_state_dirty(user_id):
    _dirty_user_ids.add(user_id)

class PersistentUserDict(dict):
    """Состояние ОДНОГО пользователя. Любое изменение ключа (set/del/pop)
    помечает пользователя "грязным" для фонового флаша (см. комментарий
    выше про write-behind) - раньше сразу писало в БД синхронно."""
    def __init__(self, user_id, *args, **kwargs):
        self._user_id = user_id
        super().__init__(*args, **kwargs)

    def __setitem__(self, key, value):
        super().__setitem__(key, value)
        _mark_user_state_dirty(self._user_id)

    def __delitem__(self, key):
        super().__delitem__(key)
        _mark_user_state_dirty(self._user_id)

    def pop(self, key, *default):
        result = super().pop(key, *default)
        _mark_user_state_dirty(self._user_id)
        return result

class PersistentUserStateStore(dict):
    """user_state целиком. user_state[user_id] = {...} оборачивает значение в
    PersistentUserDict и помечает пользователя "грязным" (новый пользователь
    появляется редко по сравнению с изменением полей, но ради единообразия
    тоже идёт через write-behind - задержка в ~1с на первую запись
    некритична); user_state.pop(user_id) удаляет запись из БД сразу (это
    редкая операция, не хот-пас, синхронность тут не мешает)."""
    def __setitem__(self, user_id, value):
        if not isinstance(value, PersistentUserDict):
            value = PersistentUserDict(user_id, value)
        super().__setitem__(user_id, value)
        _mark_user_state_dirty(user_id)

    def pop(self, user_id, *default):
        result = super().pop(user_id, *default)
        _dirty_user_ids.discard(user_id)
        delete_user_state(user_id)
        return result

def save_user_state(user_id, state_dict):
    """Синхронная версия (принимает dict, сама делает json.dumps) - используй
    только когда сериализация точно происходит на основном потоке (сейчас
    нигде в горячем пути не вызывается напрямую). Для write-behind флаша
    см. save_user_state_json ниже - там сериализация сделана ДО ухода в
    отдельный поток, а не внутри него."""
    save_user_state_json(user_id, json.dumps(state_dict, ensure_ascii=False))

def save_user_state_json(user_id, state_json):
    """Пишет уже готовую JSON-строку в БД. Используется
    flush_dirty_user_states() - json.dumps() там делается СИНХРОННО на
    основном потоке (быстрая операция для словаря одного пользователя, не
    блокирует event loop ощутимо), а не здесь в фоновом потоке
    asyncio.to_thread. Причина: некоторые места кода мутируют вложенные
    структуры user_state НА МЕСТЕ (например queue_multi_progress -
    progress['results'][key] = ... без пересоздания словаря) - если бы
    json.dumps() выполнялся в отдельном потоке параллельно с основным event
    loop, такая мутация ровно в момент сериализации теоретически могла бы
    поймать "dictionary changed size during iteration" в json-энкодере.
    Сериализация на основном потоке (где no other coroutine не может
    вклиниться между строк без await) убирает этот риск полностью - в
    отдельном потоке остаётся только собственно диск-bound запись в SQLite."""
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO user_states (user_id, state_json, updated_at) VALUES (?, ?, ?) '
            'ON CONFLICT(user_id) DO UPDATE SET state_json = excluded.state_json, updated_at = excluded.updated_at',
            (user_id, state_json, datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'))
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить состояние пользователя {user_id}: {e}")

def delete_user_state(user_id):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute('DELETE FROM user_states WHERE user_id = ?', (user_id,))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось удалить состояние пользователя {user_id}: {e}")

async def flush_dirty_user_states():
    """Сбрасывает в БД всех пользователей, помеченных "грязными" с прошлого
    флаша (см. write-behind комментарий у PersistentUserDict выше). Берём
    АКТУАЛЬНОЕ in-memory состояние на момент флаша (а не то, что было в
    момент пометки) - если после пометки пришли ещё изменения, они попадут
    в эту же запись, лишний флаш не нужен. Если что-то поменяется уже ПОКА
    идёт asyncio.to_thread ниже - пользователь просто останется/попадёт
    обратно в _dirty_user_ids и будет сохранён на следующем цикле.
    json.dumps() делаем ЗДЕСЬ, на основном потоке (см. docstring
    save_user_state_json про причину) - в отдельный поток уходит только
    сама запись в SQLite."""
    if not _dirty_user_ids:
        return
    to_flush = list(_dirty_user_ids)
    _dirty_user_ids.difference_update(to_flush)
    for user_id in to_flush:
        state = user_state.get(user_id)
        if state is None:
            continue
        try:
            state_json = json.dumps(dict(state), ensure_ascii=False)
            await asyncio.to_thread(save_user_state_json, user_id, state_json)
        except Exception as e:
            logger.error(f"❌ Не удалось сохранить состояние пользователя {user_id} (фоновый флаш): {e}")
            _dirty_user_ids.add(user_id)  # попробуем ещё раз на следующем цикле

async def user_state_flusher():
    """Фоновая задача - раз в USER_STATE_FLUSH_INTERVAL_SECONDS сбрасывает
    накопившихся "грязных" пользователей в БД (см. write-behind комментарий
    у PersistentUserDict выше)."""
    while True:
        await asyncio.sleep(USER_STATE_FLUSH_INTERVAL_SECONDS)
        try:
            await flush_dirty_user_states()
        except Exception as e:
            logger.error(f"❌ Ошибка фонового флаша user_state: {e}")

def load_all_user_states():
    """Восстанавливает user_state из БД при старте бота - без этого все
    водители слетали бы на выбор города после каждого редеплоя."""
    try:
        init_db()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT user_id, state_json FROM user_states')
        rows = cursor.fetchall()
        conn.close()
        restored = 0
        for user_id, state_json in rows:
            try:
                data = json.loads(state_json)
                # dict.__setitem__ напрямую - в обход персистентности, иначе
                # мы бы тут же переписали в БД то, что только что из неё прочитали
                dict.__setitem__(user_state, user_id, PersistentUserDict(user_id, data))
                restored += 1
            except Exception:
                continue
        logger.info(f"✅ Восстановлено состояние {restored} пользователей из БД")
    except Exception as e:
        logger.error(f"❌ Не удалось восстановить состояния пользователей: {e}")

# ИСПРАВЛЕНО 21.09.2026 (баг найден пользователем - после каждого редеплоя
# на Railway бот перезапускается, а очередь "последних 2 сообщений"
# (_recent_bot_message_ids, см. SingleMessageMiddleware ниже) раньше жила
# ТОЛЬКО в памяти процесса - после рестарта она обнулялась, и все старые
# сообщения, отправленные ДО рестарта, переставали быть кому-либо известны
# и никогда не удалялись, из-за чего в чате копилась куча сообщений вместо
# 2. Теперь очередь дублируется в БД (recent_bot_messages, см. init_db) при
# каждом изменении и восстанавливается при старте - аналогично user_states/
# load_all_user_states выше.
def save_recent_bot_message(chat_id, message_id):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute('INSERT INTO recent_bot_messages (chat_id, message_id) VALUES (?, ?)', (chat_id, message_id))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить id сообщения в очередь чата {chat_id}: {e}")

def delete_recent_bot_message_row(chat_id, message_id):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute('DELETE FROM recent_bot_messages WHERE chat_id = ? AND message_id = ?', (chat_id, message_id))
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось убрать id сообщения из очереди чата {chat_id}: {e}")

def load_all_recent_bot_messages():
    """Восстанавливает _recent_bot_message_ids из БД при старте бота - без
    этого после каждого редеплоя старые сообщения, отправленные в прошлых
    запусках, навсегда "зависали" бы в чатах (см. комментарий выше)."""
    try:
        init_db()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT chat_id, message_id FROM recent_bot_messages ORDER BY id ASC')
        rows = cursor.fetchall()
        conn.close()
        for chat_id, message_id in rows:
            _recent_bot_message_ids.setdefault(chat_id, []).append(message_id)
        logger.info(f"✅ Восстановлена очередь последних сообщений для {len(_recent_bot_message_ids)} чатов из БД")
    except Exception as e:
        logger.error(f"❌ Не удалось восстановить очередь последних сообщений: {e}")

# ДОБАВЛЕНО 22.09.2026 (см. комментарий у CREATE TABLE last_reply_keyboard_messages
# в init_db) - персистентность для _last_reply_keyboard_msg_id, той же
# схемой, что recent_bot_messages выше (save/load переживают рестарт
# Railway). По одной строке на чат - INSERT ... ON CONFLICT UPDATE, старое
# значение просто перезаписывается новым (нам нужен только последний id).
def save_last_reply_keyboard_message(chat_id, message_id):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO last_reply_keyboard_messages (chat_id, message_id, updated_at) VALUES (?, ?, CURRENT_TIMESTAMP) '
            'ON CONFLICT(chat_id) DO UPDATE SET message_id=excluded.message_id, updated_at=excluded.updated_at',
            (chat_id, message_id)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить последнее menu-сообщение чата {chat_id}: {e}")

def load_all_last_reply_keyboard_messages():
    """Восстанавливает _last_reply_keyboard_msg_id (и _last_reply_keyboard_sent_at
    - см. комментарий у REPLY_KEYBOARD_STALE_HOURS выше по файлу) из БД при
    старте - без этого после каждого редеплоя сообщение с меню, отправленное
    в прошлом запуске, никогда бы не удалялось следующим таким сообщением
    (см. комментарий у CREATE TABLE last_reply_keyboard_messages в init_db)."""
    try:
        init_db()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT chat_id, message_id, updated_at FROM last_reply_keyboard_messages')
        rows = cursor.fetchall()
        conn.close()
        for chat_id, message_id, updated_at in rows:
            _last_reply_keyboard_msg_id[chat_id] = message_id
            try:
                _last_reply_keyboard_sent_at[chat_id] = datetime.strptime(updated_at, '%Y-%m-%d %H:%M:%S')
            except Exception:
                pass  # старая строка без парсибельного updated_at - просто не заполняем TTL, кнопка-подстраховка появится раньше срока, не страшно
        logger.info(f"✅ Восстановлены последние menu-сообщения для {len(rows)} чатов из БД")
    except Exception as e:
        logger.error(f"❌ Не удалось восстановить последние menu-сообщения: {e}")

user_state = PersistentUserStateStore()

_flights_data_cache = None
_flights_data_mtime = None

# ИСПРАВЛЕНО 20.09.2026 (жалоба - "надо чтобы бот давал последние загруженные
# данные, а не нули, даже если Yandex заблокировал ключ"): fetch_yandex_data.py
# уже старается не затирать flights_data.json нулями при сбое ОДНОГО запуска
# (см. previous_result в fetch_yandex_data.py), но это не спасает первый
# прогон после переезда на новый /data volume (там ещё нет старого файла,
# затирать нечем) и любой другой случай, когда в файле УЖЕ оказались нули
# (как случилось 20.09.2026 из-за блокировки ключа Яндексом на 501/500
# запросов). Поэтому здесь, на стороне бота (а не сборщика данных), держим
# ОТДЕЛЬНЫЙ файл на постоянном volume с последним НЕПУСТЫМ списком прилётов
# по каждому аэропорту - и если свежий flights_data.json вдруг говорит "0
# рейсов" для аэропорта, который не закрыт, подставляем сюда этот последний
# хороший снепшот вместо нулей (с пометкой stale=True, чтобы при желании
# можно было показать водителю "данные могут быть не совсем свежие").
LAST_GOOD_FLIGHTS_FILE = os.path.join(DATA_DIR, 'last_good_flights.json')


def _load_last_good_flights():
    try:
        with open(LAST_GOOD_FLIGHTS_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception:
        return {}


def _save_last_good_flights(snapshot):
    try:
        with open(LAST_GOOD_FLIGHTS_FILE, 'w', encoding='utf-8') as f:
            json.dump(snapshot, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить {LAST_GOOD_FLIGHTS_FILE}: {e}")


def _apply_last_good_flights_fallback(data):
    """Мутирует data['airports'][icao]['arrivals'] на месте: если пусто и
    аэропорт не закрыт - подставляет последний непустой снепшот. Обновляет
    и сам снепшот на диске, когда встречает свежие непустые данные."""
    if not data or 'airports' not in data:
        return data

    last_good = _load_last_good_flights()
    changed = False

    for icao, airport_info in data.get('airports', {}).items():
        if airport_info.get('closed'):
            continue
        arrivals = airport_info.get('arrivals') or []
        if arrivals:
            # Свежие данные реально есть - запоминаем их как новый "последний хороший" снепшот
            last_good[icao] = {
                'arrivals': arrivals,
                'saved_at': data.get('generated_at'),
            }
            changed = True
        else:
            # Пусто в свежем файле - если есть сохранённый непустой снепшот, подставляем его
            fallback = last_good.get(icao)
            if fallback and fallback.get('arrivals'):
                airport_info['arrivals'] = fallback['arrivals']
                airport_info['stale'] = True
                airport_info['stale_since'] = fallback.get('saved_at')
                logger.warning(
                    f"⚠️ {icao}: свежие данные пустые (0 прилётов) - подставляю последний "
                    f"непустой снепшот от {fallback.get('saved_at', '?')} ({len(fallback['arrivals'])} рейсов)"
                )
            else:
                # ДОБАВЛЕНО 21.09.2026 (диагностика бага "весь день 0% по
                # всем аэропортам, хотя должен был сработать fallback") -
                # раньше в этом случае просто молчали, из-за чего было
                # невозможно понять по логам, ПОЧЕМУ fallback не сработал:
                # то ли last_good_flights.json пуст/отсутствует, то ли в
                # нём просто нет записи для конкретно этого icao (например,
                # Yandex ни разу за всё время работы бота не прислал по
                # нему непустой ответ). Теперь явно логируем оба случая.
                if not last_good:
                    logger.warning(
                        f"⚠️ {icao}: свежие данные пустые (0 прилётов), fallback НЕ применён - "
                        f"last_good_flights.json пуст или отсутствует на диске ({LAST_GOOD_FLIGHTS_FILE})"
                    )
                else:
                    logger.warning(
                        f"⚠️ {icao}: свежие данные пустые (0 прилётов), fallback НЕ применён - "
                        f"для этого аэропорта ещё ни разу не сохранялся непустой снепшот "
                        f"(в last_good_flights.json сейчас {len(last_good)} других аэропортов: "
                        f"{sorted(last_good.keys())})"
                    )

    if changed:
        _save_last_good_flights(last_good)

    return data


def load_flights_data():
    """Загружает flights_data.json (генерируется fetch_yandex_data.py локально).
    Кэширует в памяти, перечитывает только если файл изменился на диске.
    Подставляет последний непустой снепшот вместо нулей, если свежие данные
    для какого-то аэропорта пустые (см. _apply_last_good_flights_fallback)."""
    global _flights_data_cache, _flights_data_mtime
    try:
        mtime = os.path.getmtime(FLIGHTS_DATA_FILE)
        if _flights_data_cache is not None and mtime == _flights_data_mtime:
            return _flights_data_cache

        with open(FLIGHTS_DATA_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)

        generated_at = datetime.fromisoformat(data['generated_at'])
        age_hours = (datetime.now() - generated_at).total_seconds() / 3600
        if age_hours > FLIGHTS_DATA_MAX_AGE_HOURS:
            logger.warning(f"⚠️ flights_data.json устарел ({age_hours:.1f}ч), но всё равно используем")

        data = _apply_last_good_flights_fallback(data)

        _flights_data_cache = data
        _flights_data_mtime = mtime
        return data
    except FileNotFoundError:
        logger.warning("⚠️ flights_data.json не найден - запусти fetch_yandex_data.py локально. Использую запасные данные.")
        return None
    except Exception as e:
        logger.error(f"❌ Ошибка чтения flights_data.json: {e}")
        return None

