# По просьбе пользователя: и Такси, и Ultima теперь видят ВСЕ прибывающие
# поезда дальнего следования (пригородные электрички не собираются вообще -
# см. fetch_trains_data.py, transport_types=train). Раньше Ultima видела
# только Сапсаны - теперь вместо фильтрации по категории Ultima просто
# ПОДСВЕЧИВАЕТСЯ акцент на Сапсанах и фирменных/премиальных поездах (см.
# is_sapsan/is_firmenny в fetch_trains_data.py и сортировку/пометки в
# show_train_station_arrivals ниже), а не скрывает остальные поезда.
def get_trains_for_station(station_code, category):
    data = load_trains_data()
    if not data:
        return None, None
    station = data.get('stations', {}).get(station_code)
    if not station:
        return None, None
    return station['name'], station.get('arrivals', [])

def _minutes_in_period(train_minutes, period_start_minutes, period_length, day_minutes=24 * 60):
    """train_minutes/period_start_minutes - минуты от полуночи (0-1439).
    Обрабатывает переход через полночь (период может начинаться в 23:45 и
    заканчиваться в 00:15 следующих суток) - без этого последние периоды
    прогноза перед полуночью теряли бы поезда, приходящиеся на начало
    следующих суток."""
    period_end_minutes = period_start_minutes + period_length
    if period_end_minutes <= day_minutes:
        return period_start_minutes <= train_minutes < period_end_minutes
    return train_minutes >= period_start_minutes or train_minutes < (period_end_minutes - day_minutes)

def compute_current_train_period_load(station_code, category, period_offset=0):
    """Загрузка вокзала на ЗАДАННЫЙ TRAIN_FORECAST_PERIOD_MINUTES-минутный
    период (по умолчанию текущий получас, округлённый вниз, МСК) - по той же
    логике, что compute_current_hour_load для аэропортов: сумма оценки
    пассажиров прибывающих в этот период поездов / (часовая ёмкость,
    пропорционально урезанная под длину периода) * 100. Раньше период был
    целый час (см. историю) - уменьшен до получаса по просьбе пользователя,
    поэтому емкость STATION_CAPACITY (задана как пас/ЧАС) тоже делим
    пропорционально - иначе один и тот же поезд в получасовом окне давал бы
    вдвое заниженный % по сравнению со старой часовой версией. Пассажиры
    считаются по СЕРЕДИНЕ диапазона оценки (passengers_min/max), как
    единственно разумный способ свести диапазон к одному числу."""
    _, arrivals = get_trains_for_station(station_code, category)
    arrivals = arrivals or []
    now = datetime.now(ZoneInfo('Europe/Moscow'))
    now_minutes = now.hour * 60 + (now.minute // TRAIN_FORECAST_PERIOD_MINUTES) * TRAIN_FORECAST_PERIOD_MINUTES
    period_start_minutes = (now_minutes + TRAIN_FORECAST_PERIOD_MINUTES * period_offset) % (24 * 60)

    def _train_minutes(t):
        h, m = t['time'].split(':')
        return int(h) * 60 + int(m)

    trains_in_period = [
        t for t in arrivals
        if _minutes_in_period(_train_minutes(t), period_start_minutes, TRAIN_FORECAST_PERIOD_MINUTES)
    ]
    total_passengers = sum((t['passengers_min'] + t['passengers_max']) / 2 for t in trains_in_period)
    hourly_capacity = STATION_CAPACITY.get(station_code, 1000)
    period_capacity = hourly_capacity * (TRAIN_FORECAST_PERIOD_MINUTES / 60)
    load = (total_passengers / period_capacity) * 100 if total_passengers > 0 else 0
    return load, trains_in_period, period_start_minutes

# Такси эконом/комфорт и Ultima видят одну и ту же афишу TimePad без разбора
# по классу - событие уже прошло фильтр по масштабу (tickets_total>=200) на
# этапе сбора данных, см. fetch_timepad_data.py. Курьер/Грузовое такси эту
# кнопку вообще не видят (см. CATEGORIES_WITHOUT_EVENTS ниже).
CATEGORIES_WITHOUT_EVENTS = {'courier', 'cargo'}

def get_events_for_user(city, category, limit=10):
    """Ближайшие события города под класс водителя. Источник - ТОЛЬКО TimePad
    (см. fetch_timepad_data.py) - KudaGo убран по просьбе пользователя (кнопка
    "Поехали" по координатам открывала именно приложение Яндекс.Навигатор
    вместо карт/браузера на части телефонов, и события были не нужны).
    Возвращает (events, city_supported) - city_supported=False значит
    TimePad вообще не покрывает этот город (нужно отдельное сообщение "нет
    данных", а не пустой список - это разные вещи)."""
    if city not in fetch_timepad_data.TIMEPAD_CITY_MAP:
        return [], False

    now_ts = datetime.now(ZoneInfo('UTC')).timestamp()
    data = load_timepad_data()
    city_events = (data or {}).get('cities', {}).get(city, [])
    # fetch_timepad_data.py уже отфильтровал по категориям и
    # tickets_total>=200 на стороне сбора данных - здесь только актуальность
    # по времени (адрес и масштаб уже гарантированы).
    upcoming = [e for e in city_events if e.get('start', 0) >= now_ts]
    upcoming.sort(key=lambda e: e['start'])
    return upcoming[:limit], True

# Часовой пояс городов афиши (используется только для событий - не путать с
# AIRPORT_TIMEZONE, который привязан к конкретным аэропортам). Дополнено
# 22.09.2026 городами с концертными Telegram-каналами (см.
# CONCERT_EVENTS_CHANNELS в fetch_concert_events.py) - остальные города пока
# без событий, оставлены на будущее расширение покрытия.
EVENT_CITY_TIMEZONE = {
    'moscow': 'Europe/Moscow',
    'spb': 'Europe/Moscow',
    'ekb': 'Asia/Yekaterinburg',
    'kazan': 'Europe/Moscow',
    'samara': 'Europe/Samara',
    'chelyabinsk': 'Asia/Yekaterinburg',
    'krasnodar': 'Europe/Moscow',
    'sochi': 'Europe/Moscow',
}

def format_event_datetime(event, city):
    """Диапазон начала-конца мероприятия в часовом поясе города - водителю
    важно понимать не только когда началось, но и когда примерно закончится
    (именно момент разъезда даёт всплеск спроса у площадки). Если TimePad не
    знает точную длительность - end==start, и показываем только начало, без
    диапазона."""
    tz = ZoneInfo(EVENT_CITY_TIMEZONE.get(city, 'Europe/Moscow'))
    start_dt = datetime.fromtimestamp(event['start'], tz)
    end_ts = event.get('end') or event['start']
    if end_ts <= event['start']:
        return start_dt.strftime('%d.%m, %H:%M')
    end_dt = datetime.fromtimestamp(end_ts, tz)
    if start_dt.date() == end_dt.date():
        return f"{start_dt.strftime('%d.%m, %H:%M')}–{end_dt.strftime('%H:%M')}"
    return f"{start_dt.strftime('%d.%m %H:%M')} – {end_dt.strftime('%d.%m %H:%M')}"

def estimate_attendance(event):
    """Возвращает (мин, макс) числа посетителей. TimePad-события всегда
    несут РЕАЛЬНОЕ число билетов (tickets_total) - оно уже прошло порог
    TIMEPAD_MIN_TICKETS на этапе сбора данных (см. fetch_timepad_data.py),
    так что отдельная догадка по ключевым словам в названии площадки не
    нужна. Диапазон 0.7x-1.0x от tickets_total проще подать водителю, чем
    точную цифру, и не выглядит как гарантия явки именно этого числа людей."""
    tickets_total = event.get('tickets_total') or 0
    return int(tickets_total * 0.7), int(tickets_total)

def build_event_message(event, city):
    """Текст + инлайн-кнопки для ОДНОГО события TimePad. "🚗 ПОЕХАЛИ": у
    TimePad нет координат площадки вообще (только текстовый адрес) - кнопка
    ведёт на ссылку-ПОИСК по адресу https://yandex.ru/maps/?text=<адрес>
    (Яндекс.Карты сами геокодируют текст), а НЕ на схему yandexnavi://
    build_route_on_map: у неё нет веб-фолбэка вообще (если у водителя не
    установлен именно Яндекс.Навигатор - кнопка молча ничего не сделает), а
    обычная https-ссылка на Яндекс.Карты открывается всегда - в приложении
    Карт/Навигатора, если оно установлено и ассоциировано с доменом, и в
    браузере в любом случае, если нет. "🔗 ПОДРОБНЕЕ" - страница события на TimePad."""
    date_str = format_event_datetime(event, city)
    lo, hi = estimate_attendance(event)
    lines = [f"🎫 *{event['title']}*"]
    address = event.get('place_address')
    if address:
        lines.append(f"📍 {address}")
    lines.append(f"👥 ~{lo}–{hi} чел.")
    lines.append(f"🗓 {date_str}")
    # Цену билета не показываем - водителям она не нужна.
    text = '\n'.join(lines)

    buttons = []
    if address:
        from urllib.parse import quote
        buttons.append(InlineKeyboardButton(text="🚗 ПОЕХАЛИ", url=f"https://yandex.ru/maps/?text={quote(address)}"))
    if event.get('url'):
        buttons.append(InlineKeyboardButton(text="🔗 ПОДРОБНЕЕ", url=event['url']))
    keyboard = InlineKeyboardMarkup(inline_keyboard=[buttons]) if buttons else None
    return text, keyboard

# Аэропорты, закрытые для гражданских полётов постоянно (не зависит от
# уведомлений Росавиации, которые могут вообще не упоминать их) - Платов
# (Ростов). Статус для них всегда "закрыт", данные по ним не собираются
# (см. fetch_yandex_data.py) и не запрашиваются.
PERMANENTLY_CLOSED_AIRPORTS = {'URRP'}

def get_airport_status(icao):
    """Статус аэропорта по последнему уведомлению Росавиации за 12ч:
    'closed' (ВВЕДЕНЫ ограничения), 'coordinated' (работает по согласованию),
    'open' (СНЯТЫ ограничения), или 'open' по умолчанию, если уведомлений нет
    вообще (не значит 100% гарантию - просто нет свежих данных об ограничениях)."""
    if icao in PERMANENTLY_CLOSED_AIRPORTS:
        return 'closed', None
    notices = get_notices_for_airport(icao)
    if not notices:
        return 'open', None
    latest = notices[0]  # notices уже отсортированы по времени, свежие первые
    text_upper = latest['text'].upper()
    if 'ПО СОГЛАСОВАНИЮ' in text_upper:
        return 'coordinated', latest
    if 'СНЯТ' in text_upper:
        return 'open', latest
    if 'ВВЕДЕН' in text_upper:
        return 'closed', latest
    return 'open', latest

AIRPORT_STATUS_DISPLAY = {
    'open': ('🟢', 'ОТКРЫТ'),
    'coordinated': ('🟡', 'РАБОТАЕТ ПО СОГЛАСОВАНИЮ'),
    'closed': ('🔴', 'ЗАКРЫТ (ограничения)'),
}

# Кадры анимации "загрузки" для show_loading_animation ниже - по просьбе
# пользователя (22.09.2026, "поработать над визуалом... строки состояния
# загрузки"), везде, где есть заметная задержка перед ответом (сетевой запрос
# к внешнему API, подсчёт нескольких кандидатов и т.п.), вместо статичного
# "⏳ Загружаю..." показываем бегущие точки - несколько edit_text подряд с
# небольшой паузой, создающие ощущение живого процесса, а не зависшего бота.
LOADING_ANIMATION_FRAMES = ["", ".", "..", "..."]
LOADING_ANIMATION_FRAME_DELAY = 0.35

async def show_loading_animation(message_sender, label):
    """Отправляет ПЕРВЫЙ кадр анимации загрузки (label + "") и возвращает
    отправленное сообщение - вызывающий код затем должен вызвать
    animate_loading(msg, label) ПАРАЛЛЕЛЬНО с реальной работой (через
    asyncio.create_task), либо просто использовать возвращённое сообщение и
    вызвать .edit_text() на нём по готовности результата (анимация тогда не
    доигрывает до конца, а сразу сменяется финальным текстом - это ожидаемо
    и нормально, не ошибка). message_sender - bound-метод answer у
    message/callback_query.message, чтобы функция была универсальной для
    обоих контекстов вызова."""
    return await message_sender(f"{label}{LOADING_ANIMATION_FRAMES[0]}")

async def animate_loading(msg, label, cycles=2):
    """Проигрывает бегущие точки на уже отправленном сообщении msg -
    cycles повторов по 4 кадра. Вызывается как фоновая asyncio.create_task
    ПАРАЛЛЕЛЬНО с реальной сетевой работой (а не await до неё - иначе
    анимация просто отыграет и застынет, не давая никакого ощущения
    "живого" процесса на время самого долгого ожидания). Молча проглатывает
    ошибки редактирования (сообщение могло быть уже заменено финальным
    текстом реальным ответом раньше, чем анимация успела доиграть - гонка
    состояний здесь ожидаема и не является багом)."""
    try:
        for _ in range(cycles):
            for frame in LOADING_ANIMATION_FRAMES[1:]:
                await asyncio.sleep(LOADING_ANIMATION_FRAME_DELAY)
                await msg.edit_text(f"{label}{frame}")
    except Exception:
        pass

def escape_md(text):
    """Экранирует спецсимволы legacy Markdown (parse_mode='Markdown'), чтобы
    непредсказуемый внешний текст (уведомления Росавиации и т.п.) не ломал
    разметку сообщения - иначе Telegram отклоняет весь месседж целиком."""
    if not text:
        return text
    for ch in ('_', '*', '`', '['):
        text = text.replace(ch, '\\' + ch)
    return text

def get_airport_flights(airport_icao):
    """Получить ПРИЛЁТЫ аэропорта из реальных данных (flights_data.json).
    Вылеты больше не собираются и не показываются (см. fetch_yandex_data.py -
    убраны ради экономии дневной квоты Yandex Rasp API). Если файла нет - для
    SVO отдаём запасной хардкод, для остальных пусто."""
    try:
        now = datetime.now()
        flights = []
        data = load_flights_data()

        if data and airport_icao in data.get('airports', {}):
            raw_flights = data['airports'][airport_icao].get('arrivals', [])
            for flight_data in raw_flights:
                time_parts = flight_data['time'].split(':')
                hour, minute = int(time_parts[0]), int(time_parts[1])
                flight_time = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
                total_pax = flight_data.get('passengers', 170)
                # economy/business берутся из fetch_yandex_data.py (уже посчитаны по типу ВС);
                # если их нет в файле (старые данные) - считаем на лету по стандартной разбивке
                economy_pax = flight_data.get('passengers_economy', round(total_pax * ECONOMY_SHARE))
                business_pax = flight_data.get('passengers_business', total_pax - economy_pax)
                # 'domestic' есть в свежих данных (посчитан в fetch_yandex_data.py);
                # если его нет (старый flights_data.json, ещё без этого поля) -
                # считаем на лету тем же классификатором, чтобы не хранить два разных.
                destination = flight_data.get('point', '')
                domestic = flight_data.get('domestic')
                if domestic is None:
                    domestic = fetch_yandex_data.is_domestic_flight(destination)
                flights.append({
                    'time': flight_data['time'],
                    'callsign': f"{flight_data['airline']} {flight_data['flight']}",
                    'destination': destination,
                    'aircraft': flight_data.get('aircraft', ''),
                    'firstSeen': int(flight_time.timestamp()),
                    'passengers': total_pax,
                    'passengers_economy': economy_pax,
                    'passengers_business': business_pax,
                    'domestic': domestic,
                    'terminal': flight_data.get('terminal'),
                })
            logger.info(f"✅ Загружено {len(flights)} реальных прилётов {airport_icao}")
            return flights

        # Запасной вариант - только для SVO, пока нет свежего flights_data.json
        if airport_icao == 'UUEE':
            for flight_data in FALLBACK_ARRIVALS_SVO:
                time_parts = flight_data['time'].split(':')
                hour, minute = int(time_parts[0]), int(time_parts[1])
                flight_time = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
                total_pax = flight_data['passengers']
                economy_pax = round(total_pax * ECONOMY_SHARE)
                business_pax = total_pax - economy_pax
                destination = flight_data.get('origin')
                flights.append({
                    'time': flight_data['time'],
                    'callsign': f"{flight_data['airline']}{flight_data['flight']}",
                    'destination': destination,
                    'aircraft': '',
                    'firstSeen': int(flight_time.timestamp()),
                    'passengers': total_pax,
                    'passengers_economy': economy_pax,
                    'passengers_business': business_pax,
                    'domestic': fetch_yandex_data.is_domestic_flight(destination),
                })
            logger.info(f"⚠️ Использую запасные данные SVO ({len(flights)} рейсов)")
            return flights

        return []
    except Exception as e:
        logger.error(f"❌ Ошибка: {e}")
        return []

def get_load_emoji(load_percent):
    # Пороги ИЗМЕНЕНЫ 21.09.2026 по просьбе пользователя (было 0-50/51-70/71-100/>100)
    if load_percent <= 25: return '🔴'
    elif load_percent <= 50: return '🟡'
    elif load_percent <= 85: return '🟢'
    else: return '🟣'

def get_load_recommendation(load_percent):
    # Формулировки статусов - по просьбе пользователя (было
    # "НЕ ЕХАТЬ/ЗАНЯТЬ ОЧЕРЕДЬ/ЕХАТЬ/СРОЧНО"). Пороги загрузки ИЗМЕНЕНЫ
    # 21.09.2026 (было 0-50/51-70/71-100/>100) на 0-25/26-50/51-85/>85.
    if load_percent <= 25: return 'Не ехать'
    elif load_percent <= 50: return 'Уточни очередь'
    elif load_percent <= 85: return 'Занимай очередь'
    else: return 'Срочно ехать'

# Для вокзалов - ПО ПРОСЬБЕ ПОЛЬЗОВАТЕЛЯ упрощённая БИНАРНАЯ индикация вместо
# 4-уровневой шкалы аэропортов выше (get_load_emoji/get_load_recommendation):
# всего 2 состояния, без отдельной кнопки - просто символ+короткая подпись в
# тексте прогноза. До 50% включительно - не ехать, выше 50% - ехать.
def get_train_load_symbol(load_percent):
    return '🟢' if load_percent > 50 else '🔴'

def get_train_load_label(load_percent):
    return 'ЕХАТЬ' if load_percent > 50 else 'НЕ ЕХАТЬ'

# DEPARTURE_LEAD_TIME_HOURS и get_departure_recommendation() убраны вместе с
# вылетами (см. get_airport_flights) - вылеты больше не собираются и не
# показываются, ради экономии дневной квоты Yandex Rasp API.

def get_db_connection():
    """Единая точка подключения к SQLite. При росте числа водителей (сотни
    одновременных отметок в час пик) SQLite по умолчанию сериализует запись -
    один писатель блокирует остальных и можно словить "database is locked".
    WAL-режим позволяет читать во время записи и сильно снижает конфликты,
    а busy_timeout заставляет соединение подождать и повторить попытку вместо
    того чтобы сразу падать с ошибкой."""
    conn = sqlite3.connect(DB_FILE, timeout=10)
    conn.execute('PRAGMA journal_mode=WAL')
    conn.execute('PRAGMA busy_timeout=10000')
    return conn

_airport_queue_log_db_initialized = False

def get_airport_queue_log_db_connection():
    """Отдельное подключение к AIRPORT_QUEUE_LOG_DB_FILE (см. комментарий у
    константы выше) - тот же WAL/busy_timeout паттерн, что и у основной
    БД (get_db_connection)."""
    conn = sqlite3.connect(AIRPORT_QUEUE_LOG_DB_FILE, timeout=10)
    conn.execute('PRAGMA journal_mode=WAL')
    conn.execute('PRAGMA busy_timeout=10000')
    return conn

def init_airport_queue_log_db():
    global _airport_queue_log_db_initialized
    if _airport_queue_log_db_initialized:
        return
    conn = get_airport_queue_log_db_connection()
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS airport_queue_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            icao TEXT NOT NULL,
            zone_key TEXT,
            zone_label TEXT,
            airport_name TEXT,
            city TEXT,
            tariffs TEXT,
            entered_at DATETIME NOT NULL,
            left_at DATETIME,
            wait_minutes INTEGER,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_airport_queue_log_user ON airport_queue_log (user_id, entered_at)')
    conn.commit()
    conn.close()
    _airport_queue_log_db_initialized = True

def log_airport_queue_entered(user_id, icao, zone_key, zone_label, city, tariffs, entered_at):
    """Новая запись при входе в зону аэропорта (см. process_airport_queue_ping) -
    возвращает id строки, чтобы потом дозаполнить left_at/wait_minutes при
    выходе (log_airport_queue_left). tariffs - список человекочитаемых строк
    (state['shift']['tariffs']), сохраняем через запятую тем же форматом,
    что и format_shift_tariffs_label."""
    init_airport_queue_log_db()
    airport = ICAO_TO_AIRPORT.get(icao)
    airport_name = airport['name'] if airport else icao
    tariffs_label = ", ".join(tariffs) if tariffs else None
    try:
        conn = get_airport_queue_log_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            'INSERT INTO airport_queue_log (user_id, icao, zone_key, zone_label, airport_name, city, tariffs, entered_at) '
            'VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
            (user_id, icao, zone_key, zone_label, airport_name, city, tariffs_label, entered_at.isoformat())
        )
        row_id = cursor.lastrowid
        conn.commit()
        conn.close()
        return row_id
    except Exception as e:
        logger.warning(f"⚠️ Не удалось записать вход в очередь аэропорта (лог) для {user_id}: {e}")
        return None

def log_airport_queue_left(row_id, left_at, wait_minutes):
    """Дозаполняет left_at/wait_minutes у строки, созданной
    log_airport_queue_entered, при выходе из зоны аэропорта. row_id может
    быть None (например, лог не удалось записать при входе) - тогда просто
    ничего не делаем."""
    if row_id is None:
        return
    init_airport_queue_log_db()
    try:
        conn = get_airport_queue_log_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            'UPDATE airport_queue_log SET left_at = ?, wait_minutes = ? WHERE id = ?',
            (left_at.isoformat(), wait_minutes, row_id)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.warning(f"⚠️ Не удалось записать выход из очереди аэропорта (лог) для строки {row_id}: {e}")

_db_initialized = False

def init_db():
    """ИЗМЕНЕНО 21.09.2026 (готовим бота к нагрузке ~1000 пользователей) -
    init_db() вызывается перед ПОЧТИ КАЖДЫМ обращением к БД по всему файлу
    (save_shift_record, save_user_state_json, save_recent_bot_message и
    т.д. - десятки мест), а внутри - ~30 CREATE TABLE/INDEX IF NOT EXISTS.
    Хотя они идемпотентны по результату, SQLite всё равно разбирает и
    проверяет схему на каждый такой вызов - то есть при активной работе
    бота это лишняя синхронная нагрузка на КАЖДЫЙ клик КАЖДОГО пользователя
    поверх и без того синхронного sqlite3-вызова. Таблицы/индексы создаются
    ровно один раз за жизнь процесса (на старте) - дальше они уже есть, и
    все последующие вызовы init_db() ничего не делают, кроме прогона всех
    CREATE IF NOT EXISTS вхолостую. Флаг ниже делает init_db() no-op после
    первого успешного вызова."""
    global _db_initialized
    if _db_initialized:
        return
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS queue (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER,
            city TEXT,
            airport TEXT,
            tariff TEXT,
            position_range TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_queue_lookup ON queue (city, airport, tariff, timestamp)')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS user_states (
            user_id INTEGER PRIMARY KEY,
            state_json TEXT,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS recent_bot_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chat_id INTEGER NOT NULL,
            message_id INTEGER NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_recent_bot_messages_chat ON recent_bot_messages (chat_id, id)')
    # ДОБАВЛЕНО 22.09.2026 (жалоба пользователя со скриншотом - "Опять не
    # удаляет сообщения", видно что сообщения с ReplyKeyboardMarkup вроде
    # "Выбери, что нужно дальше" / "✅ Бот обновлён" копятся в чате
    # одновременно, хотя должно оставаться только одно последнее меню - см.
    # _last_reply_keyboard_msg_id выше). БАГ: recent_bot_messages (общая
    # очередь) пережила добавление персистентности в БД ещё 21.09.2026, а
    # вот _last_reply_keyboard_msg_id (id ПОСЛЕДНЕГО сообщения с меню на
    # чат) как жила только в памяти процесса, так и осталась - при каждом
    # редеплое Railway (а их в этой сессии было много) она обнулялась.
    # Следующее сообщение с меню после рестарта не находило "предыдущее" (в
    # свежем пустом dict prev_id всегда None) и не удаляло его - то самое
    # menu-сообщение, отправленное ДО рестарта, зависало в чате навсегда.
    # Фикс - тот же паттерн, что и у recent_bot_messages: отдельная таблица,
    # по одной строке на чат (последнее известное menu-сообщение), значение
    # обновляется при каждой отправке и восстанавливается при старте (см.
    # load_all_last_reply_keyboard_messages в main()).
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS last_reply_keyboard_messages (
            chat_id INTEGER PRIMARY KEY,
            message_id INTEGER NOT NULL,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS airport_statuses (
            icao TEXT PRIMARY KEY,
            status TEXT,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS rain_state (
            city TEXT PRIMARY KEY,
            last_event_start TEXT,
            last_weight INTEGER,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS holiday_pushes_sent (
            holiday_key TEXT,
            city TEXT,
            kind TEXT,
            sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (holiday_key, city, kind)
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS high_demand_alerts_sent (
            icao TEXT,
            relevant_class TEXT,
            target_date TEXT,
            target_hour INTEGER,
            sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (icao, relevant_class, target_date, target_hour)
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS peak_hour_alerts_sent (
            city TEXT,
            target_date TEXT,
            target_hour INTEGER,
            sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (city, target_date, target_hour)
        )
    ''')
    # ДОБАВЛЕНО 23.09.2026 (см. комментарий у find_upcoming_peak_start -
    # исправление пуша "час пик" для Ultima): старая таблица выше не
    # различала категорию, поэтому дедуп по (city, date, hour) у такси и
    # Ultima мог случайно "занять" друг друга, если пик по обеим таблицам
    # приходится на один и тот же час - INSERT OR IGNORE тихо не создал бы
    # вторую отметку из-за конфликта PRIMARY KEY, и вторая категория
    # решила бы, что пуш ей тоже уже отправлен, хотя это не так. Новая
    # таблица с category в первичном ключе - отдельный дедуп на каждую
    # категорию, старая больше не используется (не удаляем ради простоты
    # миграции).
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS peak_hour_alerts_sent_v2 (
            city TEXT,
            category TEXT,
            target_date TEXT,
            target_hour INTEGER,
            sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (city, category, target_date, target_hour)
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS green_demand_alerts_sent (
            icao TEXT,
            relevant_class TEXT,
            target_date TEXT,
            target_hour INTEGER,
            sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (icao, relevant_class, target_date, target_hour)
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS shared_orders (
            order_id INTEGER PRIMARY KEY AUTOINCREMENT,
            sender_id INTEGER NOT NULL,
            sender_contact TEXT NOT NULL,
            city TEXT NOT NULL,
            category TEXT NOT NULL,
            pickup TEXT NOT NULL,
            dropoff TEXT NOT NULL,
            price TEXT NOT NULL,
            car_class TEXT NOT NULL,
            passengers TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'open',
            accepted_by INTEGER,
            accepted_by_contact TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            accepted_at DATETIME
        )
    ''')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_shared_orders_status ON shared_orders (status, created_at)')
    # Миграция: номер телефона клиента добавлен позже, чем сама таблица -
    # CREATE TABLE IF NOT EXISTS не трогает уже существующую (на Railway)
    # таблицу, колонку нужно добавлять отдельно. SQLite не умеет "ADD COLUMN
    # IF NOT EXISTS", поэтому сначала проверяем через PRAGMA.
    cursor.execute('PRAGMA table_info(shared_orders)')
    existing_columns = {row[1] for row in cursor.fetchall()}
    if 'client_phone' not in existing_columns:
        cursor.execute('ALTER TABLE shared_orders ADD COLUMN client_phone TEXT')
    # Миграция (22.09.2026, по прямой просьбе пользователя): размеры/объём/вес
    # груза - ТОЛЬКО для класса "Грузовая машина" (см. SHARE_ORDER_CARGO_CLASS_NAME),
    # у остальных классов остаются NULL. "Нужен грузчик?" - обязательный
    # выбор Да/Нет для трёх непассажирских классов (см.
    # SHARE_ORDER_LOADER_CHOICE_BY_CLASS), храним как 'yes'/'no'. Тот же
    # PRAGMA table_info + ADD COLUMN паттерн, что у client_phone выше -
    # таблица shared_orders на Railway уже существует.
    for col, coltype in (
        ('cargo_length_cm', 'REAL'), ('cargo_width_cm', 'REAL'), ('cargo_height_cm', 'REAL'),
        ('cargo_volume_m3', 'REAL'), ('cargo_weight_kg', 'REAL'),
        ('loader_needed', 'TEXT'),
        # Взаимное подтверждение выполнения заказа (по прямой просьбе
        # пользователя, 22.09.2026: "чтобы было что оба приняли ...
        # верификация обоих подтверждения прошла") - счётчик у принявшего
        # увеличивается только когда ОБА поля не NULL, см.
        # confirm_shared_order_done ниже.
        ('sender_confirmed_at', 'DATETIME'), ('accepter_confirmed_at', 'DATETIME'),
    ):
        if col not in existing_columns:
            cursor.execute(f'ALTER TABLE shared_orders ADD COLUMN {col} {coltype}')
    # Миграция (22.09.2026, по прямой просьбе пользователя: "надо добавить
    # поля моя комиссия ... нужно везде сделать поле цена от и до, но
    # необязательно чтобы обе цены были указаны - достаточно одной цифры") -
    # старая колонка price TEXT NOT NULL ОСТАЁТСЯ как есть (колонки не
    # удаляем - см. паттерн выше) и по-прежнему заполняется при создании
    # заказа для обратной совместимости (см. create_shared_order), но
    # реальным источником истины для новых заказов становятся price_from/
    # price_to. commission_from/commission_to - НЕобязательное поле целиком
    # (комиссия за передачу заказа может быть не у всех отправителей).
    # Тот же PRAGMA table_info + ADD COLUMN паттерн, что и выше.
    for col, coltype in (
        ('price_from', 'TEXT'), ('price_to', 'TEXT'),
        ('commission_from', 'TEXT'), ('commission_to', 'TEXT'),
    ):
        if col not in existing_columns:
            cursor.execute(f'ALTER TABLE shared_orders ADD COLUMN {col} {coltype}')
    # "▶️ НАЧАТЬ СМЕНУ"/"⏹ Завершить смену" (по просьбе пользователя,
    # 20.09.2026) - история смен водителя: дата, длительность, км. Хранится
    # ОТДЕЛЬНОЙ таблицей (а не в user_states JSON), чтобы не перезаписывать
    # растущий блоб на каждое изменение состояния и чтобы можно было делать
    # обычные SQL-запросы по дате (см. get_shift_history/save_shift_record,
    # показывается в "💰 ФИНАНСЫ" -> "📈 СТАТИСТИКА СМЕН" за 6 месяцев).
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS shift_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            shift_date TEXT NOT NULL,
            started_at DATETIME NOT NULL,
            duration_minutes INTEGER NOT NULL,
            km REAL NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_shift_history_user_date ON shift_history (user_id, shift_date)')
    # "📊 ДЕНЬ - ИТОГ" (расчёт финансов, см. send_courier_finance_result) -
    # сохраняем каждый посчитанный итог в отдельную таблицу (по просьбе
    # пользователя, 20.09.2026: "выдаётся суммарный доход сохраняется в
    # статистику") - независимо от shift_history, т.к. расчёт можно сделать
    # и без привязки к конкретной смене (например, за прошлый день задним
    # числом).
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS finance_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            calc_date TEXT NOT NULL,
            income REAL NOT NULL,
            net_profit REAL NOT NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_finance_history_user_date ON finance_history (user_id, calc_date)')
    # Миграция: количество выполненных заказов за день добавлено позже, чем
    # сама таблица finance_history (по просьбе пользователя, 21.09.2026) -
    # CREATE TABLE IF NOT EXISTS не трогает уже существующую (на Railway)
    # таблицу, колонку нужно добавлять отдельно (см. аналогичную миграцию
    # client_phone у shared_orders выше).
    cursor.execute('PRAGMA table_info(finance_history)')
    existing_columns = {row[1] for row in cursor.fetchall()}
    if 'trips_count' not in existing_columns:
        cursor.execute('ALTER TABLE finance_history ADD COLUMN trips_count INTEGER')
    # Профиль водителя (см. CABINET_WEBAPP_PATH ниже) - ник/ФИО, тариф,
    # машина - вводится в личном кабинете (WebApp), отдельная таблица (не
    # user_state), т.к. это устойчивые анкетные данные, а не сиюминутное
    # состояние навигации по боту, по просьбе пользователя 21.09.2026.
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS driver_profiles (
            user_id INTEGER PRIMARY KEY,
            full_name TEXT,
            tariff TEXT,
            car_model TEXT,
            car_plate TEXT,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    # Миграция (22.09.2026, по прямой просьбе пользователя) - счётчик
    # выполненных заказов у водителя, который ПРИНЯЛ заказ (accepted_by в
    # shared_orders), увеличивается только после взаимного подтверждения
    # обеих сторон (см. confirm_shared_order_done/increment_completed_orders
    # ниже). Тот же PRAGMA table_info + ADD COLUMN паттерн.
    cursor.execute('PRAGMA table_info(driver_profiles)')
    existing_columns = {row[1] for row in cursor.fetchall()}
    if 'completed_orders_count' not in existing_columns:
        cursor.execute('ALTER TABLE driver_profiles ADD COLUMN completed_orders_count INTEGER DEFAULT 0')
    # Миграция (20.09.2026): на уже существующей БД таблица shift_history
    # могла быть создана раньше без этой колонки - CREATE TABLE IF NOT
    # EXISTS её не добавит, поэтому добавляем отдельно, игнорируя ошибку
    # "duplicate column", если колонка уже есть (повторный запуск init_db).
    try:
        cursor.execute('ALTER TABLE shift_history ADD COLUMN airport_wait_minutes INTEGER NOT NULL DEFAULT 0')
    except sqlite3.OperationalError:
        pass
    # Дедуп пушей о перекрытиях/крупных ДТП (по просьбе пользователя,
    # 20.09.2026: "делай пуши перекрытий... и крупные ДТП") - event_key
    # уникален на пост (ссылка на сообщение, если есть, иначе время+текст,
    # тот же принцип дедупа, что уже используется в merge_city_messages
    # fetch_road_events.py) - не даёт разослать пуш дважды за один и тот же
    # пост при каждом прогоне road_events_updater (раз в
    # ROAD_EVENTS_UPDATE_INTERVAL_MINUTES минут, пост остаётся в свежей
    # ленте несколько прогонов подряд, пока не истечёт LOOKBACK_HOURS).
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS road_event_alerts_sent (
            city TEXT,
            event_key TEXT,
            sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (city, event_key)
        )
    ''')
    # Простая key-value таблица для служебных отметок бота - сейчас только
    # 'last_deployed_commit' (по просьбе пользователя, 20.09.2026: "сделай
    # так чтобы приходило сообщение что бот обновился" - см.
    # notify_users_about_new_deploy ниже). Отдельная таблица вместо
    # добавления колонки куда-то в существующие - это не про конкретного
    # пользователя/город/событие, а глобальное состояние самого бота.
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS bot_meta (
            key TEXT PRIMARY KEY,
            value TEXT
        )
    ''')
    # Платная подписка (по просьбе пользователя, 20.09.2026: "сделай так
    # чтобы бот был платный семь дней подписка будет бесплатно на восьмой
    # день будет платная подписка в месяц она будет стоить 149 руб.") -
    # trial_started_at ставится один раз при первом обращении пользователя
    # к боту (см. ensure_subscription), paid_until - до какого момента
    # (UTC, тот же формат '%Y-%m-%d %H:%M:%S', что и везде в файле) оплачен
    # доступ, продлевается на 30 дней при каждом подтверждённом платеже
    # Tinkoff. last_order_id - последний созданный, но необязательно ещё
    # оплаченный заказ (для сверки в webhook).
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS subscriptions (
            user_id INTEGER PRIMARY KEY,
            trial_started_at DATETIME NOT NULL,
            paid_until DATETIME,
            last_order_id TEXT,
            expired_notified INTEGER DEFAULT 0
        )
    ''')
    # ДОБАВЛЕНО 23.09.2026 (по факту - Tinkoff Init отказывал с ErrorCode 309
    # "request.validate.expected.receipt": для этого терминала обязателен
    # фискальный чек по 54-ФЗ, а в чеке законодательно нужен контакт
    # покупателя - Email или Phone). receipt_email собирается у водителя
    # ОДИН раз перед первой оплатой (см. get_receipt_email/set_receipt_email/
    # create_tinkoff_payment ниже) и переиспользуется для всех следующих
    # платежей. Таблица уже существует в проде, поэтому колонка добавляется
    # через ALTER TABLE в try/except (см. тот же паттерн у referrals выше).
    try:
        cursor.execute('ALTER TABLE subscriptions ADD COLUMN receipt_email TEXT')
    except Exception:
        pass  # колонка уже существует - обычная ситуация при каждом рестарте
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS subscription_payments (
            order_id TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            amount_kopecks INTEGER NOT NULL,
            status TEXT NOT NULL DEFAULT 'NEW',
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            confirmed_at DATETIME
        )
    ''')
    # ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "подготовь так же
    # пуши 3 2 1 день 1 час и 10 мин до окончания подписки чтобы приходили с
    # кнопкой оплатить подписку") - по одной строке на пользователя+порог
    # (см. SUBSCRIPTION_REMINDER_THRESHOLDS/check_subscription_reminders
    # ниже), чтобы каждый порог слался РОВНО один раз за текущий оплаченный
    # период - как только paid_until продлевается новым платежом, старые
    # строки за прошлый период больше не совпадают ни с одним будущим
    # порогом (см. active_until в самой проверке), а после продления мы их
    # явно чистим (см. confirm_subscription_payment/grant_free_month), чтобы
    # они не мешали посчитать пороги для НОВОГО periода.
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS subscription_expiry_reminders (
            user_id INTEGER NOT NULL,
            threshold TEXT NOT NULL,
            sent_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (user_id, threshold)
        )
    ''')
    # Реферальная программа (по просьбе пользователя, 20.09.2026: "нужно
    # будет продумать в основном меню реферальная программа кнопка...") -
    # 2 уровня, привязка при первом /start?ref_<id> у НОВОГО пользователя
    # (см. register_referral), не переписывается повторно. referred_by_level2
    # считается ОДИН раз при регистрации (реферер реферера на тот момент) -
    # не пересчитывается задним числом, если у реферера потом поменяется его
    # собственный referred_by (в этой реализации referred_by у пользователя
    # и так не меняется после первой привязки).
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS referrals (
            user_id INTEGER PRIMARY KEY,
            referred_by INTEGER,
            referred_by_level2 INTEGER,
            joined_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            balance_kopecks INTEGER DEFAULT 0,
            total_earned_kopecks INTEGER DEFAULT 0,
            total_withdrawn_kopecks INTEGER DEFAULT 0
        )
    ''')
    # ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "2 реферальные
    # системы: юр.лицо приглашает водителей 40/20/10%, обычная реферальная
    # 30/15/5%, 3 уровня вместо 2"): таблица уже существует в проде, поэтому
    # новые колонки добавляем через ALTER TABLE (CREATE TABLE IF NOT EXISTS
    # выше не трогает уже созданную таблицу) - referred_by_level3 для
    # третьего уровня начислений (см. register_referral), referrer_type
    # ('individual' по умолчанию/'legal_entity' - см. REFERRAL_RATES_PERCENT
    # и admin_set_referrer_type) определяет, по какой шкале процентов этот
    # человек получает начисления со своих рефералов. ALTER TABLE ADD COLUMN
    # падает, если колонка уже есть - оборачиваем в try/except, чтобы
    # повторный запуск init_db (при каждом старте бота) не ронял процесс.
    for _migration_sql in (
        'ALTER TABLE referrals ADD COLUMN referred_by_level3 INTEGER',
        "ALTER TABLE referrals ADD COLUMN referrer_type TEXT DEFAULT 'individual'",
    ):
        try:
            cursor.execute(_migration_sql)
        except Exception:
            pass  # колонка уже существует - обычная ситуация при каждом рестарте
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_referrals_by1 ON referrals (referred_by)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_referrals_by2 ON referrals (referred_by_level2)')
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_referrals_by3 ON referrals (referred_by_level3)')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS referral_earnings (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            earner_user_id INTEGER NOT NULL,
            source_user_id INTEGER NOT NULL,
            level INTEGER NOT NULL,
            amount_kopecks INTEGER NOT NULL,
            order_id TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS referral_withdrawals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            amount_kopecks INTEGER NOT NULL,
            fee_kopecks INTEGER NOT NULL,
            payout_kopecks INTEGER NOT NULL,
            card_number TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'pending',
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            processed_at DATETIME
        )
    ''')
    # Карта водителей (по прямой просьбе пользователя, 21.09.2026: "карта
    # водителей все те кто есть в этом боте чтобы они нажимали и все видели
    # друг друга") - строка появляется/пропадает вместе со сменой (по
    # уточнению пользователя, 21.09.2026: "когда он нажимает начать смену он
    # автоматически появляется на карте когда завершает смену на карте его
    # не видно" - см. start_shift_and_notify/finish_shift), и только пока их
    # последний пинг геопозиции не старше MAP_VISIBILITY_STALE_MINUTES (см.
    # get_map_positions). Одна строка на пользователя (последняя известная
    # позиция), а не история - для карты нужна только текущая точка.
    # tariffs - тарифы, выбранные при старте смены (см.
    # shift_tariffs_keyboard), JSON-массив строк, для подписи маркера.
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS map_positions (
            user_id INTEGER PRIMARY KEY,
            city TEXT NOT NULL,
            category TEXT NOT NULL,
            lat REAL NOT NULL,
            lon REAL NOT NULL,
            tariffs TEXT NOT NULL DEFAULT '[]',
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    cursor.execute('PRAGMA table_info(map_positions)')
    existing_columns = {row[1] for row in cursor.fetchall()}
    if 'tariffs' not in existing_columns:
        cursor.execute("ALTER TABLE map_positions ADD COLUMN tariffs TEXT NOT NULL DEFAULT '[]'")
    if 'heading' not in existing_columns:
        # ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - показывать на
        # карте направление движения машинки): направление в градусах
        # (0-360, по часовой от севера), как его отдаёт Telegram в живой
        # геопозиции (Location.heading) - может отсутствовать (NULL), если
        # устройство водителя его не передаёт (не все телефоны/версии
        # клиента это умеют). См. update_map_position/get_map_positions.
        cursor.execute("ALTER TABLE map_positions ADD COLUMN heading INTEGER")
    cursor.execute('CREATE INDEX IF NOT EXISTS idx_map_positions_city ON map_positions (city, updated_at)')
    # ДОБАВЛЕНО 22.09.2026 (см. блок "ЗАПРАВКИ + ЭЛЕКТРОЗАРЯДКИ НА КАРТЕ" выше
    # по файлу) - крауд-отметки "что есть на заправке/свободна ли зарядка".
    # station_id - osm "type/id" из fuel_charging_data.json (см.
    # fetch_fuel_charging_data.py), НЕ строка из основной user_state - таблицы
    # никак не зависят от того, когда в последний раз пересобирали сам JSON
    # со списком точек, пока сам id заправки/зарядки не поменялся.
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS gas_station_fuel_status (
            station_id TEXT NOT NULL,
            fuel_type TEXT NOT NULL,
            available INTEGER NOT NULL,
            reported_by INTEGER,
            reported_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (station_id, fuel_type)
        )
    ''')
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS charging_station_status (
            station_id TEXT PRIMARY KEY,
            status TEXT NOT NULL,
            occupied_by INTEGER,
            updated_by INTEGER,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    ''')
    conn.commit()
    conn.close()
    _db_initialized = True

SHIFT_HISTORY_MONTHS = 6  # сколько месяцев хранить/показывать в статистике (по просьбе пользователя)

def save_shift_record(user_id, started_at, duration_minutes, km, airport_wait_minutes=0):
    """Сохраняет одну завершённую смену в историю (см. finish_shift) -
    shift_date берём из started_at по UTC (дата начала смены, не окончания -
    так смена, начатая поздно вечером и законченная за полночь, попадает в
    статистику того дня, когда водитель фактически начал работать)."""
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO shift_history (user_id, shift_date, started_at, duration_minutes, km, airport_wait_minutes) VALUES (?, ?, ?, ?, ?, ?)',
            (user_id, started_at.date().isoformat(), started_at.strftime('%Y-%m-%d %H:%M:%S'), duration_minutes, km, airport_wait_minutes)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить смену пользователя {user_id}: {e}")

def get_shift_history(user_id, months=SHIFT_HISTORY_MONTHS):
    """Смены пользователя за последние `months` месяцев, по дате начала
    (новые сверху) - используется и для списка по дням (show_shift_stats), и
    для общих итогов (сумма км/часов за период). Возвращает кортежи
    (shift_date, duration_minutes, km, airport_wait_minutes)."""
    try:
        init_db()
        conn = get_db_connection()
        cutoff = (datetime.now(timezone.utc) - timedelta(days=months * 30)).date().isoformat()
        cursor = conn.execute(
            'SELECT shift_date, duration_minutes, km, airport_wait_minutes FROM shift_history '
            'WHERE user_id = ? AND shift_date >= ? ORDER BY shift_date DESC, started_at DESC',
            (user_id, cutoff)
        )
        rows = cursor.fetchall()
        conn.close()
        return rows
    except Exception as e:
        logger.error(f"❌ Не удалось прочитать историю смен пользователя {user_id}: {e}")
        return []

def get_finance_history(user_id, months=SHIFT_HISTORY_MONTHS):
    """Посчитанные итоги "📊 ДЕНЬ - ИТОГ" пользователя за последние `months`
    месяцев (см. save_finance_result/finance_history) - используется для
    графика заработка в личном кабинете (см. handle_cabinet_data_api).
    Возвращает кортежи (calc_date, income, net_profit, trips_count), новые
    сверху (trips_count может быть None - для расчётов, сохранённых до
    появления этого поля, 21.09.2026)."""
    try:
        init_db()
        conn = get_db_connection()
        cutoff = (datetime.now(timezone.utc) - timedelta(days=months * 30)).date().isoformat()
        cursor = conn.execute(
            'SELECT calc_date, income, net_profit, trips_count FROM finance_history '
            'WHERE user_id = ? AND calc_date >= ? ORDER BY calc_date DESC, id DESC',
            (user_id, cutoff)
        )
        rows = cursor.fetchall()
        conn.close()
        return rows
    except Exception as e:
        logger.error(f"❌ Не удалось прочитать историю финансов пользователя {user_id}: {e}")
        return []

def save_finance_result(user_id, income, net_profit, trips_count=None):
    """Сохраняет один посчитанный итог "📊 ДЕНЬ - ИТОГ" (см.
    send_courier_finance_result) в статистику - по просьбе пользователя,
    20.09.2026 ("выдаётся сумарный доход сохраняется в статистику").
    trips_count - количество выполненных заказов за день, опционально
    (по просьбе пользователя, 21.09.2026)."""
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO finance_history (user_id, calc_date, income, net_profit, trips_count) VALUES (?, ?, ?, ?, ?)',
            (user_id, datetime.now(timezone.utc).date().isoformat(), income, net_profit, trips_count)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить итог дня пользователя {user_id}: {e}")

def get_driver_profile(user_id):
    """Профиль водителя из личного кабинета (см. driver_profiles в init_db) -
    None, если ещё ничего не заполнял."""
    try:
        init_db()
        conn = get_db_connection()
        cursor = conn.execute(
            'SELECT full_name, tariff, car_model, car_plate, completed_orders_count FROM driver_profiles WHERE user_id = ?', (user_id,)
        )
        row = cursor.fetchone()
        conn.close()
        if not row:
            return None
        return {'full_name': row[0] or '', 'tariff': row[1] or '', 'car_model': row[2] or '', 'car_plate': row[3] or '',
                'completed_orders_count': row[4] or 0}
    except Exception as e:
        logger.error(f"❌ Не удалось прочитать профиль водителя {user_id}: {e}")
        return None

def save_driver_profile(user_id, full_name, tariff, car_model, car_plate):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO driver_profiles (user_id, full_name, tariff, car_model, car_plate, updated_at) VALUES (?, ?, ?, ?, ?, ?) '
            'ON CONFLICT(user_id) DO UPDATE SET full_name = excluded.full_name, tariff = excluded.tariff, '
            'car_model = excluded.car_model, car_plate = excluded.car_plate, updated_at = excluded.updated_at',
            (user_id, full_name, tariff, car_model, car_plate, datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'))
        )
        conn.commit()
        conn.close()
        return True
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить профиль водителя {user_id}: {e}")
        return False

def save_airport_status(icao, status):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO airport_statuses (icao, status, updated_at) VALUES (?, ?, ?) '
            'ON CONFLICT(icao) DO UPDATE SET status = excluded.status, updated_at = excluded.updated_at',
            (icao, status, datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'))
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить статус аэропорта {icao}: {e}")

def load_all_airport_statuses():
    """Последний известный статус каждого аэропорта (из прошлого прогона) -
    хранится в БД, а не в памяти, чтобы рестарт/редеплой бота не считался
    "изменением статуса" и не рассылал ложные пуши всем водителям."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT icao, status FROM airport_statuses')
    rows = cursor.fetchall()
    conn.close()
    return {icao: status for icao, status in rows}

def save_rain_state(city, event_start, weight):
    """event_start - ISO-строка начала того события осадков, о котором уже
    отправлен пуш (или None, если сейчас ничего не запушено). weight - "сила"
    осадков на момент пуша (см. WEATHERCODE_INFO) - нужна, чтобы отличить
    усиление (дождь -> ливень, weight вырос) от простого повтора того же
    прогноза на следующем прогоне."""
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO rain_state (city, last_event_start, last_weight, updated_at) VALUES (?, ?, ?, ?) '
            'ON CONFLICT(city) DO UPDATE SET last_event_start = excluded.last_event_start, '
            'last_weight = excluded.last_weight, updated_at = excluded.updated_at',
            (city, event_start, weight, datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'))
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить состояние осадков для {city}: {e}")

def load_all_rain_states():
    """Последнее запушенное событие осадков по каждому городу (время начала +
    сила) - хранится в БД по тому же принципу, что и load_all_airport_statuses():
    рестарт/редеплой бота не должен считаться поводом для нового пуша."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT city, last_event_start, last_weight FROM rain_state')
    rows = cursor.fetchall()
    conn.close()
    return {city: (event_start, weight) for city, event_start, weight in rows}

def was_holiday_push_sent(holiday_key, city, kind):
    """kind - 'lead' (за HOLIDAY_LEAD_DAYS до) или 'day' (в сам день, дедуп
    внутри ОДНОГО дня - см. mark_holiday_push_sent/holiday_checker). city -
    ключ города или 'ALL' для национального праздника (используем единую
    запись вместо 12 отдельных, т.к. рассылка национального праздника всё
    равно идёт одним проходом по всем городам сразу)."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT 1 FROM holiday_pushes_sent WHERE holiday_key = ? AND city = ? AND kind = ?',
        (holiday_key, city, kind)
    )
    row = cursor.fetchone()
    conn.close()
    return row is not None

def mark_holiday_push_sent(holiday_key, city, kind):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT OR IGNORE INTO holiday_pushes_sent (holiday_key, city, kind) VALUES (?, ?, ?)',
            (holiday_key, city, kind)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось отметить пуш о празднике ({holiday_key}, {city}, {kind}): {e}")

def format_user_contact(user):
    """Контакт для связи между водителями - ник через @ (как просил
    пользователь). У части аккаунтов Telegram ник не задан вообще -
    запасной вариант: имя + числовой ID (по нему тоже можно найти человека
    через пересылку сообщения, хоть и не так напрямую, как по нику)."""
    if user.username:
        return f"@{user.username}"
    name = escape_md(user.full_name or 'без имени')
    return f"{name} (ник не задан, ID: {user.id})"

def create_shared_order(sender_id, sender_contact, city, category, pickup, dropoff, price_from, price_to, car_class,
                         passengers, client_phone=None, loader_needed=None, cargo_length_cm=None, cargo_width_cm=None,
                         cargo_height_cm=None, cargo_volume_m3=None, cargo_weight_kg=None,
                         commission_from=None, commission_to=None):
    """price_from/price_to - диапазон стоимости поездки (по прямой просьбе
    пользователя, 22.09.2026 - "нужно везде сделать поле цена от и до, но
    необязательно чтобы обе цены были указаны"), commission_from/
    commission_to - тот же диапазон для "моя комиссия" (НЕобязательное поле
    целиком). Старая колонка price TEXT NOT NULL заполняется для обратной
    совместимости комбинированным значением - см. price_compat ниже."""
    init_db()
    if price_from and price_to:
        price_compat = f"{price_from}-{price_to}"
    else:
        price_compat = price_from or price_to or ''
    conn = get_db_connection()
    cursor = conn.execute(
        'INSERT INTO shared_orders (sender_id, sender_contact, city, category, pickup, dropoff, price, price_from, '
        'price_to, car_class, passengers, client_phone, loader_needed, cargo_length_cm, cargo_width_cm, '
        'cargo_height_cm, cargo_volume_m3, cargo_weight_kg, commission_from, commission_to) '
        'VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        (sender_id, sender_contact, city, category, pickup, dropoff, price_compat, price_from, price_to, car_class,
         passengers, client_phone, loader_needed, cargo_length_cm, cargo_width_cm, cargo_height_cm, cargo_volume_m3,
         cargo_weight_kg, commission_from, commission_to)
    )
    order_id = cursor.lastrowid
    conn.commit()
    conn.close()
    return order_id

_SHARED_ORDER_FIELDS = ['order_id', 'sender_id', 'sender_contact', 'city', 'category', 'pickup', 'dropoff',
                         'price', 'car_class', 'passengers', 'status', 'accepted_by', 'accepted_by_contact',
                         'created_at', 'accepted_at', 'client_phone', 'cargo_length_cm', 'cargo_width_cm',
                         'cargo_height_cm', 'cargo_volume_m3', 'cargo_weight_kg', 'loader_needed',
                         'sender_confirmed_at', 'accepter_confirmed_at',
                         'price_from', 'price_to', 'commission_from', 'commission_to']

def format_share_order_price_range(from_val, to_val, label='Стоимость', emoji='💰'):
    """Универсальный форматтер для полей-диапазонов "от/до" - цена поездки и
    "моя комиссия" (по прямой просьбе пользователя, 22.09.2026: "нужно везде
    сделать поле цена от и до, но необязательно чтобы обе цены были указаны -
    достаточно одной цифры"). Если задана только ОДНА граница - показываем её
    БЕЗ "от"/"до" (подтверждено пользователем явно, а не "от 1500 ₽"), если
    заданы ОБЕ - диапазоном "1500–2000 ₽", если НИ ОДНОЙ - пустая строка
    (используется в условных строках, как у пассажиров/грузчика/груза).
    Переиспользуется и для price, и для commission, чтобы не дублировать
    логику форматирования от/до."""
    from_val = from_val if from_val not in (None, '') else None
    to_val = to_val if to_val not in (None, '') else None
    if from_val is None and to_val is None:
        return ""
    if from_val is not None and to_val is not None:
        value = f"{from_val}–{to_val}"
    else:
        value = str(from_val if from_val is not None else to_val)
    return f"{emoji} {label}: {value} ₽\n"

def get_shared_order(order_id):
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(f'SELECT {", ".join(_SHARED_ORDER_FIELDS)} FROM shared_orders WHERE order_id = ?', (order_id,))
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    return dict(zip(_SHARED_ORDER_FIELDS, row))

def is_shared_order_expired(order):
    """SHARED_ORDER_EXPIRY_HOURS (решение пользователя - 1 час) с момента
    создания. created_at хранится в UTC (SQLite CURRENT_TIMESTAMP), поэтому
    сравниваем с datetime.now(UTC), а не с местным временем сервера."""
    try:
        created = datetime.strptime(order['created_at'], '%Y-%m-%d %H:%M:%S').replace(tzinfo=ZoneInfo('UTC'))
    except Exception:
        return False  # не смогли распарсить - не считаем протухшим, чтобы не терять заказ на пустом месте
    return datetime.now(ZoneInfo('UTC')) - created > timedelta(hours=SHARED_ORDER_EXPIRY_HOURS)

def try_accept_shared_order(order_id, accepted_by, accepted_by_contact):
    """Атомарно "забирает" заказ - условие status='open' прямо в WHERE
    гарантирует, что при одновременном нажатии "Принять" двумя водителями
    выиграет только тот, чей UPDATE применится первым (SQLite сериализует
    запись на уровне файла БД) - остальные получат rowcount=0 и поймут, что
    опоздали, без отдельных блокировок в коде бота."""
    init_db()
    conn = get_db_connection()
    cursor = conn.execute(
        "UPDATE shared_orders SET status='accepted', accepted_by=?, accepted_by_contact=?, accepted_at=? "
        "WHERE order_id=? AND status='open'",
        (accepted_by, accepted_by_contact, datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'), order_id)
    )
    conn.commit()
    won = cursor.rowcount == 1
    conn.close()
    return won

def expire_shared_order(order_id):
    init_db()
    conn = get_db_connection()
    conn.execute("UPDATE shared_orders SET status='expired' WHERE order_id=? AND status='open'", (order_id,))
    conn.commit()
    conn.close()

def increment_completed_orders(user_id):
    """Счётчик выполненных заказов у ПРИНЯВШЕГО заказ водителя (по прямой
    просьбе пользователя, 22.09.2026 - "пока без системы оценивания", просто
    число). driver_profiles может ещё не иметь строки для этого user_id
    (профиль не заполнялся) - ON CONFLICT ... DO UPDATE (тот же паттерн, что
    save_driver_profile выше) создаёт строку с 1 или увеличивает существующую."""
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO driver_profiles (user_id, completed_orders_count) VALUES (?, 1) '
            'ON CONFLICT(user_id) DO UPDATE SET completed_orders_count = COALESCE(completed_orders_count, 0) + 1',
            (user_id,)
        )
        conn.commit()
        cursor = conn.execute('SELECT completed_orders_count FROM driver_profiles WHERE user_id=?', (user_id,))
        row = cursor.fetchone()
        conn.close()
        return row[0] if row else None
    except Exception as e:
        logger.error(f"❌ Не удалось увеличить счётчик выполненных заказов для {user_id}: {e}")
        return None

def confirm_shared_order_done(order_id, is_sender):
    """Отмечает подтверждение выполнения заказа. ИЗМЕНЕНО 22.09.2026 (прямая
    просьба пользователя - "засчитывается только у того, кто заказ принял...
    тот, кто его дал - он ему не нужен"): взаимное подтверждение убрано,
    остался только accepter_confirmed_at (is_sender всегда False у
    единственного вызывающего - order_done_callback; параметр оставлен для
    совместимости сигнатуры/на случай если понадобится другая сторона
    позже). Возвращает (order_after, just_completed) - just_completed=True,
    только если ИМЕННО ЭТО нажатие впервые проставило accepter_confirmed_at
    (защита от повторного тапа, который иначе удвоил бы счётчик)."""
    init_db()
    conn = get_db_connection()
    now = datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S')
    col = 'sender_confirmed_at' if is_sender else 'accepter_confirmed_at'
    cursor = conn.execute(f"UPDATE shared_orders SET {col}=? WHERE order_id=? AND {col} IS NULL", (now, order_id))
    conn.commit()
    just_completed = cursor.rowcount == 1  # False, если уже подтверждали раньше (повторный тап на кнопку)
    conn.close()
    order = get_shared_order(order_id)
    if just_completed and order and order['status'] != 'completed':
        conn = get_db_connection()
        conn.execute("UPDATE shared_orders SET status='completed' WHERE order_id=?", (order_id,))
        conn.commit()
        conn.close()
        order = get_shared_order(order_id)
    return order, just_completed

