# Водители сами отмечают, сколько машин видят в очереди на аэропорту - выбором
# диапазона, а не точного числа (точно посчитать чужие машины в моменте
# нереально). Диапазоны по 5: 1-5, 6-10, ... 96-100.
QUEUE_RANGES = [(i, i + 4) for i in range(1, 101, 5)]

def queue_range_label(idx):
    lo, hi = QUEUE_RANGES[idx]
    return f"{lo}-{hi}"

def format_airport_local_time(utc_timestamp_str, airport_icao):
    """Время отметки в БД хранится как datetime.now() сервера (Railway работает
    в UTC), поэтому для показа пользователю его нужно перевести в местное
    время КОНКРЕТНОГО аэропорта - иначе увидим UTC вместо реального часа, тот
    же баг, что уже правили с расписанием рейсов."""
    try:
        naive = datetime.strptime(utc_timestamp_str, '%Y-%m-%d %H:%M:%S')
        aware_utc = naive.replace(tzinfo=ZoneInfo('UTC'))
        tz_name = AIRPORT_TIMEZONE.get(airport_icao, 'Europe/Moscow')
        local = aware_utc.astimezone(ZoneInfo(tz_name))
        return local.strftime('%H:%M')
    except Exception:
        return utc_timestamp_str

def _queue_airport_key(airport_icao, zone_key=None):
    """Ключ аэропорта в таблице queue - обычно просто icao, но для
    аэропортов с терминальными зонами (сейчас только Шереметьево/UUEE, см.
    AIRPORT_TERMINAL_ZONES) с суффиксом "#zone_key" - ИСПРАВЛЕНО 20.09.2026
    (по просьбе пользователя, вслед за разведением B/C и D на разные точки
    на карте): раньше отметки очереди у обеих терминальных зон писались под
    одним и тем же icao=UUEE и физически не различались - водитель,
    стоящий у Терминала D, видел (и портил) общую очередь Терминала B/C, и
    наоборот. Схема БД не менялась (колонка airport как была TEXT) - просто
    для зональных аэропортов туда пишется составной ключ. Старые
    отметки без суффикса (до этого фикса) просто перестают совпадать с
    новыми зональными запросами и угасают сами по TTL (QUEUE_ENTRY_TTL_MINUTES) -
    отдельная миграция не нужна."""
    return f"{airport_icao}#{zone_key}" if zone_key else airport_icao

def queue_submit_report(user_id, city, airport_icao, category, range_str, zone_key=None):
    """Сохраняет отметку водителя о длине очереди. Это не "встать в очередь" -
    просто разовый отчёт "я сейчас вижу вот столько машин", поэтому старые
    отметки не удаляются при новой - копится история, из которой потом берём
    последние отметки для оценки."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'INSERT INTO queue (user_id, city, airport, tariff, position_range, timestamp) VALUES (?, ?, ?, ?, ?, ?)',
        (user_id, city, _queue_airport_key(airport_icao, zone_key), category, range_str,
         datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'))
    )
    conn.commit()
    conn.close()

def user_recent_queue_marks(user_id, city, airport_icao, zone_key=None):
    """Собственные СВЕЖИЕ (за QUEUE_ENTRY_TTL_MINUTES) отметки ЭТОГО водителя
    для этого аэропорта/терминала - {tariff: range_str}, самая свежая по
    каждому tariff. Добавлено 20.09.2026 по просьбе пользователя: "если он
    отметился в зоне аэропорта раз, второй раз можно уже не спрашивать" - на
    повторном пуше "давно рядом с аэропортом" (см. send_airport_queue_push)
    так можно предложить водителю просто подтвердить "я всё ещё тут" одной
    кнопкой (переотправить те же тарифы/диапазоны с новым временем), не
    заставляя заново проходить весь выбор тарифа и диапазона машин."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cutoff = (datetime.now(ZoneInfo('UTC')) - timedelta(minutes=QUEUE_ENTRY_TTL_MINUTES)).strftime('%Y-%m-%d %H:%M:%S')
    cursor.execute(
        'SELECT tariff, position_range, timestamp FROM queue WHERE user_id = ? AND city = ? AND airport = ? '
        'AND timestamp >= ? ORDER BY timestamp ASC',
        (user_id, city, _queue_airport_key(airport_icao, zone_key), cutoff)
    )
    rows = cursor.fetchall()
    conn.close()
    marks = {}
    for tariff, range_str, ts in rows:
        marks[tariff] = range_str  # ASC порядок - последняя запись по каждому tariff перезапишет более раннюю
    return marks

def queue_latest_report(city, airport_icao, category, zone_key=None):
    """Последняя свежая отметка водителя (за QUEUE_ENTRY_TTL_MINUTES) - без
    усреднения, просто тот диапазон, который отметил последний водитель.
    Возвращает (range_str, timestamp) или (None, None), если свежих отметок нет."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cutoff = (datetime.now(ZoneInfo('UTC')) - timedelta(minutes=QUEUE_ENTRY_TTL_MINUTES)).strftime('%Y-%m-%d %H:%M:%S')
    cursor.execute(
        'SELECT position_range, timestamp FROM queue WHERE city = ? AND airport = ? AND tariff = ? AND timestamp >= ? '
        'ORDER BY timestamp DESC LIMIT 1',
        (city, _queue_airport_key(airport_icao, zone_key), category, cutoff)
    )
    row = cursor.fetchone()
    conn.close()
    return row if row else (None, None)

def queue_latest_report_for_category(city, airport_icao, category, zone_key=None):
    """Как queue_latest_report, но БЕЗ привязки к конкретному тарифу - берёт
    самую свежую отметку любого водителя данной КАТЕГОРИИ (такси/Ultima/...)
    на аэропорту, независимо от того, какой именно тариф он указал
    (queue_class_key пишет tariff как "taxi:Комфорт+" и т.п., либо просто
    "taxi" без тарифа) - нужно для карты аэропортов (см.
    handle_map_airports_api), где нет смысла дробить по тарифам."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cutoff = (datetime.now(ZoneInfo('UTC')) - timedelta(minutes=QUEUE_ENTRY_TTL_MINUTES)).strftime('%Y-%m-%d %H:%M:%S')
    airport_key = _queue_airport_key(airport_icao, zone_key)
    cursor.execute(
        'SELECT position_range, timestamp FROM queue WHERE city = ? AND airport = ? '
        'AND (tariff = ? OR tariff LIKE ?) AND timestamp >= ? '
        'ORDER BY timestamp DESC LIMIT 1',
        (city, airport_key, category, f'{category}:%', cutoff)
    )
    row = cursor.fetchone()
    conn.close()
    return row if row else (None, None)

bot = None
dp = Dispatcher()
router = Router()

# По просьбе пользователя (19.09.2026): "режим одного сообщения" - бот
# держит в чате только своё САМОЕ ПОСЛЕДНЕЕ сообщение, стирая предыдущее
# перед отправкой нового (вместо накопления истории кнопок/карточек).
# ИЗМЕНЕНО 21.09.2026 (просьба пользователя: "оставлял тока последних 2
# сообщения, остальное удалял, чтобы чисто в чате было") - теперь хранится
# НЕБОЛЬШАЯ ОЧЕРЕДЬ (KEEP_LAST_N_MESSAGES=2) id последних сообщений на чат
# вместо одного: перед отправкой нового сообщения удаляются ВСЕ сообщения
# в очереди, которые выйдут за пределы последних N ПОСЛЕ добавления нового
# (т.е. в чате всегда остаётся новое + (N-1) предыдущих).
# Реализовано ОДНИМ местом на уровне HTTP-запросов к Telegram API (aiogram
# request middleware), а не правкой каждого из ~285 мест с .answer() в
# коде бота - middleware перехватывает КАЖДЫЙ исходящий sendMessage, после
# отправки добавляет id нового сообщения в очередь чата и удаляет всё, что
# выпало за пределы KEEP_LAST_N_MESSAGES. Если удаление не удалось
# (сообщение уже стёрто пользователем, прошло >48ч и Telegram сам не даёт
# удалить, и т.п.) - тихо игнорируем, это не должно ломать отправку нового
# сообщения.
#
# ВАЖНО (баг найден 19.09.2026): сообщения с ReplyKeyboardMarkup (нижнее
# меню кнопок 8/8 и т.п.) НЕ удаляются и НЕ добавляются в очередь на
# удаление. В Telegram reply-клавиатура привязана к КОНКРЕТНОМУ сообщению
# чата, а не существует отдельно от него - если удалить то самое сообщение,
# у пользователя вместе с ним пропадает и нижнее меню, пока не придёт новое
# сообщение с клавиатурой. Поэтому такие сообщения (и учёт "что можно
# удалить" тоже) не участвуют в этой логике - они остаются в чате как
# обычно, стирается только всё остальное (карточки событий, текстовые
# ответы без меню и т.п).
KEEP_LAST_N_MESSAGES = 2
_recent_bot_message_ids = {}  # chat_id -> список последних message_id бота (без reply-клавиатуры), новые в конце

# ДОБАВЛЕНО 22.09.2026 (жалоба пользователя со скриншотом - "Опять он не
# удаляет сообщения смотри их 3 после моего"): сообщения с
# ReplyKeyboardMarkup (нижнее меню) специально НИКОГДА не попадают в общую
# очередь _recent_bot_message_ids (см. комментарий выше) - иначе меню могло
# бы пропасть, если удалить последнее такое сообщение раньше, чем пришло
# новое с тем же меню. Но из-за этого они раньше копились в чате
# БЕСКОНЕЧНО (например "✅ Смена начата" - шлётся с клавиатурой при каждом
# старте смены). Решение: держим отдельно id ПОСЛЕДНЕГО отправленного
# сообщения с меню на чат - когда уходит новое такое сообщение (меню уже
# гарантированно на месте), СТАРОЕ можно спокойно удалить, оно больше не
# нужно. Так в чате всегда остаётся ровно одно (самое свежее) сообщение с
# меню, а не все подряд.
_last_reply_keyboard_msg_id = {}  # chat_id -> message_id последнего сообщения с ReplyKeyboardMarkup

# ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя - "сделай так чтобы
# события грузились все бот не удалял и оставлял тока два последних"): по
# умолчанию KEEP_LAST_N_MESSAGES=2 стирает ВСЕ сообщения бота без разбора,
# включая карточки афиши ("🎭 СОБЫТИЯ ГОРОДА" - до 20 отдельных сообщений
# одно за другим), из-за чего в чате оставались только 2 последние карточки,
# а остальные исчезали почти сразу после отправки. Нужно исключение именно
# для этого экрана - карточки событий должны оставаться в чате все, не
# участвуя в общей чистке. Реализовано через contextvar (а не отдельным
# параметром у каждого из ~285 message.answer() в файле): хендлер, который
# шлёт события, оборачивает свою рассылку в _skip_message_trim.set(True)/
# reset(token), а middleware ниже читает этот флаг перед каждой отправкой -
# сообщения, отправленные внутри такого блока, не попадают в очередь на
# удаление вообще (та же ветка, что уже была у сообщений с ReplyKeyboardMarkup).
_skip_message_trim = contextvars.ContextVar('skip_message_trim', default=False)

# ИЗМЕНЕНО 21.09.2026 (готовим бота к нагрузке ~1000 пользователей) -
# save_recent_bot_message/delete_recent_bot_message_row (см. ниже) делают
# синхронный sqlite3.connect+execute+commit+close. SingleMessageMiddleware
# вызывает их на КАЖДОЕ исходящее сообщение бота - это самый горячий путь
# во всём файле (буквально любой ответ любому пользователю). Раньше это
# было await'ом прямо в middleware, блокируя единственный event loop для
# ВСЕХ пользователей на время диска. Теперь уходит в фоновый поток и не
# ожидается (fire-and-forget) - middleware возвращает результат отправки
# сообщения сразу, не дожидаясь записи в БД; сама запись - только
# бухгалтерия для восстановления после рестарта (см. load_all_recent_bot_
# messages), не влияет на корректность работы бота в моменте, так что
# ждать её незачем. _background_tasks хранит сильную ссылку на task, пока
# он не завершится - без этого asyncio может (в редких случаях) собрать
# task сборщиком мусора до его выполнения.
_background_tasks = set()

def _fire_and_forget(coro):
    task = asyncio.create_task(coro)
    _background_tasks.add(task)
    task.add_done_callback(_background_tasks.discard)

# ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "сделаем чтобы он всё
# это делал только с 1 минутным таймером удаления чтобы успели прочитать"),
# ИЗМЕНЕНО 22.09.2026 (тот же день, повторная просьба - "сократим время
# удаление сообщение с 60 секунд до 30 секунд"): везде, где общая чистка
# чата (SingleMessageMiddleware, ChatCleanupIncomingMiddleware,
# track_bot_update_message, startup-пасс в main()) раньше удаляла
# "выпавшие" сообщения СРАЗУ, теперь ставим удаление через задержку
# DELETE_MESSAGE_DELAY_SECONDS, чтобы у человека было время прочитать
# сообщение, прежде чем оно исчезнет. Сама постановка в очередь (кого в
# итоге удалить) не меняется - меняется только момент физического
# bot.delete_message. fire-and-forget (через _fire_and_forget) - ждать
# результат не нужно, это фоновая уборка.
# ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - "оставлял на 5 минут"):
# было 30 секунд, теперь 5 минут - больше времени прочитать сообщение,
# прежде чем оно удалится из чата.
DELETE_MESSAGE_DELAY_SECONDS = 300

async def _delayed_delete_message(chat_id, message_id, delay=DELETE_MESSAGE_DELAY_SECONDS):
    await asyncio.sleep(delay)
    try:
        await bot.delete_message(chat_id=chat_id, message_id=message_id)
    except Exception:
        pass  # сообщение уже удалено/недоступно для удаления - не критично

def _schedule_delete_message(chat_id, message_id, delay=DELETE_MESSAGE_DELAY_SECONDS):
    if not bot:
        return
    _fire_and_forget(_delayed_delete_message(chat_id, message_id, delay))

# ==================== MENU BUTTON ЛИЧНОГО КАБИНЕТА (21.09.2026) ====================
# По просьбе пользователя - открывать "Личный кабинет" в один тап, а не
# через промежуточное сообщение с инлайн-кнопкой (см. open_cabinet_from_menu
# выше в файле). У кнопок с web_app= в Reply-клавиатуре initData приходит
# пустым (проверено на реальном устройстве - см. комментарий у cabinet_row в
# services_keyboard), а вот "кнопка меню" слева от поля ввода (Menu Button,
# bot.set_chat_menu_button) с web_app= передаёт initData так же штатно, как
# инлайн-кнопки - и открывается в один тап, без промежуточного сообщения.
# Устанавливается ПЕРСОНАЛЬНО на чат (chat_id=user_id), т.к. сама ссылка
# зависит от тарифов конкретной категории водителя (?tariffs=...) - в
# отличие от команд бота, Menu Button можно задавать per-chat.
_cabinet_menu_button_cache = {}  # user_id -> последний выставленный cabinet_url, чтобы не дёргать API повторно с тем же URL

async def set_cabinet_menu_button(user_id, cabinet_url):
    if _cabinet_menu_button_cache.get(user_id) == cabinet_url:
        return
    try:
        await bot.set_chat_menu_button(
            chat_id=user_id,
            menu_button=MenuButtonWebApp(text="Кабинет", web_app=WebAppInfo(url=cabinet_url)),
        )
        _cabinet_menu_button_cache[user_id] = cabinet_url
    except Exception as e:
        logger.warning(f"⚠️ Не удалось выставить Menu Button личного кабинета для {user_id}: {e}")

# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "сделать чтобы всегда
# ... снизу эта кнопка была всегда", уточнено в диалоге: кнопка должна жить
# В САМИХ сообщениях, инлайн, НЕ в нижней reply-клавиатуре) - инлайн-кнопка
# "🚕 МЕНЮ TAXI HELPER", которая всегда есть на исходящих сообщениях бота,
# кроме тех, что уже несут ReplyKeyboardMarkup (её сюда специально не лезем -
# reply-клавиатура и так уже даёт доступ к меню, и Telegram не разрешает
# одному сообщению одновременно ReplyKeyboardMarkup и InlineKeyboardMarkup).
# Реализовано ЦЕНТРАЛИЗОВАННО в SingleMessageMiddleware (а не в каждом из
# ~285 message.answer() по файлу) - для сообщений без разметки кнопка
# добавляется как единственная, для сообщений с уже своей InlineKeyboardMarkup
# - отдельной строкой снизу существующих кнопок.
MAIN_MENU_INLINE_BUTTON_TEXT = "🚕 МЕНЮ TAXI HELPER"
MAIN_MENU_INLINE_BUTTON_CALLBACK = "open_services_menu"

# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "надо чтобы бот
# проверял, если вдруг [нижнее меню] пропала, то выкидывал это сообщение [с
# кнопкой]") - у Telegram Bot API нет способа спросить "жива ли ещё нижняя
# ReplyKeyboardMarkup у пользователя" (её можно потерять, если пользователь
# сам очистил историю чата/удалил сообщение с меню - бот об этом никак не
# узнаёт). Подстраховка: считаем нижнее меню "точно ещё на месте" только
# REPLY_KEYBOARD_STALE_HOURS часов после последней отправки - после этого
# инлайн-кнопка "МЕНЮ TAXI HELPER" на обычных сообщениях включается снова
# (см. reply_keyboard_already_open ниже), даже если меню технически всё ещё
# никуда не делось - лишняя кнопка раз в сутки не мешает, а вот полное
# отсутствие способа вернуться в меню - серьёзный тупик для пользователя.
REPLY_KEYBOARD_STALE_HOURS = 12
_last_reply_keyboard_sent_at = {}  # chat_id -> datetime последней отправки сообщения с ReplyKeyboardMarkup

def _with_main_menu_button(reply_markup):
    """Возвращает reply_markup с добавленной строкой "МЕНЮ TAXI HELPER" -
    ReplyKeyboardMarkup не трогаем (возвращаем как есть), к
    InlineKeyboardMarkup дописываем строку снизу, при отсутствии разметки
    создаём новую с одной этой кнопкой. Всегда возвращает НОВЫЙ объект (не
    мутирует переданный) - на случай, если markup переиспользуется где-то
    ещё как общий объект."""
    menu_row = [InlineKeyboardButton(text=MAIN_MENU_INLINE_BUTTON_TEXT, callback_data=MAIN_MENU_INLINE_BUTTON_CALLBACK)]
    if reply_markup is None:
        return InlineKeyboardMarkup(inline_keyboard=[menu_row])
    if isinstance(reply_markup, InlineKeyboardMarkup):
        return InlineKeyboardMarkup(inline_keyboard=list(reply_markup.inline_keyboard) + [menu_row])
    return reply_markup  # ReplyKeyboardMarkup и прочее - без изменений

class SingleMessageMiddleware(BaseRequestMiddleware):
    async def __call__(self, make_request, bot_instance: Bot, method: TelegramMethod[TelegramType]):
        if isinstance(method, SendMessage):
            chat_id = method.chat_id
            has_reply_keyboard = isinstance(method.reply_markup, ReplyKeyboardMarkup)
            # УТОЧНЕНО 23.09.2026 (прямая просьба пользователя - "кнопка
            # появляется, если меню кнопок снизу не открыто") - нижняя
            # reply-клавиатура в Telegram, once отправлена, остаётся у
            # пользователя пристыкованной постоянно (не привязана к
            # конкретному сообщению) - то есть уже даёт доступ к меню.
            # Поэтому инлайн-кнопку "МЕНЮ TAXI HELPER" добавляем ТОЛЬКО пока
            # у этого чата ещё ни разу не было отправлено такое меню
            # (_last_reply_keyboard_msg_id ещё пусто для chat_id) - как
            # только оно появилось, дублировать доступ к меню инлайн-кнопкой
            # на каждом сообщении больше не нужно.
            # См. REPLY_KEYBOARD_STALE_HOURS выше - "открыто" не навсегда, а
            # только пока последняя отправка не устарела (подстраховка на
            # случай, если меню у пользователя реально пропало, а бот об
            # этом узнать не может).
            last_sent_at = _last_reply_keyboard_sent_at.get(chat_id)
            reply_keyboard_already_open = (
                chat_id in _last_reply_keyboard_msg_id
                and last_sent_at is not None
                and (datetime.utcnow() - last_sent_at) < timedelta(hours=REPLY_KEYBOARD_STALE_HOURS)
            )
            if not has_reply_keyboard and not reply_keyboard_already_open:
                method.reply_markup = _with_main_menu_button(method.reply_markup)
            skip_trim = _skip_message_trim.get()
            result = await make_request(bot_instance, method)
            try:
                if has_reply_keyboard:
                    # ДОБАВЛЕНО 22.09.2026 (см. комментарий у
                    # _last_reply_keyboard_msg_id выше) - меню само по себе
                    # никогда не в общей очереди (чтобы не пропало), но
                    # предыдущее сообщение с меню в ЭТОМ чате теперь можно
                    # спокойно удалить - новое (вот это) уже доставлено, оно
                    # его полностью заменяет.
                    prev_id = _last_reply_keyboard_msg_id.get(chat_id)
                    _last_reply_keyboard_msg_id[chat_id] = result.message_id
                    _last_reply_keyboard_sent_at[chat_id] = datetime.utcnow()
                    # ИСПРАВЛЕНО 22.09.2026 - без записи в БД это значение
                    # терялось при каждом рестарте Railway, и первое
                    # menu-сообщение после рестарта никогда не удаляло то,
                    # что было отправлено ДО него (см. CREATE TABLE
                    # last_reply_keyboard_messages в init_db).
                    _fire_and_forget(asyncio.to_thread(save_last_reply_keyboard_message, chat_id, result.message_id))
                    if prev_id is not None and prev_id != result.message_id:
                        _schedule_delete_message(chat_id, prev_id)
                elif skip_trim:
                    # Карточки событий (_skip_message_trim) - как и раньше,
                    # не участвуют в чистке вообще, остаются все.
                    pass
                else:
                    queue = _recent_bot_message_ids.setdefault(chat_id, [])
                    queue.append(result.message_id)
                    _fire_and_forget(asyncio.to_thread(save_recent_bot_message, chat_id, result.message_id))
                    # Удаляем всё, что выпало за пределы последних KEEP_LAST_N_MESSAGES
                    # (с задержкой DELETE_MESSAGE_DELAY_SECONDS - см. комментарий
                    # у _schedule_delete_message выше, "чтобы успели прочитать").
                    while len(queue) > KEEP_LAST_N_MESSAGES:
                        old_id = queue.pop(0)
                        _fire_and_forget(asyncio.to_thread(delete_recent_bot_message_row, chat_id, old_id))
                        _schedule_delete_message(chat_id, old_id)
            except Exception:
                pass
            return result
        return await make_request(bot_instance, method)

# ДОБАВЛЕНО 21.09.2026 (просьба пользователя - "надо чтобы бот всегда чистил
# все сообщения в чате оставлял тока два последних"): SingleMessageMiddleware
# выше чистит только СОБСТВЕННЫЕ исходящие сообщения бота - входящие
# сообщения пользователя (нажатия reply-кнопок вроде "ОТДАТЬ ЗАКАЗ"/"ЧАЕВЫЕ",
# любой текст, который человек сам печатает боту) этой логикой не
# затрагивались и копились в чате бесконечно. Этот outer middleware
# добавляет id ВХОДЯЩЕГО сообщения пользователя в ТУ ЖЕ общую очередь
# _recent_bot_message_ids[chat_id], что и SingleMessageMiddleware, - так
# бот и пользователь считаются вместе, и в чате гарантированно остаются
# только последние KEEP_LAST_N_MESSAGES сообщений суммарно, независимо от
# того, кто их отправил.
#
# Исключение: сообщения с активной трансляцией геопозиции
# (message.location is not None, live_period) - Telegram привязывает саму
# трансляцию к этому сообщению, удаление оборвёт "Трансляция геопозиции" у
# пользователя (водитель встал в очередь аэропорта/едет на карте). Такие
# сообщения не добавляются в очередь на удаление и не удаляются.
#
# Зарегистрирован как dp.message.outer_middleware (см. main(), рядом с
# SubscriptionMiddleware) - отрабатывает на каждое входящее сообщение
# ДО хендлера, после чего хендлер отрабатывает как обычно.
class ChatCleanupIncomingMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        message = event if isinstance(event, types.Message) else None
        if message is None or message.location is not None:
            return await handler(event, data)
        chat_id = message.chat.id
        try:
            queue = _recent_bot_message_ids.setdefault(chat_id, [])
            queue.append(message.message_id)
            _fire_and_forget(asyncio.to_thread(save_recent_bot_message, chat_id, message.message_id))
            while len(queue) > KEEP_LAST_N_MESSAGES:
                old_id = queue.pop(0)
                _fire_and_forget(asyncio.to_thread(delete_recent_bot_message_row, chat_id, old_id))
                if old_id == message.message_id:
                    # Само это входящее сообщение уже выпало за пределы
                    # очереди (KEEP_LAST_N_MESSAGES=1 или похожая ситуация) -
                    # удалять его ДО обработки хендлером нельзя, хендлер
                    # ещё должен на него отреагировать. Просто пропускаем
                    # удаление в этом единственном случае.
                    continue
                _schedule_delete_message(chat_id, old_id)
        except Exception:
            pass
        return await handler(event, data)

async def initialize_bot():
    global bot
    try:
        logger.info("📡 Инициализирую бота...")
        bot = Bot(token=BOT_TOKEN)
        bot.session.middleware(SingleMessageMiddleware())
        me = await bot.get_me()
        logger.info(f"✅ Бот: @{me.username}")
        # На боте где-то раньше (вручную или другим запуском) был включён
        # webhook - Telegram не даёт одновременно webhook и getUpdates
        # (polling, см. dp.start_polling ниже), из-за чего в логах Railway
        # сыпался TelegramConflictError "can't use getUpdates method while
        # webhook is active". Снимаем webhook явно при каждом старте - если
        # его и не было, вызов просто ничего не делает (безопасно вызывать
        # всегда), а если был - синхронизирует бота обратно на polling.
        try:
            webhook_info = await bot.get_webhook_info()
            if webhook_info.url:
                logger.warning(f"⚠️ Обнаружен активный webhook ({webhook_info.url}) - удаляю, бот работает через polling")
                await bot.delete_webhook(drop_pending_updates=False)
                logger.info("✅ Webhook удалён")
        except Exception as e:
            logger.error(f"❌ Не удалось проверить/удалить webhook: {e}")
        return True
    except Exception as e:
        logger.error(f"❌ Ошибка: {e}")
        return False

