# ---- Свои паттерны спроса для Курьера и Грузового такси (по просьбе
# пользователя, 20.09.2026: "дай расклад для курьеров... и для грузовых
# такси" - уточнено через AskUserQuestion, что нужны СВОИ правила для
# каждой категории, не общегородской шаблон такси выше). У этих категорий
# нет данных по аэропортам/прилётам, так что источник спроса принципиально
# другой:
#   - Курьер: пик заказов доставки еды - обед и ужин каждый день. Пятница/
#     суббота/воскресенье - по прямому уточнению пользователя (20.09.2026:
#     "пятница суббота воскресенье как и для курьеров эти дни самые
#     доходные") - весь день спрос выше обычного (люди чаще заказывают
#     еду на дом/на встречи в выходные, не только в обед/ужин), и
#     дополнительно поздняя ночь 23:00-02:00 - отдельный доходный отрезок
#     после баров/вечеринок.
#   - Грузовое такси: в будни - рабочие часы бизнеса/складов/ТЦ
#     (9:00-18:00) - основной спрос от компаний. Пятница/суббота/
#     воскресенье - по прямому уточнению пользователя - НЕ склады (они
#     закрыты), а частные переезды и перевозка мебели/техники: люди
#     переезжают и возят крупные покупки именно в выходные, пик
#     10:00-20:00.
# Обе шкалы используют ту же структуру (start_h, end_h, level, label) и тот
# же PEAK_LEVEL_EMOJI/LABEL, что и WEEKDAY_HOUR_LOAD - переиспользуются те
# же функции форматирования/скоринга (см. get_current_peak_level_for,
# format_peak_hours_text_for ниже).
