# Категория -> своя таблица паттернов (см. комментарий выше). Такси/Ultima
# и любая не перечисленная категория используют общий WEEKDAY_HOUR_LOAD.
CATEGORY_WEEKDAY_HOUR_LOAD = {
    'courier': COURIER_WEEKDAY_HOUR_LOAD,
    'cargo': CARGO_WEEKDAY_HOUR_LOAD,
}

def get_weekday_hour_load(category, city=None):
    """Возвращает таблицу паттернов (WEEKDAY_HOUR_LOAD-совместимую) для
    данной категории - свою для courier/cargo, реальные данные
    MOSCOW_TAXI_HOUR_LOAD для Москвы + обычного такси (category в (None,
    'taxi')), реальные данные MOSCOW_ULTIMA_HOUR_LOAD для Москвы + Ultima
    (category == 'ultima'), общую WEEKDAY_HOUR_LOAD для остальных (другие
    города) - см. CATEGORY_WEEKDAY_HOUR_LOAD, MOSCOW_TAXI_DEMAND_PERCENT и
    MOSCOW_ULTIMA_DEMAND_PERCENT выше."""
    if city == 'moscow':
        if category in (None, 'taxi'):
            return MOSCOW_TAXI_HOUR_LOAD
        if category == 'ultima':
            return MOSCOW_ULTIMA_HOUR_LOAD
    return CATEGORY_WEEKDAY_HOUR_LOAD.get(category, WEEKDAY_HOUR_LOAD)

def get_city_now(city):
    """Текущее время в часовом поясе города - переиспользует AIRPORT_TIMEZONE
    через первый аэропорт города (все города бота однозонные по времени -
    даже там, где несколько аэропортов/зон Шереметьево, часовой пояс один
    и тот же на весь город), тем же паттерном, что get_airport_now."""
    airports = AIRPORTS_INFO.get(city) or []
    tz_name = AIRPORT_TIMEZONE.get(airports[0]['icao'], 'Europe/Moscow') if airports else 'Europe/Moscow'
    try:
        return datetime.now(ZoneInfo(tz_name))
    except Exception:
        return datetime.now()

CATEGORY_PEAK_HOURS_SUBTITLE = {
    # Подзаголовок под заголовком "ЧАСЫ ПИКА" - поясняет водителю, что для
    # courier/cargo это НЕ общегородской спрос такси, а расклад именно под
    # его категорию (см. CATEGORY_WEEKDAY_HOUR_LOAD выше).
    'courier': '_по времени активных заказов доставки еды (обед/ужин, пт-вс доходнее)_\n',
    'cargo': '_будни - рабочие часы бизнеса, пт-вс - переезды и перевозка мебели/техники_\n',
}

def format_peak_hours_text(city, target_weekday=None, category=None):
    """Текст с часами пика для города. target_weekday=None - текущий день
    (по местному времени города); 0-6 - конкретный день недели (для кнопок
    "смотреть другой день"). Показывает ТОЛЬКО заданные в таблице диапазоны -
    часы вне списка не перечисляются (обычный/средний спрос, отдельная
    строка не нужна). category - своя таблица для courier/cargo (см.
    get_weekday_hour_load/CATEGORY_PEAK_HOURS_SUBTITLE), иначе общая
    таблица такси/Ultima, как раньше."""
    now = get_city_now(city)
    weekday = target_weekday if target_weekday is not None else now.weekday()
    city_name = CITY_DISPLAY_NAMES.get(city, city)
    is_moscow_real_data = city == 'moscow' and category in (None, 'taxi', 'ultima')
    pattern = get_weekday_hour_load(category, city=city)[weekday]

    lines = [f"📅 *Часы пика — {city_name}, {WEEKDAY_NAMES[weekday]}*"]
    subtitle = CATEGORY_PEAK_HOURS_SUBTITLE.get(category)
    if is_moscow_real_data and category == 'ultima':
        lines.append('_реальные данные по спросу на Ultima (Business/Premier/Élite), % от максимума за сутки_\n')
    elif is_moscow_real_data:
        lines.append('_реальные данные по спросу на такси (эконом/комфорт/комфорт+), % от максимума за сутки_\n')
    elif subtitle:
        lines.append(subtitle)
    else:
        lines.append("")
    for start_h, end_h, level, label in pattern:
        emoji = PEAK_LEVEL_EMOJI[level]
        if start_h < end_h:
            time_range = f"{start_h:02d}:00–{end_h:02d}:00"
        else:  # диапазон через полночь (например, 22-24 + 0-1 показаны отдельными строками - не переносим через день)
            time_range = f"{start_h:02d}:00–{end_h:02d}:00"
        lines.append(f"{emoji} {time_range} — {label}")

    if target_weekday is None:
        cur_hour = now.hour
        cur_level = None
        for start_h, end_h, level, label in pattern:
            if start_h <= cur_hour < end_h:
                cur_level = level
                break
        if cur_level:
            lines.append(f"\n_Сейчас ({now.strftime('%H:%M')}): {PEAK_LEVEL_EMOJI[cur_level]} {PEAK_LEVEL_LABEL[cur_level]}_")
        else:
            lines.append(f"\n_Сейчас ({now.strftime('%H:%M')}): {PEAK_LEVEL_EMOJI['mid']} {PEAK_LEVEL_LABEL['mid']}_")

    if category == 'courier':
        lines.append(
            "\n_Ориентир по типичным часам заказов доставки еды - реальный "
            "спрос зависит от сервиса и района, погода может сдвинуть пик._"
        )
    elif category == 'cargo':
        lines.append(
            "\n_Ориентир по рабочим часам бизнеса и складов - реальный спрос "
            "зависит от конкретных заказчиков и логистики в городе._"
        )
    elif is_moscow_real_data:
        lines.append(
            "\n_Реальные данные по спросу на такси в Москве - конкретный день "
            "может отличаться (погода, события, пробки)._"
        )
    else:
        lines.append(
            "\n_Общая модель по данным Яндекс.Такси и статистике заказов по России - "
            "ориентир, не точный прогноз для конкретной минуты. Погода (дождь/снег) "
            "может резко повысить спрос вне этих часов._"
        )
    return '\n'.join(lines)

def get_current_peak_level(city, category=None):
    """Уровень спроса ('low'/'mid'/'high'/'peak') ПРЯМО СЕЙЧАС по местному
    времени города, по модели WEEKDAY_HOUR_LOAD (такси/Ultima) или своей
    таблице для courier/cargo (см. get_weekday_hour_load) - переиспользуется
    в компоновке "Куда ехать" (see WHERE_TO_GO_* ниже), чтобы не дублировать
    поиск текущего диапазона. category=None - как раньше, общая таблица
    такси."""
    now = get_city_now(city)
    pattern = get_weekday_hour_load(category, city=city)[now.weekday()]
    for start_h, end_h, level, _label in pattern:
        if start_h <= now.hour < end_h:
            return level
    return 'mid'

PEAK_HOUR_PUSH_LEAD_MINUTES = 30  # за сколько минут до начала уведомляем - см. peak_hour_alert_checker ниже

def find_upcoming_peak_start(city, category=None, lead_minutes=PEAK_HOUR_PUSH_LEAD_MINUTES):
    """Ищет ближайшее НАЧАЛО диапазона уровня 'peak' (час пик, не просто
    high/mid) в пределах lead_minutes от текущего момента - для пуша "через
    30 минут начинается час пик". Проверяет только СЕГОДНЯШНИЙ день недели
    и завтрашний (на случай, если пик начинается сразу после полуночи,
    например суббота 00:00 - конец пятницы) - lead_minutes всегда меньше
    часа, этого достаточно, дальше можно не смотреть.

    ИСПРАВЛЕНО 23.09.2026 (жалоба пользователя, скриншот - "я выбрал
    Ultima, зачем мне эконом/комфорт"): раньше всегда бралась таблица такси
    (get_weekday_hour_load(None, ...)), даже для водителей Ultima - в
    Москве у такси и Ultima РАЗНЫЕ реальные данные (MOSCOW_TAXI_HOUR_LOAD/
    MOSCOW_ULTIMA_HOUR_LOAD, см. get_weekday_hour_load), из-за чего Ultima
    получала пуш с эконом/комфорт/комфорт+ вместо Business/Premier/Elite.
    Теперь category передаётся явно - см. check_peak_hour_alerts ниже,
    который теперь проверяет 'taxi' и 'ultima' раздельно.

    Возвращает dict {target_date, target_hour, label} или None. target_date/
    target_hour - для дедупа (see was_peak_hour_alert_sent), должны совпадать
    с калиндарной датой/часом НАЧАЛА диапазона (а не датой "сейчас")."""
    now = get_city_now(city)
    window_end = now + timedelta(minutes=lead_minutes)
    hour_load = get_weekday_hour_load(category, city=city)

    for check_date, weekday in ((now, now.weekday()), (window_end, window_end.weekday())):
        pattern = hour_load[weekday]
        for start_h, end_h, level, label in pattern:
            if level != 'peak':
                continue
            # Момент начала диапазона в системе того же дня, что и check_date -
            # start_h может быть 0 (полночь) для диапазонов, начинающихся
            # сразу после смены дня (см. _WEEKDAY_PATTERN_SATURDAY).
            start_dt = check_date.replace(hour=start_h, minute=0, second=0, microsecond=0)
            if now < start_dt <= window_end:
                return {
                    'target_date': start_dt.strftime('%Y-%m-%d'),
                    'target_hour': start_h,
                    'label': label,
                    'start_dt': start_dt,
                }
    return None

def peak_hours_weekday_keyboard(current_weekday, category=None):
    """Инлайн-кнопки переключения дня недели - 7 кнопок, текущий день
    отмечен, остальные ведут на peak_day_{0-6}[_{category}]. category
    добавлен в callback_data только для courier/cargo (у них своя таблица
    часов пика - см. CATEGORY_WEEKDAY_HOUR_LOAD) - для остальных категорий
    формат callback_data не меняется, чтобы не задеть уже рабочую логику
    такси/Ultima."""
    suffix = f"_{category}" if category in CATEGORY_WEEKDAY_HOUR_LOAD else ""
    buttons = []
    row = []
    for i, short_name in enumerate(WEEKDAY_SHORT_NAMES):
        label = f"• {short_name} •" if i == current_weekday else short_name
        row.append(InlineKeyboardButton(text=label, callback_data=f"peak_day_{i}{suffix}"))
        if len(row) == 4:
            buttons.append(row)
            row = []
    if row:
        buttons.append(row)
    return InlineKeyboardMarkup(inline_keyboard=buttons)

def services_keyboard(category=None, city=None, user_id=None):
    # (21.09.2026) По просьбе пользователя ВСЕ подписи кнопок (Reply- и
    # Inline-клавиатуры) по всему боту написаны ЗАГЛАВНЫМИ БУКВАМИ - эмодзи
    # и знаки препинания не трогаем, меняем регистр только у букв (.upper()).
    # ВАЖНО: текст кнопки - это "ключ", по которому её ищут обработчики
    # (message.text == "...", словари вида NEARBY_BUTTON_TO_KIND), поэтому
    # при любом изменении текста кнопки нужно поменять ВСЕ места, где эта
    # строка сравнивается/используется как ключ, иначе кнопка перестанет
    # работать молча.
    # Итоговый набор кнопок меню услуг (по заданному порядку). "Заказы
    # города" (было "ПОВЫШЕННЫЙ СПРОС") убрана по просьбе пользователя - была
    # заглушкой без своей логики. "Дорожные события" тоже пока без
    # обработчика - как было. "🎭 СОБЫТИЯ ГОРОДА" (афиша TimePad) - только
    # у Такси/Ultima, курьеру и грузовому такси не актуальна (см.
    # CATEGORIES_WITHOUT_EVENTS). "✈️🚆 АВИА/ЖД" объединяет аэропорты и
    # вокзалы в одну кнопку главного меню (короче список) - при нажатии
    # show_transport_menu показывает инлайн-подменю с двумя вариантами;
    # "🚆 ВОКЗАЛЫ" внутри него виден, только если город в TRAIN_CITIES (см.
    # STATION_CITY) - иначе только "✈️ АЭРОПОРТЫ". "🔄 ОТДАТЬ ЗАКАЗ" - теперь
    # доступна ВСЕМ категориям (по просьбе пользователя 22.09.2026, см.
    # SHARE_ORDER_CAR_CLASSES).
    # "🧰 ИНСТРУМЕНТЫ ВОДИТЕЛЯ" - отдельный модуль (см.
    # COURIER_MODULE_CATEGORIES) с финансовым калькулятором смены +
    # заглушки под карту точек; изначально делался под курьеров, но по
    # просьбе пользователя открыт всем категориям (калькулятор дохода/км/
    # топлива/часов одинаково полезен и такси, и грузовому такси).
    # "🌤 ПОГОДА" - на верхнем уровне (не внутри "Инструменты водителя") по
    # просьбе пользователя - почасовой прогноз + автопуш за RAIN_LEAD_MINUTES
    # минут до начала осадков (см. блок "ПОГОДА / ОСАДКИ" выше по файлу).
    # Раскладка в 2 колонки (по просьбе пользователя, тот же приём, что и в
    # courier_module_keyboard) - пункты сначала собираются в плоский список
    # (с учётом всех условий по категории выше), а потом режутся по 2 в ряд,
    # так что раскладка остаётся 2-колоночной независимо от того, сколько
    # именно кнопок видно конкретной категории.
    # "🔓 БЕСПЛАТНЫЙ VPN TAXI HELPER" - НЕ в общей 2-колоночной сетке ниже, а
    # отдельной строкой в самом низу (перед "← НАЗАД"/"🏙 ВЫБОР ГОРОДА") - по
    # просьбе пользователя.
    # "▶️ НАЧАТЬ СМЕНУ"/"⏹ Завершить смену" - САМАЯ верхняя строка меню, ВЫШЕ
    # "💰 КУДА ЕХАТЬ ➡️" (по прямой просьбе пользователя, 20.09.2026) - одна
    # кнопка-переключатель (текст меняется в зависимости от того, идёт ли
    # смена, см. is_shift_active/toggle_shift), доступна ВСЕМ категориям (в
    # отличие от "Куда ехать" - секундомер и километраж смены равно полезны
    # курьеру/грузовому такси).
    # "💰 КУДА ЕХАТЬ ➡️" - следующей строкой (по просьбе пользователя) -
    # раньше была внутри "Инструменты водителя", перенесена сюда как самая
    # важная кнопка (решает, куда именно ехать прямо сейчас). Доступна
    # только категориям с аэропортами (см. CATEGORIES_WITHOUT_AIRPORTS) -
    # сводка построена на аэропортах/вокзалах/часах пика для ПАССАЖИРСКИХ
    # поездок, для курьера/грузового такси не актуальна (см. обсуждение с
    # пользователем 19.09.2026).
    # user_id - опциональный (по умолчанию None), чтобы не переписывать
    # КАЖДЫЙ из ~19 существующих вызовов services_keyboard(category, city) в
    # файле: без него кнопка безопасно показывает "▶️ НАЧАТЬ СМЕНУ" (тот же
    # эффект, как если бы смена не шла) - минорная неточность на редких
    # экранах, где именно этот вызов не передал user_id, а не падение.
    # По просьбе пользователя (20.09.2026): "Начать смену" и "Куда ехать" -
    # каждая на всю ширину, друг под другом (было в одном ряду) - крупнее и
    # заметнее как самые важные кнопки главного меню.
    # "💰 КУДА ЕХАТЬ ➡️" теперь видна ВСЕМ категориям (20.09.2026) - раньше
    # была скрыта для courier/cargo (не было данных для расчёта), теперь у
    # них есть своя версия сводки на своих часах пика (см.
    # compute_where_to_go/score_city_candidate) - убрано условие
    # "category not in CATEGORIES_WITHOUT_AIRPORTS" для этой кнопки.
    shift_active = is_shift_active(user_state.get(user_id, {})) if user_id is not None else False
    top_rows = [[KeyboardButton(text="⏹ ЗАВЕРШИТЬ СМЕНУ" if shift_active else "✅ НАЧАТЬ СМЕНУ")]]
    # "🗺 КАРТА ВОДИТЕЛЕЙ" (по просьбе пользователя, 21.09.2026) - в одном
    # ряду с "💰 КУДА ЕХАТЬ ➡️", а не отдельной строкой внизу меню - открывает
    # интерактивную WebApp-карту через web_app=WebAppInfo (единственный
    # надёжный способ открыть кастомную веб-страницу внутри Telegram).
    # Показывается только если PUBLIC_URL задан (Telegram требует HTTPS для
    # WebApp - на локальном/без Public Networking запуске такой ссылки нет) и
    # известен город (карта показывает водителей конкретного города). Сама
    # видимость НА карте включается/выключается сменой (см. "▶️ Начать
    # смену"/"⏹ Завершить смену" - блок "СМЕНА" ниже), кнопка тут просто
    # открывает карту.
    # "💰 КУДА ЕХАТЬ ➡️" сама стала WebApp (по просьбе пользователя,
    # 21.09.2026, "и куда ехать тоже сделай миниапс") - тот же принцип, что
    # у "🌤 ПОГОДА" выше: город/категория не персональные данные (берутся из
    # ?city=&category= в URL, как у карты), поэтому initData не нужен и
    # можно вешать web_app= прямо на кнопку Reply-клавиатуры. Если
    # PUBLIC_URL/city не заданы - остаётся старая текстовая кнопка (шлёт
    # обычное сообщение через send_where_to_go, как раньше) - этот же
    # текстовый хендлер (@router.message(lambda message: message.text ==
    # "💰 КУДА ЕХАТЬ ➡️")) НЕ удалён и продолжает работать всегда, в т.ч.
    # как фолбэк, если WebApp по какой-то причине не откроется.
    if PUBLIC_URL and city and category:
        where_to_go_url = f"{PUBLIC_URL}{WHERE_TO_GO_WEBAPP_PATH}?city={urllib.parse.quote(city)}&category={urllib.parse.quote(category)}"
        where_to_go_row = [KeyboardButton(text="💰 КУДА ЕХАТЬ ➡️", web_app=WebAppInfo(url=where_to_go_url))]
    else:
        where_to_go_row = [KeyboardButton(text="💰 КУДА ЕХАТЬ ➡️")]
    if category in MAP_CATEGORY_STYLE and PUBLIC_URL and city:
        map_url = f"{PUBLIC_URL}{MAP_WEBAPP_PATH}?city={urllib.parse.quote(city)}&category={urllib.parse.quote(category)}"
        where_to_go_row.append(KeyboardButton(text="🗺 КАРТА ВОДИТЕЛЕЙ", web_app=WebAppInfo(url=map_url)))
    top_rows.append(where_to_go_row)

    # По просьбе пользователя (21.09.2026): "надо обьеденить кнопки
    # инструменты водителя и настройки сделать одну кнопку Личный кабинет и в
    # нем сделать приложение где будут все функции этих кнопок" - "🧰
    # Инструменты водителя" и "⚙️ НАСТРОЙКИ" убраны из главного меню (сами
    # хендлеры courier_module_keyboard/show_notification_settings и их
    # подпункты НЕ удалены - оставлены как есть на случай, если куда-то ещё
    # ведут внутренние переходы, просто из главного меню на них больше нет
    # прямого пути), вместо них - одна кнопка "👤 ЛИЧНЫЙ КАБИНЕТ"
    # (web_app=WebAppInfo, тот же паттерн, что у "🗺 КАРТА ВОДИТЕЛЕЙ" выше),
    # открывающая расширенный /cabinet WebApp со всеми разделами обеих кнопок
    # (включая гео-фичи "Рядом" через navigator.geolocation в браузере -
    # см. блок "ЛИЧНЫЙ КАБИНЕТ (WebApp)"). Тот же guard PUBLIC_URL and city,
    # что у карты - Telegram требует HTTPS для WebApp, локально такой ссылки
    # нет. Если PUBLIC_URL/city не заданы - кнопка просто не показывается
    # (как и у карты) - других пользователей это не оставляет без доступа,
    # т.к. раньше (до этого изменения) сами эти функции были доступны только
    # из главного меню без такого guard, но теперь единственный путь к ним -
    # эта кнопка; отсутствие PUBLIC_URL - редкий локальный/дев-запуск.
    # ВАЖНО (21.09.2026, по факту): кнопка в Reply-клавиатуре с web_app=
    # (как у "🗺 КАРТА ВОДИТЕЛЕЙ" выше) НЕ передаёт Telegram initData -
    # проверено на реальном устройстве (debug на экране кабинета показал
    # tg=ok, platform/version распознаны из хэша, но initData.len=0 и
    # initDataUnsafe.user=absent). Карта эту проблему не показывала, т.к.
    # отдаёт публичные данные без проверки подписи, а личному кабинету
    # initData обязателен (там персональные данные). Сначала кабинет
    # открывался через промежуточное сообщение с инлайн-кнопкой
    # (open_cabinet_from_menu) - у инлайн-кнопок initData передаётся
    # штатно, но это два тапа. По просьбе пользователя (21.09.2026, "в один
    # тап") - теперь используем Menu Button (кнопка слева от поля ввода,
    # bot.set_chat_menu_button) с web_app= - initData у неё тоже передаётся
    # штатно, а открывается в один тап, без лишнего сообщения. Ссылка
    # зависит от тарифов категории, поэтому выставляем ПЕРСОНАЛЬНО на чат
    # (см. set_cabinet_menu_button) - лёгкий fire-and-forget с кэшем по
    # user_id, чтобы не дёргать API Telegram на каждый показ меню с одним и
    # тем же URL. Сама кнопка "👤 ЛИЧНЫЙ КАБИНЕТ" из Reply-клавиатуры теперь
    # УБРАНА (по просьбе пользователя, "удали тогда её из меню") -
    # open_cabinet_from_menu ниже оставлен в коде на случай регресса Menu
    # Button, но с главного меню на него больше нет прямого пути.
    if PUBLIC_URL and city and user_id is not None:
        tariff_options = CATEGORIES.get(category, {}).get('tariffs', [])
        cabinet_url = f"{PUBLIC_URL}{CABINET_WEBAPP_PATH}?tariffs={urllib.parse.quote(','.join(tariff_options))}"
        _fire_and_forget(set_cabinet_menu_button(user_id, cabinet_url))

    # items теперь хранит готовые KeyboardButton (не текст) - нужно для
    # "🌤 ПОГОДА" ниже, которая в зависимости от PUBLIC_URL/city либо
    # обычная кнопка, либо WebApp (см. комментарий там).
    items = []
    items.append(KeyboardButton(text="🔄 ОТДАТЬ ЗАКАЗ"))
    # "🌤 ПОГОДА" - миниапп с анимацией (по просьбе пользователя, 21.09.2026,
    # "погоду тоже сделай миниапсом красивое анимирование") - погода не
    # персональные данные (город берётся из query-параметра URL, как у
    # карты), поэтому initData не нужен и можно вешать web_app= прямо на
    # кнопку Reply-клавиатуры (в отличие от личного кабинета - см.
    # комментарий выше про initData.len=0 у web_app в Reply-клавиатуре,
    # ограничение касается именно ПОДПИСАННЫХ данных, публичным данным оно
    # не мешает - тот же принцип, что уже у "🗺 КАРТА ВОДИТЕЛЕЙ"). Если
    # PUBLIC_URL/city не заданы - остаётся старая текстовая кнопка
    # (show_weather_forecast ниже сама разберётся, если city вдруг пуст).
    if PUBLIC_URL and city:
        weather_url = f"{PUBLIC_URL}{WEATHER_WEBAPP_PATH}?city={urllib.parse.quote(city)}"
        items.append(KeyboardButton(text="🌤 ПОГОДА", web_app=WebAppInfo(url=weather_url)))
    else:
        items.append(KeyboardButton(text="🌤 ПОГОДА"))
    # "💳 ЧАЕВЫЕ" вынесена в главное меню (по просьбе пользователя,
    # 21.09.2026) - раньше была только внутри "🧰 ИНСТРУМЕНТЫ ВОДИТЕЛЯ"
    # (сейчас недоступной с главного меню, см. комментарий выше), тот же
    # текст статьи/ссылок, что и раньше (см. show_tips_app_main_menu ниже -
    # новый хендлер без требования in_courier_module, старый "💳 Получить
    # чаевые" внутри courier_module_keyboard не трогали). НЕ добавляется в
    # общий список items (2-колоночная сетка ниже) - по повторной просьбе
    # пользователя (21.09.2026, "чаевые спусти вниз в самый выше кнопок
    # назад и выбор города") кнопка теперь отдельной строкой в самом низу
    # меню, прямо над "← НАЗАД"/"🏙 ВЫБОР ГОРОДА" (см. buttons.append ниже).
    # "✈️🚆 АВИА/ЖД" убрана отсюда (по просьбе пользователя, 21.09.2026:
    # "авиа жд и событие города в одну строчку") - раньше была в этой общей
    # 2-колоночной сетке (парой со следующей по списку кнопкой), теперь
    # ставится в один ряд с "🚨 СОБЫТИЯ ГОРОДА"/"⛔ ДОРОЖНЫЕ СОБЫТИЯ" ниже
    # (см. events_row).
    # "🎭 СОБЫТИЯ ГОРОДА" и "⛔ ДОРОЖНЫЕ СОБЫТИЯ" объединены в ОДНУ кнопку
    # главного меню (по финальному уточнению пользователя, 20.09.2026:
    # "объедини в главном меню их в одну"; эмодзи кнопки в меню уточнялся
    # пользователем дважды - сначала "⛔События города", затем финально
    # "🚨 СОБЫТИЯ ГОРОДА") - при нажатии показывает инлайн-подменю с двумя
    # вариантами (там уже свои подписи "🎭 СОБЫТИЯ ГОРОДА"/"⛔ Дорожные
    # события"), см. show_events_and_roads_menu/open_city_events_from_menu/
    # open_road_events_from_menu ниже). Для courier/cargo
    # (CATEGORIES_WITHOUT_EVENTS) афиша не актуальна - им показываем кнопку
    # "⛔ ДОРОЖНЫЕ СОБЫТИЯ" отдельно, как раньше. НЕ добавляем эту кнопку в
    # общий список items (2-колоночная сетка выше) - она в одном ряду с
    # "✈️🚆 АВИА/ЖД" (см. events_row ниже).
    events_button_text = "🚨 СОБЫТИЯ ГОРОДА" if category not in CATEGORIES_WITHOUT_EVENTS else "⛔ ДОРОЖНЫЕ СОБЫТИЯ"

    buttons = []
    buttons.extend(top_rows)
    buttons.extend(
        items[i:i + 2]
        for i in range(0, len(items), 2)
    )
    # "✈️🚆 АВИА/ЖД" + "🚨 СОБЫТИЯ ГОРОДА"/"⛔ ДОРОЖНЫЕ СОБЫТИЯ" - один ряд
    # (по прямой просьбе пользователя, 21.09.2026). Если категория без
    # аэропортов (CATEGORIES_WITHOUT_AIRPORTS), в ряду остаётся только кнопка
    # событий - без второй кнопки.
    # Обе кнопки стали WebApp (21.09.2026, тот же публичный паттерн, что у
    # "🌤 ПОГОДА"/"💰 КУДА ЕХАТЬ" выше - данные не персональные, берутся из
    # ?city=&category= в URL) - при PUBLIC_URL/city заданных вешаем web_app=
    # прямо на кнопку Reply-клавиатуры; иначе (как и везде выше) остаётся
    # старая обычная текстовая кнопка, старые текстовые хендлеры
    # (show_transport_menu/show_events_and_roads_menu/show_road_events) НЕ
    # убраны и продолжают работать как фолбэк.
    events_row = []
    if category not in CATEGORIES_WITHOUT_AIRPORTS:
        # ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "а кнопку встать
        # в очередь тоже надо вывести пусть будет и тут"): "✈️🚆 АВИА/ЖД"
        # ПЕРЕСТАЛА быть прямой web_app=-кнопкой в Reply-клавиатуре - теперь
        # мини-апп умеет ещё и ОТМЕЧАТЬ очередь (личное действие, требует
        # initData), а у Reply-клавиатуры web_app= initData НЕ передаёт (та
        # же проблема, что была у личного кабинета - initData.len=0,
        # initDataUnsafe.user=absent). Кнопка снова обычная текстовая -
        # хендлер show_transport_menu теперь сам шлёт инлайн-кнопку с
        # web_app= (тот же рабочий паттерн, что у cabinet/share-order).
        events_row.append(KeyboardButton(text="✈️🚆 АВИА/ЖД"))
    if PUBLIC_URL and city:
        events_url = f"{PUBLIC_URL}{EVENTS_WEBAPP_PATH}?city={urllib.parse.quote(city)}&category={urllib.parse.quote(category)}"
        if category in CATEGORIES_WITHOUT_EVENTS:
            events_url += "&tab=roads"
        events_row.append(KeyboardButton(text=events_button_text, web_app=WebAppInfo(url=events_url)))
    else:
        events_row.append(KeyboardButton(text=events_button_text))
    buttons.append(events_row)
    # "👤 ЛИЧНЫЙ КАБИНЕТ" здесь БОЛЬШЕ НЕТ как отдельной кнопки Reply-
    # клавиатуры (убрана по просьбе пользователя, 21.09.2026 - "удали тогда
    # её из меню") - открывается через Menu Button (см. комментарий выше,
    # set_cabinet_menu_button), кнопка слева от поля ввода сообщения.
    # "⛽ ГДЕ БЕНЗИН" + "💳 ЧАЕВЫЕ" - один ряд, прямо над "🔓 БЕСПЛАТНЫЙ VPN"
    # (по прямой просьбе пользователя, 22.09.2026 - "сделай кнопки где
    # бензин и чаевые в одну строку выше бесплатного впн"). "⛽ ГДЕ БЕНЗИН"
    # раньше была только внутри courier_module_keyboard - тот же текстовый
    # хендлер show_fuel_bot ниже по файлу срабатывает и здесь, отдельно
    # добавлять не нужно.
    buttons.append([KeyboardButton(text="⛽ ГДЕ БЕНЗИН"), KeyboardButton(text="💳 ЧАЕВЫЕ")])
    # "🤝 РЕФЕРАЛЬНАЯ ПРОГРАММА" (по просьбе пользователя, 20.09.2026) - см.
    # блок "РЕФЕРАЛЬНАЯ ПРОГРАММА" ниже (show_referral_program и остальные
    # хендлеры referral_*).
    # "💳 ОПЛАТИТЬ ПОДПИСКУ" (по прямой просьбе пользователя, 22.09.2026 -
    # "а где в боте кнопка оплатить подписку то сделай ее с кнопкой рядом
    # реферальная программа") - раньше кнопка "💳 ОПЛАТИТЬ" появлялась
    # только на экране-блокировке после окончания пробного периода
    # (SUBSCRIPTION_PAYWALL_TEXT/SubscriptionMiddleware), самостоятельной
    # кнопки в меню не было. Теперь есть отдельный экран (см.
    # show_subscription_status ниже) - можно оплатить/продлить заранее, не
    # дожидаясь блокировки, в одном ряду с реферальной программой.
    # ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - "когда она оплачена
    # выводить текст оплатить подписку поменяй на дату сколько дней осталось
    # до окончания подписки") - см. subscription_menu_button_text ниже: если
    # подписка реально ОПЛАЧЕНА (не просто триал), кнопка вместо "ОПЛАТИТЬ"
    # показывает дату окончания и сколько дней осталось.
    buttons.append([KeyboardButton(text=subscription_menu_button_text(user_id)), KeyboardButton(text="🤝 РЕФЕРАЛЬНАЯ ПРОГРАММА")])
    # "🔓 БЕСПЛАТНЫЙ VPN TAXI HELPER" - ИЗМЕНЕНО 23.09.2026 (прямая просьба
    # пользователя - "кнопку большую бесплатный vpn перенеси предпоследней
    # строчкой снизу"): раньше стояла сразу под "⛽ ГДЕ БЕНЗИН"/"💳 ЧАЕВЫЕ",
    # теперь - предпоследняя строка (прямо над "❓ ПОДДЕРЖКА"/"🏙 ВЫБОР ГОРОДА").
    buttons.append([KeyboardButton(text="🔓 БЕСПЛАТНЫЙ VPN TAXI HELPER")])
    # "❓ ПОДДЕРЖКА" (по просьбе пользователя, 22.09.2026 - "поддержка,
    # которая сама будет отвечать в боте") - ИЗМЕНЕНО 23.09.2026 (прямая
    # просьба пользователя - "на главной меню вместо кнопки назад перенеси
    # кнопку поддержка"): раньше была отдельной строкой над "← НАЗАД"/
    # "🏙 ВЫБОР ГОРОДА", теперь встала НА МЕСТО "← НАЗАД" в нижнем ряду -
    # своей отдельной строки больше нет. "🏙 ВЫБОР ГОРОДА" уже даёт по сути
    # тот же эффект возврата (открывает выбор города), поэтому отдельная
    # кнопка "Назад" на этом (главном) экране была избыточна.
    buttons.append([KeyboardButton(text="❓ ПОДДЕРЖКА"), KeyboardButton(text="🏙 ВЫБОР ГОРОДА")])
    return ReplyKeyboardMarkup(resize_keyboard=True, keyboard=buttons)

# ==================== МОДУЛЬ "ИНСТРУМЕНТЫ ВОДИТЕЛЯ" (бывш. "Курьеру") ====================
# Изначально прототип (courier-bot-package) делался под курьеров/доставку
# (Яндекс.Еда, Купер, СДЭК, WB/Ozon-логистика), но пользователь попросил
# открыть его всем категориям - формулы (доход/км/топливо/часы -> чистая
# прибыль) одинаково применимы к такси и грузовому такси, специфики именно
# под курьера в них нет. Встраивается тем же паттерном, что и остальной бот:
# JSON/state, никакой БД (в отличие от исходной спеки прототипа, где
# предполагался Postgres+PostGIS - на этом этапе не нужен, все "точечные"
# разделы ниже пока заглушки). Рабочий сейчас - только 💰 Финансы (см.
# COURIER_FINANCE_* ниже). Остальные 4 пункта меню - "в разработке" (текст
# как в самом прототипе, экран data-view="soon").
COURIER_MODULE_CATEGORIES = set(CATEGORIES.keys())  # все категории

COURIER_STUB_SECTIONS = {
    "🛠 ТО ТРАНСПОРТА",
}

# "🚻 ТУАЛЕТЫ"/"🅿️ ПАРКОВКА" переведены с заглушки на реальные точки
# (OpenStreetMap) + добавлены "🔧 ШИНОМОНТАЖ"/"🚿 МОЙКИ" - см.
# NEARBY_SERVICES/show_nearby_prompt/handle_nearby_location ниже. Кнопка
# запрашивает геолокацию, показывает ближайшие NEARBY_RESULTS_COUNT точек с
# расстоянием и часами работы (если есть в OSM) и кнопкой "Поехали" (открывает
# маршрут в Яндекс Навигаторе) на каждую.
# Раскладка в 2 колонки (по просьбе пользователя) - тексты кнопок сокращены,
# где были длинные (см. NEARBY_BUTTON_TO_KIND). "🔔 Уведомления" - отдельная
# настройка, какие типы автопушей получать (см. блок "НАСТРОЙКИ ПУШЕЙ" ниже).
def courier_module_keyboard(category=None):
    """"📍 ОЧЕРЕДЬ У АЭРОПОРТА" здесь больше НЕТ (перенесена в "⚙️ НАСТРОЙКИ",
    см. notification_settings_keyboard/toggle_airport_queue_inline, по
    просьбе пользователя 19.09.2026)."""
    buttons = [
        [KeyboardButton(text="💰 ФИНАНСЫ"), KeyboardButton(text="📈 СПРОС СЕЙЧАС")],
        [KeyboardButton(text="📅 ЧАСЫ ПИКА"), KeyboardButton(text="🚻 ТУАЛЕТЫ")],
        [KeyboardButton(text="🅿️ ПАРКОВКА"), KeyboardButton(text="🔧 ШИНОМОНТАЖ")],
        [KeyboardButton(text="🚿 МОЙКИ"), KeyboardButton(text="🍷 АЛКОМАРКЕТЫ 24Ч")],
        [KeyboardButton(text="🛒 МАГАЗИНЫ 24Ч"), KeyboardButton(text="🔌 ЭЛЕКТРОЗАРЯДКИ")],
        # "⛽ ГДЕ БЕНЗИН" перенесена сюда из главного меню (по просьбе
        # пользователя, 19.09.2026) - раньше была отдельной кнопкой в
        # services_keyboard.
        [KeyboardButton(text="🛠 ТО ТРАНСПОРТА"), KeyboardButton(text="⛽ ГДЕ БЕНЗИН")],
        # "💳 ПОЛУЧИТЬ ЧАЕВЫЕ" - по просьбе пользователя (20.09.2026) - ссылки
        # на приложение "Яндекс Чаевые: на карту по QR" (App Store/Google
        # Play), см. show_tips_app.
        [KeyboardButton(text="💳 ПОЛУЧИТЬ ЧАЕВЫЕ")],
    ]
    # "💰 КУДА ЕХАТЬ ➡️" отсюда убрана - перенесена в services_keyboard как
    # верхняя строка главного меню (по просьбе пользователя, 19.09.2026).
    # "🔔 Уведомления" тоже отсюда убрана - теперь доступна через
    # "⚙️ НАСТРОЙКИ" в главном меню (по просьбе пользователя, 19.09.2026).
    # "📍 ОЧЕРЕДЬ У АЭРОПОРТА" тоже отсюда убрана (по просьбе пользователя,
    # 19.09.2026) - переключатель перенесён в "⚙️ НАСТРОЙКИ" (см.
    # notification_settings_keyboard/toggle_airport_queue_inline).
    buttons.append([KeyboardButton(text="← НАЗАД"), KeyboardButton(text="🏙 ВЫБОР ГОРОДА")])
    return ReplyKeyboardMarkup(resize_keyboard=True, keyboard=buttons)

def notification_settings_keyboard(state, category=None):
    """Инлайн-клавиатура с переключателями по каждому типу пуша (✅/☐) -
    нажатие на кнопку тоглит именно этот тип и перерисовывает клавиатуру на
    месте (см. toggle_notification_setting), без отправки нового сообщения.
    "📍 ОЧЕРЕДЬ У АЭРОПОРТА" добавлена сюда же отдельной строкой-
    переключателем (по просьбе пользователя, 19.09.2026 - раньше была
    отдельной кнопкой в "Инструменты водителя", теперь тоже настройка) -
    скрыта для courier/cargo (см. CATEGORIES_WITHOUT_AIRPORTS), как и была."""
    buttons = []
    for key, info in NOTIFICATION_TYPES.items():
        mark = '✅' if notifications_enabled(state, key) else '☐'
        buttons.append([InlineKeyboardButton(
            text=f"{mark} {info['emoji']} {info['label']}",
            callback_data=f"notif_toggle_{key}",
        )])
    if category not in CATEGORIES_WITHOUT_AIRPORTS:
        queue_mark = '✅' if state.get('airport_queue_active') else '☐'
        buttons.append([InlineKeyboardButton(
            text=f"{queue_mark} 📍 Очередь у аэропорта",
            callback_data="notif_toggle_airport_queue",
        )])
    # "🛣 Счётчик км" как отдельный переключатель здесь БЫЛ (20.09.2026), но
    # по уточнению пользователя перепроектирован в "▶️ НАЧАТЬ СМЕНУ"/
    # "⏹ Завершить смену" в главном меню - см. блок "СМЕНА" ниже
    # (start_shift/finish_shift). Настройка отсюда убрана.
    # "🗺 Показываться на карте" отдельным тумблером здесь БЫЛА (21.09.2026),
    # но по прямому уточнению пользователя (21.09.2026) заменена на триггер
    # "▶️ НАЧАТЬ СМЕНУ"/"⏹ Завершить смену" - показ на карте включается
    # автоматически при начале смены (водитель сразу же выбирает тарифы, в
    # которых работает - см. shift_tariffs_keyboard/toggle_shift) и
    # выключается при завершении. Отдельной настройки больше нет.
    return InlineKeyboardMarkup(inline_keyboard=buttons)

# Кнопка (текст меню) -> ключ в NEARBY_SERVICES. Тексты сокращены под
# раскладку в 2 колонки (см. courier_module_keyboard) - было "🅿️ Парковка /
# остановка", стало "🅿️ ПАРКОВКА".
NEARBY_BUTTON_TO_KIND = {
    "🚻 ТУАЛЕТЫ": 'toilets',
    "🅿️ ПАРКОВКА": 'parking',
    "🔧 ШИНОМОНТАЖ": 'tires',
    "🚿 МОЙКИ": 'car_wash',
    "🍷 АЛКОМАРКЕТЫ 24Ч": 'alcohol',
    "🛒 МАГАЗИНЫ 24Ч": 'grocery24',
    "🔌 ЭЛЕКТРОЗАРЯДКИ": 'ev_charging',
}

NEARBY_SERVICES = {
    # 'noun' - винительный падеж мн. числа для фразы "найти ближайшие ___"
    # (show_nearby_prompt) - для этих слов совпадает с именительным (label).
    'toilets': {'file': 'toilets_data.json', 'label': 'Туалеты', 'emoji': '🚻', 'noun': 'туалеты'},
    'parking': {'file': 'parking_data.json', 'label': 'Бесплатные парковки', 'emoji': '🅿️', 'noun': 'бесплатные парковки'},
    'tires': {'file': 'tires_data.json', 'label': 'Шиномонтажи', 'emoji': '🔧', 'noun': 'шиномонтажи'},
    'car_wash': {'file': 'car_wash_data.json', 'label': 'Автомойки', 'emoji': '🚿', 'noun': 'автомойки'},
    # Алкомаркеты и магазины - по прямой просьбе пользователя показываем ТОЛЬКО
    # круглосуточные (фильтрация уже на этапе сбора, см. is_24h в
    # fetch_alcohol_data.py/fetch_grocery24_data.py) - label честно об этом говорит.
    'alcohol': {'file': 'alcohol_data.json', 'label': 'Алкомаркеты 24 часа', 'emoji': '🍷', 'noun': 'круглосуточные алкомаркеты'},
    'grocery24': {'file': 'grocery24_data.json', 'label': 'Магазины 24 часа', 'emoji': '🛒', 'noun': 'круглосуточные магазины'},
    'ev_charging': {'file': 'ev_charging_data.json', 'label': 'Электрозарядки', 'emoji': '🔌', 'noun': 'электрозарядки'},
}
NEARBY_RESULTS_COUNT = 5

# Только для kind='toilets': точки бывают не только явными туалетами
# (amenity=toilets), но и местами, где туалет почти наверняка есть, хотя явно
# не помечен в OSM - заправки/кафе/рестораны (по просьбе пользователя, см.
# fetch_toilets_data.py). ТЦ (mall) в список намеренно НЕ входит - убрано по
# прямой просьбе пользователя (туалет в ТЦ часто не быстро найти/дойти).
# Подписываем явным словом "ТУАЛЕТ" + категория заведения, чтобы сразу было
# видно, что это место, где искать туалет (а не просто список заведений) -
# по просьбе пользователя, пример: "ТУАЛЕТ Ресторан Брудер". Для явного
# amenity=toilets отдельная категория не нужна - там просто "ТУАЛЕТ".
# Старые данные (собранные до этого расширения) поля 'kind' не имеют -
# render_nearby_results ниже просто не покажет префикс, это нормально.
NEARBY_POINT_KIND_LABELS = {
    'toilet': 'ТУАЛЕТ',
    'fuel': 'ТУАЛЕТ АЗС',
    'cafe': 'ТУАЛЕТ Кафе',
    'restaurant': 'ТУАЛЕТ Ресторан',
}

_nearby_cache = {}
_nearby_mtime = {}

def load_nearby_data(kind):
    """Читает <kind>_data.json (см. fetch_toilets_data.py/fetch_parking_data.py/
    fetch_tires_data.py/fetch_car_wash_data.py) с тем же кэшем по mtime, что и
    load_road_events/load_flights_data - файлы обновляются НЕ фоновой задачей
    бота (Overpass недоступен с Railway/облака), а вручную/по расписанию с
    компьютера с доступом в обход блокировки (см. docstring фетчеров)."""
    global _nearby_cache, _nearby_mtime
    cfg = NEARBY_SERVICES[kind]
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), cfg['file'])
    try:
        mtime = os.path.getmtime(path)
        if _nearby_cache.get(kind) is not None and _nearby_mtime.get(kind) == mtime:
            return _nearby_cache[kind]
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        _nearby_cache[kind] = data
        _nearby_mtime[kind] = mtime
        return data
    except FileNotFoundError:
        return None
    except Exception as e:
        logger.error(f"❌ Ошибка чтения {cfg['file']}: {e}")
        return None

def haversine_km(lat1, lon1, lat2, lon2):
    """Расстояние по прямой между двумя точками (км) - этого достаточно для
    сортировки "ближайшие N", точный маршрут посчитает уже сам Яндекс
    Навигатор по кнопке "Поехали"."""
    r = 6371.0
    phi1, phi2 = radians(lat1), radians(lat2)
    dphi = radians(lat2 - lat1)
    dlambda = radians(lon2 - lon1)
    a = sin(dphi / 2) ** 2 + cos(phi1) * cos(phi2) * sin(dlambda / 2) ** 2
    return 2 * r * asin(sqrt(a))

def nearest_airport(lat, lon):
    """Ближайший аэропорт (из AIRPORT_COORDS) к точке (lat, lon) - основа
    фичи "Очередь у аэропорта" (см. блок AIRPORT_QUEUE_* и
    process_airport_queue_ping ниже, рядом с push_airport_status_change).
    Возвращает (icao, dist_km) или (None, None), если AIRPORT_COORDS пуст."""
    best_icao, best_dist = None, None
    for icao, (a_lat, a_lon) in AIRPORT_COORDS.items():
        dist = haversine_km(lat, lon, a_lat, a_lon)
        if best_dist is None or dist < best_dist:
            best_icao, best_dist = icao, dist
    return best_icao, best_dist

def nearest_airport_zone(lat, lon):
    """Как nearest_airport(), но для аэропортов с несколькими терминальными
    зонами (см. AIRPORT_TERMINAL_ZONES - сейчас только UUEE/Шереметьево:
    "b", "c" и "d") дополнительно определяет БЛИЖАЙШУЮ зону внутри этого
    аэропорта, а не просто центр аэропорта в целом. Логика в два шага:
    1) находим ближайший АЭРОПОРТ как раньше (nearest_airport) - это не
       меняется, у Шереметьево остаётся один ICAO-код UUEE, просто внутри
       него теперь есть под-деление;
    2) если у найденного аэропорта есть зоны в AIRPORT_TERMINAL_ZONES -
       среди НИХ отдельно ищем ближайшую и считаем расстояние уже до неё
       (точнее, чем до усреднённой точки всего аэропорта), иначе zone_key/
       zone_label = None и расстояние - как раньше, до AIRPORT_COORDS[icao].
    Возвращает (icao, dist_km, zone_key, zone_label)."""
    icao, dist_km = nearest_airport(lat, lon)
    if icao is None:
        return None, None, None, None
    zones = AIRPORT_TERMINAL_ZONES.get(icao)
    if not zones:
        return icao, dist_km, None, None
    best_zone_key, best_zone_label, best_zone_dist = None, None, None
    for zone_key, zone_data in zones.items():
        z_lat, z_lon = zone_data['coords']
        d = haversine_km(lat, lon, z_lat, z_lon)
        if best_zone_dist is None or d < best_zone_dist:
            best_zone_key, best_zone_label, best_zone_dist = zone_key, zone_data['label'], d
    return icao, best_zone_dist, best_zone_key, best_zone_label

def nearest_nearby_points(kind, city, lat, lon, count=NEARBY_RESULTS_COUNT):
    """Возвращает (расстояние_км, точка) для ближайших count точек в городе,
    отсортированные по расстоянию. None - данные вообще не собраны (файла
    нет/битый), [] - данные есть, но конкретно для этого города пока пусто
    (сбор пока покрывает не все города - см. docstring фетчеров)."""
    data = load_nearby_data(kind)
    if not data:
        return None
    points = data.get('cities', {}).get(city, [])
    if not points:
        return []
    scored = [(haversine_km(lat, lon, p['lat'], p['lon']), p) for p in points]
    scored.sort(key=lambda x: x[0])
    return scored[:count]

def yandex_navi_url(lat, lon):
    """Ссылка кнопки "Поехали" - маршрут до точки в Яндекс Навигаторе/Картах.
    ВАЖНО: раньше тут была кастомная схема "yandexnavi://build_route_on_map?..."
    - Telegram Bot API отклоняет такие ссылки в инлайн-кнопках как невалидные
    (BUTTON_URL_INVALID), из-за чего сообщение целиком не отправлялось (весь
    список ближайших точек пропадал - баг, найденный пользователем живьём:
    первое сообщение "Готово" доходило, второе с кнопками - нет). Универсальная
    ссылка yandex.ru/maps с rtext/rtt - обычный https:// URL (Telegram его
    принимает), на телефоне с установленным Яндекс Навигатором/Картами
    открывается сразу в приложении (Yandex зарегистрировал universal links на
    этот домен), иначе - в браузере как веб-версия Яндекс Карт с готовым
    маршрутом."""
    return f"https://yandex.ru/maps/?rtext=~{lat},{lon}&rtt=auto"

def nearby_location_keyboard():
    return ReplyKeyboardMarkup(resize_keyboard=True, keyboard=[
        [KeyboardButton(text="📍 ОТПРАВИТЬ ГЕОЛОКАЦИЮ", request_location=True)],
        [KeyboardButton(text="❌ ОТМЕНА")],
    ])

def format_nearby_distance(dist_km):
    return f"{dist_km * 1000:.0f} м" if dist_km < 1 else f"{dist_km:.1f} км"

def render_nearby_results(kind, scored_points):
    """Текст + инлайн-клавиатура с кнопкой "🚕 Поехали" на каждую из ближайших
    точек (открывает маршрут в Яндекс Навигаторе - см. yandex_navi_url).
    Цену НЕ показываем - в OSM её почти никогда нет ни для шиномонтажей, ни
    для моек (решение пользователя - показывать без неё, а не выдумывать)."""
    cfg = NEARBY_SERVICES[kind]
    lines = [f"{cfg['emoji']} *{cfg['label']} — ближайшие {len(scored_points)}*\n"]
    buttons = []
    for i, (dist_km, point) in enumerate(scored_points, start=1):
        # У немалой части точек в OSM нет названия - раньше тут стояла
        # заглушка "Без названия", по просьбе пользователя убрали: если
        # названия нет, просто не показываем его (не выдумываем и не
        # подписываем никак), только номер и расстояние. Адрес не собираем и
        # не показываем вообще - в исходных данных (OSM) его тоже нет.
        name = point.get('name')
        title = f"*{escape_md(name)}* — " if name else ""
        # Категория точки (только для "Туалеты" - см. NEARBY_POINT_KIND_LABELS):
        # ТЦ/АЗС/кафе/ресторан показываем значком ПЕРЕД названием, чтобы было
        # видно, что это не гарантированный туалет, а место, где он вероятно есть.
        kind_label = NEARBY_POINT_KIND_LABELS.get(point.get('kind'))
        prefix = f"{kind_label} " if kind_label else ""
        hours = point.get('hours')
        hours_line = f"   🕐 {escape_md(hours)}" if hours else "   🕐 часы работы не указаны"
        # Только для kind='ev_charging' (см. extract_specs в
        # fetch_ev_charging_data.py) - тип/количество/мощность разъёмов, по
        # прямой просьбе пользователя показываем сразу в списке, а не только
        # по клику. Если specs нет (не было socket:* тегов в OSM) - строку не
        # показываем вообще, как и с часами работы.
        specs = point.get('specs')
        specs_line = f"\n   🔌 {escape_md(specs)}" if specs else ""
        lines.append(f"{i}. {prefix}{title}{format_nearby_distance(dist_km)}\n{hours_line}{specs_line}")
        buttons.append([InlineKeyboardButton(
            text=f"{i}. 🚕 Поехали",
            url=yandex_navi_url(point['lat'], point['lon']),
        )])
    text = '\n\n'.join(lines)
    return text, InlineKeyboardMarkup(inline_keyboard=buttons)

def courier_finance_cancel_keyboard():
    return ReplyKeyboardMarkup(resize_keyboard=True, keyboard=[[KeyboardButton(text="❌ ОТМЕНА")]])

# Резерв на износ/ремонт - фиксированный % от валового дохода (см. README
# прототипа: "доход минус топливо минус резерв на износ"). Пользователь явно
# попросил 10% - в отличие от топлива это не физическая величина, а
# отложенная "подушка" на будущий ремонт/амортизацию, поэтому считается от
# дохода, а не от километража.
COURIER_WEAR_RESERVE_RATE = 0.10

# Налог по умолчанию - 6% (стандартная ставка УСН "доходы"/самозанятость),
# считается от ВАЛОВОГО дохода (по просьбе пользователя, 20.09.2026) - можно
# поменять на любую свою ставку на шаге 'tax_rate'.
DEFAULT_TAX_RATE_PERCENT = 6.0

COURIER_FINANCE_STEP_PROMPTS = {
    'income': "💰 Доход за день, ₽ (с учётом вычета комиссии сервисов, только число):",
    'trips': "🚕 Количество выполненных заказов за день (только число):",
    'km': "🚗 Километраж за день, км:",
    'consumption': "⛽ Расход топлива на 100 км (л или кВтч):",
    'fuel_price': "💵 Стоимость топлива за литр/кВтч, ₽:",
    'car_ownership': "🚘 Машина:",
    'rent': "🚘 Аренда ТС за день, ₽:",
    'expenses': "📦 Доп. расходы за день, ₽ (питание, ремонты, доп. покупки - если нет, пришли 0):",
    'tax_rate': f"🧾 Ставка налога, % от дохода (обычно {DEFAULT_TAX_RATE_PERCENT:g}% - можно указать свою):",
    'hours': "🕐 Сколько часов длилась смена (можно дробно, например 5.5):",
}

# "Машина: своя (в т.ч. кредит/лизинг) / в аренде" - по просьбе пользователя
# (20.09.2026): резерв на износ/ремонт (10%, см. COURIER_WEAR_RESERVE_RATE)
# имеет смысл только если машина СВОЯ (или куплена в кредит/лизинг - тогда
# её ремонт и амортизация оплачивает сам водитель); если машина В АРЕНДЕ -
# износ/ремонт несёт арендодатель, резерв не учитываем, чтобы не занижать
# "чистыми" задвоением расхода (аренда и так уже платится отдельной строкой).
# Спрашивается ОДИН РАЗ и запоминается как профиль (см.
# FINANCE_REMEMBERED_FIELDS) - у водителя это не меняется день ото дня.
CAR_OWNERSHIP_OWN = 'own'      # своя / кредит / лизинг - резерв на износ учитываем
CAR_OWNERSHIP_RENTED = 'rented'  # в аренде - резерв на износ НЕ учитываем
CAR_OWNERSHIP_LABELS = {
    CAR_OWNERSHIP_OWN: "своя / кредит / лизинг",
    CAR_OWNERSHIP_RENTED: "в аренде",
}

