async def send_welcome_pitch(message: types.Message):
    """Отправляет новому пользователю приветственный питч с картинкой, затем
    отдельным сообщением - объяснение про геолокацию. Если файл картинки не
    найден (например, ещё не закоммичен на Railway), не роняем /start -
    просто шлём текст без фото.

    ИЗМЕНЕНО 22.09.2026, затем уточнено тем же днём (жалоба пользователя,
    потом "Только приветственное" - т.е. защищать от автоудаления
    (см. SingleMessageMiddleware/ChatCleanupIncomingMiddleware,
    KEEP_LAST_N_MESSAGES=2) только сам приветственный питч
    (картинка+текст), а НЕ текст про геолокацию - его чистить как
    обычно. Только питч отправляется внутри _skip_message_trim - как
    и карточки событий - и не попадает в очередь на автоудаление."""
    token = _skip_message_trim.set(True)
    try:
        if os.path.isfile(WELCOME_PHOTO_PATH):
            await message.answer_photo(
                FSInputFile(WELCOME_PHOTO_PATH),
                caption=WELCOME_PITCH_TEXT,
                parse_mode='Markdown'
            )
        else:
            await message.answer(WELCOME_PITCH_TEXT, parse_mode='Markdown')
    except Exception as e:
        logger.error(f"❌ Не удалось отправить приветственную картинку: {e}")
        await message.answer(WELCOME_PITCH_TEXT, parse_mode='Markdown')
    finally:
        _skip_message_trim.reset(token)
    await message.answer(WELCOME_GEO_TEXT, parse_mode='Markdown')

async def send_start_screen(message: types.Message):
    """Общий код /start и кнопки "🏙 ВЫБОР ГОРОДА" - сбрасывает весь user_state
    (включая любой незавершённый черновик заказа/расчёта) и возвращает на
    экран выбора города. Кнопка добавлена, чтобы не заставлять пользователя
    искать команду /start в интерфейсе Telegram - она есть на всех
    клавиатурах ниже корневого экрана (см. category_keyboard,
    services_keyboard, courier_module_keyboard)."""
    init_db()
    user_state.pop(message.from_user.id, None)
    # Обновлённый визуал стартового экрана (по просьбе пользователя,
    # 22.09.2026 - "поработать над визуалом бота на всех страницах", начиная с
    # главного меню) - тот же стиль оформления, что уже прижился в "Куда
    # ехать": крупный заголовок, разделитель, короткая подпись назначения.
    # ИЗМЕНЕНО 22.09.2026 (продолжение той же правки, "пробегись по боту
    # поработай над визуальной частью ... в наших цветах стилистике") -
    # разделитель "━━━" заменён на общий WHERE_TO_GO_DIVIDER ("┄┄┄"), чтобы
    # по всему боту был ОДИН стиль разделителя, а не три разных (были ещё
    # "▓▓▓" и голый "━━━" в разных экранах - см. остальные правки этого дня).
    text = (
        "🚕✨ *TAXI HELPER*\n"
        "_Помощник водителя такси и курьера_\n"
        f"{WHERE_TO_GO_DIVIDER}\n\n"
        "🏙 Выбери свой город 👇"
    )
    await message.answer(text, reply_markup=city_keyboard(), parse_mode='Markdown')

@router.message(Command("start"))
async def start(message: types.Message):
    # Реферальная ссылка - t.me/<бот>?start=ref_<id рефера> (см. блок
    # "РЕФЕРАЛЬНАЯ ПРОГРАММА" ниже, register_referral). Привязка происходит
    # ТОЛЬКО при первом /start с таким параметром у пользователя, у которого
    # ещё нет реферера - повторные переходы по чужим ссылкам ничего не
    # меняют.
    # Приветственный питч + просьба включить геолокацию - только самому
    # первому /start у пользователя (проверяем ДО send_start_screen, которая
    # чистит user_state - иначе индикатор "новый ли это пользователь" был бы
    # уже потерян).
    is_new_user = message.from_user.id not in user_state
    parts = (message.text or '').split(maxsplit=1)
    if len(parts) == 2 and parts[1].startswith('ref_'):
        ref_code = parts[1][len('ref_'):]
        if ref_code.isdigit():
            referrer_id = int(ref_code)
            if referrer_id != message.from_user.id:
                register_referral(message.from_user.id, referrer_id)
    if is_new_user:
        await send_welcome_pitch(message)
    await send_start_screen(message)

# ДОБАВЛЕНО 23.09.2026 (см. MAIN_MENU_INLINE_BUTTON_TEXT/_with_main_menu_button
# выше) - хендлер инлайн-кнопки "🚕 МЕНЮ TAXI HELPER", которая теперь висит
# почти на каждом сообщении бота. Открывает главное меню сервисов (те же
# кнопки, что и после старта смены/выбора города - services_keyboard) для
# уже выбранных города/категории; если пользователь их ещё не выбрал (самое
# первое сообщение, "первое /start"), откатывается на send_start_screen -
# экран выбора города.
@router.callback_query(lambda c: c.data == MAIN_MENU_INLINE_BUTTON_CALLBACK)
async def open_services_menu(callback_query: types.CallbackQuery):
    try:
        await callback_query.answer()
    except Exception:
        pass
    user_id = callback_query.from_user.id
    state = user_state.get(user_id, {})
    category = state.get('category')
    city = state.get('city')
    if not category or not city:
        await send_start_screen(callback_query.message)
        return
    await callback_query.message.answer(
        "📋 Меню",
        reply_markup=services_keyboard(category, city, user_id),
    )

# ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя - "ждать нет времени",
# нужно было прямо сейчас проверить сырой ответ Yandex Rasp API на предмет
# полей статуса рейса/задержки, не дожидаясь плановой точки расписания или
# рестарта бота). Скрытая админская команда - форсирует внеплановое
# обновление flights_data.json НЕМЕДЛЕННО, в обход всех проверок
# "свежести"/расписания в airports_data_updater(). Доступна ТОЛЬКО
# ADMIN_USER_ID, чтобы обычные пользователи бота не могли жать её пачками и
# жечь дневную квоту API (500 запросов/сутки, см. DAILY_SAFETY_LIMIT в
# fetch_yandex_data.py).
ADMIN_USER_ID = 147611511

@router.message(Command("forcefetch"))
async def force_fetch_flights(message: types.Message):
    if message.from_user.id != ADMIN_USER_ID:
        return
    await message.answer("⏳ Форсирую обновление flights_data.json прямо сейчас...")
    try:
        async with _yandex_api_lock:
            status = await asyncio.to_thread(fetch_yandex_data.main)
        if status == 'daily_limit_reached':
            await message.answer("🚫 Дневной лимит запросов исчерпан - обновление пропущено.")
        else:
            fresh_age = _data_file_age_minutes(FLIGHTS_DATA_FILE)
            await message.answer(f"✅ Готово. flights_data.json обновлён (возраст файла: {fresh_age:.1f} мин).")
    except Exception as e:
        logger.error(f"❌ Ошибка /forcefetch: {e}")
        await message.answer(f"❌ Ошибка при обновлении: {e}")

