@router.message(lambda message: message.text == "📅 ЧАСЫ ПИКА" and user_state.get(message.from_user.id, {}).get('in_courier_module'))
async def show_peak_hours(message: types.Message):
    """Часы пика по дням недели (см. блок "ЧАСЫ ПИКА ПО ДНЯМ НЕДЕЛИ" выше
    по файлу) - показывает ТЕКУЩИЙ день недели по местному времени города
    (get_city_now), с инлайн-кнопками переключения на любой другой день
    (peak_hours_weekday_keyboard -> peak_day_{0-6})."""
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    if not city:
        await message.answer("Сначала выбери город 🏙")
        return
    category = state.get('category')
    now = get_city_now(city)
    text = format_peak_hours_text(city, target_weekday=None, category=category)
    keyboard = peak_hours_weekday_keyboard(now.weekday(), category=category)
    await message.answer(text, reply_markup=keyboard, parse_mode='Markdown')

@router.callback_query(lambda c: c.data.startswith('peak_day_'))
async def switch_peak_hours_day(callback_query: types.CallbackQuery):
    """Переключение дня недели на экране "ЧАСЫ ПИКА" - перерисовывает то же
    сообщение (edit_text), без "Сейчас: ..." строки (она осмысленна только
    для текущего реального дня, см. format_peak_hours_text). callback_data -
    "peak_day_{0-6}" (такси/Ultima) или "peak_day_{0-6}_{category}"
    (courier/cargo - своя таблица часов пика, см.
    peak_hours_weekday_keyboard) - category берём из callback_data, а не из
    user_state, чтобы переключение дней недели корректно работало даже если
    пользователь сменил категорию, не закрывая старое сообщение "ЧАСЫ ПИКА"."""
    user_id = callback_query.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    if not city:
        await callback_query.answer("Начни заново с /start", show_alert=True)
        return
    parts = callback_query.data.split('_')
    weekday = int(parts[2])
    category = parts[3] if len(parts) > 3 else None
    if weekday < 0 or weekday > 6:
        await callback_query.answer("Ошибка!", show_alert=True)
        return
    text = format_peak_hours_text(city, target_weekday=weekday, category=category)
    keyboard = peak_hours_weekday_keyboard(weekday, category=category)
    await callback_query.message.edit_text(text, reply_markup=keyboard, parse_mode='Markdown')
    await callback_query.answer()

# ==================== "КУДА ЕХАТЬ" (сводная рекомендация) ====================
# Пока ТОЛЬКО для такси/Ultima (см. courier_module_keyboard - кнопка скрыта
# для CATEGORIES_WITHOUT_AIRPORTS). Сравнивает несколько "кандидатов" -
# каждый аэропорт города и обобщённый "Город/центр" - по условному баллу
# спроса, собранному из уже существующих источников данных бота:
#   - аэропорт: загрузка прилётов ПРЯМО СЕЙЧАС (compute_current_availability),
#     статус Росавиации (get_airport_status - штраф, если закрыт/по
#     согласованию) и живая очередь у аэропорта (queue_latest_report по ЛЮБОМУ
#     тарифу - штраф, если очередь уже большая, даже при высокой загрузке)
#   - "Город/центр": уровень часа пика (get_current_peak_level) + бонус за
#     дождь/снег (weathercode из fetch_rain_forecast, тот же источник, что
#     уже используется для пуш-уведомлений о дожде)
# Разные единицы измерения (% загрузки аэропорта vs уровень пика города) -
# ЗНАЧИТ, это не физически точный расчёт, а понятный водителю ориентир с
# объяснением "почему" - как и WEEKDAY_HOUR_LOAD выше, ориентир, не прогноз.
# "Длинная" очередь для целей этого скоринга - от 21 машины (5-й диапазон
# QUEUE_RANGES и дальше). Строится из самого QUEUE_RANGES, а не захардкожена
# отдельным списком строк - чтобы не разъехаться, если шаг/границы диапазонов
# когда-нибудь изменятся (см. QUEUE_RANGES выше по файлу).
WHERE_TO_GO_QUEUE_LONG_RANGES = {f'{lo}-{hi}' for lo, hi in QUEUE_RANGES if lo >= 21}

def pluralize_ru(n, one, few, many):
    """Русское склонение по числу: 1 рейс / 2 рейса / 5 рейсов. Стандартное
    правило падежей (11-14 - всегда "many", иначе по последней цифре)."""
    n_abs = abs(n)
    if 11 <= n_abs % 100 <= 14:
        return many
    last = n_abs % 10
    if last == 1:
        return one
    if 2 <= last <= 4:
        return few
    return many

def score_station_candidate(city, code, station, category):
    """Балл и обоснование для одного вокзала города - тот же принцип, что
    score_airport_candidate, но на бинарной шкале вокзалов (см.
    get_train_load_symbol/get_train_load_label) вместо 4-уровневой шкалы
    аэропортов. По просьбе пользователя (21.09.2026) вокзалы тоже участвуют
    в "Куда ехать", а не только аэропорты. score - тот же % загрузки
    текущего получаса, что показывается на кнопке вокзала в разделе
    "✈️🚆 АВИА/ЖД" - шкалы сопоставимы (обе - % от часовой ёмкости),
    прямое сравнение с score аэропорта корректно."""
    load, trains_in_period, _ = compute_current_train_period_load(code, category)
    reasons = []
    if trains_in_period > 0:
        train_word = pluralize_ru(trains_in_period, "поезд", "поезда", "поездов")
        reasons.append(f"{trains_in_period} {train_word} в этот получас")
    else:
        reasons.append("прибытий в этот получас нет")
    label = get_train_load_label(load)
    if label == 'ЕХАТЬ':
        reasons.append("стоит подъехать")
    return {'label': f"🚆 {station['name']}", 'score': load, 'reasons': reasons, 'closed': False, 'advice': None}

async def score_airport_candidate(city, airport, category):
    """Считает балл и обоснование для одного аэропорта города. Возвращает
    dict {label, score, reasons: [str, ...], closed: bool}. relevant_class -
    та же логика, что CATEGORY_TO_CLASS в остальном боте (эконом/бизнес/все)."""
    icao = airport['icao']
    zone_key = airport.get('zone_key')
    relevant_class = CATEGORY_TO_CLASS.get(category, 'total')
    reasons = []

    status, _notice = get_airport_status(icao)
    if airport.get('closed') or status == 'closed':
        return {'label': airport['name'], 'score': -1000, 'reasons': ['аэропорт закрыт'], 'closed': True, 'advice': None}

    avail = compute_current_availability(icao, relevant_class, zone_key=zone_key)
    score = avail['load']  # базовый балл - % загрузки прилётов на текущий час
    n_flights = len(avail['arrivals_now'])
    if n_flights > 0:
        flight_word = pluralize_ru(n_flights, "рейс", "рейса", "рейсов")
        reasons.append(f"{n_flights} {flight_word} в этот час")
    else:
        reasons.append("прилётов в этот час нет")

    if status == 'coordinated':
        score *= 0.7
        reasons.append("работает по согласованию")

    # Очередь - раньше показывали ТОЛЬКО когда она "длинная" (>=21 машины,
    # WHERE_TO_GO_QUEUE_LONG_RANGES), а меньшие отметки молча пропадали из
    # сводки "куда ехать" - водитель не видел никакой очереди, даже если её
    # только что кто-то отметил в мини-аппе/по пушу. ИЗМЕНЕНО 22.09.2026
    # (прямая просьба пользователя - "и в сводки куда поехать аэропортов
    # тоже должно показывать какая очередь сейчас по какому тарифу"):
    # теперь показываем отметку по КАЖДОМУ тарифу отдельно, если она есть,
    # тем же форматом, что уже используется на карте водителей (см.
    # handle_map_airports_api) - штраф к score по-прежнему только за
    # действительно длинную очередь, но видимость в тексте больше не
    # зависит от длины. Ключ в БД - "{category}:{tariff}" (см.
    # queue_class_key) - без category без тарифа тоже проверяем (вдруг
    # отмечали без выбора конкретного тарифа).
    tariffs = CATEGORIES.get(category, {}).get('tariffs') or []
    worst_range = None
    if tariffs:
        queue_parts = []
        for tariff in tariffs:
            range_str, _ts = queue_latest_report(city, icao, f"{category}:{tariff}", zone_key=zone_key)
            if range_str:
                queue_parts.append(f"{tariff}: {range_str}")
                if range_str in WHERE_TO_GO_QUEUE_LONG_RANGES:
                    worst_range = range_str
        if queue_parts:
            reasons.append("очередь - " + ", ".join(queue_parts))
    else:
        range_str, _ts = queue_latest_report(city, icao, category, zone_key=zone_key)
        if range_str:
            reasons.append(f"очередь - {range_str}")
            if range_str in WHERE_TO_GO_QUEUE_LONG_RANGES:
                worst_range = range_str
    if worst_range:
        score *= 0.6

    return {'label': airport['name'], 'score': score, 'reasons': reasons, 'closed': False, 'advice': None}

# Развёрнутая рекомендация по типам заведений для "Город/центр" - по
# просьбе пользователя (21.09.2026): просто "повышенный спрос" мало что
# говорит водителю, нужен конкретный совет КУДА именно в центре ехать/
# держаться, в зависимости от дня недели и текущего уровня спроса. Пятница/
# суббота вечер-ночь - ночная жизнь (клубы/бары/рестораны/стриптиз-клубы),
# будни вечер - рестораны/бары после работы, будни утро/день - деловой
# центр/офисы/ТЦ. Формулировки водитель дал сам (пятница-суббота = ночная
# жизнь, будни = обычный деловой трафик) - остальное подобрано по аналогии,
# не строгий факт, а ориентир ("держись центра и этих заведений").
_CITY_ADVICE_WEEKEND_NIGHT = (
    "ночь клубов, баров и ресторанов - держись центра и заведений ночной "
    "жизни (клубы, бары, рестораны, стриптиз-клубы): люди разъезжаются "
    "поздно и часто берут такси именно от входа"
)
_CITY_ADVICE_WEEKEND_EVENING = (
    "вечер пятницы/субботы - люди едут в центр в рестораны, бары и клубы: "
    "держись районов с заведениями, спрос будет расти к ночи"
)
_CITY_ADVICE_WORKDAY_EVENING = (
    "вечер буднего дня - спрос из бизнес-центров/офисов и ресторанов/баров "
    "после работы, держись делового центра"
)
_CITY_ADVICE_WORKDAY_PEAK = (
    "час пик буднего дня - основной поток из жилых районов в центр/офисы "
    "(или обратно вечером), держись крупных транспортных направлений"
)
_CITY_ADVICE_DEFAULT = "держись центра города и оживлённых районов"

# Свои советы "куда именно держаться" для Курьера/Грузового такси (по
# просьбе пользователя, 20.09.2026 - "Куда ехать" для этих категорий
# строится на своих правилах: обед/ужин для курьера, рабочие часы бизнеса
# для грузового такси - см. CATEGORY_WEEKDAY_HOUR_LOAD выше). Развёрнутый
# совет по конкретным местам, не просто "спрос выше/ниже".
_COURIER_ADVICE_LUNCH = (
    "обеденный пик - держись у бизнес-центров, офисов и ТЦ с фудкортами, "
    "много заказов на доставку обеда"
)
_COURIER_ADVICE_DINNER = (
    "вечерний пик - основной поток из жилых районов, держись рядом с "
    "популярными ресторанами/тёмными кухнями и плотной жилой застройкой"
)
_COURIER_ADVICE_LATE_NIGHT = (
    "поздняя ночь пятницы/субботы/воскресенья - доходный отрезок после "
    "баров и вечеринок, держись рядом с ночными заведениями и клубами"
)
_COURIER_ADVICE_WEEKEND_DAY = (
    "выходной день - спрос выше обычного будня весь день (не только в "
    "обед/ужин), держись жилых районов и заведений с доставкой"
)
_COURIER_ADVICE_DEFAULT = "держись районов с высокой плотностью кафе/ресторанов и жилой застройки"

_CARGO_ADVICE_PEAK = (
    "рабочий пик - держись рядом с логистическими центрами, складами, "
    "оптовыми базами и промзонами, много заявок на перевозку грузов"
)
_CARGO_ADVICE_WORKDAY = "рабочее время - держись деловых районов и складских зон"
_CARGO_ADVICE_WEEKEND_PEAK = (
    "пик переездов и вывоза мебели/техники - держись жилых районов, ТЦ с "
    "мебелью/бытовой техникой и новостроек, где люди заезжают"
)
_CARGO_ADVICE_WEEKEND_DAY = "выходной - в основном частные переезды и перевозка крупных покупок, держись жилых районов"
_CARGO_ADVICE_DEFAULT = "сейчас спрос низкий - заявок будет немного"

def get_cargo_advice(level, is_weekend):
    if is_weekend:
        if level == 'peak':
            return _CARGO_ADVICE_WEEKEND_PEAK
        if level == 'high':
            return _CARGO_ADVICE_WEEKEND_DAY
        return _CARGO_ADVICE_DEFAULT
    if level == 'peak':
        return _CARGO_ADVICE_PEAK
    if level in ('mid', 'high'):
        return _CARGO_ADVICE_WORKDAY
    return _CARGO_ADVICE_DEFAULT

def get_city_advice(city, level, category=None):
    """Развёрнутый совет ПО ТИПАМ ЗАВЕДЕНИЙ для "Город/центр", в зависимости
    от дня недели (местное время города) и текущего уровня спроса. См.
    комментарий у _CITY_ADVICE_* выше про логику. weekday 4=пятница,
    5=суббота, 6=воскресенье (как в get_city_now().weekday()). category -
    для courier/cargo использует свои советы (обед/ужин + доходные пт/сб/вс
    для курьера, get_cargo_advice для грузового) вместо таксишной логики
    ночь/будни/выходные, т.к. паттерн спроса у них принципиально другой
    (см. CATEGORY_WEEKDAY_HOUR_LOAD - у обеих категорий пятница/суббота/
    воскресенье теперь отдельные доходные дни, по просьбе пользователя,
    20.09.2026)."""
    if category == 'courier':
        now = get_city_now(city)
        weekday = now.weekday()
        hour = now.hour
        is_weekend = weekday in (4, 5, 6)
        if is_weekend and (hour < 2 or hour >= 23):
            return _COURIER_ADVICE_LATE_NIGHT
        if level == 'peak' and 11 <= hour < 15:
            return _COURIER_ADVICE_LUNCH
        if level == 'peak':
            return _COURIER_ADVICE_DINNER
        if is_weekend and level == 'high':
            return _COURIER_ADVICE_WEEKEND_DAY
        return _COURIER_ADVICE_DEFAULT
    if category == 'cargo':
        now = get_city_now(city)
        is_weekend = now.weekday() in (4, 5, 6)
        return get_cargo_advice(level, is_weekend)

    now = get_city_now(city)
    weekday = now.weekday()
    hour = now.hour
    # Ночная зона пятницы/субботы переходит через полночь на следующий день
    # недели (пятница ночью -> уже суббота, суббота ночью -> уже
    # воскресенье) - поэтому проверяем ЧАСЫ ПОСЛЕ полуночи (hour < 4) у
    # СЛЕДУЮЩЕГО дня (5=суббота, 6=воскресенье), а не у самого (4,5).
    is_weekend_night_zone = (
        (weekday in (4, 5) and hour >= 22) or
        (weekday in (5, 6) and hour < 4)
    )
    is_weekend_evening = weekday in (4, 5) and 18 <= hour < 22
    if is_weekend_night_zone:
        return _CITY_ADVICE_WEEKEND_NIGHT
    if is_weekend_evening:
        return _CITY_ADVICE_WEEKEND_EVENING
    if weekday <= 3:  # будни (пн-чт)
        if level == 'peak':
            return _CITY_ADVICE_WORKDAY_PEAK
        if hour >= 18:
            return _CITY_ADVICE_WORKDAY_EVENING
    return _CITY_ADVICE_DEFAULT

async def score_city_candidate(city, category=None):
    """Балл для обобщённого "Город/центр" - на основе часа пика + погоды.
    Единицы условные (не %, как у аэропортов) - подобраны так, чтобы часы
    пика были заметно приоритетнее аэропорта со средней загрузкой, а низкий
    спрос - явно ниже почти любого аэропорта с прилётами. category -
    courier/cargo используют свою таблицу часов пика (см.
    get_current_peak_level/CATEGORY_WEEKDAY_HOUR_LOAD)."""
    level = get_current_peak_level(city, category=category)
    level_score = {'low': 10, 'mid': 40, 'high': 70, 'peak': 100}[level]
    reasons = [PEAK_LEVEL_LABEL[level]]

    score = level_score
    # ИЗМЕНЕНО 21.09.2026 - читаем готовый почасовой снепшот погоды
    # (weather_data.json, обновляется раз в час) вместо live-запроса к
    # Open-Meteo на каждый расчёт "Куда ехать" (см. get_cached_weather_forecast).
    forecast = get_cached_weather_forecast(city)
    if forecast:
        current = forecast.get('current', {})
        code = current.get('weathercode')
        if code in PRECIP_WEATHERCODES:
            _name, _weight, emoji = describe_weathercode(code)
            # ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - прислал
            # 10-балльную шкалу влияния осадков на спрос, отдельную для
            # Ultima и для обычного такси, см. CATEGORY_RAIN_IMPACT) - балл
            # осадков теперь зависит от категории: у Ultima дождь поднимает
            # спрос заметнее. impact 0-10 -> бонус 0-80 баллов (было: общий
            # вес 1-8 -> 8-64, без разницы между категориями).
            impact = rain_impact_score(code, category)
            bonus = impact * 8
            score += bonus
            reasons.append(f"{emoji} осадки сейчас - спрос выше обычного")
        else:
            # ДОБАВЛЕНО 21.09.2026 по просьбе пользователя - если осадков
            # сейчас нет, но по почасовому прогнозу они начнутся в пределах
            # RAIN_LEAD_MINUTES (тот же порог, что у упреждающих пушей
            # push_rain_alert), даём водителю подъехать заранее: бонус
            # поменьше, чем за уже идущие осадки (impact 0-10 -> 0-40 баллов,
            # тоже по категории - см. комментарий выше).
            upcoming = find_upcoming_precip_event(forecast, city)
            if upcoming and upcoming['hour_offset'] > 0:
                impact = rain_impact_score(upcoming['code'], category)
                bonus = impact * 4
                score += bonus
                reasons.append(f"{upcoming['emoji']} скоро осадки - спрос скоро вырастет")

    advice = get_city_advice(city, level, category=category)
    return {'label': 'Город / центр', 'score': score, 'reasons': reasons, 'closed': False, 'advice': advice}

# Концертное событие начинает давать всплеск спроса ЗА CONCERT_EVENT_LEAD_HOURS
# часов до начала (люди подъезжают заранее) и ОСТАЁТСЯ актуальным ещё
# CONCERT_EVENT_TAIL_HOURS часов после заявленного окончания (расходятся не
# все разом) - за пределами этого окна событие не показываем кандидатом в
# "Куда ехать" вообще (см. score_concert_event_candidates ниже).
CONCERT_EVENT_LEAD_HOURS = 1
CONCERT_EVENT_TAIL_HOURS = 1

def score_concert_event_candidates(city, category, limit=3):
    """Кандидаты "Куда ехать" на основе афиши концертов (см.
    get_upcoming_concert_events_for_category) - по просьбе пользователя
    (22.09.2026). Показываем только события, которые СЕЙЧАС релевантны по
    времени (см. CONCERT_EVENT_LEAD_HOURS/TAIL_HOURS выше), не всю афишу -
    иначе список "Куда ехать" был бы забит мероприятиями через неделю.
    Балл выше для события, которое вот-вот начнётся/только что началось
    (момент максимального наплыва - и подвоза, и разъезда), чем для того,
    что скоро закончится. Единицы условные, той же шкалы, что у
    score_city_candidate (peak=100), чтобы конкретное крупное событие могло
    обгонять общий уровень "Город/центр", но не обгоняло автоматически
    любой аэропорт с реальными прилётами."""
    events = get_upcoming_concert_events_for_category(city, category, limit=20)
    now_ts = datetime.now(ZoneInfo('UTC')).timestamp()
    candidates = []
    for post in events:
        try:
            start_ts = datetime.fromisoformat(post['start']).timestamp()
            end_ts = datetime.fromisoformat(post['end']).timestamp() if post.get('end') else start_ts
        except Exception:
            continue
        window_start = start_ts - CONCERT_EVENT_LEAD_HOURS * 3600
        window_end = end_ts + CONCERT_EVENT_TAIL_HOURS * 3600
        if not (window_start <= now_ts <= window_end):
            continue  # ещё рано или уже неактуально - не показываем кандидатом
        if now_ts < start_ts:
            score = 90  # скоро начнётся - подвоз гостей
        elif now_ts <= end_ts:
            score = 70  # мероприятие идёт - спрос ровнее, чем на входе/выходе
        else:
            score = 95  # уже закончилось (в пределах "хвоста") - самый пик разъезда
        reasons = ["мероприятие по афише"]
        if post.get('place'):
            reasons.append(post['place'])
        label = f"🎤 {post.get('title') or 'Мероприятие'}"
        candidates.append({'label': label, 'score': score, 'reasons': reasons, 'closed': False, 'advice': None})
    candidates.sort(key=lambda c: c['score'], reverse=True)
    return candidates[:limit]

async def compute_where_to_go(city, category):
    """Считает и сортирует всех кандидатов (аэропорты + вокзалы + актуальные
    события афиши + "Город/центр") по баллу - возвращает список dict от
    score_airport_candidate/score_station_candidate/score_concert_event_candidates/
    score_city_candidate, отсортированный по убыванию score, закрытые
    аэропорты (score=-1000) уходят в конец списка. Вокзалы добавлены по
    просьбе пользователя (21.09.2026) - только для городов из TRAIN_CITIES
    (см. STATION_CITY). Афиша концертов добавлена по просьбе пользователя
    (22.09.2026) - только события, актуальные ПРЯМО СЕЙЧАС (см.
    score_concert_event_candidates), не более 3, чтобы не забивать список.

    Курьер/Грузовое такси (20.09.2026): аэропорты, вокзалы и афиша концертов
    им не релевантны (это про пассажирские поездки с рейсов/на мероприятия) -
    для этих категорий единственный кандидат - "Город/центр", но посчитанный
    по СВОЕЙ таблице часов пика и советам (см. score_city_candidate/
    get_city_advice, category передаётся туда)."""
    if category in CATEGORIES_WITHOUT_AIRPORTS:
        return [await score_city_candidate(city, category=category)]

    # Каждый источник кандидатов обёрнут в свой try/except (по факту бага
    # 21.09.2026: "Не удалось посчитать варианты" стабильно на каждое
    # нажатие "КУДА ЕХАТЬ" - раньше ЛЮБОЕ исключение в ОДНОМ аэропорту/
    # вокзале/источнике роняло ВСЮ сводку, хотя остальные кандидаты
    # считались нормально. Теперь сбойный источник просто пропускается (с
    # логом полного traceback - см. logger.exception, а не только str(e), -
    # чтобы при следующей похожей ошибке сразу было видно причину), а не
    # берёт с собой всю фичу. "Город/центр" в конце - последняя надежда:
    # если он тоже упадёт, тогда уже показываем пользователю общую ошибку
    # (см. send_where_to_go), это по-прежнему возможно, но теперь только
    # когда сломано действительно всё, а не один источник."""
    candidates = []
    for airport in AIRPORTS_INFO.get(city, []):
        # Как и в ICAO_TO_AIRPORT - у Шереметьево несколько зональных записей
        # с одним icao (B/C и D), каждая - самостоятельный кандидат (разная
        # загрузка по зоне), дедуп не нужен, в отличие от ICAO_TO_AIRPORT.
        try:
            candidates.append(await score_airport_candidate(city, airport, category))
        except Exception:
            logger.exception(f"❌ Не удалось посчитать кандидата 'Куда ехать' для аэропорта {airport.get('icao')} ({city})")
    if city in TRAIN_CITIES:
        try:
            trains_data = load_trains_data()
            if trains_data and trains_data.get('stations'):
                city_stations = {code: st for code, st in trains_data['stations'].items() if STATION_CITY.get(code) == city}
                for code, station in city_stations.items():
                    try:
                        candidates.append(score_station_candidate(city, code, station, category))
                    except Exception:
                        logger.exception(f"❌ Не удалось посчитать кандидата 'Куда ехать' для вокзала {code} ({city})")
        except Exception:
            logger.exception(f"❌ Не удалось загрузить вокзалы для 'Куда ехать' ({city})")
    try:
        candidates.extend(score_concert_event_candidates(city, category))
    except Exception:
        logger.exception(f"❌ Не удалось посчитать афишу для 'Куда ехать' ({city})")
    # "Город/центр" тоже обёрнут в try/except (по факту повторной жалобы
    # пользователя, 21.09.2026: ошибка "Не удалось посчитать варианты"
    # продолжала стабильно повторяться для Такси Ultima в Москве даже
    # ПОСЛЕ того как остальные источники выше уже были защищены - то есть
    # реальная причина была именно здесь, в этом последнем, единственном
    # НЕзащищённом вызове). Раньше комментарий говорил "последняя надежда,
    # если и он упадёт - покажем общую ошибку" - но раз он падал каждый
    # раз, лучше не ронять всю сводку, а просто остаться без карточки
    # "Город/центр": compute_where_to_go в худшем случае вернёт кандидатов
    # только из аэропортов/вокзалов/афиши (или вообще пустой список -
    # format_where_to_go_text уже умеет корректно показать "нет данных" в
    # этом случае, не падая).
    try:
        candidates.append(await score_city_candidate(city, category=category))
    except Exception:
        logger.exception(f"❌ Не удалось посчитать кандидата 'Город/центр' для 'Куда ехать' ({city}/{category})")
    candidates.sort(key=lambda c: c['score'], reverse=True)
    return candidates

# Ранговые эмодзи для мест в списке "Остальные варианты" - по просьбе
# пользователя сделать сводку "красочнее" (21.09.2026): медаль для топ-3,
# дальше нейтральная точка. WHERE_TO_GO_RANK_EMOJI - медали 2 и 3 места
# (1 место уже показано отдельным блоком "Сейчас лучше всего" с 🏆).
WHERE_TO_GO_RANK_EMOJI = ['🥈', '🥉']

def _where_to_go_score_bar(score):
    """Условная визуальная шкала загрузки под score (0-100%+) - просто
    заполненность кружками, чисто декоративно (не привязана к 4-уровневой
    шкале аэропортов, т.к. у "Города" и вокзалов другие единицы/диапазоны).
    5 сегментов, каждый ~20 очков, максимум забивается на 5-м."""
    filled = min(5, max(0, round(score / 20)))
    return '●' * filled + '○' * (5 - filled)

WHERE_TO_GO_DIVIDER = "┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄"

def format_where_to_go_text(city, category, candidates, extra_header=None):
    """extra_header - по просьбе пользователя (20.09.2026): позволяет
    встроить сообщение "СМЕНА НАЧАТА" прямо в начало сводки "Куда ехать"
    (см. toggle_shift), одним сообщением вместо двух отдельных.

    Визуальное оформление обновлено по просьбе пользователя (20.09.2026,
    "сделай красивое оформление") - точечный разделитель вместо сплошной
    линии (легче читается), топ-вариант в рамке из ▓, компактные блоки без
    лишних пустых строк между заголовком и содержимым."""
    city_name = CITY_DISPLAY_NAMES.get(city, city)
    now = get_city_now(city)
    lines = []
    if extra_header:
        lines.append(extra_header)
        lines.append(WHERE_TO_GO_DIVIDER)
    lines.extend([
        f"🧭 *КУДА ЕХАТЬ · {city_name.upper()}*",
        f"🕐 {now.strftime('%H:%M')} · {WEEKDAY_NAMES[now.weekday()]}",
    ])

    open_candidates = [c for c in candidates if not c['closed']]
    if not open_candidates:
        lines.append(WHERE_TO_GO_DIVIDER)
        lines.append("⛔ Все аэропорты города сейчас закрыты - ориентируйся на центр города и часы пика (см. «📅 Часы пика»).")
        return '\n'.join(lines)

    best = open_candidates[0]
    reasons_str = ', '.join(best['reasons'])
    lines.append("▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓")
    lines.append(f"🏆 *{best['label']}*")
    lines.append(f"{_where_to_go_score_bar(best['score'])}  {reasons_str}")
    if best.get('advice'):
        lines.append(f"💡 {best['advice'][0].upper()}{best['advice'][1:]}.")
    lines.append("▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓")

    if len(open_candidates) > 1:
        lines.append("")
        lines.append("*Остальные варианты:*")
        for i, c in enumerate(open_candidates[1:]):
            rank_emoji = WHERE_TO_GO_RANK_EMOJI[i] if i < len(WHERE_TO_GO_RANK_EMOJI) else '▫️'
            lines.append("")
            lines.append(f"{rank_emoji} *{c['label']}*")
            lines.append(f"{_where_to_go_score_bar(c['score'])}  {', '.join(c['reasons'])}")
            # "Город/центр" не всегда занимает 1 место, но развёрнутый совет
            # по заведениям (см. get_city_advice) важен водителю в любом
            # случае - показываем его и здесь, а не только когда "Город"
            # лучший вариант (по просьбе пользователя, 21.09.2026: совет
            # пропадал, если аэропорт набирал больше баллов).
            if c.get('advice'):
                lines.append(f"💡 _{c['advice'][0].upper()}{c['advice'][1:]}._")

    closed = [c for c in candidates if c['closed']]
    if closed:
        lines.append(WHERE_TO_GO_DIVIDER)
        lines.append("⛔ *Закрыто сейчас:* " + ', '.join(c['label'] for c in closed))

    # По просьбе пользователя (19.09.2026): "оценка перекрытий" - число
    # активных перекрытий в городе (тот же источник, что "⛔ Дорожные
    # события" - is_closure, см. fetch_road_events.py) добавлено сюда общим
    # предупреждением, БЕЗ привязки к конкретному аэропорту/вокзалу/месту -
    # по тексту поста нельзя надёжно понять, у какого именно места
    # перекрытие, так что это просто общий сигнал "сейчас в городе неспокойно
    # на дорогах", а не часть расчёта score конкретного варианта.
    closures_count = count_active_road_closures(city)
    if closures_count:
        lines.append(WHERE_TO_GO_DIVIDER)
        word = "перекрытие" if closures_count == 1 else ("перекрытия" if 2 <= closures_count <= 4 else "перекрытий")
        lines.append(f"🚧 Сейчас в городе {closures_count} активных {word} - см. «⛔ Дорожные события».")

    lines.append(WHERE_TO_GO_DIVIDER)
    if category == 'courier':
        lines.append(
            "_Ориентир по часам активных заказов доставки еды - не гарантия "
            "заработка, реальный спрос может отличаться._"
        )
    elif category == 'cargo':
        lines.append(
            "_Ориентир по рабочим часам бизнеса и складов - не гарантия "
            "заработка, реальный спрос может отличаться._"
        )
    else:
        lines.append(
            "_Ориентир на основе прилётов, статуса аэропортов, очереди и часов "
            "пика - не гарантия заработка, реальный спрос может отличаться._"
        )
    return '\n'.join(lines)

_where_to_go_in_progress = set()  # user_id-ы, для которых сейчас уже считается сводка

async def send_where_to_go(message: types.Message, user_id, city, category, extra_header=None):
    """Общая логика сводки "Куда ехать" - вынесена из show_where_to_go, чтобы
    её же можно было вызвать программно сразу после начала смены (по просьбе
    пользователя, 20.09.2026), а не только по нажатию кнопки "💰 КУДА ЕХАТЬ".
    Не делает проверок города/категории - это ответственность вызывающего.
    extra_header - см. format_where_to_go_text (встраивает "СМЕНА НАЧАТА" в
    начало этого же сообщения, вместо отдельного - по просьбе пользователя,
    20.09.2026)."""
    # Защита от повторного нажатия, пока предыдущий запрос ещё считается
    # (баг 19.09.2026: двойной тап запускал два параллельных расчёта -
    # SingleMessageMiddleware удалял статус-сообщение ПЕРВОГО запроса при
    # отправке статус-сообщения ВТОРОГО, и последующий status_msg.edit_text
    # первого запроса падал на уже удалённом сообщении - без try/except это
    # тихо роняло всю задачу, и "Считаю варианты..." зависало навсегда).
    if user_id in _where_to_go_in_progress:
        return
    _where_to_go_in_progress.add(user_id)
    try:
        status_msg = await show_loading_animation(message.answer, "🧭 Считаю варианты")
        anim_task = asyncio.create_task(animate_loading(status_msg, "🧭 Считаю варианты"))
        try:
            candidates = await compute_where_to_go(city, category)
        except Exception:
            anim_task.cancel()
            # logger.exception (не просто logger.error с str(e)) - пишет
            # полный traceback в логи Railway, а не только текст исключения -
            # без этого при повторной похожей ошибке невозможно понять,
            # ГДЕ именно внутри compute_where_to_go она произошла (баг
            # 21.09.2026: "Не удалось посчитать варианты" стабильно на
            # каждое нажатие, но по одному str(e) причину было не найти).
            logger.exception(f"❌ Ошибка расчёта 'Куда ехать' для {city}/{category}")
            fallback_text = "⚠️ Не удалось посчитать варианты. Попробуй ещё раз через минуту."
            if extra_header:
                fallback_text = f"{extra_header}\n{WHERE_TO_GO_DIVIDER}\n{fallback_text}"
            try:
                await status_msg.edit_text(fallback_text, parse_mode='Markdown' if extra_header else None)
            except Exception:
                await message.answer(fallback_text, parse_mode='Markdown' if extra_header else None)
            return
        anim_task.cancel()
        text = format_where_to_go_text(city, category, candidates, extra_header=extra_header)
        try:
            await status_msg.edit_text(text, parse_mode='Markdown')
        except Exception:
            # status_msg уже мог быть удалён (см. комментарий выше) -
            # отправляем результат новым сообщением, чтобы он точно дошёл.
            await message.answer(text, parse_mode='Markdown')
    finally:
        _where_to_go_in_progress.discard(user_id)

@router.message(lambda message: message.text == "💰 КУДА ЕХАТЬ ➡️")
async def show_where_to_go(message: types.Message):
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    category = state.get('category')
    if not city:
        await message.answer("Сначала выбери город 🏙")
        return
    # Курьер/Грузовое такси (20.09.2026): раньше кнопка была полностью
    # скрыта для этих категорий (не было аэропортов/прилётов, на которых
    # строилась сводка) - теперь у них есть своя версия "Куда ехать" (см.
    # compute_where_to_go/score_city_candidate: единственный кандидат
    # "Город/центр", посчитанный по своей таблице часов пика).
    await send_where_to_go(message, user_id, city, category)

@router.message(lambda message: message.text == "⚙️ НАСТРОЙКИ")
async def show_notification_settings(message: types.Message):
    """"⚙️ НАСТРОЙКИ" в главном меню (по просьбе пользователя, 19.09.2026,
    перенесена сюда из "Инструменты водителя", где была кнопкой
    "🔔 Уведомления"). Пока внутри только один раздел - настройка автопушей
    по типам (см. блок "НАСТРОЙКИ ПУШЕЙ" выше по файлу): каждый тип
    переключается отдельной инлайн-кнопкой (✅/☐), нажатие тоглит и
    перерисовывает клавиатуру на месте. Если в будущем добавятся другие
    настройки - здесь будет промежуточное меню."""
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    category = state.get('category')
    await message.answer(
        "🔔 *Уведомления*\n\nВыбери, какие пуши получать - нажми, чтобы включить/выключить:",
        reply_markup=notification_settings_keyboard(state, category),
        parse_mode='Markdown',
    )

@router.callback_query(lambda c: c.data.startswith("notif_toggle_") and c.data != "notif_toggle_airport_queue")
async def toggle_notification_setting(callback_query: types.CallbackQuery):
    await callback_query.answer()
    user_id = callback_query.from_user.id
    notif_key = callback_query.data[len("notif_toggle_"):]
    if notif_key not in NOTIFICATION_TYPES:
        return
    state = user_state[user_id]
    prefs = dict(state.get('notif_prefs') or {})
    prefs[notif_key] = not notifications_enabled(state, notif_key)
    state['notif_prefs'] = prefs
    await callback_query.message.edit_reply_markup(reply_markup=notification_settings_keyboard(state, state.get('category')))

@router.callback_query(lambda c: c.data == "notif_toggle_airport_queue")
async def toggle_airport_queue_inline(callback_query: types.CallbackQuery):
    """Переключатель "📍 ОЧЕРЕДЬ У АЭРОПОРТА" внутри "⚙️ НАСТРОЙКИ" (по
    просьбе пользователя, 19.09.2026 - перенесена сюда из "Инструменты
    водителя", где раньше была отдельной reply-кнопкой, см.
    toggle_airport_queue_tracking - та же логика влкл/выкл живой геопозиции,
    только теперь тоглится инлайн-кнопкой на месте, без ухода с экрана
    настроек). При первом включении показываем инструкцию по трансляции
    геопозиции отдельным сообщением (её нельзя уместить в подпись
    инлайн-кнопки)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state[user_id]
    category = state.get('category')
    if category in CATEGORIES_WITHOUT_AIRPORTS:
        return
    if state.get('airport_queue_active'):
        state['airport_queue_active'] = False
        state['airport_queue'] = {}
        await callback_query.message.edit_reply_markup(reply_markup=notification_settings_keyboard(state, category))
        await callback_query.message.answer("⏹ Отслеживание очереди у аэропорта остановлено.")
        return
    enable_airport_queue_tracking(user_id)
    await callback_query.message.edit_reply_markup(reply_markup=notification_settings_keyboard(state, category))
    await callback_query.message.answer(airport_queue_enable_text(), parse_mode='Markdown')

# ==================== "СМЕНА" ====================
# По просьбе пользователя (20.09.2026, взамен более раннего варианта с
# отдельным переключателем "Счётчик км" в Настройках): кнопка "▶️ Начать
# смену" в главном меню (см. services_keyboard) одновременно запускает
# секундомер смены и счётчик пройденных км по живой геопозиции (та же
# трансляция, что и "Очередь у аэропорта" - Telegram шлёт обновления как
# edited_message.location, см. km_counter_ping ниже и общий фильтр
# _location_tracking_active рядом с хендлерами location). Кнопка меняется на
# "⏹ Завершить смену" - при нажатии показывает итог (время + км) и СРАЗУ
# сохраняет запись в таблицу shift_history (см. save_shift_record) для
# статистики за 6 месяцев в "💰 ФИНАНСЫ" (см. show_shift_stats).
#
# state['shift'] = {'started_at': iso, 'total_km': float, 'last_lat': float,
# 'last_lon': float} - есть шифт = смена идёт, отсутствует/None = не идёт.
SHIFT_MAX_JUMP_KM = 3.0  # скачок между двумя пингами больше этого - считаем сбоем GPS/потерей сигнала, км не прибавляем (просто обновляем точку)

def is_shift_active(state):
    return bool(state.get('shift'))

# Тарифы для выбора при начале смены (по прямой просьбе пользователя,
# 21.09.2026: "чтобы в начале смены он указывал в каких тарифах он будет
# работать" - можно выбрать несколько сразу, например Эконом+Комфорт).
# СВОЙ список тарифов под каждую категорию (по прямому уточнению
# пользователя, 21.09.2026: "нет смысла предлагать если человек выбрал
# ультима предлагай тарифы эконом комфорт... в такси ты пишешь эконом
# комфорт комфорт + минивэн... детский... Ультиме бизнес премьер Elite и
# круиз") - источник правды теперь CATEGORIES[category]['tariffs'] (те же
# тарифы, что и в остальном боте), а не отдельный общий список для всех.
def shift_tariff_options(category):
    """Список тарифов для выбора при старте смены КОНКРЕТНОЙ категории - см.
    CATEGORIES[category]['tariffs']. У cargo он пуст (нет смысла выбирать
    тариф грузовому такси) - для такой категории тарифный экран вообще не
    показывается, см. toggle_shift."""
    return CATEGORIES.get(category, {}).get('tariffs', [])

def shift_tariffs_keyboard(category, selected):
    """Инлайн-клавиатура выбора тарифов перед стартом смены - несколько
    можно выбрать одновременно (✅/☐, тоглятся на месте), внизу кнопка
    "▶️ НАЧАТЬ СМЕНУ" подтверждает выбор. selected - set выбранных строк
    тарифа (из shift_tariff_options(category)); тариф идентифицируется по
    своему порядковому индексу в списке (callback_data), т.к. сами названия
    тарифов могут содержать пробелы/плюсы, неудобные для callback_data."""
    tariffs = shift_tariff_options(category)
    buttons = []
    for idx, label in enumerate(tariffs):
        mark = '✅' if label in selected else '☐'
        buttons.append([InlineKeyboardButton(text=f"{mark} {label}", callback_data=f"shift_tariff_toggle_{idx}")])
    buttons.append([InlineKeyboardButton(text="▶️ НАЧАТЬ СМЕНУ", callback_data="shift_tariff_confirm")])
    return InlineKeyboardMarkup(inline_keyboard=buttons)

def format_shift_tariffs_label(tariffs):
    """"Эконом, Комфорт" - для подписи маркера на карте (см.
    map_webapp_html/handle_map_positions_api) и для текста сообщения
    "СМЕНА НАЧАТА". Тарифы уже человекочитаемые строки (см.
    CATEGORIES[category]['tariffs']) - просто склеиваем через запятую."""
    return ", ".join(tariffs)

def start_shift(user_id, tariffs=None):
    state = user_state[user_id]
    state['shift'] = {
        'started_at': datetime.now(timezone.utc).isoformat(), 'total_km': 0.0,
        'tariffs': list(tariffs or []),
    }

def km_counter_ping(user_id, lat, lon):
    """Обрабатывает один пинг живой геопозиции для счётчика км текущей смены -
    вызывается из тех же хендлеров location/edited_message, что и
    process_airport_queue_ping (независимо от неё - обе функции могут
    отрабатывать на один и тот же пинг, если у водителя одновременно идёт
    смена и включена очередь у аэропорта). Ничего не делает, если смена не
    идёт (see is_shift_active)."""
    state = user_state[user_id]
    shift = state.get('shift')
    if not shift:
        return
    shift = dict(shift)
    last_lat, last_lon = shift.get('last_lat'), shift.get('last_lon')
    if last_lat is not None and last_lon is not None:
        jump = haversine_km(last_lat, last_lon, lat, lon)
        if jump <= SHIFT_MAX_JUMP_KM:
            shift['total_km'] = shift.get('total_km', 0.0) + jump
    shift['last_lat'] = lat
    shift['last_lon'] = lon
    state['shift'] = shift

SHIFT_LONG_WARNING_HOURS = 12  # после скольких часов за рулём слать предупреждающий пуш (по просьбе пользователя, 20.09.2026)
SHIFT_LONG_WARNING_CHECK_MINUTES = 10  # как часто фоновая задача проверяет длительность активных смен

# По просьбе пользователя (20.09.2026): "сделай так чтобы смена автоматически
# завершалась после 18 часов секундомера ведь юзер может забыть" - за
# SHIFT_AUTO_FINISH_WARN_MINUTES до лимита шлём предупреждение "смена скоро
# завершится автоматически" (флаг warned_auto_finish, тот же принцип
# дедупа, что warned_12h), а по достижении SHIFT_AUTO_FINISH_HOURS -
# завершаем смену сами (finish_shift_and_notify) и предлагаем указать доход,
# как при обычном ручном завершении (по прямому уточнению пользователя).
SHIFT_AUTO_FINISH_HOURS = 18
SHIFT_AUTO_FINISH_WARN_MINUTES = 30

async def check_long_shifts():
    """Фоновая задача (см. asyncio.create_task в main()) - раз в
    SHIFT_LONG_WARNING_CHECK_MINUTES проверяет всех водителей с активной
    сменой (is_shift_active): шлёт предупреждающий пуш о >12 часов за рулём
    (см. SHIFT_LONG_WARNING_HOURS), предупреждает за
    SHIFT_AUTO_FINISH_WARN_MINUTES до автозавершения на
    SHIFT_AUTO_FINISH_HOURS часах, и автоматически завершает смену, если
    водитель забыл это сделать сам. Оба предупреждения - ОДИН РАЗ за смену
    (флаги в state['shift'], сбрасываются сами собой, т.к. finish_shift
    целиком удаляет state['shift']). Берём срез user_state (list(...)), как
    и другие фоновые рассылки в файле - список не должен "плыть" по ходу
    итерации."""
    while True:
        try:
            await asyncio.sleep(SHIFT_LONG_WARNING_CHECK_MINUTES * 60)
            if not bot:
                continue
            now = datetime.now(timezone.utc)
            for user_id, state in list(user_state.items()):
                if not isinstance(state, dict):
                    continue
                shift = state.get('shift')
                if not shift:
                    continue
                try:
                    started_at = datetime.fromisoformat(shift['started_at'])
                except Exception:
                    continue
                elapsed_hours = (now - started_at).total_seconds() / 3600

                # Автозавершение - проверяем ПЕРВЫМ (если лимит уже
                # достигнут, смена завершается и остальные пуши для неё уже
                # не нужны - state['shift'] исчезнет).
                if elapsed_hours >= SHIFT_AUTO_FINISH_HOURS:
                    category = state.get('category')
                    city = state.get('city')
                    try:
                        await finish_shift_and_notify(
                            user_id, category, city,
                            functools.partial(bot.send_message, user_id),
                            header=(
                                f"⏰ *Смена автоматически завершена после {SHIFT_AUTO_FINISH_HOURS} часов "
                                "секундомера* - мы решили, что ты мог просто забыть её выключить."
                            ),
                        )
                    except Exception as e:
                        logger.error(f"❌ Не удалось автозавершить смену пользователю {user_id}: {e}")
                    continue

                if elapsed_hours >= SHIFT_AUTO_FINISH_HOURS - SHIFT_AUTO_FINISH_WARN_MINUTES / 60 and not shift.get('warned_auto_finish'):
                    try:
                        await bot.send_message(
                            user_id,
                            f"⏰ *Смена скоро завершится автоматически* (через ~{SHIFT_AUTO_FINISH_WARN_MINUTES} мин, "
                            f"по достижении {SHIFT_AUTO_FINISH_HOURS} часов секундомера) - если ты всё ещё за рулём, "
                            "ничего делать не нужно, просто учти это. Завершить сейчас можно кнопкой "
                            "«⏹ ЗАВЕРШИТЬ СМЕНУ» в главном меню.",
                            parse_mode='Markdown',
                        )
                    except Exception as e:
                        logger.error(f"❌ Не удалось отправить пуш о скором автозавершении смены пользователю {user_id}: {e}")
                    shift = dict(state.get('shift') or {})
                    if shift:
                        shift['warned_auto_finish'] = True
                        state['shift'] = shift

                if elapsed_hours < SHIFT_LONG_WARNING_HOURS or shift.get('warned_12h'):
                    continue
                try:
                    await bot.send_message(
                        user_id,
                        f"⚠️ *Ты за рулём уже больше {SHIFT_LONG_WARNING_HOURS} часов подряд!*\n\n"
                        "Долгая смена без отдыха повышает риск аварии - сделай перерыв, "
                        "если получится.\n\n"
                        "Завершить смену можно кнопкой «⏹ ЗАВЕРШИТЬ СМЕНУ» в главном меню.",
                        parse_mode='Markdown',
                    )
                except Exception as e:
                    logger.error(f"❌ Не удалось отправить пуш о долгой смене пользователю {user_id}: {e}")
                # Ставим флаг независимо от успеха отправки - иначе при
                # временной ошибке Telegram будем долбить пуш каждую
                # проверку до конца смены.
                shift = dict(state.get('shift') or {})
                if shift:
                    shift['warned_12h'] = True
                    state['shift'] = shift
        except Exception as e:
            logger.error(f"❌ Ошибка в check_long_shifts: {e}")

def finish_shift(user_id):
    """Останавливает смену, возвращает (duration_minutes, total_km,
    airport_wait_minutes) и сохраняет запись в БД (save_shift_record) -
    вызывается из toggle_shift. Не падает, если смены не было (защитный
    случай - кнопка не должна быть видна в этом состоянии, но на всякий
    случай)."""
    state = user_state[user_id]
    shift = state.pop('shift', None)
    if not shift:
        return 0, 0.0, 0
    started_at = datetime.fromisoformat(shift['started_at'])
    now = datetime.now(timezone.utc)
    duration_minutes = max(0, round((now - started_at).total_seconds() / 60))
    total_km = shift.get('total_km', 0.0)
    airport_wait_minutes = shift.get('airport_wait_minutes', 0)
    # Если смена завершается, пока водитель ещё в радиусе аэропорта
    # (state['airport_queue']['entered_outer_at'] не сброшен) - досчитываем
    # незакрытый интервал простоя, иначе он бы потерялся (см. основной учёт
    # в process_airport_queue_ping при выходе из радиуса).
    aq = state.get('airport_queue') or {}
    if aq.get('entered_outer_at'):
        try:
            entered_at = datetime.fromisoformat(aq['entered_outer_at'])
            airport_wait_minutes += max(0, round((now - entered_at).total_seconds() / 60))
        except Exception:
            pass
    save_shift_record(user_id, started_at, duration_minutes, total_km, airport_wait_minutes)
    # По прямой просьбе пользователя (21.09.2026): "когда завершает смену на
    # карте его не видно" - убираем сразу, не дожидаясь устаревания точки
    # (см. MAP_VISIBILITY_STALE_MINUTES).
    try:
        delete_map_position(user_id)
    except Exception:
        logger.exception(f"❌ Не удалось убрать с карты водителей user_id={user_id} при завершении смены")
    return duration_minutes, total_km, airport_wait_minutes

def format_shift_duration(minutes):
    hours, mins = divmod(minutes, 60)
    if hours and mins:
        return f"{hours} ч {mins} мин"
    if hours:
        return f"{hours} ч"
    return f"{mins} мин"

RU_WEEKDAYS = ('понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота', 'воскресенье')

def format_shift_start_label(started_at):
    """"20:14, суббота" - для сообщения о начале смены (по просьбе
    пользователя, 20.09.2026). started_at - datetime в UTC (как хранится в
    state['shift']['started_at']) - переводим в московское время (UTC+3) для
    показа, т.к. весь бот ориентирован на российских водителей."""
    local = started_at + timedelta(hours=3)
    weekday = RU_WEEKDAYS[local.weekday()]
    return f"{local.strftime('%H:%M')}, {weekday}"

@router.message(lambda message: message.text in ("✅ НАЧАТЬ СМЕНУ", "⏹ ЗАВЕРШИТЬ СМЕНУ"))
async def toggle_shift(message: types.Message):
    """Одна кнопка-переключатель наверху главного меню (выше "💰 КУДА ЕХАТЬ",
    см. services_keyboard) - текст меняется в зависимости от того, идёт ли
    смена, т.к. это одна и та же позиция клавиатуры."""
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    category = state.get('category')
    city = state.get('city')
    if not city:
        await message.answer("Сначала выбери город!")
        return

    if message.text == "✅ НАЧАТЬ СМЕНУ":
        if is_shift_active(state):
            return  # защитный случай - кнопка не должна была показать "Начать", если смена уже идёт
        # По прямой просьбе пользователя (21.09.2026): "когда он нажимает
        # начать смену он автоматически появляется на карте... чтобы в
        # начале смены он указывал в каких тарифах он будет работать и это
        # являлась триггером определении его на карте" - категориям, у
        # которых вообще есть карта (см. MAP_CATEGORY_STYLE), сначала
        # показываем выбор тарифов; остальным (на будущее, если появятся
        # категории без карты) смена стартует сразу без этого шага.
        # Тарифный экран показываем только там, где вообще есть свой список
        # тарифов (shift_tariff_options) - у cargo он пуст, выбирать нечего.
        if category in MAP_CATEGORY_STYLE and shift_tariff_options(category):
            state['shift_tariff_pending'] = set()
            await message.answer(
                "🚕 В каких тарифах работаешь эту смену? Выбери один или несколько, потом нажми «▶️ Начать смену».",
                reply_markup=shift_tariffs_keyboard(category, set()),
            )
            return
        # ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "надо сделать
        # так чтобы начать смену нельзя было без включённой геолокации") -
        # см. require_live_location_for_shift_start ниже.
        if await require_live_location_for_shift_start(message, user_id, state, tariffs=[]):
            return
        await start_shift_and_notify(message.answer, user_id, category, city, tariffs=[])
        return

    if not is_shift_active(state):
        return  # защитный случай - кнопка не должна была показать "Завершить", если смены нет
    await finish_shift_and_notify(user_id, category, city, message.answer)

class _AnswerFuncAsMessage:
    """Тонкая обёртка вокруг функции-отправителя (message.answer или
    callback_query.message.answer) с сигнатурой message.answer - нужна
    только там, куда функцию уже передали САМУ ПО СЕБЕ (как target в
    start_shift_and_notify), а не объект message целиком, но код дальше
    (send_where_to_go) вызывает именно message.answer(...)."""
    def __init__(self, answer_func):
        self.answer = answer_func

async def start_shift_and_notify(target, user_id, category, city, tariffs):
    """Общая логика старта смены: запускает секундомер/счётчик км
    (start_shift), сразу выводит водителя на карту (update_map_position,
    только для категорий с картой - см. MAP_CATEGORY_STYLE) и шлёт сообщение
    "СМЕНА НАЧАТА" + сводку "Куда ехать". target - message.answer (обычный
    старт) или callback_query.message.answer (после выбора тарифов, см.
    shift_tariff_confirm)."""
    start_shift(user_id, tariffs=tariffs)
    if category in MAP_CATEGORY_STYLE:
        # На карту водитель попадёт с первым же пингом живой геопозиции
        # (см. maybe_update_map_position) - тут только помечаем смену
        # активной с известными тарифами; сама точка появится, как только
        # придёт геопозиция. Если у бота уже есть свежая точка (водитель
        # транслировал геопозицию до старта смены) - публикуем сразу, чтобы
        # не ждать следующего пинга.
        fresh = get_fresh_live_location(user_id)
        if fresh:
            try:
                update_map_position(user_id, city, category, fresh[0], fresh[1], tariffs=tariffs)
            except Exception:
                logger.exception(f"❌ Не удалось сразу вывести на карту user_id={user_id}")
    started_at = datetime.fromisoformat(user_state[user_id]['shift']['started_at'])
    tariffs_line = ""
    if tariffs:
        tariffs_line = f"🚕 Тарифы: {format_shift_tariffs_label(tariffs)}\n"
    shift_header = (
        "🟢 *СМЕНА НАЧАТА*\n"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        f"🕐 {format_shift_start_label(started_at)}\n"
        f"{tariffs_line}"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        "📎 Чтобы считался километраж и ты был виден на карте водителей: Геопозиция → "
        "*«Транслировать геопозицию»* → *«Пока не отключу»*.\n"
        "_Без трансляции секундомер идёт как обычно, но км и показ на карте не сработают._"
    )
    # По просьбе пользователя (20.09.2026): сообщение "СМЕНА НАЧАТА" и
    # сводка "Куда ехать" - теперь ОДНО сообщение (раньше были два
    # отдельных) - см. extra_header у send_where_to_go/
    # format_where_to_go_text. Сначала обновляем клавиатуру коротким
    # тех.сообщением (Reply-клавиатуру нельзя приложить к тому же
    # сообщению, что инлайн-результат "Куда ехать"). Раньше это было
    # только для категорий с аэропортами - теперь доступно всем, включая
    # courier/cargo (у них теперь тоже есть сводка "Куда ехать" на
    # своих часах пика, см. compute_where_to_go).
    await target("✅ Смена начата", reply_markup=services_keyboard(category, city, user_id))
    # send_where_to_go ожидает объект message (зовёт message.answer(...)
    # внутри) - target у нас уже сама функция answer (message.answer или
    # callback_query.message.answer), поэтому оборачиваем в простой объект с
    # атрибутом .answer вместо неё самой (см. _AnswerFuncAsMessage ниже).
    await send_where_to_go(_AnswerFuncAsMessage(target), user_id, city, category, extra_header=shift_header)

@router.callback_query(lambda c: c.data.startswith("shift_tariff_toggle_"))
async def shift_tariff_toggle(callback_query: types.CallbackQuery):
    """Тоггл одного тарифа в клавиатуре выбора перед стартом смены (см.
    shift_tariffs_keyboard) - хранится временно в
    state['shift_tariff_pending'], пока водитель не нажмёт "▶️ Начать
    смену" (shift_tariff_confirm)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state[user_id]
    if 'shift_tariff_pending' not in state:
        return  # смена уже стартовала другим путём/клавиатура устарела
    category = state.get('category')
    tariffs = shift_tariff_options(category)
    try:
        idx = int(callback_query.data[len("shift_tariff_toggle_"):])
        label = tariffs[idx]
    except (ValueError, IndexError):
        return
    selected = set(state['shift_tariff_pending'])
    if label in selected:
        selected.discard(label)
    else:
        selected.add(label)
    state['shift_tariff_pending'] = selected
    await callback_query.message.edit_reply_markup(reply_markup=shift_tariffs_keyboard(category, selected))

@router.callback_query(lambda c: c.data == "shift_tariff_confirm")
async def shift_tariff_confirm(callback_query: types.CallbackQuery):
    """Кнопка "▶️ НАЧАТЬ СМЕНУ" внутри клавиатуры выбора тарифов - можно
    подтвердить и без единого выбранного тарифа (просто не будет подписи
    тарифов на карте, останется только категория)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state[user_id]
    if is_shift_active(state):
        return  # защитный случай - двойное нажатие
    tariffs = sorted(state.pop('shift_tariff_pending', set()))
    category = state.get('category')
    city = state.get('city')
    if not city:
        await callback_query.message.answer("Сначала выбери город!")
        return
    # ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "начать смену
    # нельзя было без включённой геолокации") - см.
    # require_live_location_for_shift_start ниже.
    if await require_live_location_for_shift_start(callback_query.message, user_id, state, tariffs=tariffs):
        await callback_query.message.edit_reply_markup(reply_markup=None)
        return
    await callback_query.message.edit_reply_markup(reply_markup=None)
    await start_shift_and_notify(callback_query.message.answer, user_id, category, city, tariffs)

async def finish_shift_and_notify(user_id, category, city, send_func, header=None):
    """Общая логика завершения смены: считает итоги (finish_shift), шлёт
    сообщение "СМЕНА ЗАВЕРШЕНА" и предлагает указать доход за день - вынесена
    из toggle_shift (по просьбе пользователя, 20.09.2026: "сделай так чтобы
    смена автоматически завершалась после 18 часов"), чтобы тем же кодом
    пользовался и хендлер кнопки "⏹ ЗАВЕРШИТЬ СМЕНУ", и фоновая
    автозавершающая задача (см. check_long_shifts). send_func - функция
    отправки сообщения с сигнатурой message.answer (kwargs reply_markup/
    parse_mode) - у ручного завершения это message.answer, у автоматического
    partial(bot.send_message, user_id). header - опциональный текст ПЕРЕД
    "СМЕНА ЗАВЕРШЕНА" (используется для "⏰ Автоматически завершена по
    достижении лимита времени", см. auto_finish_long_shifts)."""
    duration_minutes, total_km, _airport_wait_minutes = finish_shift(user_id)
    # По просьбе пользователя (21.09.2026): сразу по завершении смены
    # показать потраченное на топливо/эл-заряд, используя ранее сохранённые
    # цену топлива и средний расход (см. FINANCE_REMEMBERED_FIELDS/
    # finance_defaults - тот же профиль, что заполняется в "💰 ФИНАНСЫ"). Если
    # ни разу не вводились - строку пропускаем (не заставляем вводить
    # прямо тут, обычный ввод остаётся в "💰 УКАЗАТЬ ДОХОД ЗА ДЕНЬ" ниже).
    state = user_state.get(user_id) or {}
    defaults = finance_defaults(state)
    consumption = defaults.get('consumption')
    fuel_price = defaults.get('fuel_price')
    fuel_line = ""
    if consumption and fuel_price:
        fuel_cost = (total_km / 100) * consumption * fuel_price
        fuel_line = f"⛽ Потрачено на топливо: ~{fuel_cost:.0f} ₽ ({consumption:g} л/100км × {fuel_price:g} ₽/л)\n"
    body = (
        "🔴 *СМЕНА ЗАВЕРШЕНА*\n"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        f"⏱ {format_shift_duration(duration_minutes)}   🛣 {total_km:.1f} км\n"
        f"{fuel_line}"
        "▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓▓\n"
        "_Запись сохранена в «💰 Финансы» → «📈 Статистика смен»._"
    )
    if header:
        body = f"{header}\n{body}"
    await send_func(body, reply_markup=services_keyboard(category, city, user_id), parse_mode='Markdown')
    # По просьбе пользователя (20.09.2026): сразу после завершения смены
    # предлагаем указать доход за день - отдельной инлайн-кнопкой (а не
    # сразу форсируем ввод текста, чтобы не мешать, если человек ещё за
    # рулём/занят). Km подставляем автоматически из только что завершённой
    # смены - см. start_finance_after_shift.
    await send_func(
        "Хочешь сразу посчитать доход за эту смену?",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="💰 УКАЗАТЬ ДОХОД ЗА ДЕНЬ", callback_data="start_finance_after_shift"),
        ]]),
    )

def airport_queue_enable_text():
    """Общий текст-инструкция - используется и в toggle_airport_queue_tracking
    (кнопка в Инструментах водителя), и в suggest_airport_queue_tracking (пуш
    сразу после выбора категории, см. select_category) - чтобы не разъезжались
    две копии текста. Рекомендуем «Пока не отключу» (а не «8 часов», как было
    раньше) - при таком выборе трансляция не обрывается сама вообще, водителю
    не нужно ничего вспоминать (если он всё же сам остановит её или она
    прервётся по другой причине - see send_airport_queue_expired_push)."""
    return (
        "📍 *Очередь в аэропорт для Тарифов Яндекс.Go*\n\n"
        "Как включить: скрепка 📎 → Геопозиция → *«Транслировать геопозицию»* → "
        "выбирай *«Пока не отключу»* - трансляция не оборвётся сама, и ты не "
        "пропустишь уведомления. Если сама прервётся (например разрядится "
        "телефон) - напомню включить заново.\n\n"
        "Дальше всё автоматически: пришлю пуш на 2 км от аэропорта, затем на 1 км и 500 м, "
        "и ещё один - через 30 минут, если всё ещё рядом. "
        "Если едешь с заказом, вставать в очередь не планируешь, или геолокация ошиблась "
        "(бывает из-за глушения GPS) - на любом из этих пушей есть кнопка «📍❌ Ошибка GPS / Очередь не требуется», "
        "она отключит напоминания на 30 минут.\n\n"
        "Помогает не терять счёт времени в очереди на получение заказа.\n\n"
        "Чтобы остановить очередь - зайди в «⚙️ Настройки» и нажми «📍 Очередь у аэропорта» ещё раз."
    )

def enable_airport_queue_tracking(user_id):
    state = user_state[user_id]
    state['airport_queue_active'] = True
    state['airport_queue'] = {}

@router.message(lambda message: message.text == "📍 ОЧЕРЕДЬ У АЭРОПОРТА" and user_state.get(message.from_user.id, {}).get('in_courier_module') and user_state.get(message.from_user.id, {}).get('category') not in CATEGORIES_WITHOUT_AIRPORTS)
async def toggle_airport_queue_tracking(message: types.Message):
    """Кнопка-переключатель (toggle, без отдельного экрана): первое нажатие
    включает отслеживание живой геопозиции и объясняет, как её включить в
    самом Telegram (бот не может запросить живую геопозицию сам - только
    обычный request_location=True, разовую точку, см. handle_nearby_location
    выше - для живой трансляции юзер обязательно жмёт 📎 сам). Повторное
    нажатие выключает и сбрасывает накопленное состояние (см.
    process_airport_queue_ping/check_airport_queue_timers рядом с
    push_airport_status_change). Скрыта для courier/cargo в самой клавиатуре
    (courier_module_keyboard) - фильтр по CATEGORIES_WITHOUT_AIRPORTS в
    декораторе тут просто защита на случай, если кнопка всё же придёт
    текстом (например с уже открытой у пользователя старой клавиатуры)."""
    user_id = message.from_user.id
    state = user_state[user_id]
    category = state.get('category')
    if state.get('airport_queue_active'):
        state['airport_queue_active'] = False
        state['airport_queue'] = {}
        await message.answer("⏹ Отслеживание очереди у аэропорта остановлено.", reply_markup=courier_module_keyboard(category))
        return
    enable_airport_queue_tracking(user_id)
    await message.answer(airport_queue_enable_text(), reply_markup=courier_module_keyboard(category), parse_mode='Markdown')

def airport_queue_bonus_line(user_id, icao, zone_key=None):
    """Необязательная строка-бонус в пуше - последняя САМООТЧЁТНАЯ отметка
    длины очереди от других водителей (см. queue_latest_report/"🚗 Занять
    очередь" - уже существующая, отдельная от геолокации фича). Если свежей
    отметки нет или класс не совпал - просто не добавляем строку, ничего не
    ломается. zone_key - см. _queue_airport_key (чтобы бонус у Шереметьево
    брался именно из очереди своего терминала, а не соседнего)."""
    city = ICAO_TO_CITY.get(icao)
    if not city:
        return ""
    range_str, ts = queue_latest_report(city, icao, queue_class_key(user_id), zone_key=zone_key)
    if not range_str:
        return ""
    local_time = format_airport_local_time(ts, icao)
    return f"\n\n🚗 Последняя отметка водителей: *{range_str}* машин в {local_time}"

def format_airport_queue_push(kind, airport, dist_km, zone_label=None):
    """zone_label - для Шереметьево (см. AIRPORT_TERMINAL_ZONES) уточняет,
    к какому именно терминальному комплексу ближе водитель ("Терминалы B/C"
    или "Терминал D") - у остальных аэропортов всегда None, текст не
    меняется."""
    name = f"{airport['emoji']} {airport['name']}"
    if zone_label:
        # airport['name'] для Шереметьево УЖЕ содержит зону нейтральной
        # записи (ICAO_TO_AIRPORT всегда берёт "SVO (Шереметьево B/C)" - см.
        # комментарий у ICAO_TO_AIRPORT) - без этой обрезки получался бы
        # видимый дубль "(Шереметьево B/C) (Терминалы B/C)" (баг, отчёт
        # пользователя 20.09.2026, скриншот). Срезаем хвост в скобках перед
        # тем как подставить актуальный zone_label.
        base_name = re.sub(r'\s*\([^)]*\)\s*$', '', airport['name'])
        name = f"{airport['emoji']} {base_name} ({zone_label})"
    # ИЗМЕНЕНО 21.09.2026 (прямая просьба пользователя, уточнена в тот же
    # день): шкала расстояний теперь 2км/1км/500м (см.
    # AIRPORT_QUEUE_RADIUS_LEVELS_KM) вместо прежних 3км/1.5км - 'enter_outer'
    # остаётся первым (самым дальним) уровнем ради обратной совместимости
    # имени, остальные - 'enter_level_N' по индексу в AIRPORT_QUEUE_RADIUS_LEVELS_KM.
    if kind == 'enter_outer':
        return f"📍 Вы примерно в {dist_km:.1f} км от {name}.\n\nОтслеживаю время рядом - напомню по мере приближения, а дальше через 30 минут, если всё ещё будете рядом."
    if isinstance(kind, str) and kind.startswith('enter_level_'):
        if dist_km < 1:
            dist_label = f"{round(dist_km * 1000)} м"
        else:
            dist_label = f"{dist_km:.1f} км"
        return f"📍 Вы уже в {dist_label} от {name} - почти на месте."
    if kind == 30:
        return f"⏱ Вы уже 30 минут рядом с {name}."
    return ""

def find_airport_queue_join_target(icao, zone_key=None):
    """Находит (city, airport_idx) в AIRPORTS_INFO для кнопки "🚗 Встать в
    очередь" на гео-пуше об аэропорте - переиспользует ту же самоотчётную
    очередь (callback_data f"join_queue_{city}_{idx}"), что и кнопка
    "🚗 ЗАНЯТЬ ОЧЕРЕДЬ" в разделе "✈️🚆 АВИА/ЖД" (см. show_range_picker). По
    прямой просьбе пользователя (20.09.2026): "каждый пуш от аэропорта
    должен предлагать чтобы водитель не забывал вставать в очередь". Для
    аэропортов с зонами (Шереметьево) ищет запись именно с нужным zone_key,
    чтобы отметка ушла в правильную зону (B/C или D), а не в первую
    попавшуюся; без совпадения по зоне - берёт первую запись с этим icao."""
    city = ICAO_TO_CITY.get(icao)
    if not city:
        return None
    airports = AIRPORTS_INFO.get(city, [])
    if zone_key:
        for i, airport in enumerate(airports):
            if airport.get('icao') == icao and airport.get('zone_key') == zone_key:
                return (city, i)
    for i, airport in enumerate(airports):
        if airport.get('icao') == icao:
            return (city, i)
    return None

def get_airport_queue_snoozed_until(state, icao):
    """Читает snooze для АЭРОПОРТА целиком (не зоны) - см. комментарий у
    AIRPORT_QUEUE_SNOOZE_MINUTES. Возвращает datetime или None."""
    store = state.get('airport_queue_snooze') or {}
    until_str = store.get(icao)
    if not until_str:
        return None
    try:
        return datetime.fromisoformat(until_str)
    except Exception:
        return None

def set_airport_queue_snooze(state, icao, minutes):
    """Ставит snooze для АЭРОПОРТА целиком на `minutes` от текущего момента -
    действует сразу на все его терминальные зоны (B/C/D у Шереметьево),
    см. handle_airport_queue_snooze."""
    store = dict(state.get('airport_queue_snooze') or {})
    store[icao] = (datetime.now(ZoneInfo('UTC')) + timedelta(minutes=minutes)).isoformat()
    state['airport_queue_snooze'] = store

async def send_airport_queue_push(user_id, icao, kind, dist_km=None, zone_label=None, zone_key=None):
    if not bot:
        return
    airport = ICAO_TO_AIRPORT.get(icao)
    if not airport:
        return
    text = format_airport_queue_push(kind, airport, dist_km if dist_km is not None else 0, zone_label)
    text += airport_queue_bonus_line(user_id, icao, zone_key)
    reply_markup = None
    target = find_airport_queue_join_target(icao, zone_key)
    if target:
        target_city, airport_idx = target
        buttons = []
        # ДОБАВЛЕНО 20.09.2026 (по просьбе пользователя - "если он отметился
        # в зоне аэропорта раз, второй раз можно уже не спрашивать"): если у
        # водителя уже есть СВОЯ свежая отметка по этому аэропорту/терминалу
        # (он уже проходил выбор тарифа и диапазона недавно) - добавляем
        # кнопку-подтверждение "✅ УЖЕ В ОЧЕРЕДИ", которая одним нажатием
        # просто освежает время той же самой отметки (тот же диапазон машин),
        # без повторного выбора тарифа/диапазона. "🚗 ВСТАТЬ В ОЧЕРЕДЬ"
        # остаётся рядом - на случай, если число машин в очереди изменилось
        # и нужно отметить заново.
        own_marks = user_recent_queue_marks(user_id, target_city, icao, zone_key)
        if own_marks:
            keep_key = f"qkeep_{target_city}_{icao}_{zone_key or '-'}"
            buttons.append([InlineKeyboardButton(text="✅ УЖЕ В ОЧЕРЕДИ", callback_data=keep_key)])
        buttons.append([InlineKeyboardButton(text="🚗 ВСТАТЬ В ОЧЕРЕДЬ" if not own_marks else "🔄 Обновить очередь", callback_data=f"join_queue_{target_city}_{airport_idx}")])
        # ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя): водитель может
        # ехать с заказом/без намерения вставать в очередь этого аэропорта -
        # кнопка снимает пуши очереди на AIRPORT_QUEUE_SNOOZE_MINUTES минут
        # для ЭТОГО аэропорта (все его зоны сразу, см. комментарий у
        # AIRPORT_QUEUE_SNOOZE_MINUTES), "чтобы человека лишний раз не
        # тревожить". На ВСЕХ пушах очереди (по прямой просьбе
        # пользователя), не только на первом. callback_data - просто icao
        # (без зоны, с 22.09.2026 - см. get_airport_queue_snoozed_until).
        buttons.append([InlineKeyboardButton(text="📍❌ ОШИБКА GPS / ОЧЕРЕДЬ НЕ ТРЕБУЕТСЯ", callback_data=f"aqsnooze_{icao}")])
        reply_markup = InlineKeyboardMarkup(inline_keyboard=buttons)
    try:
        await bot.send_message(user_id, text, reply_markup=reply_markup, parse_mode='Markdown')
    except Exception as e:
        logger.warning(f"⚠️ Не удалось отправить пуш об очереди у аэропорта пользователю {user_id}: {e}")

# ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "когда выезжаешь за
# пределы зоны аэропорта он присылает пуш и там отмечаешься что ты покинул
# очередь"): пуш при ВЫХОДЕ из внешнего радиуса зоны аэропорта (см.
# process_airport_queue_ping, ветка "Вышел за пределы внешнего радиуса") -
# с инлайн-кнопкой "🚪 Я ПОКИНУЛ ОЧЕРЕДЬ". Пока кнопка просто подтверждает
# нажатие ("Отмечено") - специально без сохранения данных, по прямой
# просьбе пользователя ("пока просто кнопка потом будем с нее данные
# собирать") - реальный сбор статистики (сколько водитель реально простоял
# в очереди и т.п.) будет отдельной задачей позже.
async def send_airport_queue_left_push(user_id, icao, zone_label=None):
    if not bot:
        return
    airport = ICAO_TO_AIRPORT.get(icao)
    if not airport:
        return
    name = f"{airport['emoji']} {airport['name']}"
    if zone_label:
        base_name = re.sub(r'\s*\([^)]*\)\s*$', '', airport['name'])
        name = f"{airport['emoji']} {base_name} ({zone_label})"
    text = f"🚪 Ты выехал(а) из зоны {name}."
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="🚪 Я ПОКИНУЛ ОЧЕРЕДЬ", callback_data=f"aqleft_{icao}")]
    ])
    try:
        await bot.send_message(user_id, text, reply_markup=keyboard)
    except Exception as e:
        logger.warning(f"⚠️ Не удалось отправить пуш о выходе из зоны аэропорта пользователю {user_id}: {e}")

@router.callback_query(lambda c: c.data.startswith("aqleft_"))
async def airport_queue_left_confirm(callback_query: types.CallbackQuery):
    """Кнопка "🚪 Я ПОКИНУЛ ОЧЕРЕДЬ" на пуше о выходе из зоны аэропорта - пока
    просто подтверждение нажатия, без сохранения данных (см. комментарий у
    send_airport_queue_left_push выше)."""
    try:
        await callback_query.answer("Отмечено ✅")
    except Exception:
        pass
    try:
        await callback_query.message.edit_reply_markup(reply_markup=None)
    except Exception:
        pass

async def send_airport_queue_expired_push(user_id, icao):
    """Пуш-напоминание на случай, когда трансляция геопозиции, судя по
    всему, закончилась (см. check_airport_queue_timers) - по просьбе
    пользователя, чтобы водитель не забывал включить её заново, если он
    всё ещё работает. icao может быть None (трансляция началась, но юзер
    ни разу не оказывался рядом ни с одним аэропортом) - тогда просто без
    упоминания конкретного аэропорта."""
    if not bot:
        return
    airport = ICAO_TO_AIRPORT.get(icao) if icao else None
    where = f" у {airport['emoji']} {airport['name']}" if airport else ""
    text = (
        f"📡 Трансляция геопозиции{where}, похоже, закончилась.\n\n"
        f"Если ты всё ещё на линии - включи её заново: скрепка 📎 → Геопозиция → "
        f"«Транслировать геопозицию» → *«Пока не отключу»*, чтобы не пропускать отметки "
        f"об очереди у аэропорта."
    )
    try:
        await bot.send_message(user_id, text, parse_mode='Markdown')
    except Exception as e:
        logger.warning(f"⚠️ Не удалось отправить пуш об окончании трансляции геопозиции пользователю {user_id}: {e}")

async def process_airport_queue_ping(user_id, lat, lon, live_period=None):
    """Обрабатывает один пинг геопозиции (и разовый message.location, и
    последующие edited_message.location трансляции - см. хендлеры ниже) -
    считает расстояние до ближайшего аэропорта (и, для Шереметьево, до
    ближайшей терминальной зоны - см. nearest_airport_zone/
    AIRPORT_TERMINAL_ZONES), шлёт пуши по мере приближения (см.
    AIRPORT_QUEUE_RADIUS_LEVELS_KM), обновляет user_state[uid]['airport_queue']
    для фонового чекера (30 мин - см. check_airport_queue_timers)."""
    state = user_state.get(user_id)
    if not state or not state.get('airport_queue_active'):
        return
    if state.get('category') in CATEGORIES_WITHOUT_AIRPORTS:
        # Защитный случай - активная трансляция, начатая ДО смены категории
        # на courier/cargo, не должна продолжать слать аэропортовые пуши.
        return
    icao, dist_km, zone_key, zone_label = nearest_airport_zone(lat, lon)
    if icao is None:
        return
    now = datetime.now(ZoneInfo('UTC'))
    aq = dict(state.get('airport_queue') or {})
    # ДОБАВЛЕНО 21.09.2026 (прямая просьба пользователя - кнопка "не буду
    # вставать в очередь" на пуше, "чтобы человека лишний раз не тревожить"),
    # ИЗМЕНЕНО 22.09.2026 (см. комментарий у AIRPORT_QUEUE_SNOOZE_MINUTES) -
    # snooze теперь хранится per-АЭРОПОРТ отдельно от aq (get_airport_queue_
    # snoozed_until), поэтому переживает скачки GPS между терминальными
    # зонами B/C/D одного аэропорта и не завязан на точное совпадение
    # (icao, zone_key) с моментом нажатия кнопки. Координаты/время
    # последнего пинга (aq['last_update_at']) всё равно обновляются ниже -
    # snooze не должен путать check_airport_queue_timers's "трансляция
    # прервалась" со снятой отметкой "не хочу пушей".
    snoozed_until = get_airport_queue_snoozed_until(state, icao)
    is_snoozed = bool(snoozed_until and now < snoozed_until)
    # ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "и пропадает если
    # человек уже встал в очередь"): если у водителя уже есть СВОЯ свежая
    # отметка (за QUEUE_ENTRY_TTL_MINUTES) по этому аэропорту/зоне - он уже
    # встал в очередь, напоминание "🚗 ВСТАТЬ В ОЧЕРЕДЬ" больше не нужно.
    # Тот же принцип, что и is_snoozed (пуш подавляется), но источник другой -
    # не ручной снуз, а факт реальной отметки. is_already_queued используется
    # и ниже (уровни расстояния), и в check_airport_queue_timers (пуш "уже 30
    # минут рядом").
    city_for_marks = ICAO_TO_CITY.get(icao)
    is_already_queued = bool(city_for_marks and user_recent_queue_marks(user_id, city_for_marks, icao, zone_key))
    # Смена АЭРОПОРТА или, для Шереметьево, смена ЗОНЫ (B <-> C <-> D,
    # это отдельные подъезды - водитель, переехавший из одной в другую,
    # по факту заново въезжает в радиус) - начинаем отслеживание с чистого
    # листа. У однозонных аэропортов zone_key всегда None, so сравнение
    # (icao, zone_key) для них эквивалентно старому сравнению icao.
    if (aq.get('icao'), aq.get('zone_key')) != (icao, zone_key):
        # Аэропорт/зона сменились - начинаем отслеживание уровней/таймера
        # заново (новый заход в радиус). is_snoozed НЕ трогаем и не гасим -
        # с 22.09.2026 он привязан к аэропорту целиком (см. комментарий у
        # AIRPORT_QUEUE_SNOOZE_MINUTES), а не к этой (icao, zone_key)-паре,
        # так что смена терминальной зоны того же аэропорта больше не
        # обходит snooze (именно это раньше ломалось при скачках GPS между
        # B/C/D у Шереметьево).
        aq = {'icao': icao, 'zone_key': zone_key}
    aq['last_update_at'] = now.isoformat()
    if live_period:
        aq['live_period'] = live_period

    # ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "зона аэропорта в
    # 1.5 км, исключение для внуково 2.5 км"): самый внешний уровень больше
    # не фиксированный AIRPORT_QUEUE_RADIUS_LEVELS_KM[0] (2 км для всех) - он
    # берётся из airport_queue_outer_radius_km(icao), у Внуково это 2.5 км,
    # у остальных 1.5 км. Уровни ПОУЖЕ (1 км/500 м) не меняются - идут следом
    # за внешним, как и раньше.
    outer_radius_km = airport_queue_outer_radius_km(icao)
    levels_km = [outer_radius_km] + [lvl for lvl in AIRPORT_QUEUE_RADIUS_LEVELS_KM[1:] if lvl < outer_radius_km]
    if dist_km <= outer_radius_km:
        if not aq.get('entered_outer_at'):
            # Первый вход в САМЫЙ ШИРОКИЙ радиус - как и раньше, начало
            # отсчёта для таймера "уже 30 минут рядом" (см. check_airport_queue_timers).
            aq['entered_outer_at'] = now.isoformat()
            aq['pushed_30'] = False
        # ИЗМЕНЕНО 22.09.2026 (жёсткая просьба пользователя - "push
        # уведомления и сбор данных осуществляется только после того когда
        # человек встал в очередь, не вставая в очередь этот пуш прийти не
        # может"): раньше лог входа (log_airport_queue_entered) создавался
        # сразу при попадании в радиус аэропорта, ДО того как водитель
        # реально отмечался в очереди - из-за этого позже, при выезде,
        # всегда уходил пуш "Ты выехал(а) из зоны"/"Я ПОКИНУЛ ОЧЕРЕДЬ", даже
        # если водитель просто проезжал мимо и в очередь вообще не вставал
        # (жалоба пользователя, скриншот). Теперь строка лога создаётся
        # ТОЛЬКО в момент, когда у водителя появляется СВОЯ свежая отметка
        # по этому аэропорту/зоне (is_already_queued - т.е. он реально нажал
        # "🚗 ВСТАТЬ В ОЧЕРЕДЬ"/"✅ УЖЕ В ОЧЕРЕДИ" или отметился через
        # "✈️🚆 АВИА/ЖД"), и только один раз за этот заход (queue_log_id ещё
        # не установлен). entered_at берём из entered_outer_at - реальное
        # время появления в зоне, а не момент отметки - чтобы wait_minutes
        # по-прежнему считал время именно ожидания у аэропорта.
        if is_already_queued and not aq.get('queue_log_id'):
            try:
                entered_at_for_log = datetime.fromisoformat(aq['entered_outer_at'])
            except Exception:
                entered_at_for_log = now
            aq['queue_log_id'] = log_airport_queue_entered(
                user_id, icao, zone_key, zone_label, city_for_marks,
                (state.get('shift') or {}).get('tariffs'), entered_at_for_log,
            )
        # ИЗМЕНЕНО 21.09.2026: раньше было только 2 фиксированных уровня
        # (outer/inner), теперь идём по levels_km (внешний уровень аэропорта +
        # оставшиеся более узкие уровни) по порядку - шлём пуш за каждый
        # уровень, который водитель проходит ВПЕРВЫЕ за этот заход
        # (entered_levels - список уже пройденных индексов уровня, чтобы не
        # дублировать пуш при повторных пингах на том же расстоянии). Если
        # сейчас snooze (водитель нажал "не буду вставать в очередь") -
        # уровень всё равно ЗАПОМИНАЕМ как пройденный (чтобы после истечения
        # snooze не засыпало пушами за все пропущенные уровни разом), но пуш
        # НЕ шлём.
        entered_levels = set(aq.get('entered_levels') or [])
        for level_idx, level_km in enumerate(levels_km):
            if dist_km <= level_km and level_idx not in entered_levels:
                entered_levels.add(level_idx)
                if not is_snoozed and not is_already_queued:
                    kind = 'enter_outer' if level_idx == 0 else f'enter_level_{level_idx}'
                    await send_airport_queue_push(user_id, icao, kind, dist_km, zone_label, zone_key)
        aq['entered_levels'] = sorted(entered_levels)
    else:
        # Вышел за пределы внешнего радиуса - сбрасываем: при возвращении
        # отсчёт (и пуши на вход/по времени) начнётся заново.
        if aq.get('entered_outer_at'):
            # ИЗМЕНЕНО 22.09.2026 (см. комментарий выше у "queue_log_id ещё
            # не установлен") - пуш "Ты выехал(а) из зоны" + "Я ПОКИНУЛ
            # ОЧЕРЕДЬ", а также запись left_at/wait_minutes в лог и учёт
            # времени простоя в финансах смены, теперь шлются/пишутся ТОЛЬКО
            # если у водителя за этот заход реально есть queue_log_id - то
            # есть он был в зоне аэропорта И успел отметиться в очереди.
            # Просто проезжавшего мимо/не вставшего в очередь водителя эти
            # пуш и сбор данных больше не касаются вообще.
            if aq.get('queue_log_id'):
                # zone_label не передаём - он вычислен для ТЕКУЩЕЙ (уже дальней)
                # точки и может не соответствовать зоне, в которой водитель
                # реально стоял (aq['zone_key']) - обходимся названием аэропорта
                # без уточнения терминала.
                await send_airport_queue_left_push(user_id, aq.get('icao') or icao)
                try:
                    entered_at = datetime.fromisoformat(aq['entered_outer_at'])
                    wait_minutes = max(0, round((now - entered_at).total_seconds() / 60))
                except Exception:
                    wait_minutes = 0
                # По просьбе пользователя (20.09.2026): если сейчас идёт смена -
                # копим суммарное время простоя в аэропорту за смену
                # (state['shift']['airport_wait_minutes']), чтобы учесть его в
                # итоговом расчёте финансов (см. send_courier_finance_result).
                shift = state.get('shift')
                if shift:
                    shift = dict(shift)
                    shift['airport_wait_minutes'] = shift.get('airport_wait_minutes', 0) + wait_minutes
                    state['shift'] = shift
                # Дозаполняем left_at/wait_minutes у строки лога, созданной
                # в момент реальной отметки в очереди (см. выше).
                log_airport_queue_left(aq.get('queue_log_id'), now, wait_minutes)
            aq = {'icao': icao, 'zone_key': zone_key, 'last_update_at': now.isoformat()}
            if live_period:
                aq['live_period'] = live_period

    state['airport_queue'] = aq

def _in_parking_zone(lat, lon, city):
    """True, если точка (lat, lon) в зоне действия фичи "Парковка" - либо в
    пределах PARKING_CITY_RADIUS_KM от центра города (RAIN_CITY_COORDS),
    либо в зоне аэропорта (nearest_airport_zone) - см. комментарий у
    PARKING_CITY_RADIUS_KM выше (аэропорт может быть за пределами города,
    например Внуково). Зоны ж/д вокзалов отдельно не проверяем - они и так
    покрыты городским радиусом.

    ВАЖНО (правка 21.09.2026): зона аэропорта для парковки НЕ включает
    радиус airport_queue_outer_radius_km(icao) - там уже работает свой пуш
    "Встать в очередь" (см. process_airport_queue_ping), и присылать вдобавок
    пуш про платную парковку в той же точке было бы дублированием/конфликтом
    (см. PARKING_AIRPORT_ZONE_RADIUS_KM). Зона парковки у аэропорта -
    "бублик" СНАРУЖИ радиуса очереди и ВНУТРИ PARKING_AIRPORT_ZONE_RADIUS_KM.
    Если аэропорт также попадает в городской радиус - городская проверка
    выше всё равно сработает как обычно, ограничение касается только самой
    зоны аэропорта."""
    city_coords = RAIN_CITY_COORDS.get(city) if city else None
    if city_coords:
        c_lat, c_lon = city_coords
        if haversine_km(lat, lon, c_lat, c_lon) <= PARKING_CITY_RADIUS_KM:
            return True
    icao, dist_km, zone_key, zone_label = nearest_airport_zone(lat, lon)
    if icao is not None and dist_km is not None:
        queue_radius_km = airport_queue_outer_radius_km(icao)
        if queue_radius_km < dist_km <= PARKING_AIRPORT_ZONE_RADIUS_KM:
            return True
    return False

async def process_parking_ping(user_id, lat, lon):
    """Обрабатывает один пинг живой геопозиции для фичи "Парковка" (см.
    блок ПАРКОВКА выше) - НЕЗАВИСИМО от process_airport_queue_ping (обе
    читают одну и ту же трансляцию, см. _location_tracking_active), только
    пока активна смена (is_shift_active). Хранит "якорную" точку
    (anchor_lat/anchor_lon/anchor_time) в user_state[uid]['parking'] - если
    новая точка ушла от якоря дальше PARKING_MOVEMENT_THRESHOLD_METERS,
    водитель едет - переставляем якорь и снимаем прежний пуш/глушение
    (новый заход стоянки). Если якорь "состарился" на PARKING_STATIONARY_
    MINUTES без движения, пуш для этого захода ещё не отправлялся и водитель
    не отметил "стою на бесплатной парковке" (free_ack) - шлём пуш."""
    state = user_state.get(user_id)
    if not state or not is_shift_active(state):
        return
    if not _in_parking_zone(lat, lon, state.get('city')):
        return
    now = datetime.now(ZoneInfo('UTC'))
    parking = dict(state.get('parking') or {})
    anchor_lat, anchor_lon = parking.get('anchor_lat'), parking.get('anchor_lon')
    moved = True
    if anchor_lat is not None and anchor_lon is not None:
        dist_m = haversine_km(lat, lon, anchor_lat, anchor_lon) * 1000
        moved = dist_m > PARKING_MOVEMENT_THRESHOLD_METERS
    if moved:
        # Новая якорная точка - новый заход "стоянки", сбрасываем пуш и
        # глушение по free_ack (снятое водителем "стою на бесплатной
        # парковке" относилось к ПРЕЖНЕМУ месту стоянки).
        parking = {
            'anchor_lat': lat, 'anchor_lon': lon,
            'anchor_time': now.isoformat(),
            'pushed': False, 'free_ack': False,
        }
        state['parking'] = parking
        return
    parking['anchor_lat'], parking['anchor_lon'] = anchor_lat, anchor_lon
    state['parking'] = parking
    if parking.get('free_ack'):
        # Отметил "стою на бесплатной" - не спрашиваем повторно, пока не
        # пройдёт PARKING_FREE_ACK_RECHECK_MINUTES с момента этой отметки
        # (см. handle_parking_free_ack, который пишет free_ack_time).
        try:
            free_ack_time = datetime.fromisoformat(parking['free_ack_time'])
        except Exception:
            return
        recheck_minutes = (now - free_ack_time).total_seconds() / 60
        if recheck_minutes < PARKING_FREE_ACK_RECHECK_MINUTES:
            return
        # Прошло 15 минут, а водитель всё ещё не поехал - снимаем
        # глушение и спрашиваем ещё раз, как будто новый заход стоянки.
        parking['free_ack'] = False
        parking.pop('free_ack_time', None)
        parking['pushed'] = False
        state['parking'] = parking
    if parking.get('pushed'):
        return
    try:
        anchor_time = datetime.fromisoformat(parking['anchor_time'])
    except Exception:
        return
    stationary_minutes = (now - anchor_time).total_seconds() / 60
    if stationary_minutes >= PARKING_STATIONARY_MINUTES:
        parking['pushed'] = True
        state['parking'] = parking
        await send_parking_push(user_id, state.get('city'))

async def send_parking_push(user_id, city):
    """Пуш "похоже, ты припарковался" - кнопки оплаты платной парковки
    (по городу/платформе, см. PARKING_APP_LINKS - пока пусто, ссылки
    добавит пользователь позже, до этого кнопок оплаты просто нет) и
    кнопка "🅿️ Стою на бесплатной парковке" (глушит пуш до следующей
    поездки, см. handle_parking_free_ack)."""
    if not bot:
        return
    text = (
        "🅿️ Похоже, ты припарковался и стоишь на месте уже несколько минут.\n\n"
        "Если парковка платная - не забудь оплатить, чтобы не словить штраф."
    )
    buttons = []
    # Сначала ссылка конкретно для города (если пользователь её пришлёт),
    # иначе - общий фолбэк PARKING_APP_LINK_FALLBACK ("Парковки России",
    # покрывает все города).
    city_links = PARKING_APP_LINKS.get(city) or {}
    links = {**PARKING_APP_LINK_FALLBACK, **city_links}
    # По прямой просьбе пользователя (22.09.2026) - если платформа водителя
    # известна (см. driver_platform_hint), показываем только его кнопку;
    # иначе (платформа неизвестна или desktop/web/macos) - обе, как раньше.
    platform_hint = driver_platform_hint(user_id)
    if links.get('ios') and platform_hint in (None, 'ios'):
        buttons.append([InlineKeyboardButton(text="💳 Оплатить парковку (iOS)", url=links['ios'])])
    if links.get('android') and platform_hint in (None, 'android'):
        buttons.append([InlineKeyboardButton(text="💳 Оплатить парковку (Android)", url=links['android'])])
    buttons.append([InlineKeyboardButton(text="🅿️ Стою на бесплатной парковке", callback_data="parking_free_ack")])
    reply_markup = InlineKeyboardMarkup(inline_keyboard=buttons)
    try:
        await bot.send_message(user_id, text, reply_markup=reply_markup)
    except Exception as e:
        logger.warning(f"⚠️ Не удалось отправить пуш о парковке пользователю {user_id}: {e}")

def _location_tracking_active(user_id):
    """True, если хоть одна из фич, использующих живую геопозицию (очередь у
    аэропорта, счётчик км текущей смены), сейчас активна у этого
    пользователя - обе читают ОДНУ и ту же трансляцию (Telegram позволяет
    транслировать только одну геопозицию за раз), см. комментарий у
    handle_airport_queue_location."""
    state = user_state.get(user_id, {})
    return bool(state.get('airport_queue_active') or is_shift_active(state))

# Сколько минут последняя точка живой трансляции считается ещё актуальной
# для разовых запросов (Мойки/Шиномонтаж/Туалеты/Парковка и т.п., см.
# show_nearby_prompt) и для подсказки "включить трансляцию" после выбора
# категории (см. select_category) - если водитель уже транслирует геопозицию
# (см. _location_tracking_active), не спрашиваем её заново, а берём
# последнюю известную точку (по жалобе пользователя, 20.09.2026: "локация
# горит уже а бот опять предлагает"). Если пинга давно не было (например,
# трансляция зависла) - точка считается устаревшей, и бот всё-таки спросит
# заново.
#
# БЫЛО 10 минут - недостаточно: Telegram не гарантирует частые edited_message
# с обновлением координат, если водитель физически стоит на месте (машина
# на стоянке, ждёт заказ и т.п.) - трансляция при этом продолжает идти, но
# новых пингов может не быть заметно дольше 10 минут, и бот снова "терял"
# то, что трансляция активна (повторная жалоба пользователя, 21.09.2026, со
# скриншотом: "сверху у нас включена трансляция локации а он опять это
# запрашивает"). Подняли до того же порога, что уже используется для
# определения "трансляция реально прервалась" у очереди аэропорта (см.
# AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES выше) - ниже этого порога транслицию
# нигде в файле не считаем остановившейся, так что логично не считать её
# остановившейся и здесь.
LIVE_LOCATION_FRESH_MINUTES = AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES

def driver_platform_hint(user_id):
    """Возвращает 'ios'/'android'/None - см. tg.platform, сохранённый в
    user_state[uid]['tg_platform'] при открытии любого WebApp этого бота
    (см. PLATFORM_REPORT_API_PATH). None - платформа ещё не известна (ни
    разу не открывал WebApp) ИЛИ это desktop/web/macos - в обоих случаях
    безопаснее предложить обе кнопки, чем угадать неверно (по прямой
    просьбе пользователя, 22.09.2026)."""
    state = user_state.get(user_id) or {}
    platform = (state.get('tg_platform') or '').lower()
    if 'ios' in platform:
        return 'ios'
    if 'android' in platform:
        return 'android'
    return None

def remember_live_location(user_id, lat, lon):
    state = user_state.get(user_id)
    if state is None:
        return
    state['last_live_location'] = {
        'lat': lat, 'lon': lon,
        'updated_at': datetime.now(timezone.utc).isoformat(),
    }

def get_fresh_live_location(user_id):
    """Возвращает (lat, lon) последней живой геопозиции, если она не старше
    LIVE_LOCATION_FRESH_MINUTES - иначе None (пусть бот спросит как обычно).
    Не требует, чтобы _location_tracking_active была True - трансляция могла
    быть включена водителем самостоятельно, без кнопок бота (см.
    handle_passive_live_location), и last_live_location всё равно свежая."""
    state = user_state.get(user_id) or {}
    loc = state.get('last_live_location')
    if not loc:
        return None
    try:
        updated_at = datetime.fromisoformat(loc['updated_at'])
    except Exception:
        return None
    age_minutes = (datetime.now(timezone.utc) - updated_at).total_seconds() / 60
    if age_minutes > LIVE_LOCATION_FRESH_MINUTES:
        return None
    return loc['lat'], loc['lon']

# ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "надо сделать так
# чтобы начать смену нельзя было без включённой геолокации чтобы трансляция
# была постоянной... это очень важно"): раньше "Начать смену" запускалась
# сразу, а напоминание про трансляцию геопозиции было просто строкой ПОСЛЕ
# старта ("Без трансляции секундомер идёт как обычно, но км и показ на карте
# не сработают") - водитель мог легко проигнорировать её и работать смену
# вообще без геопозиции. Теперь старт смены БЛОКИРУЕТСЯ, пока у бота нет
# свежей точки живой геопозиции (см. get_fresh_live_location/
# LIVE_LOCATION_FRESH_MINUTES) - технически бот не может ЗАСТАВИТЬ Telegram
# транслировать геопозицию постоянно (это решение самого пользователя в
# приложении), поэтому "постоянная трансляция" обеспечивается тем, что (1)
# смена не стартует без хотя бы одного свежего пинга геопозиции, и (2) все
# хендлеры геопозиции (см. maybe_start_pending_shift ниже) продолжают
# получать пинги, пока трансляция идёт - если она прервётся, это уже
# отдельно ловит check_airport_queue_timers/AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES
# для функций, которые от неё зависят.
def shift_geolocation_required_text():
    return (
        "📍 *Для старта смены нужна геопозиция.*\n\n"
        "Без неё бот не может считать километраж, показывать тебя на карте "
        "водителей и следить за очередью у аэропорта. Включи трансляцию: "
        "скрепка 📎 → Геопозиция → *«Транслировать геопозицию»* → "
        "*«Пока не отключу»*.\n\n"
        "Как только геопозиция придёт - смена стартует автоматически, "
        "повторно нажимать «Начать смену» не нужно."
    )

async def require_live_location_for_shift_start(message, user_id, state, tariffs):
    """Проверяет, есть ли свежая геопозиция (get_fresh_live_location) перед
    реальным стартом смены. Если её нет - откладывает старт в
    state['shift_start_pending'] (список тарифов, уже выбранных на
    предыдущем экране, если он был) и просит включить трансляцию; как
    только придёт первый пинг геопозиции - maybe_start_pending_shift ниже
    запускает смену автоматически с этими же тарифами. Возвращает True,
    если старт был заблокирован (вызывающий код должен остановиться и НЕ
    стартовать смену сейчас), False - если геопозиция уже есть и можно
    стартовать сразу."""
    if get_fresh_live_location(user_id):
        return False
    state['shift_start_pending'] = list(tariffs) if tariffs else []
    await message.answer(shift_geolocation_required_text(), parse_mode='Markdown')
    return True

async def maybe_start_pending_shift(message, user_id):
    """Вызывается из всех хендлеров геопозиции (живой и разовой) сразу после
    remember_live_location - если у пользователя есть отложенный старт смены
    (см. require_live_location_for_shift_start), запускает её теперь, с
    сохранёнными тарифами, без повторного нажатия "Начать смену"."""
    state = user_state.get(user_id)
    if not state or 'shift_start_pending' not in state:
        return
    tariffs = state.pop('shift_start_pending')
    if is_shift_active(state):
        return  # смена уже стартовала другим путём, отложенный старт больше не нужен
    category = state.get('category')
    city = state.get('city')
    if not city:
        return
    await start_shift_and_notify(message.answer, user_id, category, city, tariffs=tariffs)

