ROAD_EVENTS_CHANNEL_LINKS = {
    'moscow': ('https://t.me/dtp777', 'Москва'),
    'spb': ('https://t.me/dtp_spb78', 'Санкт-Петербург'),
}
ROAD_EVENTS_SHOW_COUNT = 5  # сколько последних сообщений пересылать в чат за раз
# ИЗМЕНЕНО 21.09.2026: сбор данных (LOOKBACK_HOURS в fetch_road_events.py)
# поднят с 6ч до 24ч, чтобы хватало данных для более долгого TTL перекрытий
# НА КАРТЕ (см. handle_map_road_events_api). Обычный список "⛔ Дорожные
# события" в чате пользователь попросил оставить как раньше - за последние
# 6 часов - поэтому здесь СВОЙ отдельный порог (ROAD_EVENTS_CHAT_LOOKBACK_HOURS),
# применяется в show_road_events поверх уже собранных (более широких) данных.
ROAD_EVENTS_CHAT_LOOKBACK_HOURS = 6
ROAD_EVENTS_LOOKBACK_HOURS_LABEL = "6 часов"  # для текста в чате - держать в синхроне с ROAD_EVENTS_CHAT_LOOKBACK_HOURS выше

_URL_RE = re.compile(r'(?:https?://|(?:www\.)?t\.me/|(?:www\.)?telegram\.me/)\S+', re.IGNORECASE)

def strip_urls_for_display(text):
    """Доп. страховка перед отправкой в чат: вырезает любую ссылку (в т.ч.
    голую t.me/... без протокола), которая могла проскочить очистку в
    fetch_road_events.py - иначе Telegram сам подставляет превью-карточку
    канала ("Проголосуйте за канал") поверх нашего сообщения."""
    if not text:
        return text
    return re.sub(r'\n{3,}', '\n\n', _URL_RE.sub('', text)).strip()

def format_road_event_time(iso_time, city):
    """Время сообщения в часовом поясе города (те же EVENT_CITY_TIMEZONE, что
    и у афиши города), в формате ЧЧ:ММ."""
    try:
        dt = datetime.fromisoformat(iso_time)
        tz_name = EVENT_CITY_TIMEZONE.get(city)
        if tz_name:
            dt = dt.astimezone(ZoneInfo(tz_name))
        return dt.strftime('%H:%M')
    except Exception:
        return ''

@router.message(lambda message: message.text == "👤 ЛИЧНЫЙ КАБИНЕТ")
async def open_cabinet_from_menu(message: types.Message):
    """Кнопка "👤 ЛИЧНЫЙ КАБИНЕТ" главного меню (см. services_keyboard) -
    сама кнопка в Reply-клавиатуре ОБЫЧНАЯ (без web_app=) - см. комментарий
    у cabinet_row в services_keyboard про то, почему: у кнопок с web_app=
    прямо в Reply-клавиатуре initData приходит пустым (проверено на
    реальном устройстве). Поэтому по нажатию просто присылаем отдельным
    сообщением инлайн-кнопку с web_app= (тот же рабочий паттерн, что и
    "👤 ЛИЧНЫЙ КАБИНЕТ"/"📈 СТАТИСТИКА СМЕН" внутри start_courier_finance) -
    у инлайн-кнопок initData передаётся нормально."""
    user_id = message.from_user.id
    state = user_state.get(user_id, {})
    category = state.get('category')
    city = state.get('city')
    if not (PUBLIC_URL and city):
        await message.answer("Личный кабинет пока недоступен - сначала выбери город 🙂")
        return
    tariff_options = CATEGORIES.get(category, {}).get('tariffs', [])
    cabinet_url = f"{PUBLIC_URL}{CABINET_WEBAPP_PATH}?tariffs={urllib.parse.quote(','.join(tariff_options))}"
    await message.answer(
        "👤 ЛИЧНЫЙ КАБИНЕТ",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="ОТКРЫТЬ", web_app=WebAppInfo(url=cabinet_url)),
        ]]),
    )

@router.message(lambda message: message.text == "⛔ ДОРОЖНЫЕ СОБЫТИЯ")
async def show_road_events(message: types.Message, user_id_override=None):
    """ДТП и дорожные происшествия по городам - пересылаем сами тексты
    последних сообщений из публичных Telegram-каналов (Москва -> @dtp777 +
    @DtOperativno слиты в одну ленту, СПб -> @dtp_spb78), а не просто даём
    ссылку на канал. Источник данных -
    road_events_data.json, который в фоне обновляет road_events_updater()
    (см. fetch_road_events.py - парсинг публичной веб-версии канала, тот же
    способ, что уже используется для уведомлений Росавиации @favt_info;
    там же фильтр "только про ДТП/перекрытия/аварии" и окно 6 часов).
    disable_web_page_preview=True на всех answer() ниже - без этого Telegram
    иногда сам подтягивал превью-карточку канала ("Проголосуйте за канал")
    по ссылке, которая могла всплыть в тексте поста. Кнопки/ссылки на сам
    канал нарочно НЕТ нигде в этом хендлере (было раньше - убрано по
    просьбе пользователя: не подсвечивать переход в канал вообще, только
    сами новости). Для городов без канала - текст-заглушка.

    user_id_override - по просьбе пользователя (объединение кнопок "События
    города"/"Дорожные события" в одну с инлайн-подменю): при вызове из
    callback_query.message.answer(...) сам message - это сообщение БОТА
    (message.from_user был бы ботом, не пользователем), поэтому вызывающий
    callback-хендлер передаёт настоящий user_id явно (см.
    open_road_events_from_menu ниже)."""
    user_id = user_id_override if user_id_override is not None else message.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    channel = ROAD_EVENTS_CHANNEL_LINKS.get(city)

    if not channel:
        await message.answer(
            "⛔ *Дорожные события*\n\nДля этого города канал с ДТП пока не подключен.",
            reply_markup=services_keyboard(state.get('category'), city, user_id),
            parse_mode='Markdown',
            disable_web_page_preview=True,
        )
        return

    _, city_name = channel
    events = get_road_events_for_city(city)
    # Список в чате - за последние ROAD_EVENTS_CHAT_LOOKBACK_HOURS (6ч), даже
    # если сами данные собраны за более широкое окно (24ч, см. комментарий у
    # ROAD_EVENTS_CHAT_LOOKBACK_HOURS выше - это окно нужно карте для
    # перекрытий с TTL 24ч, но список в чате пользователь просил не трогать).
    chat_cutoff = (datetime.now(ZoneInfo('UTC')) - timedelta(hours=ROAD_EVENTS_CHAT_LOOKBACK_HOURS)).isoformat()
    events = [e for e in events if e.get('time', '') >= chat_cutoff]

    if not events:
        await message.answer(
            f"⛔ *Дорожные события — {city_name}*\n\n"
            f"За последние {ROAD_EVENTS_LOOKBACK_HOURS_LABEL} новых ДТП/перекрытий не было, "
            "либо данные ещё не собраны.",
            parse_mode='Markdown',
            disable_web_page_preview=True,
        )
        return

    # По просьбе пользователя (19.09.2026): "оценка перекрытий города" -
    # посты с is_closure=True (перекрытие/ограничение проезда, см.
    # is_road_closure в fetch_road_events.py) выносятся отдельным блоком
    # НАВЕРХ сообщения - водителю важнее всего видеть в первую очередь то,
    # где вообще нельзя проехать, а не листать всю ленту ДТП. Остальные
    # события (обычные ДТП/аварии без явного перекрытия) идут дальше, как
    # раньше, единым списком.
    closures = [e for e in events[:ROAD_EVENTS_SHOW_COUNT] if e.get('is_closure')]
    others = [e for e in events[:ROAD_EVENTS_SHOW_COUNT] if not e.get('is_closure')]

    lines = [f"⛔ *Дорожные события — {city_name}* (за последние {ROAD_EVENTS_LOOKBACK_HOURS_LABEL})\n"]
    if closures:
        lines.append(f"🚧 *Активные перекрытия ({len(closures)})*")
        for event in closures:
            time_str = format_road_event_time(event.get('time', ''), city)
            text = escape_md(strip_urls_for_display(event.get('text', '').strip()))
            prefix = f"🕐 {time_str}\n" if time_str else ""
            lines.append(f"{prefix}{text}")
        if others:
            lines.append("— — —")
    for event in others:
        time_str = format_road_event_time(event.get('time', ''), city)
        text = escape_md(strip_urls_for_display(event.get('text', '').strip()))
        prefix = f"🕐 {time_str}\n" if time_str else ""
        lines.append(f"{prefix}{text}")
    message_text = '\n\n'.join(lines)

    # Telegram режет сообщение на 4096 символах - при большом количестве
    # длинных постов подряд подрезаем, чтобы не словить ошибку отправки.
    if len(message_text) > 4000:
        message_text = message_text[:4000] + "…"

    await message.answer(
        message_text,
        parse_mode='Markdown',
        disable_web_page_preview=True,
    )


def build_concert_event_message(post, city):
    """Текст + инлайн-кнопки для ОДНОГО структурированного концертного
    события (см. parse_event_fields в fetch_concert_events.py) - тот же стиль,
    что build_event_message у TimePad. "🚗 ПОЕХАЛИ" - поиск по названию места
    на Яндекс.Картах (как и у TimePad, координат у канала нет, только текстовое
    название площадки/адреса); показывается только если место распознано."""
    tz = ZoneInfo(EVENT_CITY_TIMEZONE.get(city, 'Europe/Moscow'))
    lines = [f"🎤 *{post.get('title') or 'Мероприятие'}*"]
    # По жалобе пользователя (20.09.2026, "события города опять пустые") -
    # если это запасной вариант (на сегодня/завтра в канале ничего не было,
    # см. get_upcoming_concert_events_for_category), помечаем явно, чтобы не
    # выглядело так, будто событие именно на сегодня/завтра.
    if post.get('is_fallback_later'):
        lines.append("_На ближайшие дни ничего не нашлось - вот что есть дальше:_")
    place = post.get('place')
    if place:
        lines.append(f"📍 {place.capitalize()}")
    try:
        start_dt = datetime.fromisoformat(post['start']).astimezone(tz)
        end_dt = datetime.fromisoformat(post['end']).astimezone(tz) if post.get('end') else None
        if start_dt.date() == (end_dt.date() if end_dt else start_dt.date()) and end_dt:
            date_str = f"{start_dt.strftime('%d.%m, %H:%M')}–{end_dt.strftime('%H:%M')} (окончание ориентировочно)"
        else:
            date_str = start_dt.strftime('%d.%m, %H:%M')
        if not post.get('start_has_explicit_time'):
            date_str += " (точное время не указано в афише)"
        lines.append(f"🗓 {date_str}")
    except Exception:
        pass
    price_rub = post.get('price_rub')
    if price_rub:
        lines.append(f"💵 {price_rub} ₽")
    elif post.get('is_free'):
        lines.append("💵 вход свободный")
    text = '\n'.join(lines)

    buttons = []
    if place:
        from urllib.parse import quote
        # По просьбе пользователя (19.09.2026) кнопка "Подробнее" убрана, а
        # "Поехали" пытались переключить на схему Яндекс.Навигатора
        # (yandexnavi://) - ИСПРАВЛЕНО (20.09.2026): Telegram Bot API
        # отклоняет инлайн-кнопки с нестандартной схемой в url как невалидные
        # (BUTTON_URL_INVALID) - это уже случалось раньше в этом же проекте с
        # той же самой схемой (см. комментарий у yandex_navi_url выше) и
        # ронялось ВСЁ сообщение целиком, включая текст карточки. Возвращено
        # на обычную https-ссылку на Яндекс.Карты (yandex_navi_url) - она
        # валидна для Telegram и открывается в приложении Навигатора/Карт,
        # если оно установлено, иначе в браузере.
        buttons.append(InlineKeyboardButton(text="🚗 ПОЕХАЛИ", url=f"https://yandex.ru/maps/?text={quote(place)}"))
    keyboard = InlineKeyboardMarkup(inline_keyboard=[buttons]) if buttons else None
    return text, keyboard

@router.message(lambda message: message.text == "🚨 СОБЫТИЯ ГОРОДА" and user_state.get(message.from_user.id, {}).get('category') not in CATEGORIES_WITHOUT_EVENTS)
async def show_events_and_roads_menu(message: types.Message):
    """"🚨 СОБЫТИЯ ГОРОДА" в главном меню теперь открывает инлайн-подменю из
    двух вариантов (объединение по просьбе пользователя, 20.09.2026; эмодзи
    кнопки в меню уточнялся дважды - финально "🚨 СОБЫТИЯ ГОРОДА") - сама
    афиша (show_city_events) и дорожные события (show_road_events) вызываются
    из callback-хендлеров ниже (open_city_events_from_menu/
    open_road_events_from_menu), передавая user_id_override, т.к.
    callback_query.message - это сообщение бота, не пользователя.
    CATEGORIES_WITHOUT_EVENTS (courier/cargo) сюда не попадают - у них
    кнопка называется "⛔ ДОРОЖНЫЕ СОБЫТИЯ" и ведёт прямо на show_road_events
    (см. services_keyboard)."""
    buttons = [
        [InlineKeyboardButton(text="🎭 СОБЫТИЯ ГОРОДА", callback_data="events_menu_city")],
        [InlineKeyboardButton(text="⛔ ДОРОЖНЫЕ СОБЫТИЯ", callback_data="events_menu_roads")],
    ]
    await message.answer("Выбери 👇", reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))

