# Сериализует доступ к общему счётчику квоты (api_usage_log.json, один ключ
# на аэропорты и поезда) между двумя НЕЗАВИСИМЫМИ фоновыми циклами ниже. Без
# этого, если графики случайно совпадут по времени, оба могут одновременно
# прочитать один и тот же "остаток на сегодня" и вместе превысить квоту -
# именно так уже один раз заблокировали ключ.
_yandex_api_lock = asyncio.Lock()


def seconds_until_hour(target_hour, tz='Europe/Moscow'):
    """Сколько секунд осталось до ближайшего наступления target_hour:00 по
    заданной таймзоне (сегодня, если ещё не наступил, иначе завтра)."""
    now = datetime.now(ZoneInfo(tz))
    target = now.replace(hour=target_hour, minute=0, second=0, microsecond=0)
    if target <= now:
        target += timedelta(days=1)
    return (target - now).total_seconds()


def _data_file_age_minutes(path):
    """Возраст ДАННЫХ в минутах по полю 'generated_at' ВНУТРИ файла (не по
    mtime на диске!) - или None если файла нет/не читается/нет поля.

    ИСПРАВЛЕНО 19.09.2026 в ночь: изначально использовался os.path.getmtime()
    (время последнего изменения файла на диске). На Railway это оказалось
    БЕССМЫСЛЕННЫМ - при каждом деплое контейнер собирается заново из git
    checkout, и mtime файла становится временем СБОРКИ образа, а не временем
    реального сбора данных. В логах это выглядело как "flights_data.json
    свежий (5мин < 25мин)" сразу после рестарта, хотя данные внутри были
    54.9 ЧАСА устаревшими (см. поле generated_at) - защита от лишних
    прогонов при рестарте из-за этого сама блокировала получение свежих
    данных после разблокировки ключа. Теперь читаем реальную дату сбора из
    содержимого файла."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        generated_at = data.get('generated_at')
        if not generated_at:
            return None
        generated_dt = datetime.fromisoformat(generated_at)
        return (datetime.now() - generated_dt).total_seconds() / 60
    except Exception:
        return None


async def airports_data_updater():
    """Фоновая задача для flights_data.json. Днём (06:00-24:00 МСК) - каждые
    FLIGHTS_DAY_INTERVAL_HOURS часов, ночью (00:00-06:00,
    FLIGHTS_NIGHT_START_HOUR-FLIGHTS_NIGHT_END_HOUR) - реже, каждые
    FLIGHTS_NIGHT_INTERVAL_HOURS часов (рейсов мало, но не ноль - по просьбе
    пользователя ночью тоже собираем, просто пореже). Запускается сразу при
    старте бота, чтобы данные были свежими с первого деплоя - НО ТОЛЬКО если
    данные реально устарели (см. MIN_FRESH_AGE_MINUTES ниже).

    ИСПРАВЛЕНО 19.09.2026: раньше запускался БЕЗУСЛОВНО при каждом старте
    бота, даже если данные были только что обновлены - на Railway это
    означало, что каждый редеплой (а их за день бывает несколько подряд при
    активной разработке) добавлял ЕЩЁ ОДИН внеплановый цикл запросов к
    Yandex Rasp сверх обычного расписания. Именно череда редеплоев в течение
    одного дня внесла свой вклад в блокировку ключа 19.09.2026 (см. письмо
    Яндекса о превышении лимита).

    ИСПРАВЛЕНО 20.09.2026 (пользователь подтвердил по консоли Яндекса - "ключ
    обновляется всегда в 00:00", то есть суточная БЛОКИРОВКА ключа (если она
    случилась) снимается именно в полночь по Москве; пользователь также явно
    задал желаемое расписание - "00:05, потом ночью каждые 2 часа до 6 утра,
    далее каждый час"): раньше следующий запуск планировался просто как
    "текущее время + interval_hours" от момента ПОСЛЕДНЕГО запуска - момент
    полуночи мог уехать на произвольное время (до целого интервала) в
    зависимости от того, когда бот стартовал, вместо того чтобы всегда
    попадать в одни и те же часы суток. Теперь расписание - это
    ФИКСИРОВАННЫЙ список конкретных часов МСК (FLIGHTS_UPDATE_HOURS_MSK:
    00:05, 02:00, 04:00, затем 06,07,...,23 - итого 21 запуск/сутки), и цикл
    каждый раз досыпает ровно до ближайшей следующей точки из этого списка,
    а не считает интервал от текущего момента - поэтому 00:05 (сразу после
    снятия суточной блокировки ключа) наступит гарантированно, независимо от
    рестартов и редеплоев в течение дня."""
    MIN_FRESH_AGE_MINUTES = 25  # не обновляем повторно, если данные моложе этого - защита от лишних запросов при частых рестартах
    # (час, минута) каждой плановой точки обновления за сутки, по возрастанию.
    FLIGHTS_UPDATE_HOURS_MSK = [
        (0, 5),  # сразу после снятия суточной блокировки ключа Яндексом
        (2, 0), (4, 0),  # ночь - реже, рейсов мало
    ] + [(h, 0) for h in range(6, 24)]  # день - каждый час, 06:00-23:00

    def _minutes_until_next_target(now_dt):
        """Сколько минут осталось до ближайшей точки из FLIGHTS_UPDATE_HOURS_MSK
        (может быть точка сегодня позже текущего времени, либо первая точка
        завтра, если все сегодняшние уже прошли)."""
        now_total = now_dt.hour * 60 + now_dt.minute
        today_targets = [h * 60 + m for h, m in FLIGHTS_UPDATE_HOURS_MSK]
        upcoming = [t for t in today_targets if t > now_total]
        if upcoming:
            return min(upcoming) - now_total
        # все точки на сегодня прошли - берём первую точку завтрашнего дня
        return (24 * 60 - now_total) + today_targets[0]

    def _is_at_or_past_a_target(now_dt, window_min=5):
        """True, если текущее время попадает в первые window_min минут
        после одной из точек расписания (т.е. пора выполнять обновление)."""
        now_total = now_dt.hour * 60 + now_dt.minute
        for h, m in FLIGHTS_UPDATE_HOURS_MSK:
            target = h * 60 + m
            if target <= now_total < target + window_min:
                return True
        return False

    # ИСПРАВЛЕНО 20.09.2026 (пользователь - "а если падает?" -> "повторять
    # через 5-10 мин"): если попытка обновления В ПЛАНОВОЙ ТОЧКЕ провалилась
    # (ключ ещё заблокирован, сетевая ошибка и т.п. - fetch_yandex_data.main()
    # кинул исключение ИЛИ тихо не обновил данные), не ждём молча до
    # следующей плановой точки расписания (это может быть до 2 часов) - вместо
    # этого делаем короткие повторные попытки каждые RETRY_INTERVAL_MINUTES,
    # пока не получится или не исчерпаем RETRY_MAX_ATTEMPTS попыток (дальше
    # уже ждём обычную плановую точку - если ключ настолько сломан, что не
    # ожил за час коротких попыток, продолжать долбить API нет смысла). Пока
    # идут повторные попытки, бот всё равно продолжает показывать
    # водителям последний ХОРОШИЙ сохранённый снепшот (last_good_flights.json,
    # см. _apply_last_good_flights_fallback) - НЕ нули.
    RETRY_INTERVAL_MINUTES = 7
    RETRY_MAX_ATTEMPTS = 8  # ~56 минут коротких попыток, потом ждём обычную плановую точку

    # ИСПРАВЛЕНО 21.09.2026 (пользователь - "давай чтобы такого больше не
    # было" после жалобы на 0% сразу после рестарта): раньше обновление
    # запускалось ТОЛЬКО в плановую точку расписания - если бот
    # перезапускался/редеплоился МЕЖДУ точками (ночью разрыв может быть до
    # 2 часов), водители всё это время видели устаревший или вообще пустой
    # flights_data.json, а last_good_flights.json на свежем Volume ещё мог
    # быть пуст, так что даже fallback подставить было нечего. Докстринг
    # функции ОБЕЩАЛ обновление сразу при старте, если данные устарели, но
    # в самом коде этой проверки не было - вот и чинили. Теперь на ПЕРВОЙ
    # итерации цикла (сразу после старта бота) дополнительно проверяем
    # возраст файла и обновляем внепланово, если он старше MIN_FRESH_AGE_MINUTES
    # или отсутствует - дальше, на всех следующих итерациях, снова работает
    # только расписание (чтобы серия редеплоев подряд не жгла лишние запросы).
    is_first_iteration = True

    while True:
        now_msk = datetime.now(ZoneInfo('Europe/Moscow'))
        hour = now_msk.hour
        is_night = FLIGHTS_NIGHT_START_HOUR <= hour < FLIGHTS_NIGHT_END_HOUR

        age_min = _data_file_age_minutes(FLIGHTS_DATA_FILE)
        at_scheduled_point = _is_at_or_past_a_target(now_msk)
        is_stale_on_startup = is_first_iteration and (age_min is None or age_min > MIN_FRESH_AGE_MINUTES)
        # На плановой точке обновляем, даже если формально "свежо" (< MIN_FRESH_AGE_MINUTES) -
        # но НЕ повторяем, если уже обновлялись совсем недавно (< 2 мин) внутри этого же окна.
        # На старте бота ДОПОЛНИТЕЛЬНО обновляем внепланово, если данные устарели -
        # не ждём следующую плановую точку (см. комментарий выше).
        should_update = (at_scheduled_point or is_stale_on_startup) and (age_min is None or age_min > 2)
        is_first_iteration = False

        if not should_update:
            sleep_min = _minutes_until_next_target(now_msk)
            logger.info(
                f"⏭️  flights_data.json - следующее плановое обновление через {sleep_min}мин "
                f"({'свежее' if (age_min is not None and age_min < MIN_FRESH_AGE_MINUTES) else 'жду плановую точку расписания'})"
            )
            await asyncio.sleep(sleep_min * 60 + 30)
            continue

        reason = "рестарт бота - данные устарели" if is_stale_on_startup and not at_scheduled_point else ("полуночное окно снятия блокировки ключа" if (hour == 0) else ('ночь' if is_night else 'день'))
        for attempt in range(1, RETRY_MAX_ATTEMPTS + 1):
            success = False
            status = None
            try:
                logger.info(f"🔄 Обновляю flights_data.json из Yandex Rasp API... ({reason}, попытка {attempt}/{RETRY_MAX_ATTEMPTS})")
                async with _yandex_api_lock:
                    status = await asyncio.to_thread(fetch_yandex_data.main)
                # fetch_yandex_data.main() сам решает, удалось ли получить хоть
                # что-то реальное (свежий mtime файла - признак успешного прогона,
                # даже если для отдельных аэропортов сработал внутренний fallback
                # на старые данные - это не считается провалом всего цикла).
                fresh_age = _data_file_age_minutes(FLIGHTS_DATA_FILE)
                success = fresh_age is not None and fresh_age < 2
            except Exception as e:
                logger.error(f"❌ Ошибка фонового обновления flights_data.json (попытка {attempt}/{RETRY_MAX_ATTEMPTS}): {e}")

            if success:
                logger.info("✅ flights_data.json обновлён")
                break

            # ИСПРАВЛЕНО 20.09.2026 (пользователь - "а если лимиты падают?"):
            # исчерпание ДНЕВНОГО лимита запросов - это не временный сбой,
            # который может пройти через 5-10 минут, а состояние, которое
            # снимется только на следующие сутки. Ретраить его каждые
            # RETRY_INTERVAL_MINUTES бессмысленно (fetch_yandex_data.main()
            # откажется от работы точно так же на 2-й, 3-й и 8-й попытке) -
            # прекращаем попытки сразу и ждём обычную плановую точку.
            # Пока ждём (в обоих случаях - и коротких ретраев, и этого) -
            # водителям всё равно показывается последний сохранённый снепшот
            # (last_good_flights.json), а не нули - бот не остаётся пустым.
            if status == 'daily_limit_reached':
                logger.error(
                    "🚫 Дневной лимит запросов к Yandex Rasp API исчерпан - повторные попытки "
                    "сегодня бессмысленны, жду следующую плановую точку расписания (или новые сутки). "
                    "Водителям по-прежнему показываем последний сохранённый снепшот."
                )
                break

            if attempt < RETRY_MAX_ATTEMPTS:
                logger.warning(
                    f"⚠️ Обновление не удалось - повторю через {RETRY_INTERVAL_MINUTES}мин "
                    f"(попытка {attempt}/{RETRY_MAX_ATTEMPTS}). Пока показываем водителям последний "
                    f"сохранённый снепшот (last_good_flights.json), не нули."
                )
                await asyncio.sleep(RETRY_INTERVAL_MINUTES * 60)
            else:
                logger.error(
                    f"🚫 Не удалось обновить flights_data.json за {RETRY_MAX_ATTEMPTS} попыток - "
                    f"похоже, ключ всё ещё заблокирован или недоступен API. Жду следующую плановую "
                    f"точку расписания. Водителям по-прежнему показываем последний сохранённый снепшот."
                )

        # После выполнения (успешного или исчерпавшего попытки) - досыпаем до
        # следующей точки расписания (не interval_hours!)
        await asyncio.sleep(_minutes_until_next_target(datetime.now(ZoneInfo('Europe/Moscow'))) * 60 + 30)


async def trains_data_updater():
    """Фоновая задача для trains_data.json (по вокзалу на каждый город бота,
    включая Сапсан - см. STATION_CITY и fetch_trains_data.py). Независимый от
    аэропортов график - раз в TRAINS_UPDATE_INTERVAL_HOURS часов,
    круглосуточно, без привязки к дню/ночи. Запускается сразу при старте
    бота - НО ТОЛЬКО если данные реально устарели (см. комментарий в
    airports_data_updater про редеплои 19.09.2026 - та же защита тут)."""
    MIN_FRESH_AGE_MINUTES = 180  # меньше половины TRAINS_UPDATE_INTERVAL_HOURS (6ч=360мин)
    while True:
        age_min = _data_file_age_minutes(TRAINS_DATA_FILE)
        if age_min is not None and age_min < MIN_FRESH_AGE_MINUTES:
            # ИСПРАВЛЕНО 20.09.2026 - та же ошибка, что была в
            # airports_data_updater (см. комментарий там): раньше после
            # пропуска на старте бот всё равно засыпал на ПОЛНЫЙ
            # TRAINS_UPDATE_INTERVAL_HOURS (6ч), а не на оставшееся время до
            # истечения MIN_FRESH_AGE_MINUTES - реальное обновление могло
            # откладываться на часы вместо нескольких минут. Теперь досыпаем
            # именно недостающее время (+30с запас).
            remaining_min = MIN_FRESH_AGE_MINUTES - age_min
            logger.info(
                f"⏭️  trains_data.json свежий ({age_min:.0f}мин < {MIN_FRESH_AGE_MINUTES}мин) - "
                f"пропускаю внеплановое обновление (вероятно, бот только что перезапустился), "
                f"следующая проверка через {remaining_min:.0f}мин"
            )
            await asyncio.sleep(remaining_min * 60 + 30)
            continue
        try:
            logger.info("🔄 Обновляю trains_data.json (Казанский/Ленинградский) из Yandex Rasp API...")
            async with _yandex_api_lock:
                await asyncio.to_thread(fetch_trains_data.main)
            logger.info("✅ trains_data.json обновлён")
        except Exception as e:
            logger.error(f"❌ Ошибка фонового обновления trains_data.json: {e}")
        await asyncio.sleep(TRAINS_UPDATE_INTERVAL_HOURS * 3600)

def format_queue_breakdown(city, icao, category, zone_key=None):
    """Блок с текущей очередью ДЛЯ КОНКРЕТНОЙ категории водителя - только его
    собственные тарифы: Такси видит Эконом/Комфорт/Комфорт+/Минивэн, Ultima -
    свои Business/Premier/Elite/Cruise. Категории без тарифов (Курьер/Грузовое
    такси) сюда вообще не попадают - у них нет доступа к аэропортам.

    zone_key=None у аэропорта БЕЗ терминальных зон - обычная сводка по всему
    аэропорту, как раньше. zone_key=None у аэропорта С зонами (сейчас только
    Шереметьево/UUEE, см. AIRPORT_TERMINAL_ZONES) - ИСПРАВЛЕНО 20.09.2026
    (вслед за разведением очереди по терминалам, см. _queue_airport_key):
    раньше в этом случае queue_latest_report искал отметку под "голым" icao,
    который с этого дня уже ничего не находит (отметки пишутся с суффиксом
    терминала) - сводка молча показывала бы "нет свежих отметок" даже при
    реальной очереди. Теперь вместо этого показываем очередь ПО КАЖДОЙ зоне
    отдельно, с подписью терминала - для мест, где неизвестен конкретный
    терминал водителя (например, общий пуш о смене статуса всего аэропорта)."""
    tariffs = CATEGORIES.get(category, {}).get('tariffs', [])
    if not tariffs:
        return ''
    zones = AIRPORT_TERMINAL_ZONES.get(icao)
    if zones and not zone_key:
        lines = [f"\n\n📋 *Очередь ({CATEGORIES[category]['name']}):*"]
        for zk, zdata in zones.items():
            lines.append(f"  *{zdata['label']}:*")
            for tariff in tariffs:
                range_str, ts = queue_latest_report(city, icao, f"{category}:{tariff}", zone_key=zk)
                if range_str:
                    local_time = format_airport_local_time(ts, icao)
                    lines.append(f"   • {tariff}: *{range_str}* машин _(отметка {local_time})_")
                else:
                    lines.append(f"   • {tariff}: нет свежих отметок")
        return '\n'.join(lines)
    lines = [f"\n\n📋 *Очередь ({CATEGORIES[category]['name']}):*"]
    for tariff in tariffs:
        range_str, ts = queue_latest_report(city, icao, f"{category}:{tariff}", zone_key=zone_key)
        if range_str:
            local_time = format_airport_local_time(ts, icao)
            lines.append(f"   • {tariff}: *{range_str}* машин _(отметка {local_time})_")
        else:
            lines.append(f"   • {tariff}: нет свежих отметок")
    return '\n'.join(lines)

# ==================== ПОГОДА / ОСАДКИ ====================
# Идея пользователя: осадки (дождь/снег/ливень и т.д.) ощутимо увеличивают
# спрос на такси и курьеров - люди уходят с улицы под крышу и заказывают
# вместо того чтобы идти пешком. Два режима:
# (1) упреждающий пуш водителям выбранного города за RAIN_LEAD_MINUTES минут
#     ДО начала (или заметного усиления) осадков - не "уже идёт", а "скоро
#     начнётся" (см. check_rain_transitions/push_rain_alert ниже);
# (2) кнопка "🌤 ПОГОДА" на верхнем уровне меню (рядом с "🔄 ОТДАТЬ ЗАКАЗ") -
#     ручной просмотр почасовой разбивки на RAIN_FORECAST_HOURS часов вперёд:
#     вид осадков + температура на каждый час (см. show_weather_forecast).

async def fetch_rain_forecast(city):
    """Почасовой прогноз (weathercode, температура) на RAIN_FORECAST_HOURS
    часов вперёд по городу через Open-Meteo - СЫРОЙ live-запрос к API.

    ИЗМЕНЕНО 21.09.2026 (пользователь - "раз в час собирал инфу... чтобы не
    нагружать лимиты", после инцидента с "Open-Meteo вернул 429"): раньше эта
    функция вызывалась НАПРЯМУЮ из каждого места, которому нужна погода
    (кнопка "🌤 ПОГОДА", "Куда ехать", утреннее приветствие, проверка на
    дождь) - то есть живой запрос к API на каждое действие пользователя.
    Теперь единственный вызывающий - weather_data_updater() (фоновая задача
    ниже), раз в WEATHER_UPDATE_INTERVAL_MINUTES по всем городам разом.
    Всё остальное читает уже готовый снепшот через get_cached_weather_forecast()
    ниже, не дёргая API вообще. Retry на 429 оставлен - полезен, даже когда
    вызовов раз в час, а не при каждом клике."""
    coords = RAIN_CITY_COORDS.get(city)
    if not coords:
        return None
    lat, lon = coords
    params = {
        'latitude': lat,
        'longitude': lon,
        'current': 'weathercode,temperature_2m',
        'hourly': 'weathercode,temperature_2m',
        'forecast_hours': RAIN_FORECAST_HOURS,
        'timezone': 'auto',
    }
    RETRY_ATTEMPTS = 3
    for attempt in range(1, RETRY_ATTEMPTS + 1):
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(OPEN_METEO_URL, params=params, timeout=aiohttp.ClientTimeout(total=15)) as resp:
                    if resp.status == 429:
                        if attempt < RETRY_ATTEMPTS:
                            wait_s = 2.0 * attempt
                            logger.warning(f"⏳ Open-Meteo 429 для {city}, попытка {attempt}/{RETRY_ATTEMPTS} - жду {wait_s}с...")
                            await asyncio.sleep(wait_s)
                            continue
                        logger.warning(f"⚠️ Open-Meteo вернул 429 для города {city} - исчерпаны все {RETRY_ATTEMPTS} попыток")
                        return None
                    if resp.status != 200:
                        logger.warning(f"⚠️ Open-Meteo вернул {resp.status} для города {city}")
                        return None
                    return await resp.json()
        except Exception as e:
            logger.warning(f"⚠️ Не удалось получить прогноз Open-Meteo для {city}: {e}")
            return None
    return None

_weather_data_cache = None
_weather_data_mtime = None

def load_weather_data():
    """Загружает weather_data.json (пишет weather_data_updater ниже, раз в
    WEATHER_UPDATE_INTERVAL_MINUTES). Кэширует в памяти, перечитывает только
    если файл изменился на диске - тот же паттерн, что load_flights_data."""
    global _weather_data_cache, _weather_data_mtime
    try:
        mtime = os.path.getmtime(WEATHER_DATA_FILE)
        if _weather_data_cache is not None and mtime == _weather_data_mtime:
            return _weather_data_cache
        with open(WEATHER_DATA_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
        _weather_data_cache = data
        _weather_data_mtime = mtime
        return data
    except FileNotFoundError:
        return None
    except Exception as e:
        logger.warning(f"⚠️ Не удалось прочитать {WEATHER_DATA_FILE}: {e}")
        return None

def get_cached_weather_forecast(city):
    """Прогноз ОДНОГО города из готового снепшота weather_data.json - без
    единого live-запроса к Open-Meteo. Возвращает тот же формат, что раньше
    отдавал fetch_rain_forecast(city) напрямую (сырой ответ Open-Meteo:
    'current'/'hourly' с weathercode+temperature_2m), поэтому весь код,
    который уже умеет читать этот формат (find_upcoming_precip_event,
    describe_weathercode и т.п.), продолжает работать без изменений - просто
    источник данных теперь кэш, а не сеть. Возвращает None, если снепшота
    ещё нет (первый запуск бота, до первого прогона weather_data_updater)
    или в нём нет записи для этого города."""
    data = load_weather_data()
    if not data:
        return None
    return (data.get('cities') or {}).get(city)

async def update_weather_data():
    """Один прогон по всем RAIN_CITY_COORDS - как и у аэропортов/вокзалов,
    пауза между городами (WEATHER_REQUEST_DELAY_SECONDS), чтобы не залпом
    бить по Open-Meteo. Город, для которого запрос не удался, просто не
    попадает в новый снепшот - ЕСЛИ в файле уже была запись для него с
    прошлого прогона, оставляем ЕЁ вместо того чтобы стереть (тот же принцип
    "лучше старые данные, чем ничего", что для рейсов/поездов, см.
    fetch_yandex_data.py 21.09.2026)."""
    WEATHER_REQUEST_DELAY_SECONDS = 1.0
    previous = load_weather_data() or {}
    previous_cities = previous.get('cities') or {}
    cities = {}
    for city in RAIN_CITY_COORDS:
        forecast = await fetch_rain_forecast(city)
        if forecast:
            cities[city] = forecast
        elif city in previous_cities:
            cities[city] = previous_cities[city]
            logger.warning(f"⚠️ {city}: свежий прогноз погоды не получен - оставляю прошлый снепшот")
        await asyncio.sleep(WEATHER_REQUEST_DELAY_SECONDS)
    result = {
        'generated_at': datetime.now().isoformat(),
        'cities': cities,
    }
    with open(WEATHER_DATA_FILE, 'w', encoding='utf-8') as f:
        json.dump(result, f, ensure_ascii=False)
    logger.info(f"💾 weather_data.json обновлён ({len(cities)}/{len(RAIN_CITY_COORDS)} городов)")

async def weather_data_updater():
    """Фоновая задача - собирает погоду по всем городам раз в
    WEATHER_UPDATE_INTERVAL_MINUTES (по прямой просьбе пользователя,
    21.09.2026, после инцидента с 429 от Open-Meteo). Запускается сразу при
    старте бота, НО ТОЛЬКО если снепшот реально устарел - тот же принцип
    защиты от лишних запросов при частых редеплоях, что у airports_data_updater/
    trains_data_updater (см. их комментарии, инцидент 19.09.2026)."""
    MIN_FRESH_AGE_MINUTES = 30  # меньше половины WEATHER_UPDATE_INTERVAL_HOURS (60мин)
    while True:
        age_min = _data_file_age_minutes(WEATHER_DATA_FILE)
        if age_min is not None and age_min < MIN_FRESH_AGE_MINUTES:
            remaining_min = MIN_FRESH_AGE_MINUTES - age_min
            logger.info(
                f"⏭️  weather_data.json свежий ({age_min:.0f}мин < {MIN_FRESH_AGE_MINUTES}мин) - "
                f"пропускаю внеплановое обновление, следующая проверка через {remaining_min:.0f}мин"
            )
            await asyncio.sleep(remaining_min * 60 + 30)
            continue
        try:
            logger.info("🔄 Обновляю weather_data.json из Open-Meteo (все города)...")
            await update_weather_data()
        except Exception as e:
            logger.error(f"❌ Ошибка фонового обновления weather_data.json: {e}")
        await asyncio.sleep(WEATHER_UPDATE_INTERVAL_MINUTES * 60)

def _current_hour_index(forecast, city):
    """ИСПРАВЛЕНО 23.09.2026 (жалоба пользователя - "идёт дождь, а бот
    показывает что будет дождь через 3 часа, может неправильно время
    показывает"): find_upcoming_precip_event раньше слепо считал, что
    hourly.time[0] - это ТЕКУЩИЙ час (hour_offset=0). Но Open-Meteo с
    параметрами forecast_hours+timezone=auto без явного start_hour вовсе не
    гарантированно начинает массив С ТЕКУЩЕГО часа - как минимум сразу после
    полуночи по местному времени города массив уже мог "сместиться"
    относительно предположения кода на несколько часов. Из-за этого
    смещения индекс, который код считал "сейчас", на самом деле был уже
    прошедшим часом, а реальный текущий (с уже идущим дождём) код видел как
    "через несколько часов". Теперь ищем нужный индекс ЯВНО - по совпадению
    с текущим часом местного времени города, вместо того чтобы полагаться
    на позицию 0 массива."""
    hourly = forecast.get('hourly', {})
    times = hourly.get('time', [])
    if not times:
        return 0
    now_hour_str = get_city_now(city).strftime('%Y-%m-%dT%H:00')
    for i, t in enumerate(times):
        if t >= now_hour_str:
            return i
    return max(0, len(times) - 1)  # весь массив в прошлом (снепшот совсем устарел) - берём последний час как least-bad вариант

def find_upcoming_precip_event(forecast, city):
    """Ищет ближайшее почасовое окно с осадками в пределах RAIN_LEAD_MINUTES
    от текущего момента - то есть "начнётся достаточно скоро, чтобы имело
    смысл предупредить водителя сейчас". Возвращает None, если в этом окне
    осадков нет, иначе dict {hour_offset, time, code, weight, name, emoji}.
    hour_offset и time.index() всегда отсчитываются от РЕАЛЬНОГО текущего
    часа (см. _current_hour_index), а не от начала массива hourly."""
    if not forecast:
        return None
    hourly = forecast.get('hourly', {})
    times = hourly.get('time', [])
    codes = hourly.get('weathercode', [])
    base = _current_hour_index(forecast, city)
    lead_hours_window = max(1, -(-RAIN_LEAD_MINUTES // 60))  # округление вверх - для 30 мин достаточно проверить час[0..1]
    for offset in range(min(lead_hours_window + 1, len(times) - base, len(codes) - base)):
        i = base + offset
        code = codes[i]
        if code in PRECIP_WEATHERCODES:
            name, weight, emoji = describe_weathercode(code)
            return {'hour_offset': offset, 'time': times[i], 'code': code, 'weight': weight, 'name': name, 'emoji': emoji, '_array_index': i}
    return None

def find_precip_event_end(forecast, start_offset):
    """От часа start_offset ищет первый ЧАС ПОСЛЕ него без осадков - до него
    считаем, что событие продолжается. Возвращает длительность в часах
    (минимум 1) или None, если по прогнозу не прекратится в пределах
    RAIN_FORECAST_HOURS."""
    hourly = forecast.get('hourly', {})
    codes = hourly.get('weathercode', [])
    for i in range(start_offset + 1, len(codes)):
        if codes[i] not in PRECIP_WEATHERCODES:
            return i - start_offset
    return None

# ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "с 23.30 до 6.30 утра
# не присылать пуш о дожде и спросе в дождь"): ночная тишина для пуша о
# дожде/усилении спроса из-за дождя (push_rain_alert) - по МЕСТНОМУ времени
# КАЖДОГО города (тот же принцип, что у утреннего приветствия 9:00 -
# см. get_city_now), а не единому московскому. Другие типы пушей (очередь
# у аэропорта, статус аэропортов и т.п.) не затрагиваются - только этот.
RAIN_PUSH_QUIET_START_HOUR, RAIN_PUSH_QUIET_START_MINUTE = 23, 30
RAIN_PUSH_QUIET_END_HOUR, RAIN_PUSH_QUIET_END_MINUTE = 6, 30

def is_rain_push_quiet_hours(city):
    """True, если сейчас в промежутке [23:30, 6:30) по местному времени
    города - окно переходит через полночь, поэтому сравниваем через минуты
    от начала суток, а не напрямую time()."""
    now = get_city_now(city)
    minutes_now = now.hour * 60 + now.minute
    start = RAIN_PUSH_QUIET_START_HOUR * 60 + RAIN_PUSH_QUIET_START_MINUTE
    end = RAIN_PUSH_QUIET_END_HOUR * 60 + RAIN_PUSH_QUIET_END_MINUTE
    if start > end:
        # Окно через полночь (23:30..23:59 ИЛИ 00:00..6:29).
        return minutes_now >= start or minutes_now < end
    return start <= minutes_now < end

async def push_rain_alert(city, event):
    """Рассылает упреждающий пуш водителям и курьерам выбранного города о
    скором начале (или усилении) осадков - в отличие от
    push_airport_status_change это касается ВСЕХ категорий (Такси/Ultima/
    Курьер/Грузовое такси - у всех может вырасти спрос), без фильтра по
    CATEGORIES_WITHOUT_AIRPORTS."""
    if not bot:
        return
    city_name = CITY_DISPLAY_NAMES.get(city, city)
    # Open-Meteo отдаёт почасовую гранулярность - hour_offset=0 это текущий
    # час (событие уже идёт), hour_offset=1 - следующий час (начнётся в
    # пределах ближайших ~60 минут, не обязательно ровно через
    # RAIN_LEAD_MINUTES - формулировка ниже намеренно не даёт точность до
    # минуты, которой у источника данных просто нет).
    if event['hour_offset'] == 0:
        when_text = "начался"
    else:
        when_text = f"ожидается в ближайшие {RAIN_LEAD_MINUTES} минут"
    duration_hours = find_precip_event_end(event['_forecast'], event['_array_index'])
    if duration_hours:
        duration_text = f"продлится примерно {duration_hours} ч"
    else:
        duration_text = f"по прогнозу не прекратится в ближайшие {RAIN_FORECAST_HOURS} ч"
    text = (
        f"{event['emoji']} *{city_name}*\n\n"
        f"{event['name'].capitalize()} {when_text}, {duration_text}.\n\n"
        f"Через {RAIN_LEAD_MINUTES} минут в городе ожидается больше заказов - "
        f"хорошее время быть на линии."
    )
    recipients = [
        uid for uid, state in list(user_state.items())
        if isinstance(state, dict) and state.get('city') == city and notifications_enabled(state, 'weather')
    ]
    if not recipients:
        logger.info(f"{event['emoji']} В городе {city} ожидаются осадки ({event['name']}), но известных пользователей нет (либо все отключили эти пуши)")
        return
    logger.info(f"{event['emoji']} В городе {city} ожидаются осадки ({event['name']}) - рассылаю {len(recipients)} пользователям")
    sent, failed = 0, 0
    for user_id in recipients:
        try:
            await bot.send_message(user_id, text, parse_mode='Markdown')
            sent += 1
        except Exception as e:
            failed += 1
            logger.warning(f"⚠️ Не удалось отправить пуш о погоде пользователю {user_id}: {e}")
        await asyncio.sleep(0.05)
    logger.info(f"{event['emoji']} Пуш о погоде в {city} разослан: {sent} успешно, {failed} ошибок")

async def check_rain_transitions():
    """Раз в прогон смотрит ближайшее окно осадков (в пределах
    RAIN_LEAD_MINUTES) по каждому городу и решает, нужен ли пуш:
    - НЕТ сохранённого события для этого времени начала -> новое событие,
      пушим (это и есть переход "нет предупреждения -> есть");
    - ЕСТЬ сохранённое, но с тем же временем начала и той же/меньшей силой ->
      это тот же прогноз, уже предупредили, повторно не пушим;
    - ЕСТЬ сохранённое с тем же временем начала, но сила ВЫРОСЛА (дождь ->
      ливень) -> по просьбе пользователя это отдельный повод для пуша
      (усиление), пушим ещё раз с обновлённым описанием;
    - окно осадков закончилось (find_upcoming_precip_event вернул None) ->
      сбрасываем сохранённое состояние, чтобы следующее событие снова
      считалось новым.
    Не пушит вообще на первом прогоне после деплоя эффективно так же, как и
    остальные проверки - т.к. на первом прогоне previous просто пуст, а
    записанное состояние появляется до первого возможного пуша (сохраняем
    ДО отправки), поэтому реальный риск дублей и не имеет значения, что БД
    "холодная" - худший случай - один лишний пуш сразу после деплоя, если
    событие уже активно, что не является спамом, а вполне уместным пушом."""
    # ИЗМЕНЕНО 21.09.2026 (пользователь - "раз в час собирал инфу... чтобы не
    # нагружать лимиты", после инцидента "Open-Meteo вернул 429"): раньше
    # этот цикл сам дёргал Open-Meteo по всем 12 городам живьём при каждом
    # прогоне (каждые RAIN_CHECK_INTERVAL_MINUTES=20 минут, плюс сразу при
    # каждом рестарте бота) - именно это и было основным источником залпов
    # запросов. Теперь читаем уже готовый снепшот weather_data.json (его
    # раз в час обновляет weather_data_updater) - НИ ОДНОГО живого запроса к
    # API из этого цикла больше нет. Снепшот почасовой (RAIN_FORECAST_HOURS
    # часов вперёд) - его достаточно, чтобы посчитать "начнётся ли дождь в
    # ближайшие RAIN_LEAD_MINUTES", не обновляя сам прогноз каждые 20 минут.
    previous = load_all_rain_states()
    for city in RAIN_CITY_COORDS:
        forecast = get_cached_weather_forecast(city)
        if not forecast:
            continue  # снепшота для этого города ещё нет - не трогаем сохранённое состояние
        event = find_upcoming_precip_event(forecast, city)
        prev_start, prev_weight = previous.get(city, (None, None))

        if event is None:
            if prev_start is not None:
                save_rain_state(city, None, None)  # осадки закончились - сбрасываем, следующее событие снова "новое"
            continue

        event['_forecast'] = forecast
        # Абсолютное время начала (а не просто offset) - чтобы отличать
        # "то же самое ещё не наступившее событие" от "новое, отдельное окно
        # осадков позже" даже если оба сейчас попадают в lead-окно.
        event_start = event['time']
        is_new_event = (prev_start != event_start)
        is_stronger = (prev_weight is not None and event['weight'] > prev_weight)

        if is_new_event or is_stronger:
            if is_rain_push_quiet_hours(city):
                # Ночная тишина (23:30-6:30 по местному времени города) -
                # НЕ сохраняем состояние (специально), чтобы то же событие
                # снова посчиталось "новым" на первом прогоне после 6:30 и
                # пуш всё-таки ушёл, просто позже, а не потерялся молча.
                logger.info(f"{event['emoji']} В городе {city} ожидаются осадки ({event['name']}), но сейчас ночная тишина (23:30-6:30) - пуш отложен")
                continue
            save_rain_state(city, event_start, event['weight'])
            await push_rain_alert(city, event)

def format_weather_forecast_text(city_name, forecast):
    """Почасовая разбивка для ручного режима (кнопка "🌤 ПОГОДА") -
    вид осадков (или "ясно"/"облачно" и т.д. по weathercode) + температура на
    каждый из RAIN_FORECAST_HOURS часов вперёд, не только ближайшее окно
    (в отличие от find_upcoming_precip_event, который смотрит только на
    RAIN_LEAD_MINUTES вперёд для целей автопуша)."""
    if not forecast:
        # ИЗМЕНЕНО 21.09.2026 - теперь это не live-запрос, а чтение снепшота
        # (см. get_cached_weather_forecast), поэтому "попробуй через минуту"
        # больше не подходит - снепшот обновляется раз в час, а не по клику.
        return f"🌤 *{city_name}*\n\nДанные о погоде пока не собраны (бот недавно перезапустился) - загляни через несколько минут."

    current = forecast.get('current', {})
    cur_code = current.get('weathercode')
    cur_temp = current.get('temperature_2m')
    cur_name, _, cur_emoji = describe_weathercode(cur_code) if cur_code is not None else ('нет данных', 0, '🌤')
    temp_str = f"{round(cur_temp)}°C" if cur_temp is not None else "н/д"
    # Разделитель WHERE_TO_GO_DIVIDER - тот же общий стиль, что и в остальных
    # карточках бота (по просьбе пользователя, 22.09.2026 - визуальный
    # проход по не-миниапп экранам), раньше здесь просто пустая строка.
    lines = [
        f"🌤 *{city_name}*", f"_Сейчас: {cur_emoji} {cur_name}, {temp_str}_",
        WHERE_TO_GO_DIVIDER, "*Прогноз на 12 часов:*",
    ]

    hourly = forecast.get('hourly', {})
    times = hourly.get('time', [])
    codes = hourly.get('weathercode', [])
    temps = hourly.get('temperature_2m', [])
    for t, code, temp in zip(times, codes, temps):
        try:
            hour_label = datetime.fromisoformat(t).strftime('%H:%M')
        except ValueError:
            hour_label = t
        name, weight, emoji = describe_weathercode(code)
        temp_label = f"{round(temp)}°C" if temp is not None else "н/д"
        if weight > 0:
            lines.append(f"{hour_label} — {emoji} {name}, {temp_label}")
        else:
            lines.append(f"{hour_label} — {emoji} {temp_label}")
    return '\n'.join(lines)

# ==================== УТРЕННЕЕ ПРИВЕТСТВИЕ (9:00) ====================
# По просьбе пользователя (20.09.2026): "сделай приветственное сообщение
# утром каждый день в 9.00 доброе утро сегодня такое-то число день такой-то
# погода такая-то хорошего дня и побольше хороших клиентов. Предлагаю
# ознакомиться с вкладкой куда поехать" - шлётся 9:00 ПО МЕСТНОМУ ВРЕМЕНИ
# КАЖДОГО ГОРОДА (город уже определяет часовой пояс через get_city_now, как
# и остальные почасовые фичи бота), с кнопкой "Да" -> сразу показывает
# сводку "Куда ехать" (тот же расчёт, что и по кнопке "💰 КУДА ЕХАТЬ",
# работает и для courier/cargo - у них своя версия, см. compute_where_to_go).
MORNING_GREETING_HOUR = 9
MORNING_GREETING_CHECK_MINUTES = 5  # как часто проверяем "наступило ли 9:00 в каком-то городе" - с запасом относительно часа

RU_MONTHS_GENITIVE = (
    'января', 'февраля', 'марта', 'апреля', 'мая', 'июня',
    'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря',
)

# По просьбе пользователя (20.09.2026): "пропиши чтобы одевались по погоде и
# напомни водителям ультима в тарифах что премьер и элит что если +25 то
# верхняя одежда не требуется" - общая фраза "одевайся по погоде" идёт всем
# категориям, а конкретное напоминание про дресс-код Премьер/Элит (верхняя
# одежда не обязательна при +25 и выше) - ТОЛЬКО категории Ultima (у
# Такси/Курьера/Грузового такси нет тарифов Премьер/Элит с таким дресс-кодом).
ULTIMA_NO_OUTERWEAR_TEMP_C = 25

async def build_morning_greeting_text(city, category=None):
    """Текст "Доброе утро" - число/день недели по местному времени города,
    текущая погода (тот же источник Open-Meteo, что и у "🌤 ПОГОДА"/пушей о
    дожде), пожелание хорошего дня и побольше клиентов - по формулировке
    пользователя. Погода - best-effort: если Open-Meteo недоступен,
    сообщение всё равно уходит, просто без строки о погоде (лучше приветствие
    без погоды, чем не прийти вообще). category='ultima' - добавляет
    напоминание про дресс-код Премьер/Элит при +25° и выше (см.
    ULTIMA_NO_OUTERWEAR_TEMP_C)."""
    now = get_city_now(city)
    date_label = f"{now.day} {RU_MONTHS_GENITIVE[now.month - 1]}, {WEEKDAY_NAMES[now.weekday()].lower()}"
    lines = [
        "☀️ *Доброе утро!*",
        f"📅 Сегодня {date_label}",
    ]
    cur_temp = None
    forecast = get_cached_weather_forecast(city)  # берём из часового кэша, не бьём Open-Meteo на каждое приветствие
    if forecast:
        current = forecast.get('current', {})
        cur_code = current.get('weathercode')
        cur_temp = current.get('temperature_2m')
        if cur_code is not None:
            cur_name, _, cur_emoji = describe_weathercode(cur_code)
            temp_str = f", {round(cur_temp)}°C" if cur_temp is not None else ""
            lines.append(f"{cur_emoji} Погода: {cur_name}{temp_str}")
    lines.append("👕 Одевайся по погоде.")
    if category == 'ultima' and cur_temp is not None and cur_temp >= ULTIMA_NO_OUTERWEAR_TEMP_C:
        lines.append(
            f"ℹ️ Напоминание по дресс-коду: при +{ULTIMA_NO_OUTERWEAR_TEMP_C}° и выше "
            "верхняя одежда для тарифов *Премьер* и *Элит* не обязательна."
        )
    # Разделитель WHERE_TO_GO_DIVIDER перед пожеланием/призывом к действию -
    # тот же общий стиль по боту (визуальный проход, 22.09.2026, прямая
    # просьба пользователя), раньше это была просто ещё одна строка подряд.
    lines.append(f"\n{WHERE_TO_GO_DIVIDER}\n")
    lines.append("Хорошего дня и побольше хороших клиентов! 🚕")
    lines.append("\nПредлагаю ознакомиться с вкладкой «Куда ехать» - подскажет, где сейчас выгоднее всего работать.")
    return '\n'.join(lines)

def morning_greeting_keyboard():
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="✅ ДА, ПОКАЗАТЬ", callback_data="morning_greeting_show_where_to_go"),
    ]])

async def push_morning_greeting(user_id, city, category=None):
    if not bot:
        return
    try:
        text = await build_morning_greeting_text(city, category=category)
        await bot.send_message(user_id, text, reply_markup=morning_greeting_keyboard(), parse_mode='Markdown')
    except Exception as e:
        logger.error(f"❌ Не удалось отправить утреннее приветствие пользователю {user_id}: {e}")

@router.callback_query(lambda c: c.data == "morning_greeting_show_where_to_go")
async def morning_greeting_show_where_to_go(callback_query: types.CallbackQuery):
    """Кнопка "✅ ДА, ПОКАЗАТЬ" на утреннем приветствии - сразу показывает
    сводку "Куда ехать" в ответ (по прямому уточнению пользователя), тем же
    вызовом, что и кнопка "💰 КУДА ЕХАТЬ" в главном меню (см. send_where_to_go)."""
    await callback_query.answer()
    user_id = callback_query.from_user.id
    state = user_state.get(user_id, {})
    city = state.get('city')
    category = state.get('category')
    if not city:
        await callback_query.message.answer("Сначала выбери город 🏙")
        return
    await send_where_to_go(callback_query.message, user_id, city, category)

async def check_morning_greetings():
    """Проверяет каждого известного пользователя: наступило ли у него в
    городе MORNING_GREETING_HOUR:00 сегодня, и не отправляли ли мы уже
    приветствие сегодня (state['last_morning_greeting_date'], сравнение по
    ЛОКАЛЬНОЙ дате города - дедуп на пользователя, не на город, т.к. у
    каждого пользователя своё поле в state). Проверяем каждые
    MORNING_GREETING_CHECK_MINUTES минут окно [9:00, 9:00+CHECK_MINUTES) -
    один пользователь получит пуш один раз за прогон, в котором окно
    сработало."""
    for user_id, state in list(user_state.items()):
        if not isinstance(state, dict):
            continue
        city = state.get('city')
        if not city:
            continue
        if not notifications_enabled(state, 'morning_greeting'):
            continue
        now = get_city_now(city)
        today_str = now.strftime('%Y-%m-%d')
        if state.get('last_morning_greeting_date') == today_str:
            continue
        if now.hour != MORNING_GREETING_HOUR:
            continue
        await push_morning_greeting(user_id, city, category=state.get('category'))
        state['last_morning_greeting_date'] = today_str

async def morning_greeting_checker():
    """Фоновая задача: раз в MORNING_GREETING_CHECK_MINUTES минут проверяет,
    не наступило ли 9:00 по местному времени у кого-то из известных
    пользователей (см. check_morning_greetings)."""
    while True:
        try:
            await check_morning_greetings()
        except Exception as e:
            logger.error(f"❌ Ошибка в morning_greeting_checker: {e}")
        await asyncio.sleep(MORNING_GREETING_CHECK_MINUTES * 60)

async def rain_checker():
    """Фоновая задача: раз в RAIN_CHECK_INTERVAL_MINUTES минут опрашивает
    Open-Meteo по каждому из 12 городов и шлёт упреждающий пуш, если в
    ближайшие RAIN_LEAD_MINUTES минут ожидаются осадки (или существующие
    осадки усиливаются) - см. check_rain_transitions."""
    while True:
        try:
            await check_rain_transitions()
        except Exception as e:
            logger.error(f"❌ Ошибка фоновой проверки погоды: {e}")
        await asyncio.sleep(RAIN_CHECK_INTERVAL_MINUTES * 60)

# ==================== ПРАЗДНИКИ (пуши) ====================

def holiday_key(holiday):
    """Уникальный идентификатор конкретной записи HOLIDAYS - дата+название+
    город - используется для дедупа в holiday_pushes_sent (нельзя просто
    использовать дату, т.к. в один день теоретически может быть больше
    одного праздника)."""
    y, m, d = holiday['date']
    return f"{y:04d}-{m:02d}-{d:02d}:{holiday['name']}:{holiday.get('city', 'ALL')}"

async def push_holiday_alert(holiday, kind):
    """Рассылает пуш о празднике - 'lead' (за HOLIDAY_LEAD_DAYS до) или 'day'
    (в сам день праздника). Национальный праздник (is_national=True) - всем
    известным пользователям во всех городах; городской (День города) -
    только пользователям этого конкретного города."""
    if not bot:
        return
    if holiday.get('is_national'):
        recipients = [
            uid for uid, state in list(user_state.items())
            if isinstance(state, dict) and notifications_enabled(state, 'holidays')
        ]
        where = "по всем городам"
    else:
        city = holiday.get('city')
        city_name = CITY_DISPLAY_NAMES.get(city, city)
        recipients = [
            uid for uid, state in list(user_state.items())
            if isinstance(state, dict) and state.get('city') == city and notifications_enabled(state, 'holidays')
        ]
        where = f"в городе {city_name}"

    if kind == 'lead':
        when_text = f"Завтра, {holiday['date'][2]:02d}.{holiday['date'][1]:02d} - {holiday['name']}"
    else:
        when_text = f"Сегодня {holiday['name']}"
    text = (
        f"{holiday['emoji']} *{when_text}*\n\n"
        f"В праздники обычно растёт спрос на такси и доставку - люди едут в гости, "
        f"на мероприятия, заказывают подарки. Хорошее время быть на линии."
    )

    if not recipients:
        logger.info(f"{holiday['emoji']} {holiday['name']} ({kind}), но известных пользователей {where} нет (либо все отключили эти пуши)")
        return
    logger.info(f"{holiday['emoji']} {holiday['name']} ({kind}) - рассылаю {len(recipients)} пользователям {where}")
    sent, failed = 0, 0
    for user_id in recipients:
        try:
            await bot.send_message(user_id, text, parse_mode='Markdown')
            sent += 1
        except Exception as e:
            failed += 1
            logger.warning(f"⚠️ Не удалось отправить пуш о празднике пользователю {user_id}: {e}")
        await asyncio.sleep(0.05)
    logger.info(f"{holiday['emoji']} Пуш о празднике «{holiday['name']}» ({kind}) разослан: {sent} успешно, {failed} ошибок")

async def check_holidays():
    """Раз в прогон смотрит календарь HOLIDAYS: для каждого праздника,
    который наступает РОВНО через HOLIDAY_LEAD_DAYS дней - шлёт разовое
    напоминание (kind='lead', дедуп через holiday_pushes_sent - лишний прогон
    в пределах того же дня не дублирует); для каждого праздника, который
    идёт СЕГОДНЯ - шлёт пуш (kind='day'), и т.к. пользователь просил "каждые
    12 часов" в сам день, day-пуш дедупится не на весь день, а на
    12-часовой слот (00:00-11:59 / 12:00-23:59 по UTC), поэтому один и тот
    же holiday_key+kind='day' может уйти дважды за день (утром и вечером),
    но не чаще."""
    today = datetime.now(ZoneInfo('UTC')).date()
    lead_target = today + timedelta(days=HOLIDAY_LEAD_DAYS)
    half_day_slot = 0 if datetime.now(ZoneInfo('UTC')).hour < 12 else 1

    for holiday in HOLIDAYS:
        y, m, d = holiday['date']
        h_date = datetime(y, m, d).date()
        key = holiday_key(holiday)
        city_key = 'ALL' if holiday.get('is_national') else holiday.get('city', 'ALL')

        if h_date == lead_target:
            if not was_holiday_push_sent(key, city_key, 'lead'):
                mark_holiday_push_sent(key, city_key, 'lead')
                await push_holiday_alert(holiday, 'lead')

        if h_date == today:
            slot_kind = f'day_{half_day_slot}'
            if not was_holiday_push_sent(key, city_key, slot_kind):
                mark_holiday_push_sent(key, city_key, slot_kind)
                await push_holiday_alert(holiday, 'day')

async def holiday_checker():
    """Фоновая задача: раз в HOLIDAY_CHECK_INTERVAL_MINUTES минут проверяет
    календарь праздников (см. check_holidays) - разовый пуш за
    HOLIDAY_LEAD_DAYS день(-я) до и до двух пушей (утро/вечер) в сам день
    праздника."""
    while True:
        try:
            await check_holidays()
        except Exception as e:
            logger.error(f"❌ Ошибка фоновой проверки праздников: {e}")
        await asyncio.sleep(HOLIDAY_CHECK_INTERVAL_MINUTES * 60)

async def check_airport_queue_timers():
    """Раз в AIRPORT_QUEUE_CHECK_INTERVAL_MINUTES проходит по всем активным
    отслеживаниям (user_state[...]['airport_queue_active']) и досылает пуши
    "уже 30 минут/1 час рядом" по прошедшему времени - независимо от того,
    приходят ли новые пинги геопозиции прямо сейчас (см. docstring у
    AIRPORT_QUEUE_CHECK_INTERVAL_MINUTES). Если новых пингов геопозиции нет
    дольше AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES (инструкция рекомендует делиться
    "Пока не отключу", так что ориентироваться на live_period самого сообщения
    больше нельзя - см. комментарий у константы) - трансляция, судя по всему,
    прервалась: гасит отслеживание и присылает напоминание включить её заново
    (по просьбе пользователя, чтобы водитель не забывал) вместо того, чтобы
    молча пушить бесконечно того, кто уже уехал, ИЛИ молча остановиться без
    единого слова тому, кто забыл, что нужно включить трансляцию заново."""
    now = datetime.now(ZoneInfo('UTC'))
    for user_id, state in list(user_state.items()):
        if not isinstance(state, dict) or not state.get('airport_queue_active'):
            continue
        aq = state.get('airport_queue') or {}

        last_update_str = aq.get('last_update_at')
        if last_update_str:
            try:
                last_update = datetime.fromisoformat(last_update_str)
            except ValueError:
                last_update = now
            if (now - last_update).total_seconds() > AIRPORT_QUEUE_STALE_TIMEOUT_MINUTES * 60:
                state['airport_queue_active'] = False
                state['airport_queue'] = {}
                await send_airport_queue_expired_push(user_id, aq.get('icao'))
                continue

        icao = aq.get('icao')
        entered_at_str = aq.get('entered_outer_at')
        if not icao or not entered_at_str:
            continue

        try:
            entered_at = datetime.fromisoformat(entered_at_str)
        except ValueError:
            continue
        elapsed_minutes = (now - entered_at).total_seconds() / 60

        # zone_label для 30/60-минутных пушей восстанавливаем из сохранённого
        # zone_key (см. process_airport_queue_ping) - у аэропортов без зон
        # (AIRPORT_TERMINAL_ZONES) zone_key всегда None, .get(None) тоже даст
        # None, текст пуша не меняется.
        zone_label = None
        zone_key = aq.get('zone_key')
        if zone_key:
            zone_data = AIRPORT_TERMINAL_ZONES.get(icao, {}).get(zone_key)
            if zone_data:
                zone_label = zone_data['label']

        # ДОБАВЛЕНО 21.09.2026: если водитель нажал "не буду вставать в
        # очередь" для этого аэропорта и snooze ещё не истёк - не шлём и
        # таймерный пуш 30 минут тоже (см. process_airport_queue_ping, тот
        # же принцип; snooze - per-аэропорт с 22.09.2026, см. комментарий у
        # AIRPORT_QUEUE_SNOOZE_MINUTES). aq.get('pushed_30') при этом НЕ
        # проставляем - чтобы пуш 30 минут всё-таки пришёл ПОСЛЕ истечения
        # snooze, если 30 минут к тому моменту уже прошли.
        snoozed_until = get_airport_queue_snoozed_until(state, icao)
        is_snoozed = bool(snoozed_until and now < snoozed_until)
        # ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "и пропадает
        # если человек уже встал в очередь") - тот же принцип, что в
        # process_airport_queue_ping: если у водителя уже есть своя свежая
        # отметка по этому аэропорту/зоне, таймерный пуш "уже 30 минут рядом"
        # тоже не нужен - он уже отметился.
        city_for_marks = ICAO_TO_CITY.get(icao)
        is_already_queued = bool(city_for_marks and user_recent_queue_marks(user_id, city_for_marks, icao, zone_key))

        aq_updated = dict(aq)
        changed = False
        # ИЗМЕНЕНО 21.09.2026 (прямая просьба пользователя): убран пуш "уже 1
        # час рядом" - AIRPORT_QUEUE_TIME_PUSHES_MIN теперь содержит только
        # 30 минут (см. константу выше), пуш 60 больше не шлётся.
        (pushed_30,) = AIRPORT_QUEUE_TIME_PUSHES_MIN
        if elapsed_minutes >= pushed_30 and not aq.get('pushed_30') and not is_snoozed and not is_already_queued:
            await send_airport_queue_push(user_id, icao, 30, zone_label=zone_label, zone_key=zone_key)
            aq_updated['pushed_30'] = True
            changed = True
        if changed:
            state['airport_queue'] = aq_updated

async def airport_queue_checker():
    """Фоновая задача: раз в AIRPORT_QUEUE_CHECK_INTERVAL_MINUTES минут
    проверяет таймеры "давно рядом с аэропортом" (см. check_airport_queue_timers)
    - пуши на вход в очередной уровень расстояния (см. AIRPORT_QUEUE_RADIUS_LEVELS_KM)
    шлются сразу по факту пинга геопозиции (см. process_airport_queue_ping),
    эта задача только за пуши по времени."""
    while True:
        try:
            await check_airport_queue_timers()
        except Exception as e:
            logger.error(f"❌ Ошибка фоновой проверки очереди у аэропорта: {e}")
        await asyncio.sleep(AIRPORT_QUEUE_CHECK_INTERVAL_MINUTES * 60)

async def push_airport_status_change(icao, airport, old_status, new_status, notice):
    """Рассылает пуш всем водителям, у кого выбран город этого аэропорта, о
    смене статуса (например ОТКРЫТ -> ЗАКРЫТ). Бот может писать первым только
    тем, кто хотя бы раз ему написал - это все, кто есть в user_state. Курьер
    и Грузовое такси этот пуш не получают - у них нет доступа к аэропортам
    вообще. Каждому водителю ДОБАВЛЯЕТСЯ персональный блок очереди - только по
    тарифам его собственной категории (Такси не видит очередь Ultima и наоборот)."""
    city = ICAO_TO_CITY.get(icao)
    if not city or not bot:
        return
    status_icon, status_text = AIRPORT_STATUS_DISPLAY[new_status]
    base_text = f"{status_icon} *{airport['emoji']} {airport['name']}*\n\nСтатус изменился: *{status_text}*"
    if notice and notice.get('text'):
        snippet = notice['text']
        if len(snippet) > 300:
            snippet = snippet[:300] + '…'
        base_text += f"\n\n_По данным Росавиации:_\n{escape_md(snippet)}"

    # Копия списка - рассылка идёт не одну секунду, а user_state тем временем
    # может меняться (кто-то жмёт кнопки), нельзя итерировать "живой" словарь
    recipients = [
        (uid, state) for uid, state in list(user_state.items())
        if isinstance(state, dict) and state.get('city') == city and state.get('category') not in CATEGORIES_WITHOUT_AIRPORTS
        and notifications_enabled(state, 'airport_status')
    ]
    if not recipients:
        logger.info(f"📢 Статус {icao} изменился ({old_status} -> {new_status}), но в городе {city} сейчас нет известных водителей с доступом к аэропортам (либо все отключили эти пуши)")
        return

    logger.info(f"📢 Статус {icao} изменился ({old_status} -> {new_status}) - рассылаю {len(recipients)} водителям города {city}")
    sent, failed = 0, 0
    for user_id, state in recipients:
        category = state.get('category')
        text = base_text + format_queue_breakdown(city, icao, category)
        text += "\n\n_Подробности во вкладке «Доступность»._"
        try:
            await bot.send_message(user_id, text, parse_mode='Markdown')
            sent += 1
        except Exception as e:
            failed += 1
            logger.warning(f"⚠️ Не удалось отправить пуш пользователю {user_id}: {e}")
        # Telegram допускает ~30 сообщений/сек в разные чаты - берём с запасом
        await asyncio.sleep(0.05)
    logger.info(f"📢 Пуш по {icao} разослан: {sent} успешно, {failed} ошибок")

# ==================== ПУШ "БОТ ОБНОВИЛСЯ" ПРИ РЕДЕПЛОЕ ====================
# По просьбе пользователя (20.09.2026): "сделай так чтобы в боте приходило
# сообщение что бот обновился до новой версии" - шлём всем известным
# пользователям короткий пуш при каждом РЕАЛЬНОМ редеплое (новый код), но не
# на каждый обычный рестарт процесса (Railway может перезапускать контейнер
# без изменений в коде - сон/краш/масштабирование). Отличаем "это новый
# деплой" от "просто рестарт" по RAILWAY_GIT_COMMIT_SHA - Railway сама
# прокидывает эту переменную окружения с SHA закоммиченного изменения,
# который сейчас развёрнут; сравниваем с последним сохранённым в bot_meta
# (см. init_db) и шлём пуш, только если он изменился. Локально/вне Railway
# переменной нет - тогда пуш не шлём вообще (иначе слали бы на каждый
# локальный запуск), см. проверку ниже.
BOT_UPDATED_MESSAGE = (
    "🔄 *Вышло обновление бота.*\n\n"
    "Если что-то в меню ниже выглядит по-старому или работает не так, как "
    "должно - нажми кнопку «Обновить бота» ниже. Это важно для более "
    "стабильной работы бота (перерисовывает меню под последнюю версию) и "
    "НЕ сбрасывает смену, город и остальные данные."
)
# ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "нужно написать не
# обновление меню, обновления бота... что если что требуется обновить бота
# нажав вот эту кнопку это важно для более стабильной версии бота"): и текст
# пуша, и кнопка переформулированы с "обновить МЕНЮ" на "обновить БОТА" -
# пользователю это понятнее и подчёркивает, что нажатие важно для
# стабильности, а не просто косметика клавиатуры. Механика кнопки НЕ
# изменилась (см. handle_refresh_menu_button ниже) - Telegram Reply-
# клавиатура на телефоне кэшируется и не перерисовывается сама по себе, пока
# бот не пришлёт НОВОЕ сообщение с новым reply_markup; раньше единственным
# способом обновить её было написать боту что-то самому. Кнопка просто
# заново шлёт ТЕКУЩИЙ services_keyboard по уже сохранённым category/city из
# user_state - НИЧЕГО в самом state не трогает (смена/черновик заказа/что
# угодно ещё остаются как были).
BOT_UPDATED_REFRESH_KEYBOARD = InlineKeyboardMarkup(inline_keyboard=[[
    InlineKeyboardButton(text="🔄 ОБНОВИТЬ БОТА", callback_data="refresh_menu"),
]])

# ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "чтобы в чате было
# только два последних сообщения [об обновлении]"): и пуш "Вышло обновление
# бота", и ответ "✅ Бот обновлён" на кнопку шлются при КАЖДОМ деплое/каждом
# нажатии - при частых редеплоях (как в этой сессии) чат быстро забивается
# одинаковыми сообщениями. Храним id последних отправленных сообщений этого
# типа на пользователя (user_state[uid]['bot_update_msg_ids'], в памяти -
# переживать рестарт бота им не нужно, максимум одно старое сообщение не
# удалится) и после каждого нового сообщения удаляем все, кроме
# BOT_UPDATE_MESSAGES_TO_KEEP последних. Best-effort - Telegram не даёт
# удалять сообщения старше 48 часов и/или уже удалённые пользователем,
# такие ошибки просто игнорируем.
BOT_UPDATE_MESSAGES_TO_KEEP = 2

async def track_bot_update_message(user_id, message_id):
    """Запоминает id только что отправленного сообщения "об обновлении бота"
    (пуш или ответ на кнопку) и удаляет более старые из чата, оставляя не
    больше BOT_UPDATE_MESSAGES_TO_KEEP последних - см. комментарий выше."""
    state = user_state.setdefault(user_id, {})
    ids = list(state.get('bot_update_msg_ids') or [])
    ids.append(message_id)
    to_delete = ids[:-BOT_UPDATE_MESSAGES_TO_KEEP] if len(ids) > BOT_UPDATE_MESSAGES_TO_KEEP else []
    state['bot_update_msg_ids'] = ids[-BOT_UPDATE_MESSAGES_TO_KEEP:]
    if not bot:
        return
    for old_id in to_delete:
        _schedule_delete_message(user_id, old_id)

def get_bot_meta(key):
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT value FROM bot_meta WHERE key=?', (key,))
    row = cursor.fetchone()
    conn.close()
    return row[0] if row else None

def _self_file_hash():
    """Хэш содержимого текущего файла (main.py) - крайний фолбэк для
    определения "версии" бота (см. notify_users_about_new_deploy), если ни
    RAILWAY_GIT_COMMIT_SHA, ни RAILWAY_DEPLOYMENT_ID недоступны в рантайме.
    Меняется при ЛЮБОМ реальном изменении кода файла - надёжно работает даже
    без переменных окружения Railway, хоть и не различает "просто рестарт" от
    деплоя, если файл не менялся (что и не нужно - тогда пуш и не должен
    слаться)."""
    try:
        with open(__file__, 'rb') as f:
            return 'file:' + hashlib.sha256(f.read()).hexdigest()[:16]
    except Exception:
        return None

def set_bot_meta(key, value):
    init_db()
    conn = get_db_connection()
    conn.execute(
        'INSERT INTO bot_meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',
        (key, value)
    )
    conn.commit()
    conn.close()

async def notify_users_about_new_deploy():
    """Вызывается один раз при старте бота (см. main()). Сравнивает текущий
    RAILWAY_GIT_COMMIT_SHA с последним сохранённым в bot_meta - если это
    ДЕЙСТВИТЕЛЬНО новый деплой (SHA изменился), шлёт короткий пуш "бот
    обновился" всем известным пользователям (всем user_id из user_state -
    по прямому уточнению пользователя, "всем известным пользователям бота",
    без привязки к notif_prefs, это не обычный тип уведомления, а
    служебное сообщение). На самом первом запуске после появления этой
    функции (сохранённого SHA ещё нет) пуш НЕ шлём - иначе все
    существующие пользователи получили бы "обновление" в момент, когда
    бот на самом деле просто впервые запомнил свою версию."""
    # По повторной жалобе пользователя (22.09.2026): "бот обновился" опять не
    # приходит - RAILWAY_GIT_COMMIT_SHA, судя по всему, не всегда доступен в
    # рантайме (зависит от способа деплоя/настроек Railway), из-за чего
    # проверка выше молча выходила и пуш никогда не проверялся. Теперь
    # пробуем НЕСКОЛЬКО источников "версии" по приоритету: RAILWAY_GIT_COMMIT_SHA
    # (самый точный, если доступен) -> RAILWAY_DEPLOYMENT_ID (Railway
    # присваивает новый ID на КАЖДЫЙ деплой, доступен даже без привязки к
    # git-триггерам) -> как последний фолбэк - хэш содержимого самого файла
    # main.py (гарантированно меняется при любом реальном изменении кода,
    # работает вообще без переменных окружения Railway).
    current_sha = (
        os.getenv('RAILWAY_GIT_COMMIT_SHA')
        or os.getenv('RAILWAY_DEPLOYMENT_ID')
        or _self_file_hash()
    )
    if not current_sha:
        logger.info("ℹ️ Не удалось определить версию (нет RAILWAY_* переменных и не удалось хэшировать файл) - пуш об обновлении не проверяется")
        return
    previous_sha = get_bot_meta('last_deployed_commit')
    set_bot_meta('last_deployed_commit', current_sha)
    if previous_sha is None:
        logger.info(f"ℹ️ Первый запуск с отслеживанием версии - запомнил SHA {current_sha[:8]}, пуш не шлю")
        return
    if previous_sha == current_sha:
        return  # обычный рестарт, код не менялся - пуш не нужен

    if not bot:
        return
    recipients = [uid for uid, state in list(user_state.items()) if isinstance(state, dict)]
    if not recipients:
        logger.info(f"🔄 Новый деплой ({previous_sha[:8]} -> {current_sha[:8]}), но известных пользователей пока нет")
        return
    logger.info(f"🔄 Новый деплой ({previous_sha[:8]} -> {current_sha[:8]}) - рассылаю пуш об обновлении {len(recipients)} пользователям")
    sent, failed = 0, 0
    for user_id in recipients:
        try:
            msg = await bot.send_message(user_id, BOT_UPDATED_MESSAGE, parse_mode='Markdown', reply_markup=BOT_UPDATED_REFRESH_KEYBOARD)
            await track_bot_update_message(user_id, msg.message_id)
            sent += 1
        except Exception as e:
            failed += 1
            logger.warning(f"⚠️ Не удалось отправить пуш об обновлении пользователю {user_id}: {e}")
        await asyncio.sleep(0.05)  # Telegram допускает ~30 сообщений/сек в разные чаты
    logger.info(f"🔄 Пуш об обновлении разослан: {sent} успешно, {failed} ошибок")

@router.callback_query(lambda c: c.data == "refresh_menu")
async def handle_refresh_menu_button(callback_query: types.CallbackQuery):
    """"🔄 ОБНОВИТЬ БОТА" под пушем "Вышло обновление бота" (см. BOT_UPDATED_MESSAGE/
    BOT_UPDATED_REFRESH_KEYBOARD выше) - просто заново отправляет ТЕКУЩИЙ
    services_keyboard по уже сохранённым category/city из user_state, чтобы
    у пользователя на телефоне перерисовалась Reply-клавиатура (она
    кэшируется Telegram и не обновляется сама, пока не придёт новое
    сообщение с новым reply_markup). НИЧЕГО в user_state не меняет и не
    сбрасывает - активная смена, черновик заказа, любое другое состояние
    остаются как были, ровно то, что просил пользователь ("сохрани уже
    активированные к примеру начатую смену")."""
    await callback_query.answer("Обновляю бота…")
    user_id = callback_query.from_user.id
    state = user_state.get(user_id, {})
    category = state.get('category')
    city = state.get('city')
    if not category or not city:
        await callback_query.message.answer(
            "Сначала выбери категорию и город, чтобы показать меню 🙂",
            reply_markup=category_keyboard(),
        )
        return
    msg = await callback_query.message.answer(
        "✅ Бот обновлён 👇",
        reply_markup=services_keyboard(category, city, user_id),
    )
    await track_bot_update_message(user_id, msg.message_id)

# ==================== ПЛАТНАЯ ПОДПИСКА ====================
# По просьбе пользователя (20.09.2026): "сделай так чтобы бот был платный
# семь дней подписка будет бесплатно на восьмой день будет платная подписка
# в месяц она будет стоить 149 руб." Уточнено в диалоге: оплата - внешняя
# ссылка на оплату (провайдер Tinkoff Kassa), при истечении триала без
# оплаты - полная блокировка бота (кроме кнопки оплаты), продление -
# "автоматическое списание каждый месяц". У пользователя пока НЕТ
# подключённых рекуррентных платежей в Tinkoff (обычный эквайринг), поэтому
# настоящее автосписание без участия пользователя технически невозможно -
# реализована ближайшая рабочая схема: бот сам присылает новую ссылку на
# оплату, как только текущий период заканчивается (сразу при следующем
# обращении к боту - см. SubscriptionMiddleware - и проактивно, см.
# subscription_expiry_checker), пользователь оплачивает в 1-2 клика.
# Когда пользователь подключит рекуррентные платежи в Tinkoff - легко
# перевести на настоящее автосписание по сохранённому RebillId, добавив его
# сохранение из ответа Tinkoff и вызов Charge вместо повторного Init.
#
# SUBSCRIPTION_ENFORCEMENT_LIVE = False (по прямой просьбе пользователя,
# 20.09.2026: "загрузим на деплой, но везде поставим заглушки, пока без
# учёта 7 дней бесплатно и так далее") - весь код подписки задеплоен и
# рабочий (таблицы, Tinkoff Init/webhook, подсчёт триала), но
# SubscriptionMiddleware ничего не блокирует, пока флаг False - текущие
# клиенты пользуются ботом как раньше. Как только Tinkoff будет настроен и
# пользователь решит включать платную подписку для всех - достаточно
# поменять этот флаг на True, деплоить ничего больше не нужно.
SUBSCRIPTION_ENFORCEMENT_LIVE = False
SUBSCRIPTION_TRIAL_DAYS = 7
SUBSCRIPTION_PRICE_RUB = 149
SUBSCRIPTION_PRICE_KOPECKS = SUBSCRIPTION_PRICE_RUB * 100
