@router.message(lambda message: message.text == "❓ ПОДДЕРЖКА")
async def show_support_menu(message: types.Message):
    await message.answer(SUPPORT_MENU_TEXT, reply_markup=support_faq_top_keyboard(), parse_mode='Markdown')

@router.callback_query(lambda c: c.data.startswith("faqcat_"))
async def faq_category_show(callback_query: types.CallbackQuery):
    try:
        await callback_query.answer()
    except Exception:
        pass
    cat_key = callback_query.data[len("faqcat_"):]
    if cat_key not in SUPPORT_FAQ_CATEGORIES:
        return
    label, _ = SUPPORT_FAQ_CATEGORIES[cat_key]
    text = f"{label}\n{WHERE_TO_GO_DIVIDER}\n\nВыбери вопрос из списка 👇"
    try:
        await callback_query.message.edit_text(text, reply_markup=support_faq_category_keyboard(cat_key), parse_mode='Markdown')
    except Exception:
        await callback_query.message.answer(text, reply_markup=support_faq_category_keyboard(cat_key), parse_mode='Markdown')

@router.callback_query(lambda c: c.data.startswith("faq_") and not c.data.startswith("faqcat_") and c.data != "faq_top")
async def faq_answer_show(callback_query: types.CallbackQuery):
    try:
        await callback_query.answer()
    except Exception:
        pass
    try:
        cat_key, idx_str = callback_query.data[len("faq_"):].split("_", 1)
        idx = int(idx_str)
        _, items = SUPPORT_FAQ_CATEGORIES[cat_key]
        _, question, answer = items[idx]
    except (ValueError, IndexError, KeyError):
        return
    text = f"❓ *{question}*\n{WHERE_TO_GO_DIVIDER}\n\n{answer}"
    try:
        await callback_query.message.edit_text(text, reply_markup=support_faq_answer_keyboard(cat_key), parse_mode='Markdown')
    except Exception:
        await callback_query.message.answer(text, reply_markup=support_faq_answer_keyboard(cat_key), parse_mode='Markdown')

@router.callback_query(lambda c: c.data == "faq_top")
async def faq_back_to_top(callback_query: types.CallbackQuery):
    try:
        await callback_query.answer()
    except Exception:
        pass
    try:
        await callback_query.message.edit_text(SUPPORT_MENU_TEXT, reply_markup=support_faq_top_keyboard(), parse_mode='Markdown')
    except Exception:
        await callback_query.message.answer(SUPPORT_MENU_TEXT, reply_markup=support_faq_top_keyboard(), parse_mode='Markdown')

TINKOFF_TERMINAL_KEY = os.getenv('TINKOFF_TERMINAL_KEY')
TINKOFF_PASSWORD = os.getenv('TINKOFF_PASSWORD')
TINKOFF_INIT_URL = 'https://securepay.tinkoff.ru/v2/Init'
# Публичный адрес бота на Railway - нужен, чтобы указать Tinkoff, куда слать
# webhook об оплате. RAILWAY_PUBLIC_DOMAIN пробрасывается Railway
# автоматически, когда у сервиса включён Public Networking (Settings ->
# Networking). PUBLIC_URL можно также задать вручную переменной окружения,
# если домен не через Railway.
_railway_domain = os.getenv('RAILWAY_PUBLIC_DOMAIN')
PUBLIC_URL = os.getenv('PUBLIC_URL') or (f'https://{_railway_domain}' if _railway_domain else None)
SUBSCRIPTION_WEBHOOK_PORT = int(os.getenv('PORT', '8080'))
SUBSCRIPTION_WEBHOOK_PATH = '/tinkoff/webhook'

# ДОБАВЛЕНО 22.09.2026 (по факту - оплата падала с ClientConnectorCertificateError:
# "self-signed certificate in certificate chain" при обращении к
# securepay.tinkoff.ru): с 2022 года Т-Банк (как и другие крупные российские
# банки) использует TLS-сертификаты, выпущенные НУЦ Минцифры (Russian Trusted
# Root CA/Sub CA) - они НЕ входят в стандартный набор доверенных корневых
# сертификатов на большинстве серверов за пределами России (в т.ч. на
# Railway), поэтому обычный aiohttp.ClientSession() отказывается проверять
# цепочку сертификата. Дело НЕ в TINKOFF_TERMINAL_KEY/TINKOFF_PASSWORD - до
# них запрос даже не доходит, падает на этапе TLS-хендшейка.
# Решение (тот же паттерн, что get_tg_webapp_js выше - self-healing
# кэширование): скачиваем оба сертификата (root+sub) с официального
# статического хостинга Госуслуг (gu-st.ru, обычный международно доверенный
# сертификат, поэтому качается без проблем) при первом платеже, сохраняем в
# DATA_DIR (тот же постоянный Railway Volume, что и БД/flights_data.json -
# переживёт редеплой, не нужно качать заново при каждом рестарте), и
# добавляем их ДОПОЛНИТЕЛЬНО к системному доверенному набору (ssl.create_
# default_context() + load_verify_locations() не заменяет системные CA, а
# добавляет к ним - обычные HTTPS-запросы продолжат работать как раньше).
RUSSIAN_TRUSTED_CA_URLS = [
    'https://gu-st.ru/content/lending/russian_trusted_root_ca_pem.crt',
    'https://gu-st.ru/content/lending/russian_trusted_sub_ca_pem.crt',
]
RUSSIAN_TRUSTED_CA_BUNDLE_FILE = os.path.join(DATA_DIR, 'russian_trusted_ca_bundle.pem')
_tinkoff_ssl_context_cache = {'context': None}


async def get_tinkoff_ssl_context():
    """Возвращает ssl.SSLContext с добавленными российскими корневыми
    сертификатами Минцифры (см. комментарий выше), кэшируя результат в
    памяти процесса после первого успешного построения. Если скачать/
    прочитать сертификаты не удалось - возвращает None (вызывающий код
    в этом случае просто не передаёт ssl= в коннектор, как и раньше, чтобы
    не ломать поведение на средах, где проблемы нет - например, если бот
    когда-нибудь будет запущен на сервере в России, где эта проблема не
    возникает)."""
    if _tinkoff_ssl_context_cache['context'] is not None:
        return _tinkoff_ssl_context_cache['context']
    try:
        if not os.path.exists(RUSSIAN_TRUSTED_CA_BUNDLE_FILE):
            logger.info("🔄 Скачиваю сертификаты НУЦ Минцифры (Russian Trusted Root/Sub CA) для оплаты через Т-Банк...")
            bundle_parts = []
            async with aiohttp.ClientSession() as session:
                for cert_url in RUSSIAN_TRUSTED_CA_URLS:
                    async with session.get(cert_url, timeout=aiohttp.ClientTimeout(total=15)) as resp:
                        resp.raise_for_status()
                        cert_text = (await resp.text()).strip()
                        if '-----BEGIN CERTIFICATE-----' not in cert_text:
                            raise ValueError(f"Ответ {cert_url} не похож на PEM-сертификат")
                        bundle_parts.append(cert_text)
            with open(RUSSIAN_TRUSTED_CA_BUNDLE_FILE, 'w') as f:
                f.write('\n'.join(bundle_parts) + '\n')
            logger.info(f"✅ Сертификаты НУЦ Минцифры сохранены в {RUSSIAN_TRUSTED_CA_BUNDLE_FILE}")
        ssl_context = ssl.create_default_context()
        ssl_context.load_verify_locations(cafile=RUSSIAN_TRUSTED_CA_BUNDLE_FILE)
        _tinkoff_ssl_context_cache['context'] = ssl_context
        return ssl_context
    except Exception as e:
        logger.error(f"❌ Не удалось подготовить сертификаты НУЦ Минцифры для оплаты через Т-Банк: {e}")
        return None

# ==================== ЛОКАЛЬНАЯ РАЗДАЧА telegram-web-app.js ====================
# По факту (21.09.2026): в "Личном кабинете" tg.initData приходил ПУСТЫМ
# (X-Telegram-Init-Data len=0 в логах) - у части российских мобильных
# операторов домен telegram.org (в отличие от самого Telegram, который
# ходит через MTProto, а не HTTPS на этот домен) бывает недоступен/
# нестабилен, из-за чего <script src="https://telegram.org/js/telegram-web-
# app.js"> в вебвью просто не загружается, window.Telegram остаётся
# undefined, и initData/tg.ready() соответственно не работают. Решение -
# раздавать этот скрипт со своего же домена (Railway точно достанет
# telegram.org - он не в России), кэшируя содержимое в памяти процесса.
TG_WEBAPP_JS_PROXY_PATH = '/static/tg-webapp.js'
_tg_webapp_js_cache = {'content': None, 'fetched_at': None}

async def get_tg_webapp_js():
    """Возвращает содержимое telegram-web-app.js, скачивая и кэша его в
    памяти при первом обращении (дальше отдаём из кэша, без похода наружу на
    каждый запрос страницы). Раз в час обновляем в фоне (на случай, если
    Telegram обновит SDK), но если сеть недоступна - отдаём последнюю
    рабочую версию из кэша, а не падаем."""
    cache = _tg_webapp_js_cache
    is_stale = cache['fetched_at'] is None or (time.time() - cache['fetched_at']) > 3600
    if cache['content'] is not None and not is_stale:
        return cache['content']
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get('https://telegram.org/js/telegram-web-app.js', timeout=aiohttp.ClientTimeout(total=10)) as resp:
                resp.raise_for_status()
                text = await resp.text()
        cache['content'] = text
        cache['fetched_at'] = time.time()
    except Exception as e:
        if cache['content'] is None:
            logger.error(f"❌ Не удалось скачать telegram-web-app.js и в кэше пусто: {e}")
        else:
            logger.warning(f"⚠️ Не удалось обновить telegram-web-app.js (использую версию из кэша): {e}")
    return cache['content']

async def handle_tg_webapp_js_proxy(request):
    content = await get_tg_webapp_js()
    if content is None:
        # Совсем нет ни свежей, ни кэшированной версии (первый запуск и сеть
        # недоступна) - редиректим на оригинал как последний шанс, лучше
        # так, чем совсем без SDK.
        raise web.HTTPFound('https://telegram.org/js/telegram-web-app.js')
    return web.Response(
        text=content, content_type='application/javascript',
        headers={'Cache-Control': 'public, max-age=3600'},
    )


def _sub_now():
    """Наивный UTC datetime (без tzinfo) - тот же формат, что и остальные
    временные метки в этом файле ('%Y-%m-%d %H:%M:%S'), чтобы не смешивать
    aware/naive datetime при сравнении."""
    return datetime.now(ZoneInfo('UTC')).replace(tzinfo=None)


def _sub_parse(value):
    return datetime.strptime(value, '%Y-%m-%d %H:%M:%S')


def _sub_format(value):
    return value.strftime('%Y-%m-%d %H:%M:%S')


def ensure_subscription(user_id):
    """Создаёт запись о подписке при первом обращении пользователя к боту -
    именно с этого момента отсчитываются SUBSCRIPTION_TRIAL_DAYS бесплатных
    дней. Если запись уже есть - ничего не делает (триал не продлевается
    повторно)."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT 1 FROM subscriptions WHERE user_id = ?', (user_id,))
    if cursor.fetchone() is None:
        cursor.execute(
            'INSERT INTO subscriptions (user_id, trial_started_at) VALUES (?, ?)',
            (user_id, _sub_format(_sub_now()))
        )
        conn.commit()
    conn.close()


def get_subscription(user_id):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT trial_started_at, paid_until FROM subscriptions WHERE user_id = ?', (user_id,))
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    return {'trial_started_at': row[0], 'paid_until': row[1]}


# ДОБАВЛЕНО 23.09.2026 (по факту - Tinkoff Init отказывал: "request.validate.
# expected.receipt" - для этого терминала обязателен чек по 54-ФЗ, а в чеке
# законодательно нужен контакт покупателя). Собираем email ОДИН раз перед
# первой оплатой (см. show_subscription_status/send_subscription_paywall/
# subscription_email_flow ниже) и переиспользуем для всех следующих
# платежей этого пользователя.
SUBSCRIPTION_EMAIL_REGEX = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')


def get_receipt_email(user_id):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT receipt_email FROM subscriptions WHERE user_id = ?', (user_id,))
    row = cursor.fetchone()
    conn.close()
    return row[0] if row and row[0] else None


def set_receipt_email(user_id, email):
    ensure_subscription(user_id)
    conn = get_db_connection()
    conn.execute('UPDATE subscriptions SET receipt_email = ? WHERE user_id = ?', (email, user_id))
    conn.commit()
    conn.close()


def subscription_active_until(user_id):
    """Возвращает datetime, до какого момента доступ открыт (конец триала
    либо paid_until, что позже), или None если записи ещё нет вообще."""
    sub = get_subscription(user_id)
    if not sub:
        return None
    active_until = _sub_parse(sub['trial_started_at']) + timedelta(days=SUBSCRIPTION_TRIAL_DAYS)
    if sub['paid_until']:
        paid_until = _sub_parse(sub['paid_until'])
        if paid_until > active_until:
            active_until = paid_until
    return active_until


def is_subscription_active(user_id):
    active_until = subscription_active_until(user_id)
    if active_until is None:
        return True  # запись ещё не создана (не должно происходить, ensure_subscription вызывается раньше) - не блокируем на всякий случай
    return _sub_now() < active_until


SUBSCRIPTION_MENU_BUTTON_DEFAULT_TEXT = "💳 ОПЛАТИТЬ ПОДПИСКУ"


# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "когда она оплачена
# выводить текст оплатить подписку поменяй на дату сколько дней осталось до
# окончания подписки"): текст кнопки в главном меню (см. services_keyboard)
# зависит от того, реально ли ОПЛАЧЕНА подписка (paid_until доходит хотя бы
# до конца триала - т.е. был хотя бы один платёж), а не просто идёт триал.
# ВАЖНО: текст кнопки - это "ключ", по которому её ищут обработчики (см.
# show_subscription_status ниже) - при изменении формата нужно поменять и
# лямбду там же.
def subscription_menu_button_text(user_id):
    if user_id is None:
        return SUBSCRIPTION_MENU_BUTTON_DEFAULT_TEXT
    sub = get_subscription(user_id)
    active_until = subscription_active_until(user_id)
    is_paid = bool(sub and sub['paid_until'] and active_until and _sub_parse(sub['paid_until']) >= active_until)
    if not is_paid:
        return SUBSCRIPTION_MENU_BUTTON_DEFAULT_TEXT
    days_left = max(0, (active_until - _sub_now()).days)
    return f"✅ Подписка до {active_until.strftime('%d.%m')} ({days_left} дн.)"


def tinkoff_generate_token(params: dict) -> str:
    """Подпись запроса к Tinkoff Kassa: берутся только плоские (не
    вложенные) поля запроса + Password из личного кабинета, сортируются по
    ключу, значения конкатенируются и хешируются SHA-256 - см.
    https://www.tbank.ru/kassa/dev/payments/#section/Podpis-zaprosa

    ИСПРАВЛЕНО 23.09.2026 (по факту - webhook стабильно приходил с "неверный
    Token", хотя PUBLIC_URL/пароль были верными): в теле webhook Tinkoff
    присылает булевы поля (например "Success": true/false) как настоящий
    JSON-boolean, aiohttp разбирает его в Python True/False, а Python
    str(True) даёт "True" с заглавной буквы - Tinkoff же при вычислении
    подписи на своей стороне использует lowercase "true"/"false". Из-за
    этого пересчитанный токен не совпадал с присланным НИКОГДА, для ЛЮБОГО
    входящего webhook (не только фейковых) - легко принять эту постоянную
    ошибку за проблему с ключами, хотя дело было только в регистре bool."""
    values = {k: v for k, v in params.items() if not isinstance(v, (dict, list))}
    values['Password'] = TINKOFF_PASSWORD

    def _tinkoff_str(v):
        if isinstance(v, bool):
            return 'true' if v else 'false'
        return str(v)

    concat = ''.join(_tinkoff_str(values[k]) for k in sorted(values.keys()))
    return hashlib.sha256(concat.encode('utf-8')).hexdigest()


def save_subscription_order(user_id, order_id, amount_kopecks):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('UPDATE subscriptions SET last_order_id = ? WHERE user_id = ?', (order_id, user_id))
    cursor.execute(
        'INSERT OR REPLACE INTO subscription_payments (order_id, user_id, amount_kopecks, status) VALUES (?, ?, ?, ?)',
        (order_id, user_id, amount_kopecks, 'NEW')
    )
    conn.commit()
    conn.close()


async def create_tinkoff_payment(user_id: int):
    """Создаёт заказ в Tinkoff Kassa (Init) и возвращает ссылку на оплату,
    либо None при ошибке (нет ключей, сеть недоступна, провайдер отказал,
    email для чека ещё не собран - см. ниже).

    ДОБАВЛЕНО 23.09.2026 (по факту - Init отказывал с ErrorCode 309
    "request.validate.expected.receipt"): для этого терминала обязателен
    фискальный чек по 54-ФЗ. Вызывающий код (show_subscription_status/
    send_subscription_paywall) обязан СНАЧАЛА собрать email через
    get_receipt_email/subscription_email_flow, прежде чем звать эту
    функцию - если email всё ещё не задан, возвращаем None с предупреждением
    в лог, чтобы не отправлять в Tinkoff заведомо невалидный запрос."""
    if not TINKOFF_TERMINAL_KEY or not TINKOFF_PASSWORD:
        logger.warning(f"⚠️ TINKOFF_TERMINAL_KEY/TINKOFF_PASSWORD не заданы - не могу создать ссылку на оплату для user_id={user_id}")
        return None
    receipt_email = get_receipt_email(user_id)
    if not receipt_email:
        logger.warning(f"⚠️ Email для чека ещё не собран - не могу создать ссылку на оплату для user_id={user_id}")
        return None
    order_id = f"sub_{user_id}_{int(time.time())}"
    params = {
        'TerminalKey': TINKOFF_TERMINAL_KEY,
        'Amount': SUBSCRIPTION_PRICE_KOPECKS,
        'OrderId': order_id,
        'Description': 'Подписка Taxi Helper на 1 месяц',
        # Обязательный блок чека (54-ФЗ) - Tax='none' соответствует УСН
        # доходы (TINKOFF_RECEIPT_TAXATION), НДС не выделяется. Это
        # ВЛОЖЕННЫЙ объект - в подпись (tinkoff_generate_token) НЕ входит,
        # там уже отфильтрованы dict/list, как того требует алгоритм Tinkoff.
        'Receipt': {
            'Email': receipt_email,
            'Taxation': TINKOFF_RECEIPT_TAXATION,
            'Items': [
                {
                    'Name': 'Подписка Taxi Helper на 1 месяц',
                    'Price': SUBSCRIPTION_PRICE_KOPECKS,
                    'Quantity': 1,
                    'Amount': SUBSCRIPTION_PRICE_KOPECKS,
                    'Tax': 'none',
                    'PaymentMethod': 'full_payment',
                    'PaymentObject': 'service',
                }
            ],
        },
    }
    if PUBLIC_URL:
        params['NotificationURL'] = f'{PUBLIC_URL}{SUBSCRIPTION_WEBHOOK_PATH}'
    else:
        logger.warning(f"⚠️ PUBLIC_URL/RAILWAY_PUBLIC_DOMAIN не заданы - Tinkoff не сможет прислать webhook об оплате для user_id={user_id}")
    payload = dict(params)
    payload['Token'] = tinkoff_generate_token(params)
    # См. комментарий у get_tinkoff_ssl_context/RUSSIAN_TRUSTED_CA_URLS выше -
    # securepay.tinkoff.ru отдаёт сертификат от НУЦ Минцифры, которого нет в
    # обычном системном доверенном наборе на Railway, поэтому без явного
    # ssl_context запрос падает с ClientConnectorCertificateError. Если
    # подготовить контекст не получилось (сеть, gu-st.ru недоступен) -
    # ssl_context будет None, и TCPConnector просто использует обычную
    # проверку по умолчанию (как и раньше).
    ssl_context = await get_tinkoff_ssl_context()
    try:
        connector = aiohttp.TCPConnector(ssl=ssl_context) if ssl_context else None
        async with aiohttp.ClientSession(connector=connector) as session:
            async with session.post(TINKOFF_INIT_URL, json=payload, timeout=aiohttp.ClientTimeout(total=15)) as resp:
                data = await resp.json()
    except Exception:
        logger.exception(f"❌ Ошибка запроса к Tinkoff Init для user_id={user_id}")
        return None
    if not data.get('Success'):
        logger.error(f"❌ Tinkoff Init отказал для user_id={user_id}: {data}")
        return None
    save_subscription_order(user_id, order_id, SUBSCRIPTION_PRICE_KOPECKS)
    return data.get('PaymentURL')


def subscription_paywall_keyboard(pay_url):
    buttons = []
    if pay_url:
        buttons.append([InlineKeyboardButton(text=f"💳 ОПЛАТИТЬ {SUBSCRIPTION_PRICE_RUB}₽", url=pay_url)])
    buttons.append([InlineKeyboardButton(text="🔄 Я ОПЛАТИЛ(А), ПРОВЕРИТЬ", callback_data="sub_pay_check")])
    return InlineKeyboardMarkup(inline_keyboard=buttons)


