    "🔒 *Пробный период закончился*\n"
    f"{WHERE_TO_GO_DIVIDER}\n\n"
    f"Бесплатные {SUBSCRIPTION_TRIAL_DAYS} дней использованы. Чтобы продолжать пользоваться ботом, "
