    app.router.add_post(SHARE_ORDER_SUBMIT_API_PATH, handle_share_order_submit_api)
    app.router.add_post(PLATFORM_REPORT_API_PATH, handle_platform_report_api)
    # Личный кабинет (см. блок "ЛИЧНЫЙ КАБИНЕТ (WebApp)" выше)
