#   'individual' (обычные пользователи, дефолт) - 30%/15%/5% по тем же
#   трём уровням.
# В обоих случаях это ПРЯМОЙ процент от суммы платежа плательщика на каждом
# уровне (не "доля от начисления уровня выше", как было раньше) - см.
# distribute_referral_earnings ниже.
REFERRAL_RATES_PERCENT = {
    'individual': [30, 15, 5],
    'legal_entity': [40, 20, 10],
}
REFERRAL_DEFAULT_TYPE = 'individual'
REFERRAL_WITHDRAWAL_FEE_PERCENT = 3
REFERRAL_MIN_WITHDRAWAL_RUB = 1000  # по прямой просьбе пользователя, 20.09.2026
# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "сделай вывод в день
# лимиты от 1000 до 10000 в день", уточнено через AskUserQuestion - лимит
# НА КАЖДОГО ВОДИТЕЛЯ отдельно, не общий на всех): сколько один человек
# может суммарно вывести за календарные сутки (UTC, тот же часовой пояс,
# что и everywhere в файле) - см. get_referral_withdrawn_today_kopecks/
# referral_withdraw_start/referral_withdraw_flow ниже. Учитываются заявки
# в статусах 'pending' и 'paid' (уже реально запрошенные/выплаченные
# деньги) - отменённых заявок в этой реализации пока не бывает.
REFERRAL_MAX_WITHDRAWAL_PER_DAY_RUB = 10000
# ЗАГЛУШКА НА БУДУЩЕЕ (по прямой просьбе пользователя - "давай настроим
# авто перевод позже пока заглушка"): сейчас выплата по заявке делается
# АДМИНОМ ВРУЧНУЮ (перевод на карту + команда /referral_paid, см. ниже).
# Автоматический перевод денег потребует отдельного продукта Т-Банка
# "Массовые выплаты" (отдельный договор/ключи, НЕ то же самое, что
# TINKOFF_TERMINAL_KEY/TINKOFF_PASSWORD для приёма оплаты подписки) - когда
# будет готово, сюда добавится реальный вызов API вместо ручной пометки.
REFERRAL_AUTO_PAYOUT_LIVE = False
ADMIN_TELEGRAM_ID = os.getenv('ADMIN_TELEGRAM_ID')  # для заявок на вывод и команд /referral_paid, /set_legal_referrer


def ensure_referral_row(user_id):
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT 1 FROM referrals WHERE user_id = ?', (user_id,))
    if cursor.fetchone() is None:
        cursor.execute('INSERT INTO referrals (user_id) VALUES (?)', (user_id,))
        conn.commit()
    conn.close()


def register_referral(user_id, referrer_id):
    """Вызывается один раз - при первом /start?start=ref_<id> у пользователя,
    у которого ЕЩЁ НЕТ привязанного реферера (не переписывает существующую
    связь, не даёт указать самого себя рефералом).

    ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - 3 уровня вместо 2):
    теперь фиксируется ещё и referred_by_level3 (реферер реферера
    реферера) - тот же принцип, что и у level2: считается ОДИН раз на
    момент регистрации, не пересчитывается задним числом."""
    if referrer_id == user_id:
        return
    ensure_referral_row(user_id)
    ensure_referral_row(referrer_id)
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT referred_by FROM referrals WHERE user_id = ?', (user_id,))
    row = cursor.fetchone()
    if row and row[0] is not None:
        conn.close()
        return
    cursor.execute('SELECT referred_by, referred_by_level2 FROM referrals WHERE user_id = ?', (referrer_id,))
    r = cursor.fetchone()
    level2 = r[0] if r else None
    level3 = r[1] if r else None
    cursor.execute(
        'UPDATE referrals SET referred_by = ?, referred_by_level2 = ?, referred_by_level3 = ? WHERE user_id = ?',
        (referrer_id, level2, level3, user_id)
    )
    conn.commit()
    conn.close()


def get_referral_downline_count(user_id):
    """Сколько человек ВСЕГО в ветке пользователя, на любую глубину (3+
    уровня тоже считаются) - ТОЛЬКО для отображения, деньги по-прежнему
    начисляются лишь на 1 и 2 уровне (см. distribute_referral_earnings). По
    просьбе пользователя (20.09.2026): "добавить видимость 3+ уровня без
    денег". SQLite умеет рекурсивные CTE (WITH RECURSIVE) - обходим дерево
    referred_by вниз от user_id."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        '''
        WITH RECURSIVE downline(uid) AS (
            SELECT user_id FROM referrals WHERE referred_by = ?
            UNION ALL
            SELECT r.user_id FROM referrals r JOIN downline d ON r.referred_by = d.uid
        )
        SELECT COUNT(*) FROM downline
        ''',
        (user_id,)
    )
    count = cursor.fetchone()[0]
    conn.close()
    return count


def get_referral_stats(user_id):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT balance_kopecks, total_earned_kopecks, total_withdrawn_kopecks FROM referrals WHERE user_id = ?',
        (user_id,)
    )
    row = cursor.fetchone()
    cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by = ?', (user_id,))
    level1_count = cursor.fetchone()[0]
    cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by_level2 = ?', (user_id,))
    level2_count = cursor.fetchone()[0]
    # ДОБАВЛЕНО 23.09.2026 (3 уровня вместо 2, см. REFERRAL_RATES_PERCENT)
    cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by_level3 = ?', (user_id,))
    level3_count = cursor.fetchone()[0]
    conn.close()
    downline_total = get_referral_downline_count(user_id)
    return {
        'balance': (row[0] or 0) if row else 0,
        'total_earned': (row[1] or 0) if row else 0,
        'total_withdrawn': (row[2] or 0) if row else 0,
        'level1_count': level1_count,
        'level2_count': level2_count,
        'level3_count': level3_count,
        'downline_total': downline_total,  # видимость на всю глубину, без денег (4+ уровень)
    }


def get_referral_breakdown(user_id, limit=20):
    """Список прямых (1 уровень) рефералов - для каждого: сколько своих
    ПРЯМЫХ рефералов он привёл (это оплачиваемый 2 уровень) и сколько
    человек всего в ЕГО ветке на любую глубину (видимость 3+ уровня без
    денег - см. get_referral_downline_count)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT user_id FROM referrals WHERE referred_by = ? ORDER BY joined_at DESC LIMIT ?',
        (user_id, limit)
    )
    level1_ids = [r[0] for r in cursor.fetchall()]
    breakdown = []
    for uid in level1_ids:
        cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by = ?', (uid,))
        sub_count = cursor.fetchone()[0]
        breakdown.append({
            'user_id': uid,
            'sub_referrals': sub_count,
            'branch_total': get_referral_downline_count(uid),
        })
    conn.close()
    return breakdown


def _credit_referral_earning(earner_id, source_id, level, amount_kopecks, order_id):
    if amount_kopecks <= 0:
        return 0
    ensure_referral_row(earner_id)
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'INSERT INTO referral_earnings (earner_user_id, source_user_id, level, amount_kopecks, order_id) VALUES (?, ?, ?, ?, ?)',
        (earner_id, source_id, level, amount_kopecks, order_id)
    )
    cursor.execute(
        'UPDATE referrals SET balance_kopecks = balance_kopecks + ?, total_earned_kopecks = total_earned_kopecks + ? WHERE user_id = ?',
        (amount_kopecks, amount_kopecks, earner_id)
    )
    conn.commit()
    conn.close()
    return amount_kopecks


def get_referrer_type(user_id):
    """'legal_entity' или 'individual' (дефолт) - см. комментарий у
    REFERRAL_RATES_PERCENT. Определяет, по какой шкале процентов ЭТОТ
    человек получает начисления со своих рефералов (не зависит от того,
    кто его самого пригласил)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT referrer_type FROM referrals WHERE user_id = ?', (user_id,))
    row = cursor.fetchone()
    conn.close()
    referrer_type = row[0] if row else None
    return referrer_type if referrer_type in REFERRAL_RATES_PERCENT else REFERRAL_DEFAULT_TYPE

def set_referrer_type(user_id, referrer_type):
    if referrer_type not in REFERRAL_RATES_PERCENT:
        return False
    ensure_referral_row(user_id)
    conn = get_db_connection()
    conn.execute('UPDATE referrals SET referrer_type = ? WHERE user_id = ?', (referrer_type, user_id))
    conn.commit()
    conn.close()
    return True

def distribute_referral_earnings(payer_user_id, amount_kopecks, order_id):
    """Вызывается из confirm_subscription_payment при каждом подтверждённом
    платеже - начисляет 1, 2 и 3 уровню (если у плательщика есть
    реферер(ы) на этой глубине). Возвращает список (earner_id, level,
    начислено_копеек) для рассылки уведомлений вызывающим кодом (сам ничего
    не шлёт - синхронная функция).

    ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - 2 схемы начислений,
    3 уровня): раньше был фиксированный процент 1 уровня + доля от него на
    2 уровне, один на всех. Теперь на каждом уровне берётся ПРЯМОЙ процент
    от суммы платежа - какой именно, зависит от referrer_type КОНКРЕТНОГО
    получателя на этом уровне (см. get_referrer_type/REFERRAL_RATES_PERCENT) -
    так что юр.лицо и обычный пользователь, стоящие на одном и том же
    уровне цепочки, получат разные суммы с одного и того же платежа."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT referred_by, referred_by_level2, referred_by_level3 FROM referrals WHERE user_id = ?',
        (payer_user_id,)
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return []
    notifications = []
    for level, earner_id in enumerate(row, start=1):
        if not earner_id:
            continue
        rates = REFERRAL_RATES_PERCENT[get_referrer_type(earner_id)]
        rate_percent = rates[level - 1]
        if rate_percent <= 0:
            continue
        amount = amount_kopecks * rate_percent // 100
        credited = _credit_referral_earning(earner_id, payer_user_id, level, amount, order_id)
        if credited:
            notifications.append((earner_id, level, credited))
    return notifications


REFERRAL_SHARE_TEXT_TEMPLATE = (
    "Пользуюсь Taxi Helper - бот-помощник для водителей такси/курьеров/грузового такси: "
    "подсказывает, куда ехать и когда самый спрос, следит за очередями в аэропортах, считает доход за смену. "
    "Заходи по ссылке 👇\n{link}"
)


def referral_menu_keyboard(referral_link, current_type=REFERRAL_DEFAULT_TYPE):
    # "🔗 МОЯ ССЫЛКА"/"📤 ПОДЕЛИТЬСЯ ССЫЛКОЙ" - по прямой просьбе пользователя
    # (20.09.2026: "нужна кнопка... чтобы люди понимали какую ссылку давать
    # чтобы делиться"). "Поделиться" - через switch_inline_query: открывает
    # у пользователя список его чатов Telegram с уже готовым текстом+ссылкой,
    # остаётся выбрать, кому переслать - самый надёжный способ "поделиться"
    # для обычной кнопки бота (Telegram не даёт ботам напрямую копировать
    # текст в буфер обмена). "Моя ссылка" - просто прислать ссылку отдельным
    # сообщением, чтобы было удобно скопировать долгим нажатием.
    #
    # ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "сразу выведи две
    # кнопки с реферальной программой для двух категорий под кнопкой
    # реферальная программа"): выбор схемы начислений ПРЯМО здесь, сверху -
    # "Юр.лицо" защищена паролем (см. referral_category_legal_start/
    # REFERRAL_LEGAL_ENTITY_PASSWORD), "Обычная" переключает сразу без
    # подтверждения. Текущий выбор отмечен галочкой.
    share_text = REFERRAL_SHARE_TEXT_TEMPLATE.format(link=referral_link)
    # ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - "поменяй где юр лица
    # убери там проценты чтобы не видели обычные юзеры") - проценты схемы
    # "юр.лицо" больше не показываются в кнопке (обычные пользователи не
    # должны видеть, насколько она выгоднее). У "Обычной" проценты оставлены -
    # это ставка самого пользователя, её скрывать незачем.
    individual_label = ("✅ " if current_type == 'individual' else "") + "👤 Обычная (30/15/5%)"
    legal_label = ("✅ " if current_type == 'legal_entity' else "") + "🏢 Юр.лицо"
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=individual_label, callback_data="referral_category_individual")],
        [InlineKeyboardButton(text=legal_label, callback_data="referral_category_legal_start")],
        [InlineKeyboardButton(text="🔗 МОЯ ССЫЛКА", callback_data="referral_link_show")],
        [InlineKeyboardButton(text="📤 ПОДЕЛИТЬСЯ ССЫЛКОЙ", switch_inline_query=share_text)],
        [InlineKeyboardButton(text="📋 МОИ РЕФЕРАЛЫ", callback_data="referral_list")],
        [InlineKeyboardButton(text="💸 ВЫВЕСТИ СРЕДСТВА", callback_data="referral_withdraw_start")],
        # ПЕРЕНЕСЕНО 23.09.2026 (прямая просьба пользователя - "фантом
        # перенеси в рефералов кнопку") - раньше "👻 ФАНТОМ" была на экранах
        # подписки (subscription_paywall_keyboard), теперь здесь, в меню
        # реферальной программы. Сама логика (PHANTOM_SUBSCRIPTION_PASSWORD/
        # phantom_start/phantom_password_flow, см. блок "ПЛАТНАЯ ПОДПИСКА"
        # выше) не менялась - только расположение кнопки, callback_data тот
        # же ("phantom_start"), поэтому хендлер трогать не нужно.
        [InlineKeyboardButton(text="👻 ФАНТОМ", callback_data="phantom_start")],
    ])


def get_referral_link(bot_username, user_id):
    return f"https://t.me/{bot_username}?start=ref_{user_id}"


def referral_withdraw_cancel_keyboard():
    return ReplyKeyboardMarkup(resize_keyboard=True, keyboard=[[KeyboardButton(text="❌ ОТМЕНА")]])


@router.message(lambda message: message.text == "🤝 РЕФЕРАЛЬНАЯ ПРОГРАММА")
async def show_referral_program(message: types.Message):
    user_id = message.from_user.id
    ensure_referral_row(user_id)
    if not REFERRAL_PROGRAM_LIVE:
        await message.answer(
            "🤝 *Реферальная программа*\n\n"
            "Скоро здесь можно будет приглашать друзей по своей ссылке и получать процент с их подписки. "
            "Раздел в разработке — совсем скоро заработает 🚀",
            parse_mode='Markdown'
        )
        return
    stats = get_referral_stats(user_id)
    me = await bot.get_me()
    link = get_referral_link(me.username, user_id)
    # ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "поработай над
    # визуальной частью ... по тому что не в миниапе") - раньше это был
    # сплошной абзац без деления на смысловые блоки. Разбито на секции тем
    # же общим разделителем WHERE_TO_GO_DIVIDER, что уже используется в
    # "Куда ехать"/"ДЕНЬ - ИТОГ" - ссылка / статистика рефералов / баланс /
    # как это работает, читается быстрее одним взглядом.
    # ИЗМЕНЕНО 23.09.2026 (3 уровня + 2 схемы начислений, см.
    # REFERRAL_RATES_PERCENT/get_referrer_type) - показываем СВОЮ шкалу
    # процентов (обычную 30/15/5 или, для юр.лиц, 40/20/10), а не одну
    # зашитую формулу на всех.
    my_rates = REFERRAL_RATES_PERCENT[get_referrer_type(user_id)]
    text = (
        "🤝 *Реферальная программа*\n"
        f"{WHERE_TO_GO_DIVIDER}\n\n"
        f"🔗 Твоя ссылка (отправляй друзьям):\n`{link}`\n\n"
        f"👥 Рефералов 1-го уровня: {stats['level1_count']}\n"
        f"👥 Рефералов 2-го уровня: {stats['level2_count']}\n"
        f"👥 Рефералов 3-го уровня: {stats['level3_count']}\n"
        f"🌳 Всего людей в твоей ветке (любая глубина): {stats['downline_total']}\n"
        f"{WHERE_TO_GO_DIVIDER}\n\n"
        f"💰 Баланс: {stats['balance'] / 100:.0f}₽\n"
        f"📈 Всего заработано: {stats['total_earned'] / 100:.0f}₽\n"
        f"📤 Всего выведено: {stats['total_withdrawn'] / 100:.0f}₽\n"
        f"{WHERE_TO_GO_DIVIDER}\n\n"
        f"_Как это работает:_ {my_rates[0]}% с каждого ежемесячного платежа приглашённого "
        f"тобой напрямую (1 уровень), {my_rates[1]}% с платежей его рефералов (2 уровень) и "
        f"{my_rates[2]}% с платежей рефералов 2 уровня (3 уровень) - прямой процент от суммы "
        f"платежа на каждом уровне. Начисляется каждый месяц, пока реферал платит подписку. "
        f"Дальше 3 уровня деньги не идут, но всю ветку целиком видно в «📋 Мои рефералы».\n\n"
        f"Вывод - только на карту, комиссия сервиса {REFERRAL_WITHDRAWAL_FEE_PERCENT}%, "
        f"минимум {REFERRAL_MIN_WITHDRAWAL_RUB}₽."
    )
    await message.answer(text, reply_markup=referral_menu_keyboard(link, get_referrer_type(user_id)), parse_mode='Markdown')


