def _find_faq_text_match(text: str):
    """Возвращает (cat_key, idx) лучшего совпадения по FAQ_TEXT_TRIGGERS
    (у кого сработало больше ключевых фраз; при равенстве - первый найденный
    по порядку словаря), или None, если ничего не подошло."""
    text_lower = text.lower()
    best_key = None
    best_score = 0
    for key, triggers in FAQ_TEXT_TRIGGERS.items():
        score = sum(1 for trig in triggers if trig in text_lower)
        if score > best_score:
            best_score = score
            best_key = key
    return best_key

@router.message(lambda message: bool((message.text or '').strip()) and not (message.text or '').startswith('/'))
async def faq_free_text_responder(message: types.Message):
    """Ловит свободный текст в чате и, если он похож на один из вопросов
    FAQ, сразу отвечает тем же ответом, что и через кнопку "❓ ПОДДЕРЖКА" -
    без единого нажатия. Без ИИ, просто поиск по ключевым словам (см.
    FAQ_TEXT_TRIGGERS выше). Если совпадения нет - ничего не отвечает, чтобы
    не мешать обычным сообщениям в чате (этот хендлер стоит последним, так
    что до него доходит только то, что не поймал ни один другой хендлер)."""
    text = (message.text or '').strip()
    if len(text) < 4:
        return
    match = _find_faq_text_match(text)
    if not match:
        return
    cat_key, idx = match
    _, items = SUPPORT_FAQ_CATEGORIES[cat_key]
    _, question, answer = items[idx]
    reply_text = f"❓ *{question}*\n{WHERE_TO_GO_DIVIDER}\n\n{answer}"
    await message.answer(reply_text, reply_markup=support_faq_answer_keyboard(cat_key), parse_mode='Markdown')

async def main():
    global bot
    if not await initialize_bot():
        return
    load_all_user_states()
    load_all_recent_bot_messages()
    load_all_last_reply_keyboard_messages()
    # На случай, если в БД скопилось больше KEEP_LAST_N_MESSAGES на чат
    # (например, при смене этой константы, или если предыдущий процесс
    # упал посреди записи) - подчищаем лишнее один раз при старте, теперь
    # уже полноценно (bot к этому моменту уже инициализирован и может
    # звать delete_message).
    # ИСПРАВЛЕНО 23.09.2026 (жалоба пользователя - "удаляется не через 30
    # секунд, а через 5 минут"): эта чистка на старте ставила такие
    # сообщения в очередь через _schedule_delete_message с ОБЫЧНОЙ задержкой
    # DELETE_MESSAGE_DELAY_SECONDS (30с) - но отсчёт шёл заново от момента
    # РЕСТАРТА бота, а не от момента, когда сообщение реально устарело (оно
    # уже выпало за пределы KEEP_LAST_N_MESSAGES ДО рестарта, то есть после
    # него пользователь успел получить ещё несколько новых сообщений). При
    # каждом редеплое (git push) эти сообщения из-за этого удалялись с
    # доп. задержкой в 30с ОТ МОМЕНТА РЕДЕПЛОЯ, а не от момента, когда они
    # устарели - если редеплой случался через несколько минут после
    # отправки, суммарная задержка росла до нескольких минут. Раз они и
    # так уже устарели к моменту рестарта - удаляем их сразу (delay=0),
    # без дополнительного ожидания.
    for _chat_id, _queue in list(_recent_bot_message_ids.items()):
        while len(_queue) > KEEP_LAST_N_MESSAGES:
            _old_id = _queue.pop(0)
            delete_recent_bot_message_row(_chat_id, _old_id)
            _schedule_delete_message(_chat_id, _old_id, delay=0)
    # Пуш "бот обновился до новой версии" (по просьбе пользователя,
    # 20.09.2026) - проверяем ОДИН раз при старте, до старта polling, но
    # ПОСЛЕ load_all_user_states (нужен список известных user_id) - см.
    # notify_users_about_new_deploy. Не блокирует остальной запуск при
    # ошибке (например, Telegram недоступен в момент старта).
    try:
        await notify_users_about_new_deploy()
    except Exception as e:
        logger.error(f"❌ Ошибка при рассылке пуша об обновлении: {e}")
    # Платная подписка (см. блок "ПЛАТНАЯ ПОДПИСКА" выше) - outer middleware
    # проверяется раньше любого хендлера в router, поэтому регистрируется до
    # dp.include_router. Отдельный webhook-сервер Tinkoff поднимается тут же
    # фоновой задачей, независимо от long polling.
    dp.message.outer_middleware(SubscriptionMiddleware())
    dp.callback_query.outer_middleware(SubscriptionMiddleware())
    dp.message.outer_middleware(ChatCleanupIncomingMiddleware())
    asyncio.create_task(start_subscription_webhook_server())
    asyncio.create_task(subscription_expiry_checker())
    asyncio.create_task(subscription_expiry_reminder_checker())
    dp.include_router(router)
    if os.getenv('YANDEX_RASP_API_KEY'):
        asyncio.create_task(airports_data_updater())
        asyncio.create_task(trains_data_updater())
    else:
        logger.warning("⚠️ YANDEX_RASP_API_KEY не задан в переменных окружения Railway - flights_data.json и trains_data.json не будут обновляться автоматически")
    asyncio.create_task(favt_notices_updater())
    asyncio.create_task(road_events_updater())
    asyncio.create_task(concert_events_updater())
    # mos_road_data_updater() ОТКЛЮЧЁН - apidata.mos.ru не резолвится даже с
    # серверов Railway (NameResolutionError на 'apidata.mos.ru' в логах),
    # не только из среды разработки. Похоже, домен просто недоступен из
    # датацентров вообще (частая практика блокировки у российских
    # госпорталов данных для зарубежных/датацентровых IP) - дело не в ключе
    # и не в датасете. Код (fetch_mos_road_data.py, load_mos_road_data,
    # mos_road_data_updater) оставлен на будущее - вдруг ограничение снимут
    # или появится способ ходить туда не с датацентрового IP.
    # asyncio.create_task(mos_road_data_updater())
    asyncio.create_task(high_demand_alert_checker())
    asyncio.create_task(green_demand_alert_checker())
    asyncio.create_task(weather_data_updater())  # раз в час собирает погоду по всем городам в weather_data.json
    asyncio.create_task(rain_checker())
    asyncio.create_task(holiday_checker())
    asyncio.create_task(airport_queue_checker())
    asyncio.create_task(peak_hour_alert_checker())
    asyncio.create_task(campaign_profit_monthly_report())
    asyncio.create_task(check_long_shifts())
    asyncio.create_task(nearby_drivers_checker())
    asyncio.create_task(morning_greeting_checker())
    asyncio.create_task(user_state_flusher())  # write-behind для user_state - см. комментарий у PersistentUserDict
    # Прогрев кэша telegram-web-app.js (21.09.2026, см. "ЛОКАЛЬНАЯ РАЗДАЧА
    # telegram-web-app.js" выше) - скачиваем сразу при старте, а не ждём
    # первого запроса от водителя (иначе первое открытие карты/кабинета
    # после рестарта ждало бы лишние секунды на поход за скриптом).
    asyncio.create_task(get_tg_webapp_js())
    # allowed_updates передаём ЯВНО (а не полагаемся на автоматическое
    # dp.resolve_used_update_types()) - похоже, это и была причина, почему
    # пуши "Очередь у аэропорта" не приходили: Telegram Bot API запоминает
    # список allowed_updates между вызовами getUpdates на своей стороне, и
    # если хоть раз polling стартовал БЕЗ edited_message в списке (например,
    # до того как в коде появился хендлер @router.edited_message, много
    # деплоев назад) - сервер мог продолжать не присылать edited_message
    # апдейты вообще, даже после того как код научился их обрабатывать. В
    # логах Railway это выглядело как "Update id=... is not handled" на
    # каждое обновление живой геопозиции - апдейт до бота не долетал в
    # обрабатываемом виде. message/edited_message/callback_query - все типы
    # апдейтов, которые реально используются хендлерами в этом файле (см.
    # @router.message/@router.edited_message/@router.callback_query).
    try:
        await dp.start_polling(bot, allowed_updates=['message', 'edited_message', 'callback_query'])
    finally:
        # На штатном рестарте/редеплое (SIGTERM, aiogram корректно
        # завершает start_polling) досбрасываем всё, что ещё не успел
        # забрать фоновый user_state_flusher() - без этого при частых
        # редеплоях (а они бывают часто) можно было бы систематически
        # терять до ~1с изменений состояния на каждом рестарте.
        try:
            await flush_dirty_user_states()
        except Exception as e:
            logger.error(f"❌ Ошибка финального флаша user_state при завершении: {e}")

if __name__ == '__main__':
    asyncio.run(main())
